import type {AmbientWindSettings, CameraSettings, Vec3} from '../../contracts';
import {
  createFractalTerrain,
  estimateMeshCpuBytes,
  type ModelComplexity
} from '../model';
import {MAX_SCENE_TRIANGLES, type LightDefinition, type MaterialDefinition, type MeshDefinition} from '../scene';
import {EnvironmentMeshBuilder, normalized} from './mesh-builder';
import {SeededRandom} from './random';
import type {
  EnvironmentMaterialDefinition,
  EnvironmentMeshBatch,
  MeadowEnvironmentBundle,
  MeadowEnvironmentOptions,
  MeadowEnvironmentPlan,
  MeadowQualityPreset,
  MeadowTriangleBreakdown
} from './types';

interface MeadowPresetConfig {
  terrainX: number;
  terrainZ: number;
  trunkRings: number;
  trunkRadial: number;
  branchCount: number;
  branchSegments: number;
  branchRadial: number;
  twigsPerBranch: number;
  twigSegments: number;
  twigRadial: number;
  leafClusters: number;
  leafCards: number;
  grassBlades: number;
  flowers: number;
  rocks: number;
  rockRadial: number;
}

export const MEADOW_PRESETS: Readonly<Record<MeadowQualityPreset, MeadowPresetConfig>> = Object.freeze({
  preview: Object.freeze({
    terrainX: 24, terrainZ: 16, trunkRings: 8, trunkRadial: 8,
    branchCount: 18, branchSegments: 2, branchRadial: 5,
    twigsPerBranch: 0, twigSegments: 2, twigRadial: 4,
    leafClusters: 60, leafCards: 2, grassBlades: 350,
    flowers: 30, rocks: 10, rockRadial: 5
  }),
  realtime: Object.freeze({
    terrainX: 40, terrainZ: 28, trunkRings: 12, trunkRadial: 12,
    branchCount: 42, branchSegments: 3, branchRadial: 7,
    twigsPerBranch: 1, twigSegments: 2, twigRadial: 5,
    leafClusters: 300, leafCards: 3, grassBlades: 2_200,
    flowers: 180, rocks: 35, rockRadial: 7
  }),
  quality: Object.freeze({
    terrainX: 80, terrainZ: 56, trunkRings: 18, trunkRadial: 16,
    branchCount: 90, branchSegments: 4, branchRadial: 9,
    twigsPerBranch: 2, twigSegments: 2, twigRadial: 6,
    leafClusters: 1_400, leafCards: 4, grassBlades: 12_000,
    flowers: 600, rocks: 110, rockRadial: 9
  }),
  cinematic: Object.freeze({
    terrainX: 128, terrainZ: 96, trunkRings: 24, trunkRadial: 24,
    branchCount: 180, branchSegments: 5, branchRadial: 12,
    twigsPerBranch: 3, twigSegments: 3, twigRadial: 8,
    leafClusters: 5_000, leafCards: 5, grassBlades: 40_000,
    flowers: 2_000, rocks: 280, rockRadial: 12
  })
});

const TERRAIN_WIDTH = 48;
const TERRAIN_DEPTH = 36;
const TREE_HEIGHT = 9.5;

function planTriangles(config: MeadowPresetConfig): MeadowTriangleBreakdown {
  return {
    terrain: config.terrainX * config.terrainZ * 2,
    tree: (config.trunkRings - 1) * config.trunkRadial * 2
      + config.branchCount * config.branchSegments * config.branchRadial * 2
      + config.branchCount * config.twigsPerBranch * config.twigSegments * config.twigRadial * 2,
    leaves: config.leafClusters * config.leafCards * 2,
    grass: config.grassBlades * 2,
    flowers: config.flowers * 6,
    rocks: config.rocks * config.rockRadial * 4
  };
}

export function planMeadowEnvironment(preset: MeadowQualityPreset = 'realtime'): MeadowEnvironmentPlan {
  const config = MEADOW_PRESETS[preset] as MeadowPresetConfig | undefined;
  if (!config) throw new RangeError(`Unknown meadow quality preset: ${preset}`);
  const triangles = planTriangles(config);
  const totalTriangles = Object.values(triangles).reduce((sum, value) => sum + value, 0);
  if (totalTriangles > MAX_SCENE_TRIANGLES) {
    throw new RangeError(`Meadow ${preset} preset requires ${totalTriangles} triangles, exceeding ${MAX_SCENE_TRIANGLES}`);
  }
  return {
    preset,
    triangles,
    totalTriangles,
    terrainXSegments: config.terrainX,
    terrainZSegments: config.terrainZ,
    branchCount: config.branchCount,
    leafClusterCount: config.leafClusters,
    grassBladeCount: config.grassBlades,
    flowerCount: config.flowers,
    rockCount: config.rocks
  };
}

function add(a: Vec3, b: Vec3): Vec3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function multiply(vector: Vec3, scalar: number): Vec3 {
  return [vector[0] * scalar, vector[1] * scalar, vector[2] * scalar];
}

function terrainHeight(mesh: MeshDefinition, xSegments: number, zSegments: number, center: Vec3, x: number, z: number): number {
  const positions = mesh.positions as ArrayLike<number>;
  const xRatio = Math.max(0, Math.min(1, (x - center[0]) / TERRAIN_WIDTH + 0.5));
  const zRatio = Math.max(0, Math.min(1, (z - center[2]) / TERRAIN_DEPTH + 0.5));
  const xGrid = xRatio * xSegments;
  const zGrid = zRatio * zSegments;
  const x0 = Math.min(xSegments - 1, Math.floor(xGrid));
  const z0 = Math.min(zSegments - 1, Math.floor(zGrid));
  const tx = xGrid - x0;
  const tz = zGrid - z0;
  const columns = xSegments + 1;
  const sample = (xi: number, zi: number): number => positions[(zi * columns + xi) * 3 + 1] ?? center[1];
  const a = sample(x0, z0);
  const b = sample(x0 + 1, z0);
  const c = sample(x0, z0 + 1);
  const d = sample(x0 + 1, z0 + 1);
  return a + (b - a) * tx + (c - a) * tz + (a - b - c + d) * tx * tz;
}

function trunkCenter(root: Vec3, ratio: number, leanX: number, leanZ: number): Vec3 {
  return [
    root[0] + leanX * ratio + Math.sin(ratio * Math.PI * 1.7) * 0.09,
    root[1] + TREE_HEIGHT * ratio,
    root[2] + leanZ * ratio + Math.sin(ratio * Math.PI * 1.25 + 0.7) * 0.07
  ];
}

function buildTree(config: MeadowPresetConfig, root: Vec3, random: SeededRandom): {mesh: MeshDefinition; tips: readonly Vec3[]} {
  const builder = new EnvironmentMeshBuilder(true);
  const leanX = random.range(-0.32, 0.32);
  const leanZ = random.range(-0.32, 0.32);
  const trunkPath: Vec3[] = [];
  const trunkRadii: number[] = [];
  const trunkWeights: number[] = [];
  for (let ring = 0; ring < config.trunkRings; ring += 1) {
    const ratio = ring / (config.trunkRings - 1);
    trunkPath.push(trunkCenter(root, ratio, leanX, leanZ));
    trunkRadii.push(0.62 * Math.pow(1 - ratio, 0.72) + 0.055);
    trunkWeights.push(Math.pow(ratio, 1.7) * 0.2);
  }
  builder.addTube(trunkPath, trunkRadii, config.trunkRadial, trunkWeights);

  const tips: Vec3[] = [];
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  for (let branch = 0; branch < config.branchCount; branch += 1) {
    const branchRatio = 0.24 + 0.64 * ((branch + random.range(0.15, 0.85)) / config.branchCount);
    const start = trunkCenter(root, branchRatio, leanX, leanZ);
    const crownShape = Math.sin(Math.PI * Math.min(1, Math.max(0, (branchRatio - 0.15) / 0.85)));
    const length = (2.0 + crownShape * 2.35) * random.range(0.82, 1.18);
    const baseAngle = branch * goldenAngle + random.range(-0.3, 0.3);
    const rise = random.range(0.22, 0.43);
    const path: Vec3[] = [];
    const radii: number[] = [];
    const weights: number[] = [];
    for (let segment = 0; segment <= config.branchSegments; segment += 1) {
      const ratio = segment / config.branchSegments;
      const angle = baseAngle + random.range(-0.05, 0.05) * ratio;
      const distance = length * ratio;
      path.push([
        start[0] + Math.cos(angle) * distance,
        start[1] + length * rise * ratio - length * 0.055 * ratio * ratio,
        start[2] + Math.sin(angle) * distance
      ]);
      radii.push((0.18 * (1 - branchRatio * 0.38)) * Math.pow(1 - ratio, 0.85) + 0.025);
      weights.push(0.08 + ratio * 0.5);
    }
    builder.addTube(path, radii, config.branchRadial, weights);
    const tip = path[path.length - 1];
    if (!tip) throw new Error('Internal branch tip invariant failed');
    tips.push(tip);

    for (let twig = 0; twig < config.twigsPerBranch; twig += 1) {
      const attachmentRatio = 0.52 + (twig + 1) / (config.twigsPerBranch + 1) * 0.34;
      const attachmentIndex = Math.min(path.length - 1, Math.max(0, Math.round(attachmentRatio * config.branchSegments)));
      const attachment = path[attachmentIndex];
      if (!attachment) throw new Error('Internal twig attachment invariant failed');
      const twigAngle = baseAngle + (twig % 2 === 0 ? 1 : -1) * random.range(0.42, 0.82);
      const twigLength = random.range(0.75, 1.35);
      const twigPath: Vec3[] = [];
      const twigRadii: number[] = [];
      const twigWeights: number[] = [];
      for (let segment = 0; segment <= config.twigSegments; segment += 1) {
        const ratio = segment / config.twigSegments;
        twigPath.push([
          attachment[0] + Math.cos(twigAngle) * twigLength * ratio,
          attachment[1] + twigLength * random.range(0.28, 0.48) * ratio,
          attachment[2] + Math.sin(twigAngle) * twigLength * ratio
        ]);
        twigRadii.push(0.065 * (1 - ratio * 0.78) + 0.012);
        twigWeights.push(0.42 + ratio * 0.38);
      }
      builder.addTube(twigPath, twigRadii, config.twigRadial, twigWeights);
      const twigTip = twigPath[twigPath.length - 1];
      if (twigTip) tips.push(twigTip);
    }
  }
  return {mesh: builder.finish(), tips};
}

function buildLeaves(config: MeadowPresetConfig, root: Vec3, tips: readonly Vec3[], random: SeededRandom): MeshDefinition {
  const builder = new EnvironmentMeshBuilder(true);
  for (let cluster = 0; cluster < config.leafClusters; cluster += 1) {
    const source = tips[cluster % tips.length] ?? add(root, [0, TREE_HEIGHT * 0.75, 0]);
    const clusterCenter: Vec3 = [
      source[0] + random.range(-0.72, 0.72),
      source[1] + random.range(-0.45, 0.65),
      source[2] + random.range(-0.72, 0.72)
    ];
    for (let card = 0; card < config.leafCards; card += 1) {
      const angle = random.range(0, Math.PI * 2) + card * Math.PI / config.leafCards;
      const up = normalized([Math.cos(angle) * random.range(-0.25, 0.25), random.range(0.82, 1.15), Math.sin(angle) * random.range(-0.25, 0.25)]);
      const side = normalized([Math.cos(angle + Math.PI / 2), random.range(-0.16, 0.16), Math.sin(angle + Math.PI / 2)]);
      const height = random.range(0.42, 0.72);
      const width = random.range(0.18, 0.34);
      const base = add(clusterCenter, multiply(up, -height * 0.46));
      const middle = add(clusterCenter, multiply(up, height * 0.03));
      const tip = add(clusterCenter, multiply(up, height * 0.54));
      builder.addQuad(base, add(middle, multiply(side, -width)), tip, add(middle, multiply(side, width)), [0, 0.72, 1, 0.72]);
    }
  }
  return builder.finish();
}

function randomFieldPosition(random: SeededRandom, center: Vec3, avoidTreeRadius: number): readonly [number, number] {
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const x = center[0] + random.range(-TERRAIN_WIDTH * 0.47, TERRAIN_WIDTH * 0.47);
    const z = center[2] + random.range(-TERRAIN_DEPTH * 0.47, TERRAIN_DEPTH * 0.47);
    if (Math.hypot(x - center[0], z - center[2]) >= avoidTreeRadius) return [x, z];
  }
  return [center[0] + avoidTreeRadius, center[2]];
}

function buildGrass(config: MeadowPresetConfig, terrain: MeshDefinition, center: Vec3, random: SeededRandom): MeshDefinition {
  const builder = new EnvironmentMeshBuilder(true);
  for (let blade = 0; blade < config.grassBlades; blade += 1) {
    const [x, z] = randomFieldPosition(random, center, 0.8);
    const y = terrainHeight(terrain, config.terrainX, config.terrainZ, center, x, z) + 0.015;
    const angle = random.range(0, Math.PI * 2);
    const side: Vec3 = [Math.cos(angle), 0, Math.sin(angle)];
    const width = random.range(0.018, 0.052);
    const height = random.range(0.28, 0.82);
    const bend: Vec3 = [random.range(-0.1, 0.1), 0, random.range(-0.1, 0.1)];
    const base: Vec3 = [x, y, z];
    const bottomLeft = add(base, multiply(side, -width));
    const bottomRight = add(base, multiply(side, width));
    const topCenter = add(base, [bend[0], height, bend[2]]);
    builder.addQuad(bottomLeft, bottomRight, add(topCenter, multiply(side, width * 0.22)), add(topCenter, multiply(side, -width * 0.22)), [0, 0, 1, 1]);
  }
  return builder.finish();
}

function buildFlowers(config: MeadowPresetConfig, terrain: MeshDefinition, center: Vec3, random: SeededRandom): MeshDefinition {
  const builder = new EnvironmentMeshBuilder(true);
  for (let flower = 0; flower < config.flowers; flower += 1) {
    const [x, z] = randomFieldPosition(random, center, 1.1);
    const ground = terrainHeight(terrain, config.terrainX, config.terrainZ, center, x, z);
    const stemHeight = random.range(0.34, 0.7);
    const flowerCenter: Vec3 = [x, ground + stemHeight, z];
    for (let petal = 0; petal < 3; petal += 1) {
      const angle = petal * Math.PI / 3 + random.range(-0.12, 0.12);
      const side: Vec3 = [Math.cos(angle), 0, Math.sin(angle)];
      const up = normalized([Math.cos(angle + Math.PI / 2) * 0.35, random.range(0.65, 0.9), Math.sin(angle + Math.PI / 2) * 0.35]);
      const height = random.range(0.16, 0.26);
      const width = random.range(0.07, 0.13);
      const base = add(flowerCenter, multiply(up, -height * 0.35));
      const middle = add(flowerCenter, multiply(up, height * 0.05));
      const tip = add(flowerCenter, multiply(up, height * 0.65));
      builder.addQuad(base, add(middle, multiply(side, -width)), tip, add(middle, multiply(side, width)), [0, 0.7, 1, 0.7]);
    }
  }
  return builder.finish();
}

function buildRocks(config: MeadowPresetConfig, terrain: MeshDefinition, center: Vec3, random: SeededRandom): MeshDefinition {
  const builder = new EnvironmentMeshBuilder(false);
  for (let rock = 0; rock < config.rocks; rock += 1) {
    const [x, z] = randomFieldPosition(random, center, 1.45);
    const ground = terrainHeight(terrain, config.terrainX, config.terrainZ, center, x, z);
    const rx = random.range(0.22, 0.72);
    const ry = random.range(0.16, 0.48);
    const rz = random.range(0.24, 0.75);
    const rockCenter: Vec3 = [x, ground + ry, z];
    const start = builder.vertexCount;
    builder.addVertex([x, ground + ry * 2, z], [0, 1, 0]);
    const irregularities: number[] = [];
    for (let segment = 0; segment < config.rockRadial; segment += 1) irregularities.push(random.range(0.82, 1.18));
    for (const latitude of [0.28, -0.28]) {
      const radialScale = Math.sqrt(1 - latitude * latitude);
      for (let segment = 0; segment < config.rockRadial; segment += 1) {
        const angle = Math.PI * 2 * segment / config.rockRadial + random.range(-0.035, 0.035);
        const irregularity = irregularities[segment] ?? 1;
        const local: Vec3 = [Math.cos(angle) * rx * radialScale * irregularity, latitude * ry, Math.sin(angle) * rz * radialScale * irregularity];
        builder.addVertex(add(rockCenter, local), normalized([local[0] / (rx * rx), local[1] / (ry * ry), local[2] / (rz * rz)]));
      }
    }
    const bottom = builder.addVertex([x, ground, z], [0, -1, 0]);
    const upper = start + 1;
    const lower = upper + config.rockRadial;
    for (let segment = 0; segment < config.rockRadial; segment += 1) {
      const next = (segment + 1) % config.rockRadial;
      const a = upper + segment;
      const b = upper + next;
      const c = lower + segment;
      const d = lower + next;
      builder.addTriangle(start, b, a);
      builder.addTriangle(a, b, c);
      builder.addTriangle(b, d, c);
      builder.addTriangle(bottom, c, d);
    }
  }
  return builder.finish();
}

function materials(): readonly EnvironmentMaterialDefinition[] {
  const definitions: Readonly<Record<string, MaterialDefinition>> = {
    ground: {baseColor: [0.18, 0.34, 0.075], roughness: 0.96, metallic: 0, surfaceDetail: 'ground', colorVariation: 0.42, detailScale: 2.4, windInfluence: 0},
    bark: {baseColor: [0.19, 0.082, 0.03], roughness: 0.88, metallic: 0, surfaceDetail: 'bark', colorVariation: 0.32, detailScale: 8, windInfluence: 0.18},
    leaves: {baseColor: [0.065, 0.3, 0.035], roughness: 0.72, metallic: 0, transmission: 0.06, doubleSided: true, surfaceDetail: 'foliage', colorVariation: 0.5, detailScale: 18, windInfluence: 1},
    grass: {baseColor: [0.105, 0.39, 0.045], roughness: 0.84, metallic: 0, doubleSided: true, surfaceDetail: 'grass', colorVariation: 0.38, detailScale: 26, windInfluence: 0.88},
    flowers: {baseColor: [0.78, 0.18, 0.38], roughness: 0.67, metallic: 0, doubleSided: true, surfaceDetail: 'foliage', colorVariation: 0.58, detailScale: 31, windInfluence: 0.76},
    rock: {baseColor: [0.34, 0.35, 0.31], roughness: 0.9, metallic: 0, surfaceDetail: 'standard', colorVariation: 0.24, detailScale: 7, windInfluence: 0}
  };
  return (Object.entries(definitions) as Array<[EnvironmentMaterialDefinition['name'], MaterialDefinition]>).map(([name, definition]) => ({name, definition}));
}

function meshComplexity(mesh: MeshDefinition): ModelComplexity {
  const nested = typeof (mesh.positions as ArrayLike<unknown>)[0] !== 'number';
  return {
    vertexCount: nested ? mesh.positions.length : mesh.positions.length / 3,
    triangleCount: mesh.indices.length / 3
  };
}

export function buildMeadowEnvironment(options: MeadowEnvironmentOptions = {}): MeadowEnvironmentBundle {
  const preset = options.preset ?? 'realtime';
  const plan = planMeadowEnvironment(preset);
  const config = MEADOW_PRESETS[preset];
  const seed = options.seed ?? 'prio-meadow';
  const center = options.center ?? [0, 0, 0];
  if (center.length !== 3 || center.some((component) => !Number.isFinite(component))) throw new RangeError('environment center must contain three finite components');
  const rootRandom = new SeededRandom(seed);
  const terrain = createFractalTerrain({
    width: TERRAIN_WIDTH,
    depth: TERRAIN_DEPTH,
    xSegments: config.terrainX,
    zSegments: config.terrainZ,
    center,
    seed: `${String(seed)}:terrain`,
    heightScale: 1.15,
    baseHeight: 1.45,
    frequency: 2.2,
    octaves: preset === 'preview' ? 4 : 6,
    persistence: 0.52,
    lacunarity: 2.05,
    budget: 'cinematic'
  });
  const root: Vec3 = [center[0], terrainHeight(terrain, config.terrainX, config.terrainZ, center, center[0], center[2]), center[2]];
  const tree = buildTree(config, root, rootRandom.fork('tree'));
  const leaves = buildLeaves(config, root, tree.tips, rootRandom.fork('leaves'));
  const grass = buildGrass(config, terrain, center, rootRandom.fork('grass'));
  const flowers = buildFlowers(config, terrain, center, rootRandom.fork('flowers'));
  const rocks = buildRocks(config, terrain, center, rootRandom.fork('rocks'));
  const batches: readonly EnvironmentMeshBatch[] = [
    {name: 'rolling-terrain', material: 'ground', mesh: terrain},
    {name: 'hero-tree', material: 'bark', mesh: tree.mesh},
    {name: 'leaf-canopy', material: 'leaves', mesh: leaves},
    {name: 'meadow-grass', material: 'grass', mesh: grass},
    {name: 'wildflowers', material: 'flowers', mesh: flowers},
    {name: 'field-rocks', material: 'rock', mesh: rocks}
  ];
  const actualBreakdown: MeadowTriangleBreakdown = {
    terrain: meshComplexity(terrain).triangleCount,
    tree: meshComplexity(tree.mesh).triangleCount,
    leaves: meshComplexity(leaves).triangleCount,
    grass: meshComplexity(grass).triangleCount,
    flowers: meshComplexity(flowers).triangleCount,
    rocks: meshComplexity(rocks).triangleCount
  };
  const actualTriangles = Object.values(actualBreakdown).reduce((sum, value) => sum + value, 0);
  if (actualTriangles !== plan.totalTriangles) throw new Error(`Environment topology mismatch: planned ${plan.totalTriangles}, built ${actualTriangles}`);
  let vertexCount = 0;
  let estimatedMeshBytes = 0;
  for (const batch of batches) {
    const complexity = meshComplexity(batch.mesh);
    vertexCount += complexity.vertexCount;
    estimatedMeshBytes += estimateMeshCpuBytes(complexity, true, batch.mesh.windWeights !== undefined);
  }

  const camera: CameraSettings = {
    position: [center[0] + 11.5, center[1] + 3.1, center[2] + 15.5],
    target: [center[0], center[1] + 4.2, center[2]],
    verticalFovDegrees: 56
  };
  const wind: AmbientWindSettings = {enabled: true, strength: 0.24, speed: 0.88, directionDegrees: 32, turbulence: 0.52};
  const lights: readonly LightDefinition[] = [
    {type: 'directional', direction: normalized([-0.48, -0.78, 0.39]), color: [1, 0.78, 0.56], intensity: 4.8, angularRadius: 0.012, castShadow: true},
    {type: 'point', position: [center[0] - 12, center[1] + 9, center[2] + 10], color: [0.42, 0.58, 1], intensity: 34, range: 32, radius: 5, castShadow: false}
  ];
  return {
    kind: 'true-life-meadow',
    preset,
    seed,
    camera,
    wind,
    navigation: {
      moveSpeed: 5.2,
      sprintMultiplier: 2.1,
      lookSensitivity: 0.13,
      eyeHeight: 1.72,
      minimum: [center[0] - TERRAIN_WIDTH * 0.49, center[1] - 1.5, center[2] - TERRAIN_DEPTH * 0.49],
      maximum: [center[0] + TERRAIN_WIDTH * 0.49, center[1] + 16, center[2] + TERRAIN_DEPTH * 0.49]
    },
    materials: materials(),
    batches,
    lights,
    stats: {
      batchCount: batches.length,
      materialCount: materials().length,
      vertexCount,
      triangleCount: actualTriangles,
      estimatedMeshBytes,
      triangles: actualBreakdown
    }
  };
}
