import type {Vec3} from '../scene';
import {resolveModelBudget} from './budget';
import type {
  CloudDensityVolume,
  CloudDensityVolumeOptions,
  CloudVolumeProfile,
  ModelDetailBudgetInput
} from './types';

const MAX_AXIS_RESOLUTION = 512;
const MAX_OCTAVES = 8;

type Resolution = readonly [number, number, number];

function finite(value: number, label: string): number {
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value))) {
    throw new RangeError(`${label} must be a finite 32-bit number`);
  }
  return value;
}

function finiteInRange(value: number, minimum: number, maximum: number, label: string): number {
  finite(value, label);
  if (value < minimum || value > maximum) {
    throw new RangeError(`${label} must be from ${minimum} through ${maximum}`);
  }
  return value;
}

function positive(value: number, label: string): number {
  finite(value, label);
  if (value <= 0) throw new RangeError(`${label} must be greater than zero`);
  return value;
}

function finiteVec3(value: Vec3, label: string, positiveOnly = false): Vec3 {
  if (!value || value.length !== 3) throw new TypeError(`${label} must contain exactly three components`);
  return [
    positiveOnly ? positive(value[0], `${label}[0]`) : finite(value[0], `${label}[0]`),
    positiveOnly ? positive(value[1], `${label}[1]`) : finite(value[1], `${label}[1]`),
    positiveOnly ? positive(value[2], `${label}[2]`) : finite(value[2], `${label}[2]`)
  ];
}

function color(value: Vec3, label: string): Vec3 {
  const result = finiteVec3(value, label);
  return [
    finiteInRange(result[0], 0, 1, `${label}[0]`),
    finiteInRange(result[1], 0, 1, `${label}[1]`),
    finiteInRange(result[2], 0, 1, `${label}[2]`)
  ];
}

function integer(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be an integer from ${minimum} through ${maximum}`);
  }
  return value;
}

function resolution(value: Resolution | undefined): Resolution {
  const input = value ?? [64, 32, 64];
  if (!input || input.length !== 3) throw new TypeError('cloud.resolution must contain exactly three components');
  return [
    integer(input[0], 2, MAX_AXIS_RESOLUTION, 'cloud.resolution[0]'),
    integer(input[1], 2, MAX_AXIS_RESOLUTION, 'cloud.resolution[1]'),
    integer(input[2], 2, MAX_AXIS_RESOLUTION, 'cloud.resolution[2]')
  ];
}

function voxelCount(value: Resolution): number {
  const count = value[0] * value[1] * value[2];
  if (!Number.isSafeInteger(count)) throw new RangeError('cloud voxel count exceeds the safe integer range');
  return count;
}

function fitResolution(requested: Resolution, budgetInput: ModelDetailBudgetInput, overflow: 'error' | 'fit'): Resolution {
  const byteBudget = resolveModelBudget(budgetInput).maxSourceBytes;
  const requestedCount = voxelCount(requested);
  if (requestedCount <= byteBudget) return requested;
  if (overflow === 'error') {
    throw new RangeError(`cloud volume requires ${requestedCount} bytes, exceeding the budget of ${byteBudget}`);
  }
  const scale = Math.cbrt(byteBudget / requestedCount);
  const fitted: [number, number, number] = [
    Math.max(2, Math.floor(requested[0] * scale)),
    Math.max(2, Math.floor(requested[1] * scale)),
    Math.max(2, Math.floor(requested[2] * scale))
  ];
  while (voxelCount(fitted) > byteBudget) {
    let axis: 0 | 1 | 2 = 0;
    if (fitted[1] / requested[1] > fitted[axis] / requested[axis]) axis = 1;
    if (fitted[2] / requested[2] > fitted[axis] / requested[axis]) axis = 2;
    if ((fitted[axis] ?? 0) <= 2) {
      const available = fitted.findIndex((component) => component > 2);
      if (available < 0) throw new RangeError('cloud budget cannot fit the minimum 2 by 2 by 2 density volume');
      axis = available as 0 | 1 | 2;
    }
    fitted[axis] = (fitted[axis] ?? 2) - 1;
  }
  return fitted;
}

function hashSeed(seed: number | string): number {
  if (typeof seed === 'number') {
    if (!Number.isFinite(seed)) throw new RangeError('cloud.seed must be finite');
    return (Math.trunc(seed) >>> 0) || 0x9e3779b9;
  }
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function lattice(seed: number, x: number, y: number, z: number): number {
  let hash = seed
    ^ Math.imul(x, 0x1f123bb5)
    ^ Math.imul(y, 0x6c8e9cf5)
    ^ Math.imul(z, 0x5f356495);
  hash = Math.imul(hash ^ (hash >>> 16), 0x7feb352d);
  hash = Math.imul(hash ^ (hash >>> 15), 0x846ca68b);
  hash ^= hash >>> 16;
  return (hash >>> 0) / 0xffff_ffff;
}

function smootherStep(value: number): number {
  return value * value * value * (value * (value * 6 - 15) + 10);
}

function mix(a: number, b: number, amount: number): number {
  return a + (b - a) * amount;
}

function clamp01(value: number): number {
  return Math.max(0, Math.min(1, value));
}

function smoothstep(edge0: number, edge1: number, value: number): number {
  const ratio = clamp01((value - edge0) / (edge1 - edge0));
  return ratio * ratio * (3 - 2 * ratio);
}

function valueNoise3(seed: number, x: number, y: number, z: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const z0 = Math.floor(z);
  const tx = smootherStep(x - x0);
  const ty = smootherStep(y - y0);
  const tz = smootherStep(z - z0);
  const z00 = mix(lattice(seed, x0, y0, z0), lattice(seed, x0 + 1, y0, z0), tx);
  const z10 = mix(lattice(seed, x0, y0 + 1, z0), lattice(seed, x0 + 1, y0 + 1, z0), tx);
  const z01 = mix(lattice(seed, x0, y0, z0 + 1), lattice(seed, x0 + 1, y0, z0 + 1), tx);
  const z11 = mix(lattice(seed, x0, y0 + 1, z0 + 1), lattice(seed, x0 + 1, y0 + 1, z0 + 1), tx);
  return mix(mix(z00, z10, ty), mix(z01, z11, ty), tz);
}

function fractalNoise(
  seed: number,
  x: number,
  y: number,
  z: number,
  octaves: number,
  persistence: number,
  lacunarity: number
): number {
  let amplitude = 1;
  let frequency = 1;
  let total = 0;
  let normalization = 0;
  for (let octave = 0; octave < octaves; octave += 1) {
    total += valueNoise3((seed + Math.imul(octave, 0x9e3779b9)) >>> 0, x * frequency, y * frequency, z * frequency) * amplitude;
    normalization += amplitude;
    amplitude *= persistence;
    frequency *= lacunarity;
  }
  return normalization === 0 ? 0 : total / normalization;
}

function profileEnvelope(profile: CloudVolumeProfile, x: number, y: number, z: number, edgeFade: number): number {
  const horizontalEdgeDistance = Math.min(x, 1 - x, z, 1 - z);
  const horizontal = edgeFade === 0 ? 1 : smoothstep(0, edgeFade, horizontalEdgeDistance);
  if (profile === 'stratus') {
    return horizontal * smoothstep(0.02, 0.18, y) * (1 - smoothstep(0.72, 0.98, y));
  }
  if (profile === 'cirrus') {
    const verticalDistance = (y - 0.62) / 0.19;
    const thinLayer = Math.exp(-verticalDistance * verticalDistance);
    return horizontal * thinLayer;
  }
  const risingBase = smoothstep(0.015, 0.16, y);
  const softAnvil = 1 - smoothstep(0.58, 0.99, y);
  return horizontal * risingBase * softAnvil;
}

function profileSignal(
  profile: CloudVolumeProfile,
  seed: number,
  x: number,
  y: number,
  z: number,
  baseFrequency: number,
  octaves: number
): number {
  const verticalFrequency = profile === 'stratus' ? 0.65 : profile === 'cirrus' ? 0.42 : 1.25;
  const primary = fractalNoise(seed, x * baseFrequency, y * baseFrequency * verticalFrequency, z * baseFrequency, octaves, 0.52, 2.03);
  const weather = fractalNoise(seed ^ 0xa511e9b3, x * 1.35, 0.37, z * 1.35, 2, 0.58, 2);
  if (profile === 'cirrus') {
    const warp = fractalNoise(seed ^ 0x63d83595, x * 2.1, y * 0.5, z * 2.1, 2, 0.5, 2);
    const streak = 0.5 + 0.5 * Math.sin((x * 1.8 + z * 7.2 + warp * 1.9) * Math.PI * 2);
    return primary * 0.43 + weather * 0.22 + streak * 0.35;
  }
  return primary * (profile === 'stratus' ? 0.52 : 0.7) + weather * (profile === 'stratus' ? 0.48 : 0.3);
}

function validateProfile(value: CloudVolumeProfile | undefined): CloudVolumeProfile {
  const profile = value ?? 'cumulus';
  if (profile !== 'cumulus' && profile !== 'stratus' && profile !== 'cirrus') {
    throw new RangeError(`Unknown cloud volume profile: ${String(profile)}`);
  }
  return profile;
}

/**
 * Builds a deterministic, tightly packed cloud density field ready for a WebGPU
 * `r8unorm` 3D texture or a CPU volume integrator. It stores only physical
 * density; lighting remains view- and light-dependent at render time.
 */
export function createCloudDensityVolume(options: CloudDensityVolumeOptions = {}): CloudDensityVolume {
  if (!options || typeof options !== 'object') throw new TypeError('cloud options must be an object');
  const requestedResolution = resolution(options.resolution);
  const actualResolution = fitResolution(requestedResolution, options.budget ?? 'cinematic', options.overflow ?? 'error');
  const size = finiteVec3(options.size ?? [18, 6, 12], 'cloud.size', true);
  const center = finiteVec3(options.center ?? [0, 0, 0], 'cloud.center');
  const profile = validateProfile(options.profile);
  const coverage = finiteInRange(options.coverage ?? 0.56, 0, 1, 'cloud.coverage');
  const densityScale = finiteInRange(options.densityScale ?? 1, 0, 64, 'cloud.densityScale');
  const baseFrequency = finiteInRange(options.baseFrequency ?? (profile === 'stratus' ? 1.8 : profile === 'cirrus' ? 3.6 : 2.7), 0.05, 128, 'cloud.baseFrequency');
  const octaves = integer(options.octaves ?? 5, 1, MAX_OCTAVES, 'cloud.octaves');
  const erosion = finiteInRange(options.erosion ?? 0.42, 0, 1, 'cloud.erosion');
  const edgeFade = finiteInRange(options.edgeFade ?? 0.08, 0, 0.5, 'cloud.edgeFade');
  const scatteringAlbedo = color(options.scatteringAlbedo ?? [0.999, 0.997, 0.99], 'cloud.scatteringAlbedo');
  const extinction = finiteInRange(options.extinction ?? 0.35, 0, 1_000, 'cloud.extinction');
  const anisotropy = finiteInRange(options.anisotropy ?? 0.72, -0.95, 0.95, 'cloud.anisotropy');
  const seed = hashSeed(options.seed ?? 1);
  const [width, height, depth] = actualResolution;
  const values = new Uint8Array(voxelCount(actualResolution));
  const threshold = 0.84 - coverage * 0.6;
  const thresholdWidth = Math.max(0.08, 1 - threshold);
  let occupiedVoxelCount = 0;
  let densitySum = 0;
  let maximumDensity = 0;

  for (let zIndex = 0; zIndex < depth; zIndex += 1) {
    const z = zIndex / (depth - 1);
    for (let yIndex = 0; yIndex < height; yIndex += 1) {
      const y = yIndex / (height - 1);
      for (let xIndex = 0; xIndex < width; xIndex += 1) {
        const x = xIndex / (width - 1);
        const envelope = profileEnvelope(profile, x, y, z, edgeFade);
        const signal = profileSignal(profile, seed, x, y, z, baseFrequency, octaves);
        const shaped = clamp01((signal - threshold) / thresholdWidth) * envelope;
        const detail = fractalNoise(
          seed ^ 0xc2b2ae35,
          x * baseFrequency * 5.3,
          y * baseFrequency * 3.7,
          z * baseFrequency * 5.3,
          Math.min(4, Math.max(2, octaves - 1)),
          0.57,
          2.11
        );
        const eroded = shaped * mix(1, smoothstep(0.13, 0.88, detail), erosion * (1 - shaped * 0.38));
        const normalizedDensity = clamp01(eroded);
        const encoded = Math.round(normalizedDensity * 255);
        const index = xIndex + width * (yIndex + height * zIndex);
        values[index] = encoded;
        if (encoded > 0) occupiedVoxelCount += 1;
        densitySum += encoded / 255;
        maximumDensity = Math.max(maximumDensity, encoded / 255);
      }
    }
  }

  const minimum: Vec3 = [center[0] - size[0] * 0.5, center[1] - size[1] * 0.5, center[2] - size[2] * 0.5];
  const maximum: Vec3 = [center[0] + size[0] * 0.5, center[1] + size[1] * 0.5, center[2] + size[2] * 0.5];
  return {
    kind: 'cloud-density-volume',
    format: 'r8unorm',
    axisOrder: 'x-y-z',
    profile,
    center,
    size,
    minimum,
    maximum,
    requestedResolution,
    resolution: actualResolution,
    density: values,
    densityScale,
    scatteringAlbedo,
    extinction,
    anisotropy,
    stats: {
      voxelCount: values.length,
      occupiedVoxelCount,
      meanNormalizedDensity: densitySum / values.length,
      maximumNormalizedDensity: maximumDensity,
      byteLength: values.byteLength,
      reduced: actualResolution[0] !== requestedResolution[0]
        || actualResolution[1] !== requestedResolution[1]
        || actualResolution[2] !== requestedResolution[2]
    }
  };
}

function sampleVoxel(volume: CloudDensityVolume, x: number, y: number, z: number): number {
  const [width, height] = volume.resolution;
  return (volume.density[x + width * (y + height * z)] ?? 0) / 255 * volume.densityScale;
}

/** Trilinearly samples decoded density at a world-space position. */
export function sampleCloudDensityVolume(volume: CloudDensityVolume, position: Vec3): number {
  if (!volume || volume.kind !== 'cloud-density-volume') throw new TypeError('volume must be a cloud density volume');
  const point = finiteVec3(position, 'cloud sample position');
  for (let axis = 0; axis < 3; axis += 1) {
    if ((point[axis] ?? 0) < (volume.minimum[axis] ?? 0) || (point[axis] ?? 0) > (volume.maximum[axis] ?? 0)) return 0;
  }
  const coordinates: [number, number, number] = [0, 0, 0];
  for (let axis = 0; axis < 3; axis += 1) {
    coordinates[axis] = ((point[axis] ?? 0) - (volume.minimum[axis] ?? 0))
      / ((volume.maximum[axis] ?? 0) - (volume.minimum[axis] ?? 0))
      * ((volume.resolution[axis] ?? 2) - 1);
  }
  const x0 = Math.floor(coordinates[0]);
  const y0 = Math.floor(coordinates[1]);
  const z0 = Math.floor(coordinates[2]);
  const x1 = Math.min(volume.resolution[0] - 1, x0 + 1);
  const y1 = Math.min(volume.resolution[1] - 1, y0 + 1);
  const z1 = Math.min(volume.resolution[2] - 1, z0 + 1);
  const tx = coordinates[0] - x0;
  const ty = coordinates[1] - y0;
  const tz = coordinates[2] - z0;
  const z00 = mix(sampleVoxel(volume, x0, y0, z0), sampleVoxel(volume, x1, y0, z0), tx);
  const z10 = mix(sampleVoxel(volume, x0, y1, z0), sampleVoxel(volume, x1, y1, z0), tx);
  const z01 = mix(sampleVoxel(volume, x0, y0, z1), sampleVoxel(volume, x1, y0, z1), tx);
  const z11 = mix(sampleVoxel(volume, x0, y1, z1), sampleVoxel(volume, x1, y1, z1), tx);
  return mix(mix(z00, z10, ty), mix(z01, z11, ty), tz);
}
