import {assertPostExtent, clampNumber} from './shared';

export type LearnedEnhancementMode = 'off' | 'same-resolution' | 'reconstruct-2x';
export type LearnedEnhancementPreset =
  | 'balanced'
  | 'photoreal-detail'
  | 'artifact-cleanup';
export type LearnedEnhancementRgb = readonly [number, number, number];
export type LearnedEnhancementNormal = readonly [number, number, number];

export interface LearnedEnhancementTap {
  readonly radiance: LearnedEnhancementRgb;
  readonly depth: number;
  readonly normal: LearnedEnhancementNormal;
  readonly albedo: LearnedEnhancementRgb;
  readonly roughness: number;
}

export interface LearnedEnhancementNeighborhood {
  readonly taps: readonly LearnedEnhancementTap[];
  readonly fallbackTaps?: readonly LearnedEnhancementTap[];
  readonly noiseEstimate: number;
  readonly confidence: number;
}

export interface LearnedEnhancementSettings {
  readonly strength: number;
  readonly cleanNoiseThreshold: number;
  readonly fullNoiseThreshold: number;
  readonly depthSigma: number;
  readonly normalExponent: number;
  readonly albedoSigma: number;
  readonly roughnessSigma: number;
  readonly minimumConfidence: number;
  readonly fullConfidence: number;
  readonly minimumRoughness: number;
  readonly fullRoughness: number;
  readonly residualLimit: number;
  readonly minimumSupport: number;
  readonly maximumRadiance: number;
  readonly accumulatedSamples: number;
}

export interface LearnedEnhancementExtent {
  readonly sourceWidth: number;
  readonly sourceHeight: number;
  readonly outputWidth: number;
  readonly outputHeight: number;
  readonly scale: 1 | 2;
}

export interface LearnedEnhancementMetrics {
  readonly mse: number;
  readonly psnr: number;
}

