import type {MeshDefinition, Vec3} from '../scene';
import {assertWithinModelBudget, resolveModelBudget} from './budget';
import {calculateSmoothNormals} from './normals';
import type {BudgetOverflowMode, ModelDetailBudget, ModelDetailBudgetInput, ModelComplexity} from './types';

const MAX_REQUESTED_SEGMENTS = 1_000_000;
const MAX_FOLD_FREQUENCY = 1_000_000;

export interface FabricEdgeDrape {
  /** Drop at the negative-X edge, in model units. */
  readonly left?: number;
  /** Drop at the positive-X edge, in model units. */
  readonly right?: number;
  /** Drop at the positive-Z edge, in model units. */
  readonly front?: number;
  /** Drop at the negative-Z edge, in model units. */
  readonly back?: number;
}

export interface GenerateFabricMeshOptions {
  readonly width?: number;
  readonly depth?: number;
  readonly center?: Vec3;
  /** X subdivisions. Mutually exclusive with targetTriangles. */
  readonly segmentsX?: number;
  /** Z subdivisions. Mutually exclusive with targetTriangles. */
  readonly segmentsZ?: number;
  /** Approximate triangle ceiling used to derive aspect-correct subdivisions. */
  readonly targetTriangles?: number;
  /** Maximum displacement contributed by layered folds, in model units. */
  readonly foldAmplitude?: number;
  /** Spatial frequency of the broad fold field. */
  readonly foldFrequency?: number;
  /** Uniform edge drop or independently controlled edge drops. */
  readonly drape?: number | FabricEdgeDrape;
  /** Optional solid-cloth extrusion. Zero keeps a single two-sided surface. */
  readonly thickness?: number;
  readonly seed?: number | string;
  readonly budget?: ModelDetailBudgetInput;
  readonly overflow?: BudgetOverflowMode;
}

export interface GeneratedFabricMesh extends MeshDefinition {
  readonly positions: Float32Array;
  readonly indices: Uint32Array;
  readonly normals: Float32Array;
  /** Per-vertex UVs spanning the full fabric surface. */
  readonly uvs: Float32Array;
  readonly segmentsX: number;
  readonly segmentsZ: number;
  readonly reduced: boolean;
  readonly thickness: number;
}

interface FabricPlan extends ModelComplexity {
  readonly segmentsX: number;
  readonly segmentsZ: number;
  readonly reduced: boolean;
}

interface ResolvedDrape {
  readonly left: number;
  readonly right: number;
  readonly front: number;
  readonly back: number;
}

interface EdgeBendSample {
  readonly coordinate: number;
  readonly drop: number;
  readonly weight: number;
  readonly sign: -1 | 0 | 1;
}

interface FabricSurfaceSample {
  readonly x: number;
  readonly y: number;
  readonly z: number;
}

function finiteFloat32(value: number, label: string): number {
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value))) {
    throw new RangeError(`${label} must be a finite 32-bit number`);
  }
  return value;
}

function positiveFloat32(value: number, label: string): number {
  finiteFloat32(value, label);
  if (value <= 0 || Math.fround(value) <= 0) throw new RangeError(`${label} must be greater than zero`);
  return value;
}

function nonNegativeFloat32(value: number, label: string): number {
  finiteFloat32(value, label);
  if (value < 0) throw new RangeError(`${label} must be non-negative`);
  return value;
}

function boundedInteger(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be an integer from ${minimum} through ${maximum}`);
  }
  return value;
}

function resolveCenter(value: Vec3 | undefined): Vec3 {
  const center = value ?? [0, 0, 0];
  if (center.length !== 3) throw new TypeError('fabric.center must have exactly three components');
  return [
    finiteFloat32(center[0], 'fabric.center[0]'),
    finiteFloat32(center[1], 'fabric.center[1]'),
    finiteFloat32(center[2], 'fabric.center[2]')
  ];
}

function resolveDrape(value: number | FabricEdgeDrape | undefined, width: number, depth: number): ResolvedDrape {
  const defaultDrop = Math.min(width, depth) * 0.07;
  if (value === undefined) {
    return {left: defaultDrop, right: defaultDrop, front: defaultDrop * 1.35, back: defaultDrop * 0.55};
  }
  if (typeof value === 'number') {
    const drop = nonNegativeFloat32(value, 'fabric.drape');
    return {left: drop, right: drop, front: drop, back: drop};
  }
  if (!value || typeof value !== 'object') throw new TypeError('fabric.drape must be a number or edge-drape object');
  return {
    left: nonNegativeFloat32(value.left ?? 0, 'fabric.drape.left'),
    right: nonNegativeFloat32(value.right ?? 0, 'fabric.drape.right'),
    front: nonNegativeFloat32(value.front ?? 0, 'fabric.drape.front'),
    back: nonNegativeFloat32(value.back ?? 0, 'fabric.drape.back')
  };
}

function fabricComplexity(segmentsX: number, segmentsZ: number, solid: boolean): ModelComplexity {
  const gridVertices = (segmentsX + 1) * (segmentsZ + 1);
  if (!solid) return {vertexCount: gridVertices, triangleCount: segmentsX * segmentsZ * 2};
  return {
    vertexCount: gridVertices * 2,
    triangleCount: segmentsX * segmentsZ * 4 + (segmentsX + segmentsZ) * 4
  };
}

function fits(segmentsX: number, segmentsZ: number, solid: boolean, budget: ModelDetailBudget): boolean {
  const complexity = fabricComplexity(segmentsX, segmentsZ, solid);
  return complexity.vertexCount <= budget.maxVertices && complexity.triangleCount <= budget.maxTriangles;
}

function fitRequestedSegments(
  requestedX: number,
  requestedZ: number,
  solid: boolean,
  budget: ModelDetailBudget,
  overflow: BudgetOverflowMode
): FabricPlan {
  const requested = fabricComplexity(requestedX, requestedZ, solid);
  if (requested.vertexCount <= budget.maxVertices && requested.triangleCount <= budget.maxTriangles) {
    return {segmentsX: requestedX, segmentsZ: requestedZ, reduced: false, ...requested};
  }
  if (overflow === 'error') {
    assertWithinModelBudget(requested, budget, 'fabric mesh');
  }

  const triangleScale = Math.sqrt(budget.maxTriangles / Math.max(requested.triangleCount, 1));
  const vertexScale = Math.sqrt(budget.maxVertices / Math.max(requested.vertexCount, 1));
  const scale = Math.min(1, triangleScale, vertexScale);
  let segmentsX = Math.max(1, Math.floor(requestedX * scale));
  let segmentsZ = Math.max(1, Math.floor(requestedZ * scale));
  while (!fits(segmentsX, segmentsZ, solid, budget)) {
    const xRatio = segmentsX / requestedX;
    const zRatio = segmentsZ / requestedZ;
    if (segmentsX > 1 && (xRatio >= zRatio || segmentsZ === 1)) segmentsX -= 1;
    else if (segmentsZ > 1) segmentsZ -= 1;
    else throw new RangeError('fabric mesh budget cannot fit the minimum supported detail');
  }
  return {segmentsX, segmentsZ, reduced: true, ...fabricComplexity(segmentsX, segmentsZ, solid)};
}

function deriveTargetSegments(
  targetTriangles: number,
  width: number,
  depth: number,
  solid: boolean,
  budget: ModelDetailBudget,
  overflow: BudgetOverflowMode
): FabricPlan {
  const minimumTriangles = solid ? 12 : 2;
  const requestedTarget = boundedInteger(targetTriangles, minimumTriangles, Number.MAX_SAFE_INTEGER, 'fabric.targetTriangles');
  if (requestedTarget > budget.maxTriangles && overflow === 'error') {
    throw new RangeError(`fabric mesh target of ${requestedTarget} triangles exceeds the budget of ${budget.maxTriangles}`);
  }
  const target = Math.min(requestedTarget, budget.maxTriangles);
  const aspect = Math.max(1e-12, Math.min(1e12, width / depth));
  let segmentsX: number;
  let segmentsZ: number;
  if (solid) {
    const maximumGridProduct = Math.max(4, Math.floor(target / 4) + 1);
    const columns = Math.max(2, Math.min(Math.floor(maximumGridProduct / 2), Math.floor(Math.sqrt(maximumGridProduct * aspect))));
    const rows = Math.max(2, Math.floor(maximumGridProduct / columns));
    segmentsX = columns - 1;
    segmentsZ = rows - 1;
  } else {
    const maximumCells = Math.max(1, Math.floor(target / 2));
    segmentsX = Math.max(1, Math.min(maximumCells, Math.floor(Math.sqrt(maximumCells * aspect))));
    segmentsZ = Math.max(1, Math.floor(maximumCells / segmentsX));
  }

  const targetBudget: ModelDetailBudget = {...budget, maxTriangles: target};
  while (!fits(segmentsX, segmentsZ, solid, targetBudget)) {
    const currentAspect = segmentsX / segmentsZ;
    if (segmentsX > 1 && (currentAspect >= aspect || segmentsZ === 1)) segmentsX -= 1;
    else if (segmentsZ > 1) segmentsZ -= 1;
    else throw new RangeError('fabric target cannot fit the minimum supported detail');
  }

  while (true) {
    const xCandidateFits = fits(segmentsX + 1, segmentsZ, solid, targetBudget);
    const zCandidateFits = fits(segmentsX, segmentsZ + 1, solid, targetBudget);
    if (!xCandidateFits && !zCandidateFits) break;
    if (xCandidateFits && zCandidateFits) {
      const xAspectError = Math.abs((segmentsX + 1) / segmentsZ - aspect);
      const zAspectError = Math.abs(segmentsX / (segmentsZ + 1) - aspect);
      if (xAspectError <= zAspectError) segmentsX += 1;
      else segmentsZ += 1;
    } else if (xCandidateFits) segmentsX += 1;
    else segmentsZ += 1;
  }

  const complexity = fabricComplexity(segmentsX, segmentsZ, solid);
  return {
    segmentsX,
    segmentsZ,
    reduced: complexity.triangleCount < requestedTarget,
    ...complexity
  };
}

function hashSeed(seed: number | string): number {
  if (typeof seed === 'number') {
    if (!Number.isFinite(seed)) throw new RangeError('fabric.seed must be finite');
    return (Math.trunc(seed) >>> 0) || 0x9e3779b9;
  }
  if (typeof seed !== 'string') throw new TypeError('fabric.seed must be a number or string');
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function lattice(seed: number, x: number, z: number): number {
  let hash = seed ^ Math.imul(x, 0x1f123bb5) ^ Math.imul(z, 0x5f356495);
  hash = Math.imul(hash ^ (hash >>> 16), 0x7feb352d);
  hash = Math.imul(hash ^ (hash >>> 15), 0x846ca68b);
  hash ^= hash >>> 16;
  return (hash >>> 0) / 0xffffffff * 2 - 1;
}

function smootherStep(value: number): number {
  const clamped = Math.max(0, Math.min(1, value));
  return clamped * clamped * clamped * (clamped * (clamped * 6 - 15) + 10);
}

function valueNoise(seed: number, x: number, z: number): number {
  const x0 = Math.floor(x);
  const z0 = Math.floor(z);
  const tx = smootherStep(x - x0);
  const tz = smootherStep(z - z0);
  const a = lattice(seed, x0, z0);
  const b = lattice(seed, x0 + 1, z0);
  const c = lattice(seed, x0, z0 + 1);
  const d = lattice(seed, x0 + 1, z0 + 1);
  const top = a + (b - a) * tx;
  const bottom = c + (d - c) * tx;
  return top + (bottom - top) * tz;
}

function fractalNoise(seed: number, x: number, z: number): number {
  let total = 0;
  let amplitude = 1;
  let normalization = 0;
  let frequency = 1;
  for (let octave = 0; octave < 4; octave += 1) {
    total += valueNoise((seed + Math.imul(octave, 0x9e3779b9)) >>> 0, x * frequency, z * frequency) * amplitude;
    normalization += amplitude;
    amplitude *= 0.52;
    frequency *= 2.07;
  }
  return total / normalization;
}

function normalizedCatenary(value: number): number {
  const shape = 2.35;
  return (Math.cosh(shape * value) - 1) / (Math.cosh(shape) - 1);
}

function bendAngle(value: number): number {
  // Matches the flat tangent at the support, then turns continuously through
  // ninety degrees at the hanging hem.
  return value + (Math.PI * 0.5 - 1) * (value * value * (3 - 2 * value));
}

function sampleEdgeBend(
  ratio: number,
  extent: number,
  drop: number,
  positiveEdge: boolean
): EdgeBendSample {
  const baseCoordinate = (ratio - 0.5) * extent;
  if (drop <= 0) return {coordinate: baseCoordinate, drop: 0, weight: 0, sign: 0};
  const band = Math.min(
    extent * 0.28,
    Math.max(extent * 0.075, Math.min(drop * 0.9, extent * 0.22))
  );
  const bandRatio = band / extent;
  const distanceFromEdge = positiveEdge ? 1 - ratio : ratio;
  if (distanceFromEdge >= bandRatio) {
    return {coordinate: baseCoordinate, drop: 0, weight: 0, sign: 0};
  }
  const materialProgress = Math.max(0, Math.min(1, 1 - distanceFromEdge / bandRatio));
  const angle = bendAngle(materialProgress);
  const support = positiveEdge ? extent * 0.5 - band : -extent * 0.5 + band;
  const sign: -1 | 1 = positiveEdge ? 1 : -1;
  const coordinate = support + sign * band * Math.sin(angle);
  const quarterTurn = 1 - Math.cos(angle);
  const hangingCurve = normalizedCatenary(materialProgress);
  return {
    coordinate,
    drop: drop * (quarterTurn * 0.68 + hangingCurve * 0.32),
    weight: smootherStep(materialProgress),
    sign
  };
}

function dominantEdge(first: EdgeBendSample, second: EdgeBendSample): EdgeBendSample {
  return first.weight >= second.weight ? first : second;
}

function sampleSurface(
  xRatio: number,
  zRatio: number,
  width: number,
  depth: number,
  amplitude: number,
  frequency: number,
  drape: ResolvedDrape,
  seed: number
): FabricSurfaceSample {
  const x = xRatio * 2 - 1;
  const z = zRatio * 2 - 1;
  const left = sampleEdgeBend(xRatio, width, drape.left, false);
  const right = sampleEdgeBend(xRatio, width, drape.right, true);
  const back = sampleEdgeBend(zRatio, depth, drape.back, false);
  const front = sampleEdgeBend(zRatio, depth, drape.front, true);
  const xEdge = dominantEdge(left, right);
  const zEdge = dominantEdge(back, front);
  const warp = fractalNoise(seed ^ 0xa511e9b3, x * frequency * 0.37, z * frequency * 0.31);
  const firstAngle = ((seed & 0xffff) / 0xffff - 0.5) * 0.7;
  const firstCosine = Math.cos(firstAngle);
  const firstSine = Math.sin(firstAngle);
  const firstX = x * firstCosine - z * firstSine;
  const firstZ = x * firstSine + z * firstCosine;
  const longFold = fractalNoise(
    seed ^ 0x63d83595,
    firstX * frequency * 1.65 + warp * 0.73,
    firstZ * frequency * 0.24 + warp * 0.19
  );
  const ridgeFold = 1 - Math.abs(fractalNoise(
    seed ^ 0x9e3779b9,
    (x * 0.71 + z * 0.7) * frequency * 0.92 + warp * 0.41,
    (-x * 0.7 + z * 0.71) * frequency * 0.19
  ));
  const crossFold = fractalNoise(
    seed ^ 0x85ebca6b,
    (x * -0.48 + z * 0.88) * frequency * 0.64,
    (x * 0.88 + z * 0.48) * frequency * 0.33 + warp * 0.27
  );
  const microFold = fractalNoise(seed ^ 0xc2b2ae35, x * frequency * 2.8, z * frequency * 2.35);
  const edgeWeight = Math.max(xEdge.weight, zEdge.weight);
  const foldEnvelope = 0.5 + edgeWeight * 0.5;
  const folds = amplitude * foldEnvelope * (
    longFold * 0.49
    + (ridgeFold - 0.52) * 0.27
    + crossFold * 0.17
    + microFold * 0.07
  );
  const crown = amplitude * 0.24 * Math.max(0, 1 - (x * x + z * z) * 0.55);
  const xPleatPhase = (seed & 0xffff) / 0xffff * Math.PI * 2;
  const zPleatPhase = ((seed >>> 16) & 0xffff) / 0xffff * Math.PI * 2;
  const xPleatWave = Math.sin((z * frequency * 1.7 + warp * 0.31) * Math.PI + xPleatPhase);
  const zPleatWave = Math.sin((x * frequency * 1.55 - warp * 0.27) * Math.PI + zPleatPhase);
  const xPleat = amplitude
    * xEdge.weight
    * (0.28 + xEdge.weight * 0.72)
    * (xPleatWave * 0.42 + crossFold * 0.1);
  const zPleat = amplitude
    * zEdge.weight
    * (0.28 + zEdge.weight * 0.72)
    * (zPleatWave * 0.42 + longFold * 0.1);
  const cornerWeight = xEdge.weight * zEdge.weight;
  const diagonalCoordinate = x * xEdge.sign + z * zEdge.sign;
  const cornerPleat = amplitude
    * cornerWeight
    * Math.sin(diagonalCoordinate * frequency * 2.2 + xPleatPhase - zPleatPhase)
    * 0.52;
  const edgeDrop = Math.hypot(left.drop + right.drop, back.drop + front.drop);
  return {
    x: xEdge.coordinate,
    y: crown + folds + xPleat + zPleat + cornerPleat - edgeDrop,
    z: zEdge.coordinate
  };
}

function writeTopIndices(indices: Uint32Array, offset: number, segmentsX: number, segmentsZ: number): number {
  const columns = segmentsX + 1;
  for (let z = 0; z < segmentsZ; z += 1) {
    for (let x = 0; x < segmentsX; x += 1) {
      const a = z * columns + x;
      const b = a + 1;
      const c = a + columns;
      const d = c + 1;
      indices.set([a, c, b, b, c, d], offset);
      offset += 6;
    }
  }
  return offset;
}

function writeSolidIndices(
  indices: Uint32Array,
  offset: number,
  segmentsX: number,
  segmentsZ: number,
  gridVertices: number
): number {
  const columns = segmentsX + 1;
  for (let z = 0; z < segmentsZ; z += 1) {
    for (let x = 0; x < segmentsX; x += 1) {
      const a = gridVertices + z * columns + x;
      const b = a + 1;
      const c = a + columns;
      const d = c + 1;
      indices.set([a, b, c, b, d, c], offset);
      offset += 6;
    }
  }
  for (let z = 0; z < segmentsZ; z += 1) {
    const topLeft = z * columns;
    const topNext = (z + 1) * columns;
    const bottomLeft = gridVertices + topLeft;
    const bottomNext = gridVertices + topNext;
    indices.set([topLeft, bottomLeft, topNext, topNext, bottomLeft, bottomNext], offset);
    offset += 6;

    const topRight = topLeft + segmentsX;
    const topRightNext = topNext + segmentsX;
    const bottomRight = gridVertices + topRight;
    const bottomRightNext = gridVertices + topRightNext;
    indices.set([topRight, topRightNext, bottomRight, topRightNext, bottomRightNext, bottomRight], offset);
    offset += 6;
  }
  for (let x = 0; x < segmentsX; x += 1) {
    const topBack = x;
    const topBackNext = x + 1;
    const bottomBack = gridVertices + topBack;
    const bottomBackNext = gridVertices + topBackNext;
    indices.set([topBack, topBackNext, bottomBack, topBackNext, bottomBackNext, bottomBack], offset);
    offset += 6;

    const topFront = segmentsZ * columns + x;
    const topFrontNext = topFront + 1;
    const bottomFront = gridVertices + topFront;
    const bottomFrontNext = gridVertices + topFrontNext;
    indices.set([topFront, bottomFront, topFrontNext, topFrontNext, bottomFront, bottomFrontNext], offset);
    offset += 6;
  }
  return offset;
}

export function generateFabricMesh(options: GenerateFabricMeshOptions = {}): GeneratedFabricMesh {
  if (!options || typeof options !== 'object') throw new TypeError('fabric options must be an object');
  const width = positiveFloat32(options.width ?? 2.2, 'fabric.width');
  const depth = positiveFloat32(options.depth ?? 2.4, 'fabric.depth');
  const center = resolveCenter(options.center);
  const foldAmplitude = nonNegativeFloat32(options.foldAmplitude ?? Math.min(width, depth) * 0.035, 'fabric.foldAmplitude');
  const foldFrequency = positiveFloat32(options.foldFrequency ?? 4.25, 'fabric.foldFrequency');
  if (foldFrequency > MAX_FOLD_FREQUENCY) {
    throw new RangeError(`fabric.foldFrequency must not exceed ${MAX_FOLD_FREQUENCY}`);
  }
  const drape = resolveDrape(options.drape, width, depth);
  const thickness = nonNegativeFloat32(options.thickness ?? 0, 'fabric.thickness');
  if (thickness > 0 && Math.fround(thickness) <= 0) {
    throw new RangeError('fabric.thickness must be representable as a positive 32-bit number');
  }
  const solid = thickness > 0;
  const budget = resolveModelBudget(options.budget);
  const overflow = options.overflow ?? 'error';
  if (overflow !== 'error' && overflow !== 'fit') throw new RangeError('fabric.overflow must be error or fit');
  const hasTarget = options.targetTriangles !== undefined;
  if (hasTarget && (options.segmentsX !== undefined || options.segmentsZ !== undefined)) {
    throw new RangeError('fabric.targetTriangles is mutually exclusive with segmentsX and segmentsZ');
  }
  const plan = hasTarget
    ? deriveTargetSegments(options.targetTriangles as number, width, depth, solid, budget, overflow)
    : fitRequestedSegments(
        boundedInteger(options.segmentsX ?? 64, 1, MAX_REQUESTED_SEGMENTS, 'fabric.segmentsX'),
        boundedInteger(options.segmentsZ ?? 64, 1, MAX_REQUESTED_SEGMENTS, 'fabric.segmentsZ'),
        solid,
        budget,
        overflow
      );
  assertWithinModelBudget(plan, budget, 'fabric mesh');

  const seed = hashSeed(options.seed ?? 'fabric');
  const columns = plan.segmentsX + 1;
  const rows = plan.segmentsZ + 1;
  const gridVertices = columns * rows;
  const positions = new Float32Array(plan.vertexCount * 3);
  const uvs = new Float32Array(plan.vertexCount * 2);
  for (let z = 0; z < rows; z += 1) {
    const zRatio = z / plan.segmentsZ;
    for (let x = 0; x < columns; x += 1) {
      const xRatio = x / plan.segmentsX;
      const vertex = z * columns + x;
      const positionOffset = vertex * 3;
      const uvOffset = vertex * 2;
      const surface = sampleSurface(
        xRatio,
        zRatio,
        width,
        depth,
        foldAmplitude,
        foldFrequency,
        drape,
        seed
      );
      const px = center[0] + surface.x;
      const py = center[1] + surface.y;
      const pz = center[2] + surface.z;
      positions[positionOffset] = finiteFloat32(px, `fabric position ${vertex}.x`);
      positions[positionOffset + 1] = finiteFloat32(py, `fabric position ${vertex}.y`);
      positions[positionOffset + 2] = finiteFloat32(pz, `fabric position ${vertex}.z`);
      uvs[uvOffset] = xRatio;
      uvs[uvOffset + 1] = zRatio;
    }
  }

  const topIndices = new Uint32Array(plan.segmentsX * plan.segmentsZ * 6);
  const topIndexOffset = writeTopIndices(topIndices, 0, plan.segmentsX, plan.segmentsZ);
  if (topIndexOffset !== topIndices.length) throw new Error('Internal fabric top index-count invariant failed');
  if (solid) {
    const topPositions = positions.slice(0, gridVertices * 3);
    const topNormals = calculateSmoothNormals(topPositions, topIndices);
    for (let vertex = 0; vertex < gridVertices; vertex += 1) {
      const topPositionOffset = vertex * 3;
      const bottomVertex = gridVertices + vertex;
      const bottomPositionOffset = bottomVertex * 3;
      const bottomUvOffset = bottomVertex * 2;
      positions[bottomPositionOffset] = finiteFloat32(
        (positions[topPositionOffset] ?? 0) - (topNormals[topPositionOffset] ?? 0) * thickness,
        `fabric bottom position ${vertex}.x`
      );
      positions[bottomPositionOffset + 1] = finiteFloat32(
        (positions[topPositionOffset + 1] ?? 0) - (topNormals[topPositionOffset + 1] ?? 0) * thickness,
        `fabric bottom position ${vertex}.y`
      );
      positions[bottomPositionOffset + 2] = finiteFloat32(
        (positions[topPositionOffset + 2] ?? 0) - (topNormals[topPositionOffset + 2] ?? 0) * thickness,
        `fabric bottom position ${vertex}.z`
      );
      uvs[bottomUvOffset] = uvs[vertex * 2] ?? 0;
      uvs[bottomUvOffset + 1] = uvs[vertex * 2 + 1] ?? 0;
    }
  }

  const indices = new Uint32Array(plan.triangleCount * 3);
  indices.set(topIndices, 0);
  let indexOffset = topIndices.length;
  if (solid) indexOffset = writeSolidIndices(indices, indexOffset, plan.segmentsX, plan.segmentsZ, gridVertices);
  if (indexOffset !== indices.length) throw new Error('Internal fabric index-count invariant failed');
  const normals = calculateSmoothNormals(positions, indices);
  return {
    positions,
    indices,
    normals,
    uvs,
    segmentsX: plan.segmentsX,
    segmentsZ: plan.segmentsZ,
    reduced: plan.reduced,
    thickness
  };
}
