import type {MeshDefinition} from '../scene';

const NORMAL_EPSILON = 1e-20;

export function calculateSmoothNormals(positions: Float32Array, indices: Uint32Array): Float32Array {
  const normals = new Float32Array(positions.length);
  for (let offset = 0; offset < indices.length; offset += 3) {
    const i0 = indices[offset];
    const i1 = indices[offset + 1];
    const i2 = indices[offset + 2];
    if (i0 === undefined || i1 === undefined || i2 === undefined) throw new Error('Internal triangle index invariant failed');
    const a = i0 * 3;
    const b = i1 * 3;
    const c = i2 * 3;
    const ax = positions[a];
    const ay = positions[a + 1];
    const az = positions[a + 2];
    const bx = positions[b];
    const by = positions[b + 1];
    const bz = positions[b + 2];
    const cx = positions[c];
    const cy = positions[c + 1];
    const cz = positions[c + 2];
    if (ax === undefined || ay === undefined || az === undefined || bx === undefined || by === undefined || bz === undefined || cx === undefined || cy === undefined || cz === undefined) {
      throw new RangeError('triangle index references a missing position');
    }
    const e1x = bx - ax;
    const e1y = by - ay;
    const e1z = bz - az;
    const e2x = cx - ax;
    const e2y = cy - ay;
    const e2z = cz - az;
    const nx = e1y * e2z - e1z * e2y;
    const ny = e1z * e2x - e1x * e2z;
    const nz = e1x * e2y - e1y * e2x;
    if (nx * nx + ny * ny + nz * nz <= NORMAL_EPSILON) throw new RangeError(`triangle ${offset / 3} is degenerate`);
    for (const vertexOffset of [a, b, c]) {
      normals[vertexOffset] = (normals[vertexOffset] ?? 0) + nx;
      normals[vertexOffset + 1] = (normals[vertexOffset + 1] ?? 0) + ny;
      normals[vertexOffset + 2] = (normals[vertexOffset + 2] ?? 0) + nz;
    }
  }
  for (let offset = 0; offset < normals.length; offset += 3) {
    const x = normals[offset] ?? 0;
    const y = normals[offset + 1] ?? 0;
    const z = normals[offset + 2] ?? 0;
    const length = Math.hypot(x, y, z);
    if (length * length <= NORMAL_EPSILON) throw new RangeError(`vertex ${offset / 3} has no usable surface normal`);
    normals[offset] = x / length;
    normals[offset + 1] = y / length;
    normals[offset + 2] = z / length;
  }
  return normals;
}

export function withSmoothNormals(mesh: Pick<MeshDefinition, 'positions' | 'indices' | 'uvs'>): MeshDefinition {
  let positions: Float32Array;
  const first = mesh.positions[0] as number | readonly number[] | undefined;
  if (typeof first === 'number' || first === undefined) {
    positions = mesh.positions instanceof Float32Array ? mesh.positions : Float32Array.from(mesh.positions as ArrayLike<number>);
  } else {
    positions = new Float32Array(mesh.positions.length * 3);
    for (let index = 0; index < mesh.positions.length; index += 1) {
      const value = mesh.positions[index] as readonly number[] | undefined;
      if (!value || value.length !== 3) throw new RangeError(`position ${index} must contain exactly three components`);
      positions.set(value, index * 3);
    }
  }
  if (positions.length < 9 || positions.length % 3 !== 0) throw new RangeError('positions must contain at least three complete vertices');
  const indices = mesh.indices instanceof Uint32Array ? mesh.indices : Uint32Array.from(mesh.indices);
  if (indices.length < 3 || indices.length % 3 !== 0) throw new RangeError('indices must contain complete triangles');
  if (mesh.uvs === undefined) return {positions, indices, normals: calculateSmoothNormals(positions, indices)};

  let uvs: Float32Array;
  const firstUv = mesh.uvs[0] as number | readonly number[] | undefined;
  if (typeof firstUv === 'number' || firstUv === undefined) {
    uvs = mesh.uvs instanceof Float32Array ? mesh.uvs : Float32Array.from(mesh.uvs as ArrayLike<number>);
  } else {
    uvs = new Float32Array(mesh.uvs.length * 2);
    for (let index = 0; index < mesh.uvs.length; index += 1) {
      const value = mesh.uvs[index] as readonly number[] | undefined;
      if (!value || value.length !== 2) throw new RangeError(`UV ${index} must contain exactly two components`);
      uvs.set(value, index * 2);
    }
  }
  if (uvs.length !== positions.length / 3 * 2) {
    throw new RangeError('UVs must contain exactly one texture coordinate per position');
  }
  for (let index = 0; index < uvs.length; index += 1) {
    if (!Number.isFinite(uvs[index])) throw new RangeError(`UV component ${index} must be finite`);
  }
  return {positions, indices, normals: calculateSmoothNormals(positions, indices), uvs};
}
