export const TRIANGLE_GPU_STRIDE = 128;
export const BVH_NODE_GPU_STRIDE = 32;
export const ANIMATED_SHADOW_BVH_HEADER_BYTES = 16;
export const ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE = 32;
export const ANIMATED_SHADOW_TRIANGLE_GPU_STRIDE = 48;
export const ANIMATED_SHADOW_BVH_MAGIC = 0x4153_4256;
export const MATERIAL_GPU_STRIDE = 128;
export const LIGHT_GPU_STRIDE = 64;

export const BVH_NODE_PRIMITIVE_COUNT_MASK = 0x3fff_ffff;
export const BVH_NODE_HAS_STATIC_SHADOW_TRIANGLES = 0x4000_0000;
export const BVH_NODE_HAS_ANIMATED_SHADOW_TRIANGLES = 0x8000_0000;

export const TRIANGLE_SHADOW_FLAG_CACHE_VALID = 1;
export const TRIANGLE_SHADOW_FLAG_ACCEPTS_BACKFACE = 1 << 1;
export const TRIANGLE_SHADOW_FLAG_OPAQUE = 1 << 2;
export const TRIANGLE_SHADOW_FLAG_MASK = TRIANGLE_SHADOW_FLAG_CACHE_VALID
  | TRIANGLE_SHADOW_FLAG_ACCEPTS_BACKFACE
  | TRIANGLE_SHADOW_FLAG_OPAQUE;
export const TRIANGLE_ANIMATED_SHADOW_SLOT_SHIFT = 3;
export const TRIANGLE_ANIMATED_SHADOW_SLOT_MASK = 0x003f_fff8;

