export const LIGHT_TYPE_DIRECTIONAL = 1;

function viewsFor(count: number, stride: number): {buffer: ArrayBuffer; floats: Float32Array; integers: Uint32Array} {
  const byteLength = count * stride;
  if (!Number.isSafeInteger(byteLength)) throw new RangeError('Packed buffer byte length is too large');
  const buffer = new ArrayBuffer(byteLength);
  return {buffer, floats: new Float32Array(buffer), integers: new Uint32Array(buffer)};
}

function writeVec3(view: Float32Array, wordOffset: number, value: Vec3): void {
  view[wordOffset] = value[0];
  view[wordOffset + 1] = value[1];
  view[wordOffset + 2] = value[2];
}

function writeVec2(view: Float32Array, wordOffset: number, value: Vec2): void {
  view[wordOffset] = value[0];
  view[wordOffset + 1] = value[1];
}

function validateTriangleForPacking(triangle: FlatTriangle, index: number): void {
  validateVec3(triangle.v0, `triangles[${index}].v0`);
  validateVec3(triangle.edge1, `triangles[${index}].edge1`);
  validateVec3(triangle.edge2, `triangles[${index}].edge2`);
  validateVec3(triangle.normal, `triangles[${index}].normal`);
  if (lengthSquared3(cross3(triangle.edge1, triangle.edge2)) <= 1e-20) {
    throw new RangeError(`triangles[${index}] is degenerate`);
  }
  if (Math.abs(lengthSquared3(triangle.normal) - 1) > 1e-3) {
    throw new RangeError(`triangles[${index}].normal must have unit length`);
  }
  const normals = triangle.vertexNormals ?? [triangle.normal, triangle.normal, triangle.normal];
  normals.forEach((normal, vertexIndex) => {
    validateVec3(normal, `triangles[${index}].vertexNormals[${vertexIndex}]`);
    if (Math.abs(lengthSquared3(normal) - 1) > 1e-3) {
      throw new RangeError(`triangles[${index}].vertexNormals[${vertexIndex}] must have unit length`);
    }
  });
  if (triangle.vertexUvs !== undefined && triangle.vertexUvs.length !== 3) {
    throw new RangeError(`triangles[${index}].vertexUvs must contain exactly three texture coordinates`);
  }
  const uvs = triangle.vertexUvs ?? [[0, 0], [0, 0], [0, 0]];
  uvs.forEach((uv, vertexIndex) => {
    validateVec2(uv, `triangles[${index}].vertexUvs[${vertexIndex}]`);
  });
  const weights = triangle.windWeights ?? [0, 0, 0];
  weights.forEach((weight, vertexIndex) => {
    assertFiniteGpuNumber(weight, `triangles[${index}].windWeights[${vertexIndex}]`);
    if (weight < 0 || weight > 1) {
      throw new RangeError(`triangles[${index}].windWeights[${vertexIndex}] must be between 0 and 1`);
    }
  });
  const windAmplitude = triangle.windAmplitude ?? 0;
  assertFiniteGpuNumber(windAmplitude, `triangles[${index}].windAmplitude`);
  if (windAmplitude < 0) throw new RangeError(`triangles[${index}].windAmplitude must be non-negative`);
  assertIntegerInRange(
    triangle.shadowFlags ?? 0,
    0,
    TRIANGLE_SHADOW_FLAG_MASK,
    `triangles[${index}].shadowFlags`
  );
  assertIntegerInRange(triangle.materialIndex, 0, 255, `triangles[${index}].materialIndex`);
}

export function calculateTriangleUvGradientMagnitudes(
  triangle: Pick<FlatTriangle, 'edge1' | 'edge2' | 'vertexUvs'>
): readonly [number, number] {
  const uvs = triangle.vertexUvs;
  if (uvs === undefined) return [0, 0];
  const areaVector = cross3(triangle.edge1, triangle.edge2);
  const areaSquared = lengthSquared3(areaVector);
  if (!(areaSquared > 1e-20)) return [0, 0];

  const barycentricU = cross3(triangle.edge2, areaVector).map(
    component => component / areaSquared
  ) as [number, number, number];
  const barycentricV = cross3(areaVector, triangle.edge1).map(
    component => component / areaSquared
  ) as [number, number, number];
  const uvEdge1 = [uvs[1][0] - uvs[0][0], uvs[1][1] - uvs[0][1]] as const;
  const uvEdge2 = [uvs[2][0] - uvs[0][0], uvs[2][1] - uvs[0][1]] as const;
  const gradientU = barycentricU.map((component, axis) => (
    component * uvEdge1[0] + barycentricV[axis]! * uvEdge2[0]
  ));
  const gradientV = barycentricU.map((component, axis) => (
    component * uvEdge1[1] + barycentricV[axis]! * uvEdge2[1]
  ));
  const magnitudes = [Math.hypot(...gradientU), Math.hypot(...gradientV)] as const;
  assertFiniteGpuNumber(magnitudes[0], 'triangle UV U-gradient magnitude');
  assertFiniteGpuNumber(magnitudes[1], 'triangle UV V-gradient magnitude');
  return magnitudes;
}

function packTriangleAtIndex(
  triangle: FlatTriangle,
  index: number,
  floats: Float32Array,
  integers: Uint32Array,
  animatedShadowSlots?: ArrayLike<number>
): void {
  validateTriangleForPacking(triangle, index);
  const word = index * (TRIANGLE_GPU_STRIDE / 4);
  writeVec3(floats, word, triangle.v0);
  integers[word + 3] = triangle.materialIndex;
  writeVec3(floats, word + 4, triangle.edge1);
  floats[word + 7] = triangle.windWeights?.[0] ?? 0;
  writeVec3(floats, word + 8, triangle.edge2);
  floats[word + 11] = triangle.windWeights?.[1] ?? 0;
  const normals = triangle.vertexNormals ?? [triangle.normal, triangle.normal, triangle.normal];
  writeVec3(floats, word + 12, normals[0]);
  floats[word + 15] = triangle.windWeights?.[2] ?? 0;
  writeVec3(floats, word + 16, normals[1]);
  floats[word + 19] = triangle.windAmplitude ?? 0;
  writeVec3(floats, word + 20, normals[2]);
  const animatedShadowSlot = animatedShadowSlots?.[index] ?? -1;
  if (
    !Number.isInteger(animatedShadowSlot)
    || animatedShadowSlot < -1
    || animatedShadowSlot >= MAX_SCENE_TRIANGLES
  ) {
    throw new RangeError(
      `animatedShadowSlots[${index}] must be -1 or an integer below ${MAX_SCENE_TRIANGLES.toLocaleString('en-US')}`
    );
  }
  const encodedAnimatedShadowSlot = animatedShadowSlot < 0
    ? 0
    : (animatedShadowSlot + 1) << TRIANGLE_ANIMATED_SHADOW_SLOT_SHIFT;
  integers[word + 23] = ((triangle.shadowFlags ?? 0) | encodedAnimatedShadowSlot) >>> 0;
  const uvs = triangle.vertexUvs ?? [[0, 0], [0, 0], [0, 0]];
  writeVec2(floats, word + 24, uvs[0]);
  writeVec2(floats, word + 26, uvs[1]);
  writeVec2(floats, word + 28, uvs[2]);
  const uvGradientMagnitudes = calculateTriangleUvGradientMagnitudes(triangle);
  writeVec2(floats, word + 30, uvGradientMagnitudes);
}

export function packTriangles(
  triangles: readonly FlatTriangle[],
  animatedShadowSlots?: ArrayLike<number>
): ArrayBuffer {
  if (triangles.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError(`Cannot pack more than ${MAX_SCENE_TRIANGLES.toLocaleString('en-US')} triangles`);
  }
  if (animatedShadowSlots !== undefined && animatedShadowSlots.length !== triangles.length) {
    throw new RangeError('animatedShadowSlots must contain one entry per triangle');
  }
  const {buffer, floats, integers} = viewsFor(triangles.length, TRIANGLE_GPU_STRIDE);
  for (let index = 0; index < triangles.length; index += 1) {
    const triangle = triangles[index];
    if (!triangle) throw new TypeError(`triangles[${index}] is missing`);
    packTriangleAtIndex(triangle, index, floats, integers, animatedShadowSlots);
  }
  return buffer;
}

export async function packTrianglesAsync(
  triangles: readonly FlatTriangle[],
  animatedShadowSlots: ArrayLike<number> | undefined,
  yieldControl: (completed: number, total: number) => void | Promise<void>
): Promise<ArrayBuffer> {
  if (triangles.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError(`Cannot pack more than ${MAX_SCENE_TRIANGLES.toLocaleString('en-US')} triangles`);
  }
  if (animatedShadowSlots !== undefined && animatedShadowSlots.length !== triangles.length) {
    throw new RangeError('animatedShadowSlots must contain one entry per triangle');
  }
  const {buffer, floats, integers} = viewsFor(triangles.length, TRIANGLE_GPU_STRIDE);
  await yieldControl(0, triangles.length);
  for (let chunkStart = 0; chunkStart < triangles.length; chunkStart += 2_048) {
    const chunkEnd = Math.min(triangles.length, chunkStart + 2_048);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const triangle = triangles[index];
      if (!triangle) throw new TypeError(`triangles[${index}] is missing`);
      packTriangleAtIndex(triangle, index, floats, integers, animatedShadowSlots);
    }
    await yieldControl(chunkEnd, triangles.length);
  }
  if (triangles.length === 0) await yieldControl(0, 0);
  return buffer;
}

export function packBvhNodes(
  nodes: readonly BvhNode[],
  reorderedTriangles?: readonly FlatTriangle[]
): ArrayBuffer {
  if (nodes.length > MAX_SCENE_TRIANGLES * 2 - 1) throw new RangeError('BVH node count exceeds the scene limit');
  const shadowContent = new Uint32Array(nodes.length);
  if (reorderedTriangles) {
    for (let index = nodes.length - 1; index >= 0; index -= 1) {
      const node = nodes[index];
      if (!node) throw new TypeError(`nodes[${index}] is missing`);
      if (node.count > 0) {
        if (node.leftFirst + node.count > reorderedTriangles.length) {
          throw new RangeError(`nodes[${index}] references triangles outside the reordered array`);
        }
        let flags = 0;
        for (let triangleIndex = node.leftFirst; triangleIndex < node.leftFirst + node.count; triangleIndex += 1) {
          const triangle = reorderedTriangles[triangleIndex];
          if (!triangle) throw new TypeError(`reorderedTriangles[${triangleIndex}] is missing`);
          flags |= Math.fround(triangle.windAmplitude ?? 0) > 0
            ? BVH_NODE_HAS_ANIMATED_SHADOW_TRIANGLES
            : BVH_NODE_HAS_STATIC_SHADOW_TRIANGLES;
        }
        shadowContent[index] = flags >>> 0;
      } else {
        const leftFlags = shadowContent[node.leftFirst] ?? 0;
        const rightFlags = shadowContent[node.leftFirst + 1] ?? 0;
        shadowContent[index] = (leftFlags | rightFlags) >>> 0;
      }
    }
  }
  const {buffer, floats, integers} = viewsFor(nodes.length, BVH_NODE_GPU_STRIDE);
  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index];
    if (!node) throw new TypeError(`nodes[${index}] is missing`);
    validateVec3(node.min, `nodes[${index}].min`);
    validateVec3(node.max, `nodes[${index}].max`);
    assertIntegerInRange(node.leftFirst, 0, 0xffff_ffff, `nodes[${index}].leftFirst`);
    assertIntegerInRange(node.count, 0, BVH_LEAF_TRIANGLE_LIMIT, `nodes[${index}].count`);
    assertIntegerInRange(node.depth, 0, BVH_MAX_DEPTH, `nodes[${index}].depth`);
    const word = index * (BVH_NODE_GPU_STRIDE / 4);
    writeVec3(floats, word, node.min);
    integers[word + 3] = node.leftFirst;
    writeVec3(floats, word + 4, node.max);
    integers[word + 7] = (node.count | (shadowContent[index] ?? 0)) >>> 0;
  }
  return buffer;
}

export async function packBvhNodesAsync(
  nodes: readonly BvhNode[],
  reorderedTriangles: readonly FlatTriangle[] | undefined,
  yieldControl: (completed: number, total: number) => void | Promise<void>
): Promise<ArrayBuffer> {
  if (nodes.length > MAX_SCENE_TRIANGLES * 2 - 1) throw new RangeError('BVH node count exceeds the scene limit');
  const shadowContent = new Uint32Array(nodes.length);
  const total = nodes.length + (reorderedTriangles ? nodes.length : 0);
  let completed = 0;
  await yieldControl(completed, total);
  if (reorderedTriangles) {
    for (let chunkEnd = nodes.length; chunkEnd > 0; chunkEnd -= 2_048) {
      const chunkStart = Math.max(0, chunkEnd - 2_048);
      for (let index = chunkEnd - 1; index >= chunkStart; index -= 1) {
        const node = nodes[index];
        if (!node) throw new TypeError(`nodes[${index}] is missing`);
        if (node.count > 0) {
          if (node.leftFirst + node.count > reorderedTriangles.length) {
            throw new RangeError(`nodes[${index}] references triangles outside the reordered array`);
          }
          let flags = 0;
          for (let triangleIndex = node.leftFirst; triangleIndex < node.leftFirst + node.count; triangleIndex += 1) {
            const triangle = reorderedTriangles[triangleIndex];
            if (!triangle) throw new TypeError(`reorderedTriangles[${triangleIndex}] is missing`);
            flags |= Math.fround(triangle.windAmplitude ?? 0) > 0
              ? BVH_NODE_HAS_ANIMATED_SHADOW_TRIANGLES
              : BVH_NODE_HAS_STATIC_SHADOW_TRIANGLES;
          }
          shadowContent[index] = flags >>> 0;
        } else {
          const leftFlags = shadowContent[node.leftFirst] ?? 0;
          const rightFlags = shadowContent[node.leftFirst + 1] ?? 0;
          shadowContent[index] = (leftFlags | rightFlags) >>> 0;
        }
      }
      completed += chunkEnd - chunkStart;
      await yieldControl(completed, total);
    }
  }

  const {buffer, floats, integers} = viewsFor(nodes.length, BVH_NODE_GPU_STRIDE);
  for (let chunkStart = 0; chunkStart < nodes.length; chunkStart += 2_048) {
    const chunkEnd = Math.min(nodes.length, chunkStart + 2_048);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const node = nodes[index];
      if (!node) throw new TypeError(`nodes[${index}] is missing`);
      validateVec3(node.min, `nodes[${index}].min`);
      validateVec3(node.max, `nodes[${index}].max`);
      assertIntegerInRange(node.leftFirst, 0, 0xffff_ffff, `nodes[${index}].leftFirst`);
      assertIntegerInRange(node.count, 0, BVH_LEAF_TRIANGLE_LIMIT, `nodes[${index}].count`);
      assertIntegerInRange(node.depth, 0, BVH_MAX_DEPTH, `nodes[${index}].depth`);
      const word = index * (BVH_NODE_GPU_STRIDE / 4);
      writeVec3(floats, word, node.min);
      integers[word + 3] = node.leftFirst;
      writeVec3(floats, word + 4, node.max);
      integers[word + 7] = (node.count | (shadowContent[index] ?? 0)) >>> 0;
    }
    completed += chunkEnd - chunkStart;
    await yieldControl(completed, total);
  }
  return buffer;
}

export function packAnimatedShadowBvh(
  nodes: readonly BvhNode[],
  reorderedMainTriangleIndices: readonly number[]
): ArrayBuffer {
  if (nodes.length > MAX_SCENE_TRIANGLES * 2 - 1) {
    throw new RangeError('Animated-shadow BVH node count exceeds the scene limit');
  }
  if (reorderedMainTriangleIndices.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError('Animated-shadow triangle count exceeds the scene limit');
  }
  const headerWords = ANIMATED_SHADOW_BVH_HEADER_BYTES / Uint32Array.BYTES_PER_ELEMENT;
  const nodeWords = ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE / Uint32Array.BYTES_PER_ELEMENT;
  const indexOffsetWords = headerWords + nodes.length * nodeWords;
  const buffer = new ArrayBuffer(
    ANIMATED_SHADOW_BVH_HEADER_BYTES
      + nodes.length * ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE
      + reorderedMainTriangleIndices.length * Uint32Array.BYTES_PER_ELEMENT
      + reorderedMainTriangleIndices.length * ANIMATED_SHADOW_TRIANGLE_GPU_STRIDE
  );
  const floats = new Float32Array(buffer);
  const integers = new Uint32Array(buffer);
  integers[0] = ANIMATED_SHADOW_BVH_MAGIC;
  integers[1] = nodes.length;
  integers[2] = indexOffsetWords;
  integers[3] = reorderedMainTriangleIndices.length;
  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index];
    if (!node) throw new TypeError(`nodes[${index}] is missing`);
    validateVec3(node.min, `nodes[${index}].min`);
    validateVec3(node.max, `nodes[${index}].max`);
    assertIntegerInRange(node.leftFirst, 0, 0xffff_ffff, `nodes[${index}].leftFirst`);
    assertIntegerInRange(node.count, 0, BVH_LEAF_TRIANGLE_LIMIT, `nodes[${index}].count`);
    const word = headerWords + index * nodeWords;
    writeVec3(floats, word, node.min);
    integers[word + 3] = node.leftFirst;
    writeVec3(floats, word + 4, node.max);
    integers[word + 7] = node.count;
  }
  for (let index = 0; index < reorderedMainTriangleIndices.length; index += 1) {
    const triangleIndex = reorderedMainTriangleIndices[index];
    if (triangleIndex === undefined) {
      throw new TypeError(`reorderedMainTriangleIndices[${index}] is missing`);
    }
    integers[indexOffsetWords + index] = assertIntegerInRange(
      triangleIndex,
      0,
      MAX_SCENE_TRIANGLES - 1,
      `reorderedMainTriangleIndices[${index}]`
    );
  }
  return buffer;
}

export async function packAnimatedShadowBvhAsync(
  nodes: readonly BvhNode[],
  reorderedMainTriangleIndices: readonly number[],
  yieldControl: (completed: number, total: number) => void | Promise<void>
): Promise<ArrayBuffer> {
  if (nodes.length > MAX_SCENE_TRIANGLES * 2 - 1) {
    throw new RangeError('Animated-shadow BVH node count exceeds the scene limit');
  }
  if (reorderedMainTriangleIndices.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError('Animated-shadow triangle count exceeds the scene limit');
  }
  const headerWords = ANIMATED_SHADOW_BVH_HEADER_BYTES / Uint32Array.BYTES_PER_ELEMENT;
  const nodeWords = ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE / Uint32Array.BYTES_PER_ELEMENT;
  const indexOffsetWords = headerWords + nodes.length * nodeWords;
  const buffer = new ArrayBuffer(
    ANIMATED_SHADOW_BVH_HEADER_BYTES
      + nodes.length * ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE
      + reorderedMainTriangleIndices.length * Uint32Array.BYTES_PER_ELEMENT
      + reorderedMainTriangleIndices.length * ANIMATED_SHADOW_TRIANGLE_GPU_STRIDE
  );
  const floats = new Float32Array(buffer);
  const integers = new Uint32Array(buffer);
  integers[0] = ANIMATED_SHADOW_BVH_MAGIC;
  integers[1] = nodes.length;
  integers[2] = indexOffsetWords;
  integers[3] = reorderedMainTriangleIndices.length;
  const total = nodes.length + reorderedMainTriangleIndices.length;
  let completed = 0;
  await yieldControl(completed, total);
  for (let chunkStart = 0; chunkStart < nodes.length; chunkStart += 2_048) {
    const chunkEnd = Math.min(nodes.length, chunkStart + 2_048);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const node = nodes[index];
      if (!node) throw new TypeError(`nodes[${index}] is missing`);
      validateVec3(node.min, `nodes[${index}].min`);
      validateVec3(node.max, `nodes[${index}].max`);
      assertIntegerInRange(node.leftFirst, 0, 0xffff_ffff, `nodes[${index}].leftFirst`);
      assertIntegerInRange(node.count, 0, BVH_LEAF_TRIANGLE_LIMIT, `nodes[${index}].count`);
      const word = headerWords + index * nodeWords;
      writeVec3(floats, word, node.min);
      integers[word + 3] = node.leftFirst;
      writeVec3(floats, word + 4, node.max);
      integers[word + 7] = node.count;
    }
    completed += chunkEnd - chunkStart;
    await yieldControl(completed, total);
  }
  for (let chunkStart = 0; chunkStart < reorderedMainTriangleIndices.length; chunkStart += 2_048) {
    const chunkEnd = Math.min(reorderedMainTriangleIndices.length, chunkStart + 2_048);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const triangleIndex = reorderedMainTriangleIndices[index];
      if (triangleIndex === undefined) {
        throw new TypeError(`reorderedMainTriangleIndices[${index}] is missing`);
      }
      integers[indexOffsetWords + index] = assertIntegerInRange(
        triangleIndex,
        0,
        MAX_SCENE_TRIANGLES - 1,
        `reorderedMainTriangleIndices[${index}]`
      );
    }
    completed += chunkEnd - chunkStart;
    await yieldControl(completed, total);
  }
  return buffer;
}

function validateMaterialForPacking(material: MaterialRecord, index: number): void {
  validateVec3(material.baseColor, `materials[${index}].baseColor`);
  validateVec3(material.emissionColor, `materials[${index}].emissionColor`);
  validateVec2(material.uvRepeat, `materials[${index}].uvRepeat`);
  validateVec2(material.atlasOffset, `materials[${index}].atlasOffset`);
  validateVec2(material.atlasScale, `materials[${index}].atlasScale`);
  assertIntegerInRange(material.textureLayer, 0, 0xffff_ffff, `materials[${index}].textureLayer`);
  assertIntegerInRange(
    material.normalTextureLayer,
    0,
    0xffff_ffff,
    `materials[${index}].normalTextureLayer`
  );
  assertIntegerInRange(
    material.roughnessTextureLayer,
    0,
    0xffff_ffff,
    `materials[${index}].roughnessTextureLayer`
  );
  assertIntegerInRange(material.textureFlags, 0, 0xffff_ffff, `materials[${index}].textureFlags`);
  for (let component = 0; component < 2; component += 1) {
    const repeat = material.uvRepeat[component] ?? Number.NaN;
    const offset = material.atlasOffset[component] ?? Number.NaN;
    const scale = material.atlasScale[component] ?? Number.NaN;
    if (repeat < 0.0001 || repeat > MAX_UV_REPEAT) {
      throw new RangeError(`materials[${index}].uvRepeat[${component}] is outside the supported range`);
    }
    if (offset < 0 || offset > 1 || scale < 0.0001 || scale > 1 || offset + scale > 1 + 1e-7) {
      throw new RangeError(`materials[${index}] atlas tile is outside normalized texture bounds`);
    }
  }
  for (const [name, value] of [
    ['roughness', material.roughness],
    ['metallic', material.metallic],
    ['emissionStrength', material.emissionStrength],
    ['transmission', material.transmission],
    ['ior', material.ior],
    ['alpha', material.alpha],
    ['windInfluence', material.windInfluence],
    ['colorVariation', material.colorVariation],
    ['detailScale', material.detailScale],
    ['roughnessVariation', material.roughnessVariation],
    ['normalStrength', material.normalStrength],
    ['textureStrength', material.textureStrength],
    ['textureNormalStrength', material.textureNormalStrength],
    ['textureRoughnessStrength', material.textureRoughnessStrength],
    ['textureLod', material.textureLod]
  ] as const) {
    assertFiniteGpuNumber(value, `materials[${index}].${name}`);
  }
  if (material.textureStrength < 0 || material.textureStrength > 1) {
    throw new RangeError(`materials[${index}].textureStrength must be from 0 through 1`);
  }
  if (material.textureNormalStrength < 0 || material.textureNormalStrength > 4) {
    throw new RangeError(`materials[${index}].textureNormalStrength must be from 0 through 4`);
  }
  if (material.textureRoughnessStrength < 0 || material.textureRoughnessStrength > 1) {
    throw new RangeError(`materials[${index}].textureRoughnessStrength must be from 0 through 1`);
  }
  if (material.textureLod < 0 || material.textureLod > MAX_TEXTURE_LOD) {
    throw new RangeError(`materials[${index}].textureLod must be from 0 through ${MAX_TEXTURE_LOD}`);
  }
}

export function packMaterials(materials: readonly MaterialRecord[]): ArrayBuffer {
  if (materials.length > 256) throw new RangeError('Cannot pack more than 256 materials');
  const {buffer, floats, integers} = viewsFor(materials.length, MATERIAL_GPU_STRIDE);
  for (let index = 0; index < materials.length; index += 1) {
    const material = materials[index];
    if (!material) throw new TypeError(`materials[${index}] is missing`);
    validateMaterialForPacking(material, index);
    const word = index * (MATERIAL_GPU_STRIDE / 4);
    writeVec3(floats, word, material.baseColor);
    floats[word + 3] = material.roughness;
    writeVec3(floats, word + 4, material.emissionColor);
    floats[word + 7] = material.emissionStrength;
    floats[word + 8] = material.metallic;
    floats[word + 9] = material.transmission;
    floats[word + 10] = material.ior;
    floats[word + 11] = material.alpha;
    let flags = material.doubleSided ? MATERIAL_FLAG_DOUBLE_SIDED : 0;
    if (material.surfaceDetail === 'foliage') flags |= MATERIAL_FLAG_FOLIAGE;
    if (material.surfaceDetail === 'bark') flags |= MATERIAL_FLAG_BARK;
    if (material.surfaceDetail === 'grass') flags |= MATERIAL_FLAG_GRASS;
    if (material.surfaceDetail === 'ground') flags |= MATERIAL_FLAG_GROUND;
    if (material.surfaceDetail === 'plaster') flags |= MATERIAL_FLAG_PLASTER;
    if (material.surfaceDetail === 'wood') flags |= MATERIAL_FLAG_WOOD;
    if (material.surfaceDetail === 'fabric') flags |= MATERIAL_FLAG_FABRIC;
    if (material.surfaceDetail === 'glass' || material.surfaceDetail === 'solid-glass') {
      flags |= MATERIAL_FLAG_GLASS;
    }
    if (material.surfaceDetail === 'solid-glass') flags |= MATERIAL_FLAG_SOLID_GLASS;
    if (material.surfaceDetail === 'unlit') flags |= MATERIAL_FLAG_UNLIT;
    integers[word + 12] = flags;
    floats[word + 13] = material.windInfluence;
    floats[word + 14] = material.colorVariation;
    floats[word + 15] = material.detailScale;
    floats[word + 16] = material.roughnessVariation;
    floats[word + 17] = material.normalStrength;
    integers[word + 18] = material.normalTextureLayer;
    integers[word + 19] = material.roughnessTextureLayer;
    integers[word + 20] = material.textureLayer;
    integers[word + 21] = material.textureFlags;
    writeVec2(floats, word + 22, material.uvRepeat);
    writeVec2(floats, word + 24, material.atlasOffset);
    writeVec2(floats, word + 26, material.atlasScale);
    floats[word + 28] = material.textureStrength;
    floats[word + 29] = material.textureNormalStrength;
    floats[word + 30] = material.textureRoughnessStrength;
    floats[word + 31] = material.textureLod;
  }
  return buffer;
}

function validateLightForPacking(light: LightRecord, index: number): void {
  validateVec3(light.type === 'point' ? light.position : light.direction, `lights[${index}].vector`);
  validateVec3(light.color, `lights[${index}].color`);
  assertFiniteGpuNumber(light.intensity, `lights[${index}].intensity`);
  assertFiniteGpuNumber(light.type === 'point' ? light.range : light.angularRadius, `lights[${index}].range`);
  if (light.type === 'point') assertFiniteGpuNumber(light.radius, `lights[${index}].radius`);
}

export function packLights(lights: readonly LightRecord[]): ArrayBuffer {
  if (lights.length > 32) throw new RangeError('Cannot pack more than 32 lights');
  const {buffer, floats, integers} = viewsFor(lights.length, LIGHT_GPU_STRIDE);
  for (let index = 0; index < lights.length; index += 1) {
    const light = lights[index];
    if (!light) throw new TypeError(`lights[${index}] is missing`);
    validateLightForPacking(light, index);
    const word = index * (LIGHT_GPU_STRIDE / 4);
    writeVec3(floats, word, light.type === 'point' ? light.position : light.direction);
    integers[word + 3] = light.type === 'point' ? LIGHT_TYPE_POINT : LIGHT_TYPE_DIRECTIONAL;
    writeVec3(floats, word + 4, light.color);
    floats[word + 7] = light.intensity;
    floats[word + 8] = light.type === 'point' ? light.range : light.angularRadius;
    floats[word + 9] = light.type === 'point' ? light.radius : 0;
    integers[word + 10] = light.castShadow ? LIGHT_FLAG_CAST_SHADOW : 0;
  }
  return buffer;
}

export function calculatePackedSceneByteLength(
  triangleCount: number,
  bvhNodeCount: number,
  materialCount: number,
  lightCount: number,
  animatedTriangleCount = triangleCount,
  animatedBvhNodeCount = bvhNodeCount
): number {
  assertIntegerInRange(triangleCount, 0, MAX_SCENE_TRIANGLES, 'triangleCount');
  assertIntegerInRange(bvhNodeCount, 0, MAX_SCENE_TRIANGLES * 2 - 1, 'bvhNodeCount');
  assertIntegerInRange(materialCount, 0, 256, 'materialCount');
  assertIntegerInRange(lightCount, 0, 32, 'lightCount');
  assertIntegerInRange(animatedTriangleCount, 0, triangleCount, 'animatedTriangleCount');
  assertIntegerInRange(animatedBvhNodeCount, 0, bvhNodeCount, 'animatedBvhNodeCount');
  return triangleCount * TRIANGLE_GPU_STRIDE
    + bvhNodeCount * BVH_NODE_GPU_STRIDE
    + materialCount * MATERIAL_GPU_STRIDE
    + lightCount * LIGHT_GPU_STRIDE
    + ANIMATED_SHADOW_BVH_HEADER_BYTES
    + animatedBvhNodeCount * ANIMATED_SHADOW_BVH_NODE_GPU_STRIDE
    + animatedTriangleCount * (
      Uint32Array.BYTES_PER_ELEMENT + ANIMATED_SHADOW_TRIANGLE_GPU_STRIDE
    );
}
