import type {Transform, TransformInput, Vec3} from './types';

const DEGREES_TO_RADIANS = Math.PI / 180;
const NORMAL_EPSILON_SQUARED = 1e-20;

export const IDENTITY_TRANSFORM: Transform = Object.freeze({
  translation: Object.freeze([0, 0, 0] as const),
  rotation: Object.freeze([0, 0, 0] as const),
  scale: Object.freeze([1, 1, 1] as const)
});

export function add3(a: Vec3, b: Vec3): Vec3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

export function subtract3(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

export function multiply3(a: Vec3, scalar: number): Vec3 {
  return [a[0] * scalar, a[1] * scalar, a[2] * scalar];
}

export function dot3(a: Vec3, b: Vec3): number {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

export function cross3(a: Vec3, b: Vec3): Vec3 {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
}

export function lengthSquared3(value: Vec3): number {
  return dot3(value, value);
}

export function normalize3(value: Vec3, label = 'vector'): Vec3 {
  const lengthSquared = lengthSquared3(value);
  if (!Number.isFinite(lengthSquared) || lengthSquared <= NORMAL_EPSILON_SQUARED) {
    throw new RangeError(`${label} must have non-zero finite length`);
  }
  const inverseLength = 1 / Math.sqrt(lengthSquared);
  return multiply3(value, inverseLength);
}

export function resolveTransform(input: TransformInput = {}, base: Transform = IDENTITY_TRANSFORM): Transform {
  return {
    translation: input.translation ?? base.translation,
    rotation: input.rotation ?? base.rotation,
    scale: input.scale ?? base.scale
  };
}

function rotateX(value: Vec3, sine: number, cosine: number): Vec3 {
  return [value[0], value[1] * cosine - value[2] * sine, value[1] * sine + value[2] * cosine];
}

function rotateY(value: Vec3, sine: number, cosine: number): Vec3 {
  return [value[0] * cosine + value[2] * sine, value[1], -value[0] * sine + value[2] * cosine];
}

function rotateZ(value: Vec3, sine: number, cosine: number): Vec3 {
  return [value[0] * cosine - value[1] * sine, value[0] * sine + value[1] * cosine, value[2]];
}

function rotateEuler(value: Vec3, rotationDegrees: Vec3): Vec3 {
  const rx = rotationDegrees[0] * DEGREES_TO_RADIANS;
  const ry = rotationDegrees[1] * DEGREES_TO_RADIANS;
  const rz = rotationDegrees[2] * DEGREES_TO_RADIANS;
  let result = rotateX(value, Math.sin(rx), Math.cos(rx));
  result = rotateY(result, Math.sin(ry), Math.cos(ry));
  return rotateZ(result, Math.sin(rz), Math.cos(rz));
}

export function transformPoint(point: Vec3, transform: Transform): Vec3 {
  const scaled: Vec3 = [
    point[0] * transform.scale[0],
    point[1] * transform.scale[1],
    point[2] * transform.scale[2]
  ];
  return add3(rotateEuler(scaled, transform.rotation), transform.translation);
}

/** Applies the inverse-transpose of scale followed by the object's Euler rotation. */
export function transformNormal(normal: Vec3, transform: Transform): Vec3 {
  const inverseScaled: Vec3 = [
    normal[0] / transform.scale[0],
    normal[1] / transform.scale[1],
    normal[2] / transform.scale[2]
  ];
  return normalize3(rotateEuler(inverseScaled, transform.rotation), 'transformed normal');
}

export function componentMin3(a: Vec3, b: Vec3): Vec3 {
  return [Math.min(a[0], b[0]), Math.min(a[1], b[1]), Math.min(a[2], b[2])];
}

export function componentMax3(a: Vec3, b: Vec3): Vec3 {
  return [Math.max(a[0], b[0]), Math.max(a[1], b[1]), Math.max(a[2], b[2])];
}
