import {
  CooperativeTextureWork,
  type CooperativeTextureWorkOptions
} from './cooperative-work';

export interface RadianceHdrImage {
  readonly width: number;
  readonly height: number;
  readonly data: Float32Array;
}

const MAX_HDR_PIXELS = 8_388_608;

export function isRadianceHdr(bytes: Uint8Array): boolean {
  if (bytes.byteLength < 6) return false;
  const prefix = new TextDecoder('ascii').decode(bytes.subarray(0, Math.min(bytes.byteLength, 16)));
  return prefix.startsWith('#?RADIANCE') || prefix.startsWith('#?RGBE');
}

export function decodeRadianceHdr(input: ArrayBuffer | Uint8Array): RadianceHdrImage {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  const header = parseHeader(bytes);
  const {width, height, xSign, ySign} = header;
  let offset = header.offset;
  const output = new Float32Array(width * height * 4);

  if (hasModernRleHeader(bytes, offset, width)) {
    const scanline = new Uint8Array(width * 4);
    for (let sourceY = 0; sourceY < height; sourceY += 1) {
      offset = decodeModernScanline(bytes, offset, width, sourceY, scanline);
      writeScanline(output, scanline, width, height, sourceY, xSign, ySign);
    }
  } else {
    const required = width * height * 4;
    requireBytes(bytes, offset, required, 'Radiance flat RGBE payload');
    const scanline = new Uint8Array(width * 4);
    for (let sourceY = 0; sourceY < height; sourceY += 1) {
      scanline.set(bytes.subarray(offset, offset + width * 4));
      offset += width * 4;
      writeScanline(output, scanline, width, height, sourceY, xSign, ySign);
    }
  }

  return {width, height, data: output};
}

export async function decodeRadianceHdrAsync(
  input: ArrayBuffer | Uint8Array,
  options: CooperativeTextureWorkOptions = {}
): Promise<RadianceHdrImage> {
  const work = new CooperativeTextureWork(options);
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  const header = parseHeader(bytes);
  const {width, height, xSign, ySign} = header;
  let offset = header.offset;
  const output = new Float32Array(width * height * 4);
  await work.checkpoint(true);

  if (hasModernRleHeader(bytes, offset, width)) {
    const scanline = new Uint8Array(width * 4);
    for (let sourceY = 0; sourceY < height; sourceY += 1) {
      offset = decodeModernScanline(bytes, offset, width, sourceY, scanline);
      writeScanline(output, scanline, width, height, sourceY, xSign, ySign);
      if (work.shouldYield()) await work.checkpoint(true);
    }
  } else {
    const required = width * height * 4;
    requireBytes(bytes, offset, required, 'Radiance flat RGBE payload');
    const scanline = new Uint8Array(width * 4);
    for (let sourceY = 0; sourceY < height; sourceY += 1) {
      scanline.set(bytes.subarray(offset, offset + width * 4));
      offset += width * 4;
      writeScanline(output, scanline, width, height, sourceY, xSign, ySign);
      if (work.shouldYield()) await work.checkpoint(true);
    }
  }

  work.assertCurrent();
  return {width, height, data: output};
}

interface RadianceHeader {
  readonly width: number;
  readonly height: number;
  readonly xSign: string;
  readonly ySign: string;
  readonly offset: number;
}

function parseHeader(bytes: Uint8Array): RadianceHeader {
  let offset = 0;
  const magic = readLine(bytes, offset);
  offset = magic.next;
  if (magic.text !== '#?RADIANCE' && magic.text !== '#?RGBE') {
    throw new TypeError('The image is not a Radiance RGBE file.');
  }

  let formatSeen = false;
  while (offset < bytes.length) {
    const line = readLine(bytes, offset);
    offset = line.next;
    if (line.text.length === 0) break;
    if (line.text.toUpperCase() === 'FORMAT=32-BIT_RLE_RGBE') formatSeen = true;
  }
  if (!formatSeen) {
    throw new TypeError('Radiance HDR must use FORMAT=32-bit_rle_rgbe.');
  }

  let resolutionLine = readLine(bytes, offset);
  offset = resolutionLine.next;
  while (resolutionLine.text.length === 0 && offset < bytes.length) {
    resolutionLine = readLine(bytes, offset);
    offset = resolutionLine.next;
  }
  const resolution = /^([+-])Y\s+(\d+)\s+([+-])X\s+(\d+)$/i.exec(resolutionLine.text);
  if (!resolution) {
    throw new TypeError(`Unsupported Radiance HDR resolution line: ${resolutionLine.text || '(missing)'}.`);
  }
  const height = Number(resolution[2]);
  const width = Number(resolution[4]);
  if (
    !Number.isSafeInteger(width)
    || !Number.isSafeInteger(height)
    || width < 1
    || height < 1
    || width * height > MAX_HDR_PIXELS
  ) {
    throw new RangeError(`Radiance HDR dimensions exceed the ${MAX_HDR_PIXELS.toLocaleString()}-pixel limit.`);
  }
  return {
    width,
    height,
    ySign: resolution[1]!,
    xSign: resolution[3]!,
    offset
  };
}

function decodeModernScanline(
  bytes: Uint8Array,
  initialOffset: number,
  width: number,
  sourceY: number,
  scanline: Uint8Array
): number {
  let offset = initialOffset;
  requireBytes(bytes, offset, 4, 'Radiance scanline header');
  if (bytes[offset] !== 2 || bytes[offset + 1] !== 2) {
    throw new TypeError(`Radiance scanline ${sourceY} has an invalid RLE header.`);
  }
  const encodedWidth = (bytes[offset + 2]! << 8) | bytes[offset + 3]!;
  offset += 4;
  if (encodedWidth !== width) {
    throw new TypeError(`Radiance scanline ${sourceY} declares width ${encodedWidth}, expected ${width}.`);
  }
  for (let channel = 0; channel < 4; channel += 1) {
    let x = 0;
    while (x < width) {
      requireBytes(bytes, offset, 1, 'Radiance RLE packet');
      const code = bytes[offset++]!;
      if (code === 0) throw new TypeError('Radiance RLE packets cannot have zero length.');
      if (code > 128) {
        const count = code - 128;
        requireBytes(bytes, offset, 1, 'Radiance RLE run');
        if (x + count > width) throw new TypeError('Radiance RLE run crosses the scanline boundary.');
        const value = bytes[offset++]!;
        for (let index = 0; index < count; index += 1) {
          scanline[(x + index) * 4 + channel] = value;
        }
        x += count;
      } else {
        const count = code;
        requireBytes(bytes, offset, count, 'Radiance RLE literal');
        if (x + count > width) throw new TypeError('Radiance RLE literal crosses the scanline boundary.');
        for (let index = 0; index < count; index += 1) {
          scanline[(x + index) * 4 + channel] = bytes[offset + index]!;
        }
        offset += count;
        x += count;
      }
    }
  }
  return offset;
}

function writeScanline(
  output: Float32Array,
  scanline: Uint8Array,
  width: number,
  height: number,
  sourceY: number,
  xSign: string,
  ySign: string
): void {
  const outputY = ySign === '-' ? sourceY : height - sourceY - 1;
  for (let sourceX = 0; sourceX < width; sourceX += 1) {
    const outputX = xSign === '+' ? sourceX : width - sourceX - 1;
    const sourceOffset = sourceX * 4;
    const outputOffset = (outputY * width + outputX) * 4;
    const exponent = scanline[sourceOffset + 3]!;
    if (exponent === 0) {
      output[outputOffset] = 0;
      output[outputOffset + 1] = 0;
      output[outputOffset + 2] = 0;
    } else {
      const scale = 2 ** (exponent - 136);
      output[outputOffset] = scanline[sourceOffset]! * scale;
      output[outputOffset + 1] = scanline[sourceOffset + 1]! * scale;
      output[outputOffset + 2] = scanline[sourceOffset + 2]! * scale;
    }
    output[outputOffset + 3] = 1;
  }
}

function hasModernRleHeader(bytes: Uint8Array, offset: number, width: number): boolean {
  if (width < 8 || width > 0x7fff || offset + 4 > bytes.length) return false;
  return bytes[offset] === 2
    && bytes[offset + 1] === 2
    && (bytes[offset + 2]! & 0x80) === 0
    && (((bytes[offset + 2]! << 8) | bytes[offset + 3]!) === width);
}

function readLine(bytes: Uint8Array, offset: number): {readonly text: string; readonly next: number} {
  if (offset >= bytes.length) return {text: '', next: offset};
  let end = offset;
  while (end < bytes.length && bytes[end] !== 0x0a) end += 1;
  let contentEnd = end;
  if (contentEnd > offset && bytes[contentEnd - 1] === 0x0d) contentEnd -= 1;
  const text = new TextDecoder('ascii', {fatal: false}).decode(bytes.subarray(offset, contentEnd)).trim();
  return {text, next: end < bytes.length ? end + 1 : end};
}

function requireBytes(bytes: Uint8Array, offset: number, count: number, label: string): void {
  if (!Number.isSafeInteger(count) || count < 0 || offset < 0 || offset + count > bytes.length) {
    throw new TypeError(`${label} is truncated.`);
  }
}
