function requireDimension(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(`${label} must be a positive safe integer.`);
  }
}

function finiteNonnegative(value: number | undefined): number {
  return Number.isFinite(value) ? Math.max(0, value ?? 0) : 0;
}

export function downsampleLinearRgbaBox(
  source: Float32Array,
  sourceWidth: number,
  sourceHeight: number,
  targetWidth: number,
  targetHeight: number
): Float32Array {
  requireDimension(sourceWidth, 'Source width');
  requireDimension(sourceHeight, 'Source height');
  requireDimension(targetWidth, 'Target width');
  requireDimension(targetHeight, 'Target height');
  if (source.length !== sourceWidth * sourceHeight * 4) {
    throw new RangeError('Linear RGBA source length must equal width * height * 4.');
  }
  if (targetWidth > sourceWidth || targetHeight > sourceHeight) {
    throw new RangeError('Environment box filtering only supports downsampling.');
  }
  if (targetWidth === sourceWidth && targetHeight === sourceHeight) {
    const copy = new Float32Array(source.length);
    for (let index = 0; index < source.length; index += 1) {
      copy[index] = finiteNonnegative(source[index]);
    }
    return copy;
  }

  const output = new Float32Array(targetWidth * targetHeight * 4);
  const scaleX = sourceWidth / targetWidth;
  const scaleY = sourceHeight / targetHeight;
  for (let targetY = 0; targetY < targetHeight; targetY += 1) {
    const sourceY0 = targetY * scaleY;
    const sourceY1 = (targetY + 1) * scaleY;
    const firstSourceY = Math.floor(sourceY0);
    const finalSourceY = Math.ceil(sourceY1) - 1;
    for (let targetX = 0; targetX < targetWidth; targetX += 1) {
      const sourceX0 = targetX * scaleX;
      const sourceX1 = (targetX + 1) * scaleX;
      const firstSourceX = Math.floor(sourceX0);
      const finalSourceX = Math.ceil(sourceX1) - 1;
      const sums = [0, 0, 0, 0];
      let totalWeight = 0;

      for (let sourceY = firstSourceY; sourceY <= finalSourceY; sourceY += 1) {
        const yWeight = Math.max(0, Math.min(sourceY + 1, sourceY1) - Math.max(sourceY, sourceY0));
        const clampedY = Math.max(0, Math.min(sourceHeight - 1, sourceY));
        for (let sourceX = firstSourceX; sourceX <= finalSourceX; sourceX += 1) {
          const xWeight = Math.max(0, Math.min(sourceX + 1, sourceX1) - Math.max(sourceX, sourceX0));
          const wrappedX = ((sourceX % sourceWidth) + sourceWidth) % sourceWidth;
          const weight = xWeight * yWeight;
          const sourceIndex = (clampedY * sourceWidth + wrappedX) * 4;
          for (let channel = 0; channel < 4; channel += 1) {
            sums[channel]! += finiteNonnegative(source[sourceIndex + channel]) * weight;
          }
          totalWeight += weight;
        }
      }

      const outputIndex = (targetY * targetWidth + targetX) * 4;
      const inverseWeight = totalWeight > 0 ? 1 / totalWeight : 0;
      for (let channel = 0; channel < 4; channel += 1) {
        output[outputIndex + channel] = sums[channel]! * inverseWeight;
      }
    }
  }
  return output;
}

export async function downsampleLinearRgbaBoxAsync(
  source: Float32Array,
  sourceWidth: number,
  sourceHeight: number,
  targetWidth: number,
  targetHeight: number,
  options: CooperativeTextureWorkOptions = {}
): Promise<Float32Array> {
  requireDownsample(source, sourceWidth, sourceHeight, targetWidth, targetHeight);
  const work = new CooperativeTextureWork(options);
  await work.checkpoint(true);
  if (targetWidth === sourceWidth && targetHeight === sourceHeight) {
    const copy = new Float32Array(source.length);
    for (let index = 0; index < source.length; index += 1) {
      copy[index] = finiteNonnegative(source[index]);
      if ((index & 0x3fff) === 0x3fff && work.shouldYield()) await work.checkpoint(true);
    }
    work.assertCurrent();
    return copy;
  }

  const output = new Float32Array(targetWidth * targetHeight * 4);
  const scaleX = sourceWidth / targetWidth;
  const scaleY = sourceHeight / targetHeight;
  for (let targetY = 0; targetY < targetHeight; targetY += 1) {
    const sourceY0 = targetY * scaleY;
    const sourceY1 = (targetY + 1) * scaleY;
    const firstSourceY = Math.floor(sourceY0);
    const finalSourceY = Math.ceil(sourceY1) - 1;
    for (let targetX = 0; targetX < targetWidth; targetX += 1) {
      const sourceX0 = targetX * scaleX;
      const sourceX1 = (targetX + 1) * scaleX;
      const firstSourceX = Math.floor(sourceX0);
      const finalSourceX = Math.ceil(sourceX1) - 1;
      const checkWithinSourceRows = (finalSourceX - firstSourceX + 1)
        * (finalSourceY - firstSourceY + 1) > 16_384;
      const sums = [0, 0, 0, 0];
      let totalWeight = 0;

      for (let sourceY = firstSourceY; sourceY <= finalSourceY; sourceY += 1) {
        const yWeight = Math.max(0, Math.min(sourceY + 1, sourceY1) - Math.max(sourceY, sourceY0));
        const clampedY = Math.max(0, Math.min(sourceHeight - 1, sourceY));
        for (let sourceX = firstSourceX; sourceX <= finalSourceX; sourceX += 1) {
          const xWeight = Math.max(0, Math.min(sourceX + 1, sourceX1) - Math.max(sourceX, sourceX0));
          const wrappedX = ((sourceX % sourceWidth) + sourceWidth) % sourceWidth;
          const weight = xWeight * yWeight;
          const sourceIndex = (clampedY * sourceWidth + wrappedX) * 4;
          for (let channel = 0; channel < 4; channel += 1) {
            sums[channel]! += finiteNonnegative(source[sourceIndex + channel]) * weight;
          }
          totalWeight += weight;
        }
        if (checkWithinSourceRows && work.shouldYield()) await work.checkpoint(true);
      }

      const outputIndex = (targetY * targetWidth + targetX) * 4;
      const inverseWeight = totalWeight > 0 ? 1 / totalWeight : 0;
      for (let channel = 0; channel < 4; channel += 1) {
        output[outputIndex + channel] = sums[channel]! * inverseWeight;
      }
      if ((targetX & 0xf) === 0xf && work.shouldYield()) await work.checkpoint(true);
    }
    if (work.shouldYield()) await work.checkpoint(true);
  }
  work.assertCurrent();
  return output;
}

function requireDownsample(
  source: Float32Array,
  sourceWidth: number,
  sourceHeight: number,
  targetWidth: number,
  targetHeight: number
): void {
  requireDimension(sourceWidth, 'Source width');
  requireDimension(sourceHeight, 'Source height');
  requireDimension(targetWidth, 'Target width');
  requireDimension(targetHeight, 'Target height');
  if (source.length !== sourceWidth * sourceHeight * 4) {
    throw new RangeError('Linear RGBA source length must equal width * height * 4.');
  }
  if (targetWidth > sourceWidth || targetHeight > sourceHeight) {
    throw new RangeError('Environment box filtering only supports downsampling.');
  }
}
import {
  CooperativeTextureWork,
  type CooperativeTextureWorkOptions
} from './cooperative-work';
