import type {HeightWindWeightOptions, WindWeightPositionInput} from './types';

function flattenAxis(positions: WindWeightPositionInput, axis: number): Float32Array {
  if (!positions || typeof positions !== 'object' || !Number.isSafeInteger(positions.length)) {
    throw new TypeError('wind positions must be an array-like collection');
  }
  const first = positions[0] as number | readonly number[] | undefined;
  if (typeof first === 'number' || first === undefined) {
    if (positions.length === 0 || positions.length % 3 !== 0) {
      throw new RangeError('wind positions must contain complete three-component vertices');
    }
    const output = new Float32Array(positions.length / 3);
    for (let vertex = 0; vertex < output.length; vertex += 1) {
      const value = (positions as ArrayLike<number>)[vertex * 3 + axis];
      if (value === undefined || !Number.isFinite(value)) throw new RangeError(`wind position ${vertex} must be finite`);
      output[vertex] = value;
    }
    return output;
  }
  if (positions.length === 0) throw new RangeError('wind positions must contain at least one vertex');
  const output = new Float32Array(positions.length);
  for (let vertex = 0; vertex < positions.length; vertex += 1) {
    const value = positions[vertex] as readonly number[] | undefined;
    const component = value?.[axis];
    if (!value || value.length !== 3 || component === undefined || !Number.isFinite(component)) {
      throw new RangeError(`wind position ${vertex} must contain three finite components`);
    }
    output[vertex] = component;
  }
  return output;
}

/** Creates anchored bend weights suitable for foliage, grass, hair, and flexible branches. */
export function createHeightWindWeights(
  positions: WindWeightPositionInput,
  options: HeightWindWeightOptions = {}
): Float32Array {
  const axis = options.axis ?? 'y';
  const axisIndex = axis === 'x' ? 0 : axis === 'y' ? 1 : 2;
  const coordinates = flattenAxis(positions, axisIndex);
  let minimum = Number.POSITIVE_INFINITY;
  let maximum = Number.NEGATIVE_INFINITY;
  for (const value of coordinates) {
    minimum = Math.min(minimum, value);
    maximum = Math.max(maximum, value);
  }
  const anchor = options.anchor ?? minimum;
  const fullBendAt = options.fullBendAt ?? maximum;
  const exponent = options.exponent ?? 1;
  const strength = options.strength ?? 1;
  if (!Number.isFinite(anchor)) throw new RangeError('wind anchor must be finite');
  if (!Number.isFinite(fullBendAt)) throw new RangeError('wind fullBendAt must be finite');
  if (!Number.isFinite(exponent) || exponent <= 0 || exponent > 16) throw new RangeError('wind exponent must be greater than zero and at most 16');
  if (!Number.isFinite(strength) || strength < 0 || strength > 1) throw new RangeError('wind strength must be from 0 through 1');
  const span = fullBendAt - anchor;
  const weights = new Float32Array(coordinates.length);
  if (Math.abs(span) <= 1e-10 || strength === 0) return weights;
  for (let index = 0; index < coordinates.length; index += 1) {
    const normalized = Math.max(0, Math.min(1, ((coordinates[index] ?? anchor) - anchor) / span));
    weights[index] = Math.pow(normalized, exponent) * strength;
  }
  return weights;
}
