import {MAX_WIND_DISPLACEMENT} from './scene/limits';

export const RASTER_SHADER = /* wgsl */ `
struct Globals {
  resolution_samples: vec4<f32>,
  output_mode: vec4<f32>,
  camera_position_tan_fov: vec4<f32>,
  camera_forward_exposure: vec4<f32>,
  camera_right_fog_density: vec4<f32>,
  camera_up_fog_height: vec4<f32>,
  fog_color_anisotropy: vec4<f32>,
  render_params: vec4<f32>,
  scene_counts: vec4<f32>,
  light_volume: vec4<f32>,
  previous_position_tan_fov: vec4<f32>,
  previous_forward: vec4<f32>,
  previous_right: vec4<f32>,
  previous_up: vec4<f32>,
  history_params: vec4<f32>,
  environment_params: vec4<f32>,
  ray_type_weights: vec4<f32>,
  path_controls: vec4<f32>,
  environment_texture_params: vec4<f32>,
  environment_irradiance_sh: array<vec4<f32>, 9>,
  environment_sunless_irradiance_sh: array<vec4<f32>, 9>,
  captured_sun_direction: vec4<f32>,
  captured_sun_irradiance: vec4<f32>,
  captured_sun_background_core: vec4<f32>,
  captured_sun_params: vec4<f32>,
  environment_orientation: vec4<f32>,
  backplate_texture_params: vec4<f32>,
  backplate_orientation: vec4<f32>,
  trace_dispatch_tile: vec4<f32>,
  cloud_bounds_min_mode: vec4<f32>,
  cloud_bounds_max_steps: vec4<f32>,
  cloud_scattering_albedo_extinction: vec4<f32>,
  cloud_density_anisotropy: vec4<f32>,
  camera_lens_params: vec4<f32>,
}

struct Triangle {
  v0: vec3<f32>,
  material_id: u32,
  edge1: vec3<f32>,
  wind_weight_0: f32,
  edge2: vec3<f32>,
  wind_weight_1: f32,
  normal_0: vec3<f32>,
  wind_weight_2: f32,
  normal_1: vec3<f32>,
  wind_amplitude: f32,
  normal_2: vec3<f32>,
  shadow_flags: u32,
  uv_0_1: vec4<f32>,
  uv_2_gradient_magnitudes: vec4<f32>,
}

struct Material {
  base_color: vec3<f32>,
  roughness: f32,
  emission_color: vec3<f32>,
  emission_strength: f32,
  metallic: f32,
  transmission: f32,
  ior: f32,
  alpha: f32,
  flags: u32,
  wind_influence: f32,
  color_variation: f32,
  detail_scale: f32,
  roughness_variation: f32,
  normal_strength: f32,
  pbr_texture_layers: vec2<u32>,
  texture_layer: u32,
  texture_flags: u32,
  uv_repeat: vec2<f32>,
  atlas_offset: vec2<f32>,
  atlas_scale: vec2<f32>,
  texture_strength: f32,
  texture_normal_strength: f32,
  texture_roughness_strength: f32,
  texture_lod: f32,
}

struct Light {
  vector: vec3<f32>,
  kind: u32,
  color: vec3<f32>,
  intensity: f32,
  range_or_angular_radius: f32,
  radius: f32,
  flags: u32,
  reserved: u32,
}

struct RasterVertexOutput {
  @builtin(position) clip_position: vec4<f32>,
  @location(0) world_position: vec3<f32>,
  @location(1) world_normal: vec3<f32>,
  @location(2) uv: vec2<f32>,
  @location(3) @interpolate(flat) material_id: u32,
  @location(4) previous_world_position: vec3<f32>,
}

struct RasterFragmentOutput {
  @location(0) hdr: vec4<f32>,
  @location(1) normal_depth: vec4<f32>,
  @location(2) albedo_roughness: vec4<f32>,
  @location(3) motion_reactive: vec4<f32>,
}

struct Surface {
  albedo: vec3<f32>,
  normal: vec3<f32>,
  roughness: f32,
  alpha: f32,
  metallic: f32,
}

struct SurfaceDerivatives {
  position_dx: vec3<f32>,
  position_dy: vec3<f32>,
  uv_dx: vec2<f32>,
  uv_dy: vec2<f32>,
}

struct DetailCoordinates {
  value: vec2<f32>,
  dx: vec2<f32>,
  dy: vec2<f32>,
}

@group(0) @binding(0) var<uniform> globals: Globals;
@group(0) @binding(1) var<storage, read> triangles: array<Triangle>;
@group(0) @binding(2) var<storage, read> materials: array<Material>;
@group(0) @binding(3) var<storage, read> lights: array<Light>;
@group(0) @binding(4) var material_textures: texture_2d_array<f32>;
@group(0) @binding(5) var material_linear_textures: texture_2d_array<f32>;
@group(0) @binding(6) var filtering_sampler: sampler;
@group(0) @binding(7) var environment_texture: texture_2d<f32>;
@group(0) @binding(8) var backplate_texture: texture_2d<f32>;

struct RasterShadowSettings {
  world_to_light: mat4x4<f32>,
  parameters: vec4<f32>,
}
@group(1) @binding(0) var<uniform> raster_shadow: RasterShadowSettings;
@group(1) @binding(1) var raster_shadow_depth: texture_depth_2d;
@group(1) @binding(2) var raster_shadow_sampler: sampler_comparison;

fn raster_shadow_visibility(position: vec3<f32>, light_index: u32) -> f32 {
  if (raster_shadow.parameters.x < 0.5 || light_index != u32(raster_shadow.parameters.y)) {
    return 1.0;
  }
  let clip = raster_shadow.world_to_light * vec4<f32>(position, 1.0);
  let uv = clip.xy * vec2<f32>(0.5, -0.5) + vec2<f32>(0.5);
  if (any(uv < vec2<f32>(0.0)) || any(uv > vec2<f32>(1.0)) || clip.z < 0.0 || clip.z > 1.0) {
    return 1.0;
  }
  var visibility = 0.0;
  for (var y = -1; y <= 1; y += 1) {
    for (var x = -1; x <= 1; x += 1) {
      visibility += textureSampleCompareLevel(
        raster_shadow_depth, raster_shadow_sampler,
        uv + vec2<f32>(f32(x), f32(y)) * raster_shadow.parameters.z,
        clip.z - raster_shadow.parameters.w
      );
    }
  }
  return visibility / 9.0;
}

const PI: f32 = 3.141592653589793;
const MAX_LIGHTS: u32 = 32u;
const MAX_SAFE_RADIANCE: f32 = 65504.0;
const MAX_WIND_DISPLACEMENT: f32 = ${MAX_WIND_DISPLACEMENT};
const MATERIAL_DOUBLE_SIDED: u32 = 1u;
const MATERIAL_FOLIAGE: u32 = 2u;
const MATERIAL_BARK: u32 = 4u;
const MATERIAL_GRASS: u32 = 8u;
const MATERIAL_GROUND: u32 = 16u;
const MATERIAL_PLASTER: u32 = 32u;
const MATERIAL_WOOD: u32 = 64u;
const MATERIAL_FABRIC: u32 = 128u;
const MATERIAL_GLASS: u32 = 256u;
const MATERIAL_UNLIT: u32 = 512u;
const NO_TEXTURE_LAYER: u32 = 0xffffffffu;
const MATERIAL_TEXTURE_BASE_COLOR: u32 = 1u;
const MATERIAL_TEXTURE_LUMINANCE_NORMAL: u32 = 2u;
const MATERIAL_TEXTURE_LUMINANCE_ROUGHNESS: u32 = 4u;
const MATERIAL_TEXTURE_INDEPENDENT_NORMAL: u32 = 8u;
const MATERIAL_TEXTURE_INDEPENDENT_ROUGHNESS: u32 = 16u;
const MATERIAL_TEXTURE_PACKED_METALLIC_ROUGHNESS: u32 = 32u;

fn safe_normalize(value: vec3<f32>, fallback: vec3<f32>) -> vec3<f32> {
  let length_squared = dot(value, value);
  if (length_squared <= 0.000000000001) {
    return fallback;
  }
  return value * inverseSqrt(length_squared);
}

fn sanitize_radiance(value: vec3<f32>) -> vec3<f32> {
  let finite = select(value, vec3<f32>(0.0), value != value);
  return clamp(finite, vec3<f32>(0.0), vec3<f32>(MAX_SAFE_RADIANCE));
}

fn fast_sine(value: f32) -> f32 {
  let wrapped = (fract(value / (2.0 * PI) + 0.5) - 0.5) * (2.0 * PI);
  let coarse = 1.27323954 * wrapped - 0.405284735 * wrapped * abs(wrapped);
  return 0.225 * (coarse * abs(coarse) - coarse) + coarse;
}

fn wind_waveform_at_time(position: vec3<f32>, animation_time: f32) -> vec3<f32> {
  var horizontal_direction = globals.history_params.yz;
  let horizontal_length_squared = dot(horizontal_direction, horizontal_direction);
  if (horizontal_length_squared <= 0.00000001) {
    horizontal_direction = vec2<f32>(1.0, 0.0);
  } else {
    horizontal_direction *= inverseSqrt(horizontal_length_squared);
  }
  let turbulence = clamp(globals.history_params.w, 0.0, 2.0);
  let time = max(animation_time, 0.0);
  let speed = max(globals.environment_params.w, 0.0);
  let perpendicular = vec2<f32>(-horizontal_direction.y, horizontal_direction.x);
  let along_wind = dot(position.xz, horizontal_direction);
  let across_wind = dot(position.xz, perpendicular);
  let phase = along_wind * 0.31 + time * speed
    + fast_sine(across_wind * 0.19 + time * 0.37) * turbulence;
  let wave_scalar = clamp(
    fast_sine(phase) * 0.62
      + fast_sine(phase * 1.73 + across_wind * 0.11 + 2.1) * 0.25
      + fast_sine(phase * 0.43 + position.y * 0.27 + 4.3) * 0.13,
    -1.0,
    1.0
  );
  let vertical_motion = fast_sine(phase * 1.31 + across_wind * 0.23) * turbulence * 0.12;
  let direction = safe_normalize(
    vec3<f32>(horizontal_direction.x, vertical_motion, horizontal_direction.y),
    vec3<f32>(horizontal_direction.x, 0.0, horizontal_direction.y)
  );
  return direction * wave_scalar;
}

fn wind_displacement_at_time(
  position: vec3<f32>,
  weight: f32,
  amplitude: f32,
  animation_time: f32
) -> vec3<f32> {
  let strength = clamp(globals.environment_params.z / MAX_WIND_DISPLACEMENT, 0.0, 1.0);
  let weighted_amplitude = max(amplitude, 0.0) * clamp(weight, 0.0, 1.0) * strength;
  if (weighted_amplitude <= 0.0) {
    return vec3<f32>(0.0);
  }
  return wind_waveform_at_time(position, animation_time) * weighted_amplitude;
}

fn wind_displacement(position: vec3<f32>, weight: f32, amplitude: f32) -> vec3<f32> {
  return wind_displacement_at_time(
    position,
    weight,
    amplitude,
    globals.environment_params.y
  );
}

fn world_to_clip(position: vec3<f32>) -> vec4<f32> {
  let relative = position - globals.camera_position_tan_fov.xyz;
  let view_depth = dot(relative, globals.camera_forward_exposure.xyz);
  let aspect = globals.resolution_samples.x / max(globals.resolution_samples.y, 1.0);
  let tan_fov = max(globals.camera_position_tan_fov.w, 0.000001);
  let near_plane = 0.01;
  let far_plane = 10000.0;
  var clip = vec4<f32>(
    dot(relative, globals.camera_right_fog_density.xyz) / (tan_fov * aspect),
    dot(relative, globals.camera_up_fog_height.xyz) / tan_fov,
    view_depth * far_plane / (far_plane - near_plane)
      - near_plane * far_plane / (far_plane - near_plane),
    view_depth
  );
  let jitter = globals.render_params.xy * clamp(globals.output_mode.w, 0.0, 1.0);
  clip.x -= 2.0 * jitter.x * view_depth / max(globals.resolution_samples.x, 1.0);
  clip.y += 2.0 * jitter.y * view_depth / max(globals.resolution_samples.y, 1.0);
  return clip;
}

fn triangle_position(triangle: Triangle, corner: u32) -> vec3<f32> {
  if (corner == 1u) {
    return triangle.v0 + triangle.edge1;
  }
  if (corner == 2u) {
    return triangle.v0 + triangle.edge2;
  }
  return triangle.v0;
}

fn triangle_normal(triangle: Triangle, corner: u32) -> vec3<f32> {
  if (corner == 1u) {
    return triangle.normal_1;
  }
  if (corner == 2u) {
    return triangle.normal_2;
  }
  return triangle.normal_0;
}

fn triangle_uv(triangle: Triangle, corner: u32) -> vec2<f32> {
  if (corner == 1u) {
    return triangle.uv_0_1.zw;
  }
  if (corner == 2u) {
    return triangle.uv_2_gradient_magnitudes.xy;
  }
  return triangle.uv_0_1.xy;
}

fn triangle_wind_weight(triangle: Triangle, corner: u32) -> f32 {
  if (corner == 1u) {
    return triangle.wind_weight_1;
  }
  if (corner == 2u) {
    return triangle.wind_weight_2;
  }
  return triangle.wind_weight_0;
}

@vertex
fn raster_vertex(@builtin(vertex_index) vertex_index: u32) -> RasterVertexOutput {
  let triangle = triangles[vertex_index / 3u];
  let corner = vertex_index % 3u;
  let base_position = triangle_position(triangle, corner);
  let wind_weight = triangle_wind_weight(triangle, corner);
  let position = base_position + wind_displacement(
    base_position,
    wind_weight,
    triangle.wind_amplitude
  );
  let previous_animation_time = max(globals.environment_params.y - 1.0 / 60.0, 0.0);
  let previous_position = base_position + wind_displacement_at_time(
    base_position,
    wind_weight,
    triangle.wind_amplitude,
    previous_animation_time
  );
  var output: RasterVertexOutput;
  output.clip_position = world_to_clip(position);
  output.world_position = position;
  output.world_normal = triangle_normal(triangle, corner);
  output.uv = triangle_uv(triangle, corner);
  output.material_id = triangle.material_id;
  output.previous_world_position = previous_position;
  return output;
}

@vertex
fn shadow_vertex(@builtin(vertex_index) vertex_index: u32) -> RasterVertexOutput {
  let triangle = triangles[vertex_index / 3u];
  let corner = vertex_index % 3u;
  let base_position = triangle_position(triangle, corner);
  let position = base_position + wind_displacement(base_position, triangle_wind_weight(triangle, corner), triangle.wind_amplitude);
  var output: RasterVertexOutput;
  output.clip_position = raster_shadow.world_to_light * vec4<f32>(position, 1.0);
  output.world_position = position;
  output.world_normal = triangle_normal(triangle, corner);
  output.uv = triangle_uv(triangle, corner);
  output.material_id = triangle.material_id;
  output.previous_world_position = position;
  return output;
}

@vertex
fn background_vertex(@builtin(vertex_index) vertex_index: u32) -> @builtin(position) vec4<f32> {
  let positions = array<vec2<f32>, 3>(
    vec2<f32>(-1.0, -1.0),
    vec2<f32>(3.0, -1.0),
    vec2<f32>(-1.0, 3.0)
  );
  return vec4<f32>(positions[vertex_index], 1.0, 1.0);
}

fn environment_source_direction(world_direction: vec3<f32>) -> vec3<f32> {
  let safe_direction = safe_normalize(world_direction, vec3<f32>(0.0, 1.0, 0.0));
  let yaw = globals.environment_texture_params.z;
  let yaw_cosine = cos(yaw);
  let yaw_sine = sin(yaw);
  let yaw_direction = vec3<f32>(
    yaw_cosine * safe_direction.x - yaw_sine * safe_direction.z,
    safe_direction.y,
    yaw_sine * safe_direction.x + yaw_cosine * safe_direction.z
  );
  return vec3<f32>(
    yaw_direction.x,
    globals.environment_orientation.y * yaw_direction.y
      - globals.environment_orientation.z * yaw_direction.z,
    globals.environment_orientation.z * yaw_direction.y
      + globals.environment_orientation.y * yaw_direction.z
  );
}

fn backplate_source_direction(world_direction: vec3<f32>) -> vec3<f32> {
  let safe_direction = safe_normalize(world_direction, vec3<f32>(0.0, 1.0, 0.0));
  let yaw = globals.backplate_texture_params.z;
  let yaw_cosine = cos(yaw);
  let yaw_sine = sin(yaw);
  let yaw_direction = vec3<f32>(
    yaw_cosine * safe_direction.x - yaw_sine * safe_direction.z,
    safe_direction.y,
    yaw_sine * safe_direction.x + yaw_cosine * safe_direction.z
  );
  return vec3<f32>(
    yaw_direction.x,
    globals.backplate_orientation.y * yaw_direction.y
      - globals.backplate_orientation.z * yaw_direction.z,
    globals.backplate_orientation.z * yaw_direction.y
      + globals.backplate_orientation.y * yaw_direction.z
  );
}

fn equirectangular_uv(direction: vec3<f32>, dimensions: vec2<u32>) -> vec2<f32> {
  let half_texel_v = 0.5 / max(f32(dimensions.y), 1.0);
  return vec2<f32>(
    fract(atan2(direction.z, direction.x) / (2.0 * PI) + 0.5),
    clamp(
      acos(clamp(direction.y, -1.0, 1.0)) / PI,
      half_texel_v,
      1.0 - half_texel_v
    )
  );
}

fn procedural_environment(direction: vec3<f32>) -> vec3<f32> {
  let sky_factor = smoothstep(-0.15, 0.8, direction.y);
  let sky = mix(
    vec3<f32>(0.78, 0.87, 1.02),
    vec3<f32>(0.12, 0.32, 0.82),
    sky_factor
  );
  return mix(vec3<f32>(0.035, 0.045, 0.065), sky, smoothstep(-0.18, 0.18, direction.y));
}

fn physical_environment_raw(direction: vec3<f32>, roughness: f32) -> vec3<f32> {
  var result = procedural_environment(direction);
  if (globals.environment_texture_params.x > 0.5) {
    let maximum_lod = f32(max(textureNumLevels(environment_texture), 1u) - 1u);
    let lod = clamp(roughness * roughness * maximum_lod, 0.0, maximum_lod);
    let dimensions = textureDimensions(environment_texture, i32(ceil(lod)));
    let source_direction = environment_source_direction(direction);
    result = max(textureSampleLevel(
      environment_texture,
      filtering_sampler,
      equirectangular_uv(source_direction, dimensions),
      lod
    ).rgb, vec3<f32>(0.0)) * max(globals.environment_texture_params.y, 0.0);
  }
  return sanitize_radiance(result * max(globals.environment_params.x, 0.0));
}

fn captured_sun_matching_active() -> bool {
  return globals.captured_sun_direction.w > 0.5
    && globals.captured_sun_params.w > 0.5
    && globals.environment_texture_params.x > 0.5;
}

fn captured_sun_world_direction() -> vec3<f32> {
  return safe_normalize(
    globals.captured_sun_direction.xyz,
    vec3<f32>(0.0, 1.0, 0.0)
  );
}

fn captured_sun_environment_scale() -> f32 {
  return max(globals.environment_texture_params.y, 0.0)
    * max(globals.environment_params.x, 0.0);
}

fn captured_environment_sun_irradiance() -> vec3<f32> {
  if (!captured_sun_matching_active()) {
    return vec3<f32>(0.0);
  }
  return max(globals.captured_sun_irradiance.xyz, vec3<f32>(0.0))
    * captured_sun_environment_scale();
}

fn remove_captured_sun_from_environment(
  full_environment: vec3<f32>,
  direction: vec3<f32>,
  roughness: f32
) -> vec3<f32> {
  if (!captured_sun_matching_active()) {
    return full_environment;
  }
  let sun_direction = captured_sun_world_direction();
  let alignment = dot(safe_normalize(direction, sun_direction), sun_direction);
  let stored_core = clamp(
    globals.captured_sun_background_core.w,
    0.0001,
    PI - 0.001
  );
  let stored_extraction = clamp(
    max(globals.captured_sun_params.x, stored_core + 0.0001),
    stored_core + 0.0001,
    PI - 0.0001
  );
  // Prefiltered environment mips spread the captured disc beyond its source
  // pixels. Expand the removal cone with roughness so the matching analytic
  // directional light remains the sole solar-energy contribution.
  let extraction = clamp(
    stored_extraction + clamp(roughness, 0.0, 1.0)
      * clamp(roughness, 0.0, 1.0) * 0.35,
    stored_core + 0.0001,
    PI - 0.0001
  );
  let spatial_weight = smoothstep(cos(extraction), cos(stored_core), alignment);
  let local_background = max(
    globals.captured_sun_background_core.xyz,
    vec3<f32>(0.0)
  ) * captured_sun_environment_scale();
  let captured_excess = max(full_environment - local_background, vec3<f32>(0.0));
  return max(full_environment - captured_excess * spatial_weight, vec3<f32>(0.0));
}

fn physical_environment(direction: vec3<f32>, roughness: f32) -> vec3<f32> {
  let full_environment = physical_environment_raw(direction, roughness);
  return sanitize_radiance(remove_captured_sun_from_environment(
    full_environment,
    direction,
    roughness
  ));
}

fn diffuse_environment_sh_coefficient(index: u32) -> vec3<f32> {
  if (captured_sun_matching_active()) {
    return globals.environment_sunless_irradiance_sh[index].xyz;
  }
  return globals.environment_irradiance_sh[index].xyz;
}

fn diffuse_environment_irradiance(normal_value: vec3<f32>) -> vec3<f32> {
  let normal = safe_normalize(normal_value, vec3<f32>(0.0, 1.0, 0.0));
  if (globals.environment_texture_params.x <= 0.5) {
    let local_sky = physical_environment_raw(normal, 0.92);
    let upper_sky = physical_environment_raw(vec3<f32>(0.0, 1.0, 0.0), 0.92);
    return sanitize_radiance((local_sky * 0.72 + upper_sky * 0.28) * PI);
  }

  let direction = environment_source_direction(normal);
  let x = direction.x;
  let y = direction.y;
  let z = direction.z;
  var irradiance = diffuse_environment_sh_coefficient(0u) * 0.2820947918;
  irradiance += diffuse_environment_sh_coefficient(1u) * (0.4886025119 * y);
  irradiance += diffuse_environment_sh_coefficient(2u) * (0.4886025119 * z);
  irradiance += diffuse_environment_sh_coefficient(3u) * (0.4886025119 * x);
  irradiance += diffuse_environment_sh_coefficient(4u) * (1.0925484306 * x * y);
  irradiance += diffuse_environment_sh_coefficient(5u) * (1.0925484306 * y * z);
  irradiance += diffuse_environment_sh_coefficient(6u) * (0.3153915653 * (3.0 * z * z - 1.0));
  irradiance += diffuse_environment_sh_coefficient(7u) * (1.0925484306 * x * z);
  irradiance += diffuse_environment_sh_coefficient(8u) * (0.5462742153 * (x * x - y * y));
  return sanitize_radiance(
    max(irradiance, vec3<f32>(0.0)) * captured_sun_environment_scale()
  );
}

fn camera_background(direction: vec3<f32>) -> vec3<f32> {
  if (globals.backplate_texture_params.x > 0.5) {
    let maximum_lod = f32(max(textureNumLevels(backplate_texture), 1u) - 1u);
    let vertical_fov = 2.0 * atan(max(globals.camera_position_tan_fov.w, 0.000001));
    let dimensions = textureDimensions(backplate_texture, 0);
    let footprint = vertical_fov * f32(dimensions.y)
      / (PI * max(globals.resolution_samples.y, 1.0));
    let lod = clamp(log2(max(footprint, 1.0)), 0.0, maximum_lod);
    let lod_dimensions = textureDimensions(backplate_texture, i32(ceil(lod)));
    let source_direction = backplate_source_direction(direction);
    return sanitize_radiance(max(textureSampleLevel(
      backplate_texture,
      filtering_sampler,
      equirectangular_uv(source_direction, lod_dimensions),
      lod
    ).rgb, vec3<f32>(0.0)) * max(globals.backplate_texture_params.y, 0.0));
  }
  // Camera-visible HDR retains its photographed solar disc. Material lighting
  // uses the partitioned environment plus the matching directional light.
  return physical_environment_raw(direction, 0.0);
}

fn camera_direction(fragment_position: vec2<f32>) -> vec3<f32> {
  let jitter = globals.render_params.xy * clamp(globals.output_mode.w, 0.0, 1.0);
  let screen = ((fragment_position + jitter) / globals.resolution_samples.xy)
    * 2.0 - vec2<f32>(1.0);
  let aspect = globals.resolution_samples.x / max(globals.resolution_samples.y, 1.0);
  return safe_normalize(
    globals.camera_forward_exposure.xyz
      + globals.camera_right_fog_density.xyz
        * (screen.x * aspect * globals.camera_position_tan_fov.w)
      - globals.camera_up_fog_height.xyz
        * (screen.y * globals.camera_position_tan_fov.w),
    globals.camera_forward_exposure.xyz
  );
}

fn project_previous_uv(position: vec3<f32>) -> vec3<f32> {
  let relative = position - globals.previous_position_tan_fov.xyz;
  let view_depth = dot(relative, globals.previous_forward.xyz);
  let safe_depth = max(view_depth, 0.0001);
  let aspect = globals.output_mode.x / max(globals.output_mode.y, 1.0);
  let ndc = vec2<f32>(
    dot(relative, globals.previous_right.xyz)
      / (safe_depth * globals.previous_position_tan_fov.w * aspect),
    -dot(relative, globals.previous_up.xyz)
      / (safe_depth * globals.previous_position_tan_fov.w)
  );
  let previous_jitter = vec2<f32>(globals.previous_forward.w, globals.previous_right.w);
  return vec3<f32>(
    ndc * 0.5 + vec2<f32>(0.5)
      - previous_jitter / max(globals.resolution_samples.xy, vec2<f32>(1.0)),
    view_depth
  );
}

fn project_previous_direction_uv(direction: vec3<f32>) -> vec3<f32> {
  let view_depth = dot(direction, globals.previous_forward.xyz);
  let safe_depth = max(view_depth, 0.0001);
  let aspect = globals.output_mode.x / max(globals.output_mode.y, 1.0);
  let ndc = vec2<f32>(
    dot(direction, globals.previous_right.xyz)
      / (safe_depth * globals.previous_position_tan_fov.w * aspect),
    -dot(direction, globals.previous_up.xyz)
      / (safe_depth * globals.previous_position_tan_fov.w)
  );
  let previous_jitter = vec2<f32>(globals.previous_forward.w, globals.previous_right.w);
  return vec3<f32>(
    ndc * 0.5 + vec2<f32>(0.5)
      - previous_jitter / max(globals.resolution_samples.xy, vec2<f32>(1.0)),
    view_depth
  );
}

fn sample_material_color(
  material: Material,
  uv: vec2<f32>,
  lod: f32,
  uv_dx: vec2<f32>,
  uv_dy: vec2<f32>
) -> vec4<f32> {
  let layer_count = max(textureNumLayers(material_textures), 1u);
  let layer = i32(min(material.texture_layer, layer_count - 1u));
  if (globals.environment_texture_params.w > 0.5) {
    return textureSampleGrad(
      material_textures,
      filtering_sampler,
      uv,
      layer,
      uv_dx * exp2(lod),
      uv_dy * exp2(lod)
    );
  }
  return textureSampleLevel(material_textures, filtering_sampler, uv, layer, lod);
}

fn sample_material_linear(
  layer_value: u32,
  uv: vec2<f32>,
  lod: f32,
  uv_dx: vec2<f32>,
  uv_dy: vec2<f32>
) -> vec4<f32> {
  let layer_count = max(textureNumLayers(material_linear_textures), 1u);
  let layer = i32(min(layer_value, layer_count - 1u));
  if (globals.environment_texture_params.w > 0.5) {
    return textureSampleGrad(
      material_linear_textures,
      filtering_sampler,
      uv,
      layer,
      uv_dx * exp2(lod),
      uv_dy * exp2(lod)
    );
  }
  return textureSampleLevel(material_linear_textures, filtering_sampler, uv, layer, lod);
}

fn mapped_normal(
  geometric_normal: vec3<f32>,
  world_position: vec3<f32>,
  uv: vec2<f32>,
  encoded_normal: vec3<f32>,
  strength: f32,
  derivatives: SurfaceDerivatives
) -> vec3<f32> {
  let position_dx = derivatives.position_dx;
  let position_dy = derivatives.position_dy;
  let uv_dx = derivatives.uv_dx;
  let uv_dy = derivatives.uv_dy;
  let determinant = uv_dx.x * uv_dy.y - uv_dx.y * uv_dy.x;
  if (abs(determinant) <= 0.00000001) {
    return geometric_normal;
  }
  let tangent_unprojected = safe_normalize(
    (position_dx * uv_dy.y - position_dy * uv_dx.y) / determinant,
    vec3<f32>(1.0, 0.0, 0.0)
  );
  let tangent = safe_normalize(
    tangent_unprojected - geometric_normal * dot(geometric_normal, tangent_unprojected),
    vec3<f32>(1.0, 0.0, 0.0)
  );
  let handedness = select(-1.0, 1.0, determinant > 0.0);
  let bitangent = safe_normalize(
    cross(geometric_normal, tangent) * handedness,
    vec3<f32>(0.0, 0.0, 1.0)
  );
  let tangent_normal = vec3<f32>(
    (encoded_normal.x * 2.0 - 1.0) * strength,
    (encoded_normal.y * 2.0 - 1.0) * strength,
    max(encoded_normal.z * 2.0 - 1.0, 0.0001)
  );
  return safe_normalize(
    tangent * tangent_normal.x
      + bitangent * tangent_normal.y
      + geometric_normal * tangent_normal.z,
    geometric_normal
  );
}

fn stable_detail_coordinates(
  position: vec3<f32>,
  normal_value: vec3<f32>,
  uv: vec2<f32>,
  derivatives: SurfaceDerivatives
) -> DetailCoordinates {
  let uv_footprint = max(length(derivatives.uv_dx), length(derivatives.uv_dy));
  if (uv_footprint > 0.0000001) {
    return DetailCoordinates(uv, derivatives.uv_dx, derivatives.uv_dy);
  }
  let absolute_normal = abs(normal_value);
  if (absolute_normal.y >= absolute_normal.x && absolute_normal.y >= absolute_normal.z) {
    return DetailCoordinates(
      position.xz,
      derivatives.position_dx.xz,
      derivatives.position_dy.xz
    );
  }
  if (absolute_normal.x >= absolute_normal.z) {
    return DetailCoordinates(
      position.yz,
      derivatives.position_dx.yz,
      derivatives.position_dy.yz
    );
  }
  return DetailCoordinates(
    position.xy,
    derivatives.position_dx.xy,
    derivatives.position_dy.xy
  );
}

fn detail_octave_visibility(footprint: f32, frequency: f32) -> f32 {
  return 1.0 - smoothstep(0.18, 0.72, max(footprint, 0.0) * frequency);
}

fn detail_material_response(material: Material) -> vec4<f32> {
  if ((material.flags & MATERIAL_FOLIAGE) != 0u) {
    return vec4<f32>(0.15, 0.12, 0.12, 0.50);
  }
  if ((material.flags & MATERIAL_BARK) != 0u) {
    return vec4<f32>(0.14, 0.15, 0.18, 0.58);
  }
  if ((material.flags & MATERIAL_GRASS) != 0u) {
    return vec4<f32>(0.13, 0.12, 0.12, 0.55);
  }
  if ((material.flags & MATERIAL_GROUND) != 0u) {
    return vec4<f32>(0.075, 0.13, 0.09, 0.48);
  }
  if ((material.flags & MATERIAL_PLASTER) != 0u) {
    return vec4<f32>(0.055, 0.08, 0.11, 0.48);
  }
  if ((material.flags & MATERIAL_WOOD) != 0u) {
    return vec4<f32>(0.12, 0.10, 0.14, 0.18);
  }
  if ((material.flags & MATERIAL_FABRIC) != 0u) {
    return vec4<f32>(0.07, 0.12, 0.16, 0.55);
  }
  if ((material.flags & MATERIAL_GLASS) != 0u) {
    return vec4<f32>(0.004, 0.08, 0.018, 0.02);
  }
  return vec4<f32>(0.02, 0.055, 0.055, 0.02);
}

fn procedural_detail_signals(
  material: Material,
  coordinates: DetailCoordinates
) -> vec4<f32> {
  let scale = clamp(material.detail_scale, 0.001, 10000.0);
  let position = coordinates.value * scale;
  let footprint = max(length(coordinates.dx), length(coordinates.dy)) * scale;
  let broad_visibility = detail_octave_visibility(footprint, 0.347);
  let medium_visibility = detail_octave_visibility(footprint, 1.731);
  let fine_visibility = detail_octave_visibility(footprint, 6.613);
  let broad = fast_sine(dot(position, vec2<f32>(0.819172, 0.480871)) + 1.173)
    * broad_visibility;
  let medium = fast_sine(dot(position, vec2<f32>(-1.37191, 1.90713)) + broad * 0.73 + 3.719)
    * medium_visibility;
  let fine = fast_sine(dot(position, vec2<f32>(5.7317, 3.1739)) + medium * 0.41 + 5.317)
    * fine_visibility;
  var color_signal = clamp(broad * 0.52 + medium * 0.31 + fine * 0.17, -1.0, 1.0);
  var roughness_signal = clamp(broad * 0.22 + medium * 0.49 + fine * 0.29, -1.0, 1.0);
  var normal_x = medium * 0.63 + fine * 0.37;
  var normal_y = fast_sine(dot(position, vec2<f32>(2.357, -4.193)) + broad * 0.37)
    * max(medium_visibility, fine_visibility);

  if ((material.flags & MATERIAL_FOLIAGE) != 0u) {
    let veins = fast_sine(position.x * 5.17 + abs(position.y) * 1.13)
      * fine_visibility;
    color_signal = clamp(broad * 0.57 + medium * 0.29 + veins * 0.14, -1.0, 1.0);
    roughness_signal = clamp(medium * 0.62 + veins * 0.38, -1.0, 1.0);
    normal_x = medium * 0.54 + veins * 0.46;
    normal_y = fine * 0.58 - veins * 0.42;
  } else if ((material.flags & MATERIAL_BARK) != 0u) {
    let ridges = fast_sine(position.x * 1.31 + position.y * 6.71 + broad * 0.91)
      * medium_visibility;
    color_signal = clamp(broad * 0.42 + ridges * 0.58, -1.0, 1.0);
    roughness_signal = clamp(medium * 0.37 + abs(ridges) * 0.63 - 0.3, -1.0, 1.0);
    normal_x = medium * 0.31 + ridges * 0.69;
    normal_y = fine * 0.47 - ridges * 0.53;
  } else if ((material.flags & MATERIAL_GRASS) != 0u) {
    let blades = fast_sine(position.x * 3.1 + position.y * 4.7 + medium * 0.61)
      * medium_visibility;
    color_signal = clamp(broad * 0.46 + medium * 0.28 + blades * 0.26, -1.0, 1.0);
    roughness_signal = clamp(medium * 0.58 + abs(blades) * 0.42 - 0.21, -1.0, 1.0);
    normal_x = blades;
    normal_y = fine * 0.53 + medium * 0.47;
  } else if ((material.flags & MATERIAL_WOOD) != 0u) {
    let growth = fast_sine(position.y * 0.617 + broad * 0.93) * broad_visibility;
    let grain = fast_sine(position.x * 7.137 + position.y * 0.137 + growth * 0.61)
      * medium_visibility;
    color_signal = clamp(growth * 0.43 + grain * 0.39 + fine * 0.18, -1.0, 1.0);
    roughness_signal = clamp(grain * 0.58 + medium * 0.29 + fine * 0.13, -1.0, 1.0);
    normal_x = grain * 0.78 + fine * 0.22;
    normal_y = growth * 0.42 + medium * 0.58;
  } else if ((material.flags & MATERIAL_FABRIC) != 0u) {
    let warp = fast_sine(position.x * 6.2831853 + broad * 0.43) * medium_visibility;
    let weft = fast_sine(position.y * 6.4076169 - broad * 0.37) * medium_visibility;
    let weave = warp * weft;
    color_signal = clamp(weave * 0.54 + broad * 0.28 + fine * 0.18, -1.0, 1.0);
    roughness_signal = clamp((abs(warp - weft) - 0.45) * 0.67 + fine * 0.33, -1.0, 1.0);
    normal_x = warp * 0.81 + fine * 0.19;
    normal_y = weft * 0.81 - fine * 0.19;
  } else if ((material.flags & MATERIAL_GLASS) != 0u) {
    let scratch = pow(
      clamp(1.0 - abs(fast_sine(position.x * 18.711 + position.y * 1.37 + broad)), 0.0, 1.0),
      12.0
    ) * fine_visibility;
    color_signal = clamp(broad * 0.12 - scratch * 0.88, -1.0, 1.0);
    roughness_signal = clamp(medium * 0.18 + scratch * 0.82, -1.0, 1.0);
    normal_x = scratch;
    normal_y = fine * 0.12;
  }
  return vec4<f32>(
    color_signal,
    roughness_signal,
    clamp(normal_x, -1.0, 1.0),
    clamp(normal_y, -1.0, 1.0)
  );
}

fn bounded_micro_albedo(
  base_albedo: vec3<f32>,
  centered_signal: f32,
  amount: f32,
  maximum_contrast: f32
) -> vec3<f32> {
  let bounded_base = clamp(base_albedo, vec3<f32>(0.0), vec3<f32>(1.0));
  let signal = clamp(centered_signal, -1.0, 1.0);
  let contrast = clamp(maximum_contrast, 0.0, 0.2);
  let darker = bounded_base * (1.0 - contrast);
  let lighter = bounded_base + (vec3<f32>(1.0) - bounded_base) * contrast;
  var micro_target = mix(bounded_base, darker, max(-signal, 0.0));
  if (signal > 0.0) {
    micro_target = mix(bounded_base, lighter, signal);
  }
  return clamp(
    mix(bounded_base, micro_target, clamp(amount, 0.0, 1.0)),
    vec3<f32>(0.0),
    vec3<f32>(1.0)
  );
}

fn procedural_mapped_normal(
  normal_value: vec3<f32>,
  derivatives: SurfaceDerivatives,
  coordinates: DetailCoordinates,
  tangent_signal: vec2<f32>
) -> vec3<f32> {
  if (dot(tangent_signal, tangent_signal) <= 0.00000001) {
    return normal_value;
  }
  let determinant = coordinates.dx.x * coordinates.dy.y
    - coordinates.dx.y * coordinates.dy.x;
  var tangent: vec3<f32>;
  var bitangent: vec3<f32>;
  if (abs(determinant) > 0.00000001) {
    let candidate = (
      derivatives.position_dx * coordinates.dy.y
        - derivatives.position_dy * coordinates.dx.y
    ) / determinant;
    tangent = safe_normalize(
      candidate - normal_value * dot(normal_value, candidate),
      vec3<f32>(1.0, 0.0, 0.0)
    );
    let handedness = select(-1.0, 1.0, determinant > 0.0);
    bitangent = safe_normalize(
      cross(normal_value, tangent) * handedness,
      vec3<f32>(0.0, 0.0, 1.0)
    );
  } else {
    let helper = select(
      vec3<f32>(0.0, 1.0, 0.0),
      vec3<f32>(1.0, 0.0, 0.0),
      abs(normal_value.y) > 0.98
    );
    tangent = safe_normalize(cross(helper, normal_value), vec3<f32>(1.0, 0.0, 0.0));
    bitangent = safe_normalize(cross(normal_value, tangent), vec3<f32>(0.0, 0.0, 1.0));
  }
  return safe_normalize(
    normal_value + tangent * tangent_signal.x + bitangent * tangent_signal.y,
    normal_value
  );
}

fn material_surface(
  material: Material,
  world_position: vec3<f32>,
  interpolated_normal: vec3<f32>,
  source_uv: vec2<f32>,
  derivatives: SurfaceDerivatives
) -> Surface {
  let maximum_lod = f32(max(textureNumLevels(material_textures), 1u) - 1u);
  let lod = clamp(material.texture_lod, 0.0, maximum_lod);
  let uv_repeat = max(material.uv_repeat, vec2<f32>(0.0001));
  let repeated = fract(source_uv * uv_repeat);
  let atlas_scale = clamp(material.atlas_scale, vec2<f32>(0.0001), vec2<f32>(1.0));
  let atlas_offset = clamp(material.atlas_offset, vec2<f32>(0.0), vec2<f32>(1.0));
  let texture_derivatives = SurfaceDerivatives(
    derivatives.position_dx,
    derivatives.position_dy,
    derivatives.uv_dx * uv_repeat * atlas_scale,
    derivatives.uv_dy * uv_repeat * atlas_scale
  );
  let lod_dimensions = vec2<f32>(textureDimensions(material_textures, i32(ceil(lod))));
  let half_texel = 0.5 / max(lod_dimensions, vec2<f32>(1.0));
  let uv = clamp(
    repeated * atlas_scale + atlas_offset,
    atlas_offset + half_texel,
    atlas_offset + atlas_scale - half_texel
  );
  var albedo = max(material.base_color, vec3<f32>(0.0));
  var alpha = clamp(material.alpha, 0.0, 1.0);
  var roughness = clamp(material.roughness, 0.02, 1.0);
  var metallic = clamp(material.metallic, 0.0, 1.0);
  let geometric_normal = safe_normalize(interpolated_normal, vec3<f32>(0.0, 1.0, 0.0));
  var normal = geometric_normal;
  if ((material.texture_flags & MATERIAL_TEXTURE_BASE_COLOR) != 0u
      && material.texture_layer != NO_TEXTURE_LAYER) {
    let sampled = sample_material_color(
      material,
      uv,
      lod,
      texture_derivatives.uv_dx,
      texture_derivatives.uv_dy
    );
    albedo = mix(albedo, albedo * max(sampled.rgb, vec3<f32>(0.0)), clamp(material.texture_strength, 0.0, 1.0));
    alpha *= sampled.a;
  }
  if ((material.texture_flags & MATERIAL_TEXTURE_PACKED_METALLIC_ROUGHNESS) != 0u
      && material.pbr_texture_layers.y != NO_TEXTURE_LAYER) {
    let maps = sample_material_linear(material.pbr_texture_layers.y, uv, lod,
      texture_derivatives.uv_dx, texture_derivatives.uv_dy);
    let map_strength = clamp(material.texture_roughness_strength, 0.0, 1.0);
    roughness = clamp(mix(roughness, material.roughness * clamp(maps.g, 0.0, 1.0), map_strength), 0.02, 1.0);
    metallic = clamp(mix(metallic, material.metallic * clamp(maps.b, 0.0, 1.0), map_strength), 0.0, 1.0);
  } else if ((material.texture_flags & MATERIAL_TEXTURE_INDEPENDENT_ROUGHNESS) != 0u
      && material.pbr_texture_layers.y != NO_TEXTURE_LAYER) {
    let mapped = sample_material_linear(
      material.pbr_texture_layers.y,
      uv,
      lod,
      texture_derivatives.uv_dx,
      texture_derivatives.uv_dy
    ).r;
    roughness = mix(roughness, clamp(mapped, 0.02, 1.0), clamp(material.texture_roughness_strength, 0.0, 1.0));
  } else if ((material.texture_flags & MATERIAL_TEXTURE_LUMINANCE_ROUGHNESS) != 0u
      && material.texture_layer != NO_TEXTURE_LAYER) {
    let mapped = dot(
      sample_material_color(
        material,
        uv,
        lod,
        texture_derivatives.uv_dx,
        texture_derivatives.uv_dy
      ).rgb,
      vec3<f32>(0.2126, 0.7152, 0.0722)
    );
    roughness = mix(roughness, clamp(mapped, 0.02, 1.0), clamp(material.texture_roughness_strength, 0.0, 1.0));
  }
  if ((material.texture_flags & MATERIAL_TEXTURE_INDEPENDENT_NORMAL) != 0u
      && material.pbr_texture_layers.x != NO_TEXTURE_LAYER
      && material.texture_normal_strength > 0.000001) {
    normal = mapped_normal(
      normal,
      world_position,
      uv,
      sample_material_linear(
        material.pbr_texture_layers.x,
        uv,
        lod,
        texture_derivatives.uv_dx,
        texture_derivatives.uv_dy
      ).rgb,
      clamp(material.texture_normal_strength, 0.0, 4.0),
      texture_derivatives
    );
  } else if ((material.texture_flags & MATERIAL_TEXTURE_LUMINANCE_NORMAL) != 0u
      && material.texture_layer != NO_TEXTURE_LAYER
      && material.texture_normal_strength > 0.000001) {
    let dimensions = max(lod_dimensions, vec2<f32>(1.0));
    let texel = vec2<f32>(1.0) / dimensions;
    let left = dot(sample_material_color(material, uv - vec2<f32>(texel.x, 0.0), lod, texture_derivatives.uv_dx, texture_derivatives.uv_dy).rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let right = dot(sample_material_color(material, uv + vec2<f32>(texel.x, 0.0), lod, texture_derivatives.uv_dx, texture_derivatives.uv_dy).rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let down = dot(sample_material_color(material, uv - vec2<f32>(0.0, texel.y), lod, texture_derivatives.uv_dx, texture_derivatives.uv_dy).rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let up = dot(sample_material_color(material, uv + vec2<f32>(0.0, texel.y), lod, texture_derivatives.uv_dx, texture_derivatives.uv_dy).rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let strength = clamp(material.texture_normal_strength, 0.0, 4.0);
    normal = mapped_normal(normal, world_position, uv, vec3<f32>(
      0.5 - (right - left) * strength,
      0.5 - (up - down) * strength,
      1.0
    ), 1.0, texture_derivatives);
  }
  if ((material.flags & MATERIAL_UNLIT) == 0u) {
    let response = detail_material_response(material);
    roughness = max(roughness, response.w);
    let color_amount = clamp(material.color_variation, 0.0, 1.0);
    let roughness_amount = clamp(material.roughness_variation, 0.0, 1.0);
    let normal_amount = clamp(material.normal_strength, 0.0, 1.0);
    let maximum_detail_amount = max(color_amount, max(roughness_amount, normal_amount));
    if (maximum_detail_amount > 0.000001) {
    let coordinates = stable_detail_coordinates(
      world_position,
      geometric_normal,
      source_uv,
      derivatives
    );
    let signals = procedural_detail_signals(material, coordinates);
    albedo = bounded_micro_albedo(albedo, signals.x, color_amount, response.x);
    roughness += signals.y * roughness_amount * response.y;
    let detail_scale = clamp(material.detail_scale, 0.001, 10000.0);
    let detail_footprint = max(length(coordinates.dx), length(coordinates.dy))
      * detail_scale;
    let resolved_normal_visibility = detail_octave_visibility(detail_footprint, 1.731);
    let unresolved_normal_variance = (1.0 - resolved_normal_visibility)
      * normal_amount * normal_amount * response.z * response.z * 0.5;
    roughness = sqrt(clamp(
      roughness * roughness + unresolved_normal_variance,
      response.w * response.w,
      1.0
    ));
    normal = procedural_mapped_normal(
      normal,
      derivatives,
      coordinates,
      signals.zw * normal_amount * response.z
    );
    }
  }
  return Surface(sanitize_radiance(albedo), normal, roughness, alpha, metallic);
}

fn fresnel_schlick(cosine: f32, f0: vec3<f32>) -> vec3<f32> {
  return f0 + (vec3<f32>(1.0) - f0) * pow(clamp(1.0 - cosine, 0.0, 1.0), 5.0);
}

fn dielectric_f0(ior: f32) -> f32 {
  let safe_ior = max(ior, 1.0001);
  let interface_ratio = (safe_ior - 1.0) / (safe_ior + 1.0);
  return clamp(interface_ratio * interface_ratio, 0.0, 1.0);
}

fn surface_reflectance_zero(surface: Surface, material: Material) -> vec3<f32> {
  return mix(
    vec3<f32>(dielectric_f0(material.ior)),
    max(surface.albedo, vec3<f32>(0.0)),
    clamp(surface.metallic, 0.0, 1.0)
  );
}

fn foliage_transmission_tint(surface: Surface) -> vec3<f32> {
  let bounded_albedo = clamp(surface.albedo, vec3<f32>(0.0), vec3<f32>(1.0));
  return mix(bounded_albedo, sqrt(bounded_albedo), 0.35);
}

fn foliage_transmission_profile(
  outgoing_direction: vec3<f32>,
  incident_direction: vec3<f32>
) -> f32 {
  let forward_alignment = clamp(dot(outgoing_direction, -incident_direction), 0.0, 1.0);
  return mix(0.65, 1.0, forward_alignment * forward_alignment);
}

fn foliage_diffuse_transmission_response(
  surface: Surface,
  material: Material,
  outgoing_direction: vec3<f32>,
  incident_direction: vec3<f32>
) -> vec3<f32> {
  let transmission = clamp(max(material.transmission, 1.0 - material.alpha), 0.0, 1.0);
  let metallic = clamp(surface.metallic, 0.0, 1.0);
  if ((material.flags & MATERIAL_FOLIAGE) == 0u
      || transmission <= 0.000001
      || metallic >= 0.999999) {
    return vec3<f32>(0.0);
  }
  let reflectance_zero = surface_reflectance_zero(surface, material);
  let outgoing_fresnel = fresnel_schlick(
    clamp(dot(surface.normal, outgoing_direction), 0.0, 1.0),
    reflectance_zero
  );
  let incident_fresnel = fresnel_schlick(
    clamp(dot(-surface.normal, incident_direction), 0.0, 1.0),
    reflectance_zero
  );
  let interface_transmission = sqrt(max(
    (vec3<f32>(1.0) - outgoing_fresnel)
      * (vec3<f32>(1.0) - incident_fresnel),
    vec3<f32>(0.0)
  ));
  return interface_transmission
    * (1.0 - metallic)
    * transmission
    * foliage_transmission_tint(surface)
    * foliage_transmission_profile(outgoing_direction, incident_direction);
}

fn foliage_environment_transmission_response(
  surface: Surface,
  material: Material,
  outgoing_direction: vec3<f32>
) -> vec3<f32> {
  let transmission = clamp(max(material.transmission, 1.0 - material.alpha), 0.0, 1.0);
  let metallic = clamp(surface.metallic, 0.0, 1.0);
  if ((material.flags & MATERIAL_FOLIAGE) == 0u
      || transmission <= 0.000001
      || metallic >= 0.999999) {
    return vec3<f32>(0.0);
  }
  let fresnel = fresnel_schlick(
    clamp(dot(surface.normal, outgoing_direction), 0.0, 1.0),
    surface_reflectance_zero(surface, material)
  );
  return (vec3<f32>(1.0) - fresnel)
    * (1.0 - metallic)
    * transmission
    * foliage_transmission_tint(surface)
    * 0.79;
}

fn direct_light_brdf(
  surface: Surface,
  material: Material,
  view_direction: vec3<f32>,
  light_direction: vec3<f32>,
  incident_radiance: vec3<f32>
) -> vec3<f32> {
  let n_dot_l = max(dot(surface.normal, light_direction), 0.0);
  let n_dot_v = max(dot(surface.normal, view_direction), 0.0001);
  if (n_dot_l <= 0.0) {
    return vec3<f32>(0.0);
  }
  let half_vector = safe_normalize(view_direction + light_direction, surface.normal);
  let n_dot_h = max(dot(surface.normal, half_vector), 0.0);
  let v_dot_h = max(dot(view_direction, half_vector), 0.0);
  let roughness = clamp(surface.roughness, 0.04, 1.0);
  let alpha = roughness * roughness;
  let alpha_squared = alpha * alpha;
  let denominator = n_dot_h * n_dot_h * (alpha_squared - 1.0) + 1.0;
  let distribution = alpha_squared / max(PI * denominator * denominator, 0.000001);
  let k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
  let geometry_v = n_dot_v / (n_dot_v * (1.0 - k) + k);
  let geometry_l = n_dot_l / (n_dot_l * (1.0 - k) + k);
  let metallic = clamp(surface.metallic, 0.0, 1.0);
  let transmission = clamp(max(material.transmission, 1.0 - material.alpha), 0.0, 1.0);
  let f0 = surface_reflectance_zero(surface, material);
  let fresnel = fresnel_schlick(v_dot_h, f0);
  let specular = distribution * geometry_v * geometry_l * fresnel
    / max(4.0 * n_dot_v * n_dot_l, 0.0001);
  let diffuse = (vec3<f32>(1.0) - fresnel)
    * (1.0 - metallic)
    * (1.0 - transmission)
    * surface.albedo / PI;
  return (diffuse + specular) * incident_radiance * n_dot_l;
}

fn shade_surface(surface: Surface, material: Material, position: vec3<f32>) -> vec3<f32> {
  let emission = sanitize_radiance(max(material.emission_color, vec3<f32>(0.0))
    * max(material.emission_strength, 0.0));
  if ((material.flags & MATERIAL_UNLIT) != 0u) {
    return sanitize_radiance(surface.albedo * emission);
  }
  let view_direction = safe_normalize(
    globals.camera_position_tan_fov.xyz - position,
    surface.normal
  );
  let metallic = clamp(surface.metallic, 0.0, 1.0);
  let transmission = clamp(max(material.transmission, 1.0 - material.alpha), 0.0, 1.0);
  let foliage = (material.flags & MATERIAL_FOLIAGE) != 0u;
  let transport_roughness = select(
    surface.roughness,
    max(surface.roughness, 0.5),
    foliage
  );
  let reflected = reflect(-view_direction, surface.normal);
  let environment_specular = physical_environment(reflected, transport_roughness);
  let environment_diffuse = diffuse_environment_irradiance(surface.normal);
  let fresnel = fresnel_schlick(
    max(dot(surface.normal, view_direction), 0.0),
    surface_reflectance_zero(surface, material)
  );
  var radiance = emission
    + environment_diffuse
      * surface.albedo
      * (vec3<f32>(1.0) - fresnel)
      * (1.0 - metallic)
      * (1.0 - transmission) / PI
    + environment_specular * fresnel;
  if (foliage) {
    radiance += diffuse_environment_irradiance(-surface.normal)
      * foliage_environment_transmission_response(surface, material, view_direction)
      / PI;
  }
  let light_count = min(min(u32(globals.light_volume.x), arrayLength(&lights)), MAX_LIGHTS);
  var primary_directional_seen = false;
  for (var index = 0u; index < MAX_LIGHTS; index += 1u) {
    if (index >= light_count) {
      break;
    }
    let light = lights[index];
    let directional = light.kind != 0u;
    let primary_directional = directional && !primary_directional_seen;
    if (directional) {
      primary_directional_seen = true;
    }
    var direction_to_light = safe_normalize(-light.vector, vec3<f32>(0.0, 1.0, 0.0));
    var attenuation = 1.0;
    if (light.kind == 0u) {
      let delta = light.vector - position;
      let distance_squared = max(dot(delta, delta), 0.0001);
      let distance_to_light = sqrt(distance_squared);
      direction_to_light = delta / distance_to_light;
      if (light.range_or_angular_radius > 0.0) {
        let range_fade = clamp(
          1.0 - distance_squared
            / (light.range_or_angular_radius * light.range_or_angular_radius),
          0.0,
          1.0
        );
        attenuation = range_fade * range_fade / distance_squared;
      } else {
        attenuation = 1.0 / distance_squared;
      }
    }
    var incident = max(light.color, vec3<f32>(0.0))
      * max(light.intensity, 0.0)
      * attenuation;
    if (primary_directional && captured_sun_matching_active()) {
      incident = captured_environment_sun_irradiance()
        * max(light.color, vec3<f32>(0.0))
        * max(light.intensity, 0.0)
        * attenuation;
    }
    incident *= raster_shadow_visibility(position, index);
    radiance += direct_light_brdf(
      surface,
      material,
      view_direction,
      direction_to_light,
      incident
    );
    if (foliage) {
      let opposite_normal_dot_light = max(dot(-surface.normal, direction_to_light), 0.0);
      radiance += foliage_diffuse_transmission_response(
        surface,
        material,
        view_direction,
        direction_to_light
      ) * incident * opposite_normal_dot_light / PI;
    }
  }
  if (transmission > 0.0 && metallic < 0.999 && !foliage) {
    let transmitted_environment = physical_environment(-view_direction, surface.roughness);
    radiance = mix(radiance, transmitted_environment, transmission * (1.0 - fresnel));
  }
  return sanitize_radiance(radiance);
}

@fragment
fn background_fragment(@builtin(position) fragment_position: vec4<f32>) -> RasterFragmentOutput {
  let direction = camera_direction(fragment_position.xy);
  let current_uv = fragment_position.xy / globals.resolution_samples.xy;
  let previous_projection = project_previous_direction_uv(direction);
  var output: RasterFragmentOutput;
  output.hdr = vec4<f32>(camera_background(direction), 1.0);
  output.normal_depth = vec4<f32>(0.0, 0.0, 0.0, 65504.0);
  output.albedo_roughness = vec4<f32>(0.0, 0.0, 0.0, 1.0);
  output.motion_reactive = vec4<f32>(previous_projection.xy - current_uv, 0.0, 65504.0);
  return output;
}

@fragment
fn shadow_fragment(input: RasterVertexOutput) {
  let derivatives = SurfaceDerivatives(dpdx(input.world_position), dpdy(input.world_position), dpdx(input.uv), dpdy(input.uv));
  if (input.material_id >= min(u32(globals.scene_counts.w), arrayLength(&materials))) {discard;}
  let material = materials[input.material_id];
  if (material.transmission > 0.001 && (material.flags & MATERIAL_FOLIAGE) == 0u) {discard;}
  let surface = material_surface(material, input.world_position, input.world_normal, input.uv, derivatives);
  if (surface.alpha < 0.1) {discard;}
}

@fragment
fn raster_fragment(
  input: RasterVertexOutput,
  @builtin(front_facing) front_facing: bool
) -> RasterFragmentOutput {
  let derivatives = SurfaceDerivatives(
    dpdx(input.world_position),
    dpdy(input.world_position),
    dpdx(input.uv),
    dpdy(input.uv)
  );
  if (input.material_id >= min(u32(globals.scene_counts.w), arrayLength(&materials))) {
    discard;
  }
  let material = materials[input.material_id];
  let double_sided = (material.flags & MATERIAL_DOUBLE_SIDED) != 0u
    || (material.flags & MATERIAL_FOLIAGE) != 0u
    || material.transmission > 0.0001
    || material.alpha < 0.9999;
  if (!front_facing && !double_sided) {
    discard;
  }
  let facing_normal = select(-input.world_normal, input.world_normal, front_facing);
  let surface = material_surface(
    material,
    input.world_position,
    facing_normal,
    input.uv,
    derivatives
  );
  if (surface.alpha < 0.1) {
    discard;
  }
  let view_depth = dot(
    input.world_position - globals.camera_position_tan_fov.xyz,
    globals.camera_forward_exposure.xyz
  );
  let current_uv = input.clip_position.xy / globals.resolution_samples.xy;
  let previous_projection = project_previous_uv(input.previous_world_position);
  let wind_reactive = select(
    0.0,
    1.0,
    material.wind_influence > 0.000001
      && globals.environment_params.z > 0.000001
  );
  let reactive = clamp(
    material.transmission
      + max(material.emission_strength, 0.0) * 0.05
      + (1.0 - surface.alpha)
      + wind_reactive,
    0.0,
    1.0
  );
  var output: RasterFragmentOutput;
  output.hdr = vec4<f32>(shade_surface(surface, material, input.world_position), 1.0);
  output.normal_depth = vec4<f32>(surface.normal, clamp(view_depth, 0.0, 65504.0));
  output.albedo_roughness = vec4<f32>(
    surface.albedo,
    select(surface.roughness, 0.0, (material.flags & MATERIAL_UNLIT) != 0u)
  );
  output.motion_reactive = vec4<f32>(
    previous_projection.xy - current_uv,
    reactive,
    select(min(previous_projection.z, 65504.0), -1.0, previous_projection.z <= 0.0)
  );
  return output;
}
`;
