import {frameTiming, normalizeVideoRecordingOptions, realtimeFrameSlot, shouldRequestKeyFrame} from './timing';
import type {
  FinishedVideoRecording,
  NormalizedVideoRecordingOptions,
  SelectedVideoEncoderConfig,
  VideoCaptureResult,
  VideoConfigurationRequest,
  VideoEncoderCapabilities,
  VideoEncoderHandle,
  VideoRecorderDependencies,
  VideoRecorderState,
  VideoRecorderStatus,
  VideoRecordingOptions,
  VideoRecordingStats,
  WebCodecsBackend
} from './types';
import {
  createBrowserWebCodecsBackend,
  negotiateVideoEncoderConfig,
  queryVideoEncoderCapabilities
} from './webcodecs';
import {WebMMuxer} from './webm-muxer';

interface MutableVideoRecordingStats extends VideoRecordingStats {}

interface PreparedCanvas {
  readonly source: CanvasImageSource;
  readonly width: number;
  readonly height: number;
  readonly copyFrame: () => void;
  readonly padded: boolean;
}

function freshStats(mode: NormalizedVideoRecordingOptions['mode']): MutableVideoRecordingStats {
  return {
    mode,
    submittedFrames: 0,
    encodedFrames: 0,
    droppedFrames: 0,
    droppedForBackpressure: 0,
    droppedForThrottle: 0,
    encodeQueueHighWaterMark: 0,
    durationUs: 0,
    encodedBytes: 0,
    bytes: 0
  };
}

function errorFrom(value: unknown): Error {
  return value instanceof Error ? value : new Error(String(value));
}

function validateCanvas(canvas: HTMLCanvasElement): void {
  if (!canvas || !Number.isSafeInteger(canvas.width) || !Number.isSafeInteger(canvas.height)) {
    throw new TypeError('A valid HTMLCanvasElement is required');
  }
  if (canvas.width <= 0 || canvas.height <= 0) {
    throw new RangeError('The recording canvas must have non-zero dimensions');
  }
  if (canvas.isConnected === false) {
    throw new Error('The recording canvas must be connected to the document');
  }
}

function createEvenCanvasFallback(
  input: HTMLCanvasElement,
  width: number,
  height: number
): PreparedCanvas {
  if (typeof document === 'undefined') {
    throw new Error('Odd-size video fallback requires a browser document');
  }
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext('2d', {alpha: false, desynchronized: true});
  if (!context) throw new Error('Could not create the even-size video staging canvas');
  const inputWidth = input.width;
  const inputHeight = input.height;

  return {
    source: canvas,
    width,
    height,
    padded: true,
    copyFrame: () => {
      if (input.width !== inputWidth || input.height !== inputHeight) {
        throw new Error('Recording canvas dimensions changed; restart video recording after resize');
      }
      context.drawImage(input, 0, 0, width, height);
    }
  };
}

function directCanvas(canvas: HTMLCanvasElement): PreparedCanvas {
  const width = canvas.width;
  const height = canvas.height;
  return {
    source: canvas,
    width,
    height,
    padded: false,
    copyFrame: () => {
      if (canvas.width !== width || canvas.height !== height) {
        throw new Error('Recording canvas dimensions changed; restart video recording after resize');
      }
    }
  };
}

function closedEncoder(encoder: VideoEncoderHandle | null): void {
  if (!encoder || encoder.state === 'closed') return;
  try {
    encoder.close();
  } catch {
    // The native encoder may already have closed after an asynchronous error.
  }
}

export class CanvasVideoRecorder {
  private readonly backend: WebCodecsBackend | null;
  private readonly now: () => number;

  private state: VideoRecorderState = 'idle';
  private message = 'Ready to record';
  private encoder: VideoEncoderHandle | null = null;
  private muxer: WebMMuxer | null = null;
  private canvas: PreparedCanvas | null = null;
  private options: NormalizedVideoRecordingOptions | null = null;
  private selectedConfig: SelectedVideoEncoderConfig | null = null;
  private stats: MutableVideoRecordingStats | null = null;
  private fatalError: Error | null = null;
  private realtimeEpochMs: number | null = null;
  private lastRealtimeSlot = -1;
  private lastKeyFrameTimestampUs: number | null = null;
  private offlineTail: Promise<void> = Promise.resolve();
  private session = 0;
  private finishedResult: FinishedVideoRecording | null = null;

  constructor(dependencies: VideoRecorderDependencies = {}) {
    this.backend =
      dependencies.backend === undefined
        ? createBrowserWebCodecsBackend()
        : dependencies.backend;
    this.now = dependencies.now ?? (() => performance.now());
  }

  static queryCapabilities(
    request: Omit<VideoConfigurationRequest, 'codec'>
  ): Promise<VideoEncoderCapabilities> {
    return queryVideoEncoderCapabilities(request);
  }

  getStatus(): Readonly<VideoRecorderStatus> {
    const stats = this.stats;
    return {
      state: this.state,
      message: this.message,
      mode: this.options?.mode ?? null,
      codec: this.selectedConfig?.codec ?? null,
      width: this.canvas?.width ?? 0,
      height: this.canvas?.height ?? 0,
      fps: this.options?.fps ?? 0,
      bitrate: this.options?.bitrate ?? 0,
      encodeQueueSize: this.encoder?.encodeQueueSize ?? 0,
      submittedFrames: stats?.submittedFrames ?? 0,
      encodedFrames: stats?.encodedFrames ?? 0,
      droppedFrames: stats?.droppedFrames ?? 0,
      droppedForBackpressure: stats?.droppedForBackpressure ?? 0,
      droppedForThrottle: stats?.droppedForThrottle ?? 0,
      encodeQueueHighWaterMark: stats?.encodeQueueHighWaterMark ?? 0,
      durationUs: stats?.durationUs ?? 0,
      encodedBytes: stats?.encodedBytes ?? 0,
      bytes: stats?.bytes ?? 0
    };
  }

  async start(
    inputCanvas: HTMLCanvasElement,
    recordingOptions: VideoRecordingOptions
  ): Promise<Readonly<SelectedVideoEncoderConfig>> {
    this.assertCanStart();
    validateCanvas(inputCanvas);
    const options = normalizeVideoRecordingOptions(recordingOptions);
    if (!this.backend) {
      this.state = 'unsupported';
      this.message = 'This browser does not expose VideoEncoder and VideoFrame';
      throw new Error(this.message);
    }

    const session = ++this.session;
    this.state = 'configuring';
    this.message = 'Selecting a WebCodecs video encoder';
    this.fatalError = null;
    this.finishedResult = null;

    let canvas = directCanvas(inputCanvas);
    let selectedConfig: SelectedVideoEncoderConfig;
    const request: VideoConfigurationRequest = {
      ...recordingOptions,
      width: canvas.width,
      height: canvas.height
    };
    try {
      selectedConfig = await negotiateVideoEncoderConfig(request, this.backend);
    } catch (firstError) {
      if (canvas.width % 2 === 0 && canvas.height % 2 === 0) {
        this.failDuringStart(firstError, session);
      }

      const evenWidth = canvas.width + (canvas.width % 2);
      const evenHeight = canvas.height + (canvas.height % 2);
      try {
        selectedConfig = await negotiateVideoEncoderConfig(
          {...recordingOptions, width: evenWidth, height: evenHeight},
          this.backend
        );
        canvas = createEvenCanvasFallback(inputCanvas, evenWidth, evenHeight);
      } catch (fallbackError) {
        this.failDuringStart(fallbackError, session);
      }
    }

    if (session !== this.session || this.state !== 'configuring') {
      throw new Error('Video recording setup was canceled');
    }

    const muxer = new WebMMuxer({
      width: canvas.width,
      height: canvas.height,
      fps: options.fps,
      codec: selectedConfig.codec,
      maxOutputBytes: options.maxOutputBytes
    });
    this.muxer = muxer;
    this.canvas = canvas;
    this.options = options;
    this.selectedConfig = selectedConfig;
    this.stats = freshStats(options.mode);
    this.realtimeEpochMs = null;
    this.lastRealtimeSlot = -1;
    this.lastKeyFrameTimestampUs = null;
    this.offlineTail = Promise.resolve();

    const encoder = this.backend.createEncoder({
      output: chunk => {
        if (session !== this.session || this.muxer !== muxer) return;
        try {
          muxer.addChunk(chunk);
          const stats = this.stats;
          if (!stats) return;
          stats.encodedFrames += 1;
          stats.encodedBytes += chunk.byteLength;
          const duration = chunk.duration ?? Math.max(1, Math.round(1_000_000 / options.fps));
          stats.durationUs = Math.max(stats.durationUs, chunk.timestamp + duration);
        } catch (error) {
          this.setFatal(errorFrom(error), session);
        }
      },
      error: error => this.setFatal(error, session)
    });

    try {
      encoder.configure(selectedConfig.config);
    } catch (error) {
      closedEncoder(encoder);
      this.failDuringStart(error, session);
    }
    if (this.fatalError) {
      closedEncoder(encoder);
      this.failDuringStart(this.fatalError, session);
    }

    this.encoder = encoder;
    this.state = 'recording';
    this.message = canvas.padded
      ? `Recording ${selectedConfig.codec.toUpperCase()} through an even-size staging canvas`
      : `Recording ${selectedConfig.codec.toUpperCase()}`;
    return selectedConfig;
  }

  captureRealtimeFrame(): VideoCaptureResult {
    const {encoder, options} = this.assertRecordingMode('realtime');
    const now = this.now();
    if (!Number.isFinite(now)) throw new Error('The monotonic clock returned a non-finite value');
    if (this.realtimeEpochMs === null) this.realtimeEpochMs = now;
    const slot = realtimeFrameSlot(Math.max(0, now - this.realtimeEpochMs), options.fps);

    if (slot <= this.lastRealtimeSlot) {
      const stats = this.requireStats();
      stats.droppedFrames += 1;
      stats.droppedForThrottle += 1;
      return {
        accepted: false,
        timestampUs: null,
        queueSize: encoder.encodeQueueSize,
        reason: 'throttled'
      };
    }

    if (encoder.encodeQueueSize >= options.maxQueueSize) {
      const stats = this.requireStats();
      stats.droppedFrames += 1;
      stats.droppedForBackpressure += 1;
      return {
        accepted: false,
        timestampUs: null,
        queueSize: encoder.encodeQueueSize,
        reason: 'backpressure'
      };
    }

    const timing = frameTiming(slot, options.fps);
    const result = this.submitFrame(timing.timestamp, timing.duration);
    this.lastRealtimeSlot = slot;
    return result;
  }

  captureOfflineFrame(): Promise<VideoCaptureResult> {
    const session = this.session;
    this.assertRecordingMode('offline');
    let resolveTail: () => void = () => undefined;
    const previous = this.offlineTail;
    this.offlineTail = new Promise<void>(resolve => {
      resolveTail = resolve;
    });

    return previous
      .then(async () => {
        const {encoder, options} = this.assertQueuedOfflineCapture(session);
        const stats = this.requireStats();
        const timing = frameTiming(stats.submittedFrames, options.fps);
        const encodedBefore = stats.encodedFrames;
        this.submitFrame(timing.timestamp, timing.duration);
        try {
          await encoder.flush();
        } catch (error) {
          const fatal = errorFrom(error);
          this.setFatal(fatal, session);
          throw fatal;
        }
        this.throwIfFatal();
        if (stats.encodedFrames <= encodedBefore) {
          const error = new Error('The video encoder did not emit the submitted offline frame');
          this.setFatal(error, session);
          throw error;
        }
        return {
          accepted: true,
          timestampUs: timing.timestamp,
          queueSize: encoder.encodeQueueSize,
          reason: null
        } as const;
      })
      .finally(resolveTail);
  }

  async finish(): Promise<FinishedVideoRecording> {
    if (this.finishedResult) return this.finishedResult;
    this.throwIfDestroyed();
    this.throwIfFatal();
    if (this.state !== 'recording') {
      throw new Error(`Cannot finish a video recorder in the ${this.state} state`);
    }

    const session = this.session;
    this.state = 'finishing';
    this.message = 'Flushing the video encoder';
    const encoder = this.requireEncoder();
    let bytes: Uint8Array;
    try {
      await this.offlineTail;
      if (session !== this.session) throw new Error('Video recording was canceled');
      await encoder.flush();
      this.throwIfFatal();
      bytes = this.requireMuxer().finalize();
    } catch (error) {
      const fatal = errorFrom(error);
      this.setFatal(fatal, session);
      closedEncoder(encoder);
      this.encoder = null;
      throw fatal;
    }
    closedEncoder(encoder);
    this.encoder = null;

    const stats = this.requireStats();
    stats.bytes = bytes.byteLength;
    const selectedConfig = this.requireSelectedConfig();
    const immutableStats = Object.freeze({...stats});
    const immutableConfig = Object.freeze({
      ...selectedConfig,
      config: Object.freeze({...selectedConfig.config})
    });
    const result: FinishedVideoRecording = {
      blob: new Blob([bytes as unknown as BlobPart], {type: 'video/webm'}),
      stats: immutableStats,
      config: immutableConfig
    };
    this.finishedResult = result;
    this.state = 'finished';
    this.message = `Finished ${stats.encodedFrames} frames (${bytes.byteLength} bytes)`;
    return result;
  }

  cancel(): void {
    if (this.state === 'destroyed' || this.state === 'canceled') return;
    this.session += 1;
    const encoder = this.encoder;
    this.encoder = null;
    if (encoder && encoder.state !== 'closed') {
      try {
        encoder.reset();
      } catch {
        // Reset may fail if an asynchronous codec error already closed the encoder.
      }
      closedEncoder(encoder);
    }
    this.muxer = null;
    this.canvas = null;
    this.finishedResult = null;
    this.state = 'canceled';
    this.message = 'Video recording canceled';
  }

  destroy(): void {
    if (this.state === 'destroyed') return;
    this.cancel();
    this.state = 'destroyed';
    this.message = 'Video recorder destroyed';
    this.options = null;
    this.selectedConfig = null;
    this.stats = null;
    this.fatalError = null;
  }

  private submitFrame(timestamp: number, duration: number): VideoCaptureResult {
    const encoder = this.requireEncoder();
    const canvas = this.canvas;
    const options = this.options;
    if (!canvas || !options) throw new Error('Video recorder has no active canvas');
    this.throwIfFatal();

    let frame: ReturnType<WebCodecsBackend['createFrame']> | null = null;
    const keyFrame = shouldRequestKeyFrame(
      timestamp,
      this.lastKeyFrameTimestampUs,
      options.keyFrameIntervalSeconds
    );
    try {
      canvas.copyFrame();
      frame = this.backend?.createFrame(canvas.source, {timestamp, duration}) ?? null;
      if (!frame) throw new Error('WebCodecs is unavailable');
      encoder.encode(frame, {keyFrame});
    } catch (error) {
      const fatal = errorFrom(error);
      this.setFatal(fatal, this.session);
      throw fatal;
    } finally {
      frame?.close();
    }

    if (keyFrame) this.lastKeyFrameTimestampUs = timestamp;
    const stats = this.requireStats();
    stats.submittedFrames += 1;
    stats.durationUs = Math.max(stats.durationUs, timestamp + duration);
    stats.encodeQueueHighWaterMark = Math.max(
      stats.encodeQueueHighWaterMark,
      encoder.encodeQueueSize
    );
    return {
      accepted: true,
      timestampUs: timestamp,
      queueSize: encoder.encodeQueueSize,
      reason: null
    };
  }

  private assertCanStart(): void {
    this.throwIfDestroyed();
    if (this.state === 'configuring' || this.state === 'recording' || this.state === 'finishing') {
      throw new Error(`Cannot start a video recorder in the ${this.state} state`);
    }
    if (this.state === 'error') {
      throw new Error('Cancel the failed recording before starting another one');
    }
  }

  private assertRecordingMode(
    mode: NormalizedVideoRecordingOptions['mode']
  ): {encoder: VideoEncoderHandle; options: NormalizedVideoRecordingOptions} {
    this.throwIfDestroyed();
    this.throwIfFatal();
    if (this.state !== 'recording') {
      throw new Error(`Video recorder is not recording (state: ${this.state})`);
    }
    const options = this.options;
    if (!options || options.mode !== mode) {
      throw new Error(`This recording is not in ${mode} mode`);
    }
    return {encoder: this.requireEncoder(), options};
  }

  private assertQueuedOfflineCapture(
    session: number
  ): {encoder: VideoEncoderHandle; options: NormalizedVideoRecordingOptions} {
    if (session !== this.session) throw new Error('Video recording was canceled');
    this.throwIfDestroyed();
    this.throwIfFatal();
    if (this.state !== 'recording' && this.state !== 'finishing') {
      throw new Error(`Video recorder is not recording (state: ${this.state})`);
    }
    const options = this.options;
    if (!options || options.mode !== 'offline') {
      throw new Error('This recording is not in offline mode');
    }
    return {encoder: this.requireEncoder(), options};
  }

  private failDuringStart(error: unknown, session: number): never {
    const failure = errorFrom(error);
    if (session === this.session) {
      this.state = 'unsupported';
      this.message = failure.message;
    }
    throw failure;
  }

  private setFatal(error: Error, session: number): void {
    if (session !== this.session || this.state === 'destroyed' || this.state === 'canceled') return;
    this.fatalError ??= error;
    this.state = 'error';
    this.message = error.message;
  }

  private throwIfFatal(): void {
    if (this.fatalError) throw this.fatalError;
  }

  private throwIfDestroyed(): void {
    if (this.state === 'destroyed') throw new Error('Video recorder has been destroyed');
  }

  private requireEncoder(): VideoEncoderHandle {
    if (!this.encoder) throw new Error('Video encoder is not configured');
    return this.encoder;
  }

  private requireMuxer(): WebMMuxer {
    if (!this.muxer) throw new Error('WebM muxer is not configured');
    return this.muxer;
  }

  private requireStats(): MutableVideoRecordingStats {
    if (!this.stats) throw new Error('Video recording statistics are unavailable');
    return this.stats;
  }

  private requireSelectedConfig(): SelectedVideoEncoderConfig {
    if (!this.selectedConfig) throw new Error('Video encoder configuration is unavailable');
    return this.selectedConfig;
  }
}
