import type {MeshDefinition, Vec3} from '../scene';

const EPSILON = 1e-20;

function normalize(vector: Vec3, label: string): Vec3 {
  const length = Math.hypot(vector[0], vector[1], vector[2]);
  if (!Number.isFinite(length) || length <= 1e-10) throw new RangeError(`${label} must have non-zero finite length`);
  return [vector[0] / length, vector[1] / length, vector[2] / length];
}

function subtract(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

function cross(a: Vec3, b: Vec3): Vec3 {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}

export class EnvironmentMeshBuilder {
  private readonly positions: number[] = [];
  private readonly normals: number[] = [];
  private readonly indices: number[] = [];
  private readonly windWeights: number[] | null;

  constructor(withWindWeights: boolean) {
    this.windWeights = withWindWeights ? [] : null;
  }

  get vertexCount(): number {
    return this.positions.length / 3;
  }

  get triangleCount(): number {
    return this.indices.length / 3;
  }

  addVertex(position: Vec3, normal: Vec3, windWeight = 0): number {
    for (let axis = 0; axis < 3; axis += 1) {
      const coordinate = position[axis];
      if (coordinate === undefined || !Number.isFinite(coordinate) || !Number.isFinite(Math.fround(coordinate))) {
        throw new RangeError(`environment vertex coordinate ${axis} must be finite`);
      }
    }
    const unitNormal = normalize(normal, 'environment vertex normal');
    if (!Number.isFinite(windWeight) || windWeight < 0 || windWeight > 1) {
      throw new RangeError('environment wind weight must be from 0 through 1');
    }
    const index = this.vertexCount;
    this.positions.push(position[0], position[1], position[2]);
    this.normals.push(unitNormal[0], unitNormal[1], unitNormal[2]);
    this.windWeights?.push(windWeight);
    return index;
  }

  addTriangle(a: number, b: number, c: number): void {
    if (a === b || a === c || b === c) throw new RangeError('environment triangle indices must be distinct');
    const read = (vertex: number): Vec3 => {
      if (!Number.isSafeInteger(vertex) || vertex < 0 || vertex >= this.vertexCount) throw new RangeError('environment triangle index is out of bounds');
      const offset = vertex * 3;
      return [this.positions[offset] ?? Number.NaN, this.positions[offset + 1] ?? Number.NaN, this.positions[offset + 2] ?? Number.NaN];
    };
    const p0 = read(a);
    const p1 = read(b);
    const p2 = read(c);
    const area = cross(subtract(p1, p0), subtract(p2, p0));
    if (area[0] * area[0] + area[1] * area[1] + area[2] * area[2] <= EPSILON) {
      throw new RangeError('environment triangle must not be degenerate');
    }
    this.indices.push(a, b, c);
  }

  addQuad(a: Vec3, b: Vec3, c: Vec3, d: Vec3, windWeights: readonly [number, number, number, number] = [0, 0, 0, 0]): void {
    const normal = normalize(cross(subtract(b, a), subtract(c, a)), 'environment quad normal');
    const start = this.vertexCount;
    this.addVertex(a, normal, windWeights[0]);
    this.addVertex(b, normal, windWeights[1]);
    this.addVertex(c, normal, windWeights[2]);
    this.addVertex(d, normal, windWeights[3]);
    this.addTriangle(start, start + 1, start + 2);
    this.addTriangle(start, start + 2, start + 3);
  }

  addTube(path: readonly Vec3[], radii: readonly number[], radialSegments: number, ringWindWeights?: readonly number[]): void {
    if (path.length < 2 || radii.length !== path.length) throw new RangeError('environment tube requires matching paths and radii with at least two rings');
    if (!Number.isSafeInteger(radialSegments) || radialSegments < 3 || radialSegments > 128) {
      throw new RangeError('environment tube radialSegments must be an integer from 3 through 128');
    }
    if (ringWindWeights && ringWindWeights.length !== path.length) throw new RangeError('environment tube wind weights must match its path');
    const start = this.vertexCount;
    for (let ring = 0; ring < path.length; ring += 1) {
      const point = path[ring];
      const radius = radii[ring];
      if (!point || radius === undefined || !Number.isFinite(radius) || radius <= 0) throw new RangeError('environment tube radii must be finite and positive');
      const previous = path[Math.max(0, ring - 1)];
      const next = path[Math.min(path.length - 1, ring + 1)];
      if (!previous || !next) throw new Error('Internal tube path invariant failed');
      const tangent = normalize(subtract(next, previous), 'environment tube tangent');
      const reference: Vec3 = Math.abs(tangent[1]) < 0.92 ? [0, 1, 0] : [1, 0, 0];
      const u = normalize(cross(reference, tangent), 'environment tube basis');
      const v = normalize(cross(tangent, u), 'environment tube basis');
      for (let segment = 0; segment < radialSegments; segment += 1) {
        const angle = Math.PI * 2 * segment / radialSegments;
        const cosine = Math.cos(angle);
        const sine = Math.sin(angle);
        const normal: Vec3 = [u[0] * cosine + v[0] * sine, u[1] * cosine + v[1] * sine, u[2] * cosine + v[2] * sine];
        this.addVertex([
          point[0] + normal[0] * radius,
          point[1] + normal[1] * radius,
          point[2] + normal[2] * radius
        ], normal, ringWindWeights?.[ring] ?? 0);
      }
    }
    for (let ring = 0; ring < path.length - 1; ring += 1) {
      const current = start + ring * radialSegments;
      const next = current + radialSegments;
      for (let segment = 0; segment < radialSegments; segment += 1) {
        const nextSegment = (segment + 1) % radialSegments;
        const a = current + segment;
        const b = current + nextSegment;
        const c = next + segment;
        const d = next + nextSegment;
        this.addTriangle(a, b, c);
        this.addTriangle(b, d, c);
      }
    }
  }

  finish(): MeshDefinition {
    if (this.triangleCount === 0) throw new RangeError('environment mesh batch must contain at least one triangle');
    const mesh: MeshDefinition = {
      positions: Float32Array.from(this.positions),
      normals: Float32Array.from(this.normals),
      indices: Uint32Array.from(this.indices)
    };
    if (this.windWeights) mesh.windWeights = Float32Array.from(this.windWeights);
    return mesh;
  }
}

export function normalized(vector: Vec3): Vec3 {
  return normalize(vector, 'environment direction');
}
