import type {MeshDefinition, Vec3} from '../scene';
import {planUvSphereDetail} from './budget';
import type {UvSphereOptions} from './types';

function finitePositive(value: number, label: string): number {
  if (!Number.isFinite(value) || value <= 0 || !Number.isFinite(Math.fround(value))) {
    throw new RangeError(`${label} must be a finite positive 32-bit number`);
  }
  return value;
}

function finiteVec3(value: Vec3, label: string): Vec3 {
  if (!value || value.length !== 3) throw new TypeError(`${label} must contain exactly three components`);
  const output = value.map((component, index) => {
    if (!Number.isFinite(component) || !Number.isFinite(Math.fround(component))) {
      throw new RangeError(`${label}[${index}] must be a finite 32-bit number`);
    }
    return component;
  }) as unknown as Vec3;
  return output;
}

export function createUvSphere(options: UvSphereOptions = {}): MeshDefinition {
  const radius = finitePositive(options.radius ?? 1, 'sphere.radius');
  const center = finiteVec3(options.center ?? [0, 0, 0], 'sphere.center');
  const plan = planUvSphereDetail(options.segments ?? 64, options.rings ?? 32, options.budget, options.overflow ?? 'error');
  const positions = new Float32Array(plan.vertexCount * 3);
  const normals = new Float32Array(plan.vertexCount * 3);
  const uvs = new Float32Array(plan.vertexCount * 2);
  const indices = new Uint32Array(plan.triangleCount * 3);

  const writeVertex = (vertex: number, nx: number, ny: number, nz: number, u: number, v: number): void => {
    const offset = vertex * 3;
    const uvOffset = vertex * 2;
    normals[offset] = nx;
    normals[offset + 1] = ny;
    normals[offset + 2] = nz;
    positions[offset] = center[0] + nx * radius;
    positions[offset + 1] = center[1] + ny * radius;
    positions[offset + 2] = center[2] + nz * radius;
    uvs[uvOffset] = u;
    uvs[uvOffset + 1] = v;
  };

  writeVertex(0, 0, 1, 0, 0.5, 0);
  let vertex = 1;
  for (let ring = 1; ring < plan.rings; ring += 1) {
    const theta = Math.PI * ring / plan.rings;
    const sinTheta = Math.sin(theta);
    const cosTheta = Math.cos(theta);
    for (let segment = 0; segment <= plan.segments; segment += 1) {
      const phi = segment === plan.segments ? 0 : Math.PI * 2 * segment / plan.segments;
      writeVertex(
        vertex,
        sinTheta * Math.cos(phi),
        cosTheta,
        sinTheta * Math.sin(phi),
        segment / plan.segments,
        ring / plan.rings
      );
      vertex += 1;
    }
  }
  const bottom = vertex;
  writeVertex(bottom, 0, -1, 0, 0.5, 1);

  let indexOffset = 0;
  const writeTriangle = (a: number, b: number, c: number): void => {
    indices[indexOffset] = a;
    indices[indexOffset + 1] = b;
    indices[indexOffset + 2] = c;
    indexOffset += 3;
  };
  for (let segment = 0; segment < plan.segments; segment += 1) {
    const current = 1 + segment;
    const next = current + 1;
    writeTriangle(0, next, current);
  }
  const ringStride = plan.segments + 1;
  for (let ring = 0; ring < plan.rings - 2; ring += 1) {
    const currentStart = 1 + ring * ringStride;
    const nextStart = currentStart + ringStride;
    for (let segment = 0; segment < plan.segments; segment += 1) {
      const a = currentStart + segment;
      const b = a + 1;
      const c = nextStart + segment;
      const d = c + 1;
      writeTriangle(a, b, c);
      writeTriangle(b, d, c);
    }
  }
  const lastRingStart = 1 + (plan.rings - 2) * ringStride;
  for (let segment = 0; segment < plan.segments; segment += 1) {
    const current = lastRingStart + segment;
    const next = current + 1;
    writeTriangle(bottom, current, next);
  }
  if (indexOffset !== indices.length) throw new Error('Internal UV sphere index count invariant failed');
  return {positions, indices, normals, uvs};
}
