import {TextureHandleRegistry} from './handles';
import {BrowserTextureImageProcessor} from './image-source';
import {
  ENVIRONMENT_SH_COEFFICIENT_COUNT,
  packEnvironmentShVec4,
  projectDiffuseIrradianceShAsync
} from './environment-sh';
import {
  analyzeCapturedEnvironmentSunAsync,
  capturedSunAlignsWithDirectionalLight,
  createSunlessEnvironmentBaseAsync,
  rotateEnvironmentDirectionToWorld,
  type CapturedEnvironmentSunProfile
} from './captured-sun';
import {downsampleLinearRgbaBoxAsync} from './environment-mips';
import {
  CooperativeTextureWork,
  type CooperativeTextureWorkOptions
} from './cooperative-work';
import type {
  BackplateMapLoadOptions,
  BackplateMapSource,
  BackplateMapStatus,
  DecodedFloatImage,
  DecodedTextureImage,
  EnvironmentMapLoadOptions,
  EnvironmentMapSource,
  EnvironmentMapStatus,
  FloatEnvironmentSource,
  TextureHandle,
  TextureImageProcessor,
  TextureImageSource,
  TextureLoadOptions,
  TextureAnisotropyLevel,
  TextureRegistryStatus,
  TextureResourceStatus
} from './types';

export const MATERIAL_TEXTURE_SIZE = 1024;
export const MATERIAL_TEXTURE_ARRAY_LAYERS = 40;
export const MAX_USER_MATERIAL_TEXTURES = MATERIAL_TEXTURE_ARRAY_LAYERS - 1;
export const MAX_ENVIRONMENT_MAP_WIDTH = 4096;
export const MAX_ENVIRONMENT_MAP_HEIGHT = 2048;
export const TEXTURE_ANISOTROPY_LEVELS = Object.freeze(
  [2, 4, 6, 8, 10, 12, 14, 16] as const
);

const MAX_LINEAR_UPLOAD_BYTES = 8 * 1024 * 1024;
const SUNLESS_ENVIRONMENT_MAX_WIDTH = 512;
const SUNLESS_ENVIRONMENT_MAX_HEIGHT = 256;

interface LoadingTextureEntry {
  readonly state: 'loading';
  readonly layer: number;
  readonly label: string;
}

interface ReadyTextureEntry {
  readonly state: 'ready';
  readonly layer: number;
  readonly label: string;
  readonly sourceWidth: number;
  readonly sourceHeight: number;
}

type TextureEntry = LoadingTextureEntry | ReadyTextureEntry;

interface FilteringSamplerSelection {
  readonly sampler: GPUSampler;
  readonly submittedMaxAnisotropy: number;
  readonly reportedMaxAnisotropy: number | null;
  readonly fallbackActive: boolean;
}

export interface GpuTextureResourcesOptions {
  readonly imageProcessor?: TextureImageProcessor;
  readonly onEnvironmentBindingChanged?: () => void;
}

export class GpuTextureResources {
  readonly #processor: TextureImageProcessor;
  readonly #onEnvironmentBindingChanged: () => void;
  readonly #textures = new TextureHandleRegistry<TextureEntry>(MAX_USER_MATERIAL_TEXTURES);
  readonly #loads = new Set<AbortController>();
  #state: TextureRegistryStatus['state'] = 'uninitialized';
  #generation = 0;
  #device: GPUDevice | null = null;
  #materialTexture: GPUTexture | null = null;
  #materialView: GPUTextureView | null = null;
  #materialLinearView: GPUTextureView | null = null;
  #sampler: GPUSampler | null = null;
  #requestedMaxAnisotropy: TextureAnisotropyLevel = 16;
  #submittedMaxAnisotropy = 0;
  #reportedMaxAnisotropy: number | null = null;
  #anisotropyFallbackActive = false;
  #fallbackEnvironmentTexture: GPUTexture | null = null;
  #fallbackEnvironmentView: GPUTextureView | null = null;
  #environmentTexture: GPUTexture | null = null;
  #environmentView: GPUTextureView | null = null;
  #backplateTexture: GPUTexture | null = null;
  #backplateView: GPUTextureView | null = null;
  #sunlessEnvironmentTexture: GPUTexture | null = null;
  #sunlessEnvironmentView: GPUTextureView | null = null;
  #environmentController: AbortController | null = null;
  #backplateController: AbortController | null = null;
  #environmentState: EnvironmentMapStatus['state'] = 'uninitialized';
  #environmentWidth = 0;
  #environmentHeight = 0;
  #environmentSourceWidth = 0;
  #environmentSourceHeight = 0;
  #environmentMipLevelCount = 1;
  #environmentGpuBytes = 0;
  #sunlessEnvironmentGpuBytes = 0;
  #environmentDynamicRange: EnvironmentMapStatus['dynamicRange'] = 'none';
  #environmentMessage = 'No environment map is loaded.';
  #environmentIntensity = 1;
  #environmentRotationDegrees = 0;
  #environmentPitchDegrees = 0;
  #backplateState: BackplateMapStatus['state'] = 'uninitialized';
  #backplateWidth = 0;
  #backplateHeight = 0;
  #backplateSourceWidth = 0;
  #backplateSourceHeight = 0;
  #backplateMipLevelCount = 1;
  #backplateGpuBytes = 0;
  #backplateDynamicRange: BackplateMapStatus['dynamicRange'] = 'none';
  #backplateMessage = 'No camera backplate is loaded.';
  #backplateIntensity = 1;
  #backplateRotationDegrees = 0;
  #backplatePitchDegrees = 0;
  #environmentIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
  #environmentSunlessIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
  #capturedSunProfile: CapturedEnvironmentSunProfile | null = null;
  #capturedSunState: 'unavailable' | 'not-detected' | 'ready' = 'unavailable';
  #capturedSunReason = 'No scene-linear float environment is loaded.';
  #lastError: string | null = null;

  constructor(options: GpuTextureResourcesOptions = {}) {
    this.#processor = options.imageProcessor ?? new BrowserTextureImageProcessor();
    this.#onEnvironmentBindingChanged = options.onEnvironmentBindingChanged ?? (() => {});
  }

  initialize(device: GPUDevice): void {
    if (this.#state === 'destroyed') {
      throw new Error('Cannot initialize destroyed GPU texture resources.');
    }
    this.releaseDevice();
    if (device.limits.maxTextureDimension2D < MATERIAL_TEXTURE_SIZE) {
      throw new RangeError(`The GPU must support ${MATERIAL_TEXTURE_SIZE}x${MATERIAL_TEXTURE_SIZE} material textures.`);
    }
    if (device.limits.maxTextureArrayLayers < MATERIAL_TEXTURE_ARRAY_LAYERS) {
      throw new RangeError(`The GPU must support at least ${MATERIAL_TEXTURE_ARRAY_LAYERS} texture-array layers.`);
    }

    const materialMipLevels = mipLevelCount(MATERIAL_TEXTURE_SIZE, MATERIAL_TEXTURE_SIZE);
    let materialTexture: GPUTexture | null = null;
    let fallbackEnvironmentTexture: GPUTexture | null = null;
    try {
      materialTexture = device.createTexture({
        label: 'PrioSDK material texture array',
        size: {
          width: MATERIAL_TEXTURE_SIZE,
          height: MATERIAL_TEXTURE_SIZE,
          depthOrArrayLayers: MATERIAL_TEXTURE_ARRAY_LAYERS
        },
        mipLevelCount: materialMipLevels,
        dimension: '2d',
        format: 'rgba8unorm',
        viewFormats: ['rgba8unorm-srgb'],
        usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
      });
      const materialView = materialTexture.createView({
        label: 'PrioSDK sRGB base-color texture array view',
        format: 'rgba8unorm-srgb',
        dimension: '2d-array',
        baseMipLevel: 0,
        mipLevelCount: materialMipLevels,
        baseArrayLayer: 0,
        arrayLayerCount: MATERIAL_TEXTURE_ARRAY_LAYERS
      });
      const materialLinearView = materialTexture.createView({
        label: 'PrioSDK linear material-data texture array view',
        format: 'rgba8unorm',
        dimension: '2d-array',
        baseMipLevel: 0,
        mipLevelCount: materialMipLevels,
        baseArrayLayer: 0,
        arrayLayerCount: MATERIAL_TEXTURE_ARRAY_LAYERS
      });
      const samplerSelection = createFilteringSampler(
        device,
        this.#requestedMaxAnisotropy,
        materialMipLevels
      );
      const sampler = samplerSelection.sampler;
      fallbackEnvironmentTexture = device.createTexture({
        label: 'PrioSDK fallback environment texture',
        size: {width: 1, height: 1, depthOrArrayLayers: 1},
        mipLevelCount: 1,
        dimension: '2d',
        format: 'rgba16float',
        usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
      });
      const fallbackEnvironmentView = fallbackEnvironmentTexture.createView({
        label: 'PrioSDK fallback environment view',
        dimension: '2d',
        format: 'rgba16float'
      });

      const white = new Uint8Array(MATERIAL_TEXTURE_SIZE * MATERIAL_TEXTURE_SIZE * 4);
      white.fill(255);
      let fallbackWidth = MATERIAL_TEXTURE_SIZE;
      let fallbackHeight = MATERIAL_TEXTURE_SIZE;
      for (let level = 0; level < materialMipLevels; level += 1) {
        const levelPixels = level === 0
          ? white
          : solidRgba8(fallbackWidth, fallbackHeight, 255, 255, 255, 255);
        writeTextureBytes(
          device.queue,
          materialTexture,
          level,
          0,
          fallbackWidth,
          fallbackHeight,
          4,
          levelPixels
        );
        fallbackWidth = Math.max(1, fallbackWidth >> 1);
        fallbackHeight = Math.max(1, fallbackHeight >> 1);
      }
      writeLinearRgba16(device.queue, fallbackEnvironmentTexture, 0, 1, 1, new Float32Array([0, 0, 0, 1]));

      this.#device = device;
      this.#materialTexture = materialTexture;
      this.#materialView = materialView;
      this.#materialLinearView = materialLinearView;
      this.#sampler = sampler;
      this.#submittedMaxAnisotropy = samplerSelection.submittedMaxAnisotropy;
      this.#reportedMaxAnisotropy = samplerSelection.reportedMaxAnisotropy;
      this.#anisotropyFallbackActive = samplerSelection.fallbackActive;
      this.#fallbackEnvironmentTexture = fallbackEnvironmentTexture;
      this.#fallbackEnvironmentView = fallbackEnvironmentView;
      this.#state = 'ready';
      this.#environmentState = 'empty';
      this.#environmentMessage = 'No environment map is loaded; procedural environment lighting remains active.';
      this.#backplateState = 'empty';
      this.#backplateMessage = 'No camera backplate is loaded; camera rays use the physical environment.';
      this.#capturedSunState = 'unavailable';
      this.#capturedSunReason = 'No scene-linear float environment is loaded.';
      this.#lastError = null;
    } catch (error) {
      safeDestroy(materialTexture);
      safeDestroy(fallbackEnvironmentTexture);
      this.#lastError = errorMessage(error);
      throw error;
    }
  }

  async loadTexture(source: TextureImageSource, options: TextureLoadOptions = {}): Promise<TextureHandle> {
    const device = this.#requireReady();
    const generation = this.#generation;
    const layer = this.#nextFreeLayer();
    const label = options.label?.trim() || 'material texture';
    const handle = this.#textures.create({state: 'loading', layer, label});
    const controller = new AbortController();
    const stopRelayingAbort = relayAbort(options.signal, controller);
    this.#loads.add(controller);
    let decoded: DecodedTextureImage | null = null;
    try {
      decoded = await this.#processor.decode(source, options, controller.signal);
      this.#assertLoadCurrent(generation, device, controller.signal);
      if (decoded.kind !== 'raster') {
        throw new TypeError('Radiance HDR and float images are supported for environment maps, not material textures.');
      }
      let width = MATERIAL_TEXTURE_SIZE;
      let height = MATERIAL_TEXTURE_SIZE;
      const levels = mipLevelCount(width, height);
      const work = this.#loadWork(generation, device, controller.signal);
      for (let level = 0; level < levels; level += 1) {
        this.#assertLoadCurrent(generation, device, controller.signal);
        const pixels = this.#processor.resampleRgba8Async === undefined
          ? this.#processor.resampleRgba8(decoded, width, height)
          : await this.#processor.resampleRgba8Async(decoded, width, height, work);
        this.#assertLoadCurrent(generation, device, controller.signal);
        requireRgbaLength(pixels.length, width, height, 'Resampled material texture');
        writeTextureBytes(device.queue, this.#materialTexture!, level, layer, width, height, 4, pixels);
        width = Math.max(1, width >> 1);
        height = Math.max(1, height >> 1);
      }
      this.#textures.set(handle, {
        state: 'ready',
        layer,
        label: options.label?.trim() || decoded.label,
        sourceWidth: decoded.width,
        sourceHeight: decoded.height
      });
      this.#lastError = null;
      return handle;
    } catch (error) {
      if (this.#textures.has(handle)) this.#textures.remove(handle);
      this.#lastError = errorMessage(error);
      throw error;
    } finally {
      decoded?.close();
      this.#loads.delete(controller);
      stopRelayingAbort();
    }
  }

  removeTexture(handle: TextureHandle): void {
    this.#requireReady();
    this.#textures.remove(handle);
  }

  resolveTextureLayer(handle: TextureHandle | null | undefined): number {
    if (handle === null || handle === undefined) return 0;
    const entry = this.#textures.get(handle);
    if (entry.state !== 'ready') throw new Error('The texture is still loading.');
    return entry.layer;
  }

  getTextureStatus(): TextureRegistryStatus;
  getTextureStatus(handle: TextureHandle): TextureResourceStatus;
  getTextureStatus(handle?: TextureHandle): TextureRegistryStatus | TextureResourceStatus {
    if (handle !== undefined) {
      const entry = this.#textures.get(handle);
      if (entry.state !== 'ready') throw new Error('The texture is still loading.');
      return {
        handle,
        state: 'ready',
        layer: entry.layer,
        label: entry.label,
        sourceWidth: entry.sourceWidth,
        sourceHeight: entry.sourceHeight,
        width: MATERIAL_TEXTURE_SIZE,
        height: MATERIAL_TEXTURE_SIZE,
        mipLevelCount: mipLevelCount(MATERIAL_TEXTURE_SIZE, MATERIAL_TEXTURE_SIZE)
      };
    }
    let loaded = 0;
    let loading = 0;
    for (const {value} of this.#textures.entries()) {
      if (value.state === 'ready') loaded += 1;
      else loading += 1;
    }
    return {
      state: this.#state,
      format: 'rgba8unorm-srgb',
      linearFormat: 'rgba8unorm',
      width: MATERIAL_TEXTURE_SIZE,
      height: MATERIAL_TEXTURE_SIZE,
      arrayLayers: MATERIAL_TEXTURE_ARRAY_LAYERS,
      mipLevelCount: mipLevelCount(MATERIAL_TEXTURE_SIZE, MATERIAL_TEXTURE_SIZE),
      fallbackLayer: 0,
      capacity: MAX_USER_MATERIAL_TEXTURES,
      loaded,
      loading,
      free: MAX_USER_MATERIAL_TEXTURES - loaded - loading,
      gpuBytes: this.#state === 'ready'
        ? estimateMipBytes(MATERIAL_TEXTURE_SIZE, MATERIAL_TEXTURE_SIZE, 4, MATERIAL_TEXTURE_ARRAY_LAYERS)
        : 0,
      requestedMaxAnisotropy: this.#requestedMaxAnisotropy,
      submittedMaxAnisotropy: this.#submittedMaxAnisotropy,
      reportedMaxAnisotropy: this.#reportedMaxAnisotropy,
      anisotropyFallbackActive: this.#anisotropyFallbackActive,
      lastError: this.#lastError
    };
  }

  async loadEnvironmentMap(
    source: EnvironmentMapSource,
    options: EnvironmentMapLoadOptions = {}
  ): Promise<EnvironmentMapStatus> {
    const device = this.#requireReady();
    const intensity = options.intensity === undefined
      ? this.#environmentIntensity
      : requireFiniteRange(options.intensity, 0, 1_000, 'Environment intensity');
    const rotation = options.rotationDegrees === undefined
      ? this.#environmentRotationDegrees
      : normalizeRotation(options.rotationDegrees);
    const pitch = options.pitchDegrees === undefined
      ? this.#environmentPitchDegrees
      : normalizePitch(options.pitchDegrees);
    const generation = this.#generation;
    this.#environmentController?.abort();
    const controller = new AbortController();
    const stopRelayingAbort = relayAbort(options.signal, controller);
    this.#environmentController = controller;
    this.#environmentState = 'loading';
    this.#environmentMessage = 'Loading environment map.';
    let decoded: DecodedTextureImage | null = null;
    let replacement: GPUTexture | null = null;
    let replacementSunless: GPUTexture | null = null;
    try {
      decoded = isFloatEnvironmentSource(source)
        ? validateFloatEnvironmentSource(source)
        : await this.#processor.decode(source, options, controller.signal);
      this.#assertLoadCurrent(generation, device, controller.signal);
      const work = this.#loadWork(generation, device, controller.signal);
      const capturedSunAnalysis = decoded.kind === 'float'
        ? await analyzeCapturedEnvironmentSunAsync(decoded.data, decoded.width, decoded.height, work)
        : {
            profile: null,
            reason: 'Captured-sun matching requires an original scene-linear Float32 or Radiance HDR source.'
          };
      const dimensions = fitEnvironmentDimensions(
        decoded.width,
        decoded.height,
        device.limits.maxTextureDimension2D
      );
      const levels = mipLevelCount(dimensions.width, dimensions.height);
      const basePixels = decoded.kind === 'float'
        ? decoded.width === dimensions.width && decoded.height === dimensions.height
          ? decoded.data
          : await downsampleLinearRgbaBoxAsync(
            decoded.data,
            decoded.width,
            decoded.height,
            dimensions.width,
            dimensions.height,
            work
          )
        : this.#processor.resampleLinearRgbaAsync === undefined
          ? this.#processor.resampleLinearRgba(decoded, dimensions.width, dimensions.height)
          : await this.#processor.resampleLinearRgbaAsync(
              decoded,
              dimensions.width,
              dimensions.height,
              work
            );
      this.#assertLoadCurrent(generation, device, controller.signal);
      requireRgbaLength(basePixels.length, dimensions.width, dimensions.height, 'Resampled environment map');
      const sunlessWidth = capturedSunAnalysis.profile !== null && decoded.kind === 'float'
        ? Math.min(decoded.width, SUNLESS_ENVIRONMENT_MAX_WIDTH)
        : 0;
      const sunlessHeight = capturedSunAnalysis.profile !== null && decoded.kind === 'float'
        ? Math.min(decoded.height, SUNLESS_ENVIRONMENT_MAX_HEIGHT)
        : 0;
      const sunlessBasePixels = capturedSunAnalysis.profile !== null && decoded.kind === 'float'
        ? await createSunlessEnvironmentBaseAsync(
            decoded.data,
            decoded.width,
            decoded.height,
            sunlessWidth,
            sunlessHeight,
            capturedSunAnalysis.profile,
            work
          )
        : null;
      const shWidth = Math.min(dimensions.width, 128);
      const shHeight = Math.min(dimensions.height, 64);
      const shPixels = await downsampleLinearRgbaBoxAsync(
        basePixels,
        dimensions.width,
        dimensions.height,
        shWidth,
        shHeight,
        work
      );
      requireRgbaLength(shPixels.length, shWidth, shHeight, 'Environment irradiance projection');
      const irradianceCoefficients = await projectDiffuseIrradianceShAsync(
        shPixels,
        shWidth,
        shHeight,
        work
      );
      const replacementIrradianceSh = packEnvironmentShVec4(irradianceCoefficients);
      const replacementSunlessIrradianceSh = packEnvironmentShVec4(
        sunlessBasePixels === null
          ? irradianceCoefficients
          : await projectDiffuseIrradianceShAsync(
              await downsampleLinearRgbaBoxAsync(
                sunlessBasePixels,
                sunlessWidth,
                sunlessHeight,
                Math.min(sunlessWidth, 128),
                Math.min(sunlessHeight, 64),
                work
              ),
              Math.min(sunlessWidth, 128),
              Math.min(sunlessHeight, 64),
              work
            )
      );
      this.#assertLoadCurrent(generation, device, controller.signal);
      replacement = device.createTexture({
        label: `PrioSDK environment map (${decoded.label})`,
        size: {width: dimensions.width, height: dimensions.height, depthOrArrayLayers: 1},
        mipLevelCount: levels,
        dimension: '2d',
        format: 'rgba16float',
        usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
      });
      const replacementView = replacement.createView({
        label: 'PrioSDK environment map view',
        dimension: '2d',
        format: 'rgba16float',
        baseMipLevel: 0,
        mipLevelCount: levels
      });
      let replacementSunlessView: GPUTextureView | null = null;
      let replacementSunlessGpuBytes = 0;
      if (sunlessBasePixels !== null) {
        const sunlessLevels = mipLevelCount(sunlessWidth, sunlessHeight);
        replacementSunless = device.createTexture({
          label: `PrioSDK sunless environment (${decoded.label})`,
          size: {width: sunlessWidth, height: sunlessHeight, depthOrArrayLayers: 1},
          mipLevelCount: sunlessLevels,
          dimension: '2d',
          format: 'rgba16float',
          usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
        });
        replacementSunlessView = replacementSunless.createView({
          label: 'PrioSDK sunless environment view',
          dimension: '2d',
          format: 'rgba16float',
          baseMipLevel: 0,
          mipLevelCount: sunlessLevels
        });
        let sunlessLevelWidth = sunlessWidth;
        let sunlessLevelHeight = sunlessHeight;
        let sunlessPixels = sunlessBasePixels;
        for (let level = 0; level < sunlessLevels; level += 1) {
          this.#assertLoadCurrent(generation, device, controller.signal);
          await writeLinearRgba16Async(
            device.queue,
            replacementSunless,
            level,
            sunlessLevelWidth,
            sunlessLevelHeight,
            sunlessPixels,
            work
          );
          const nextWidth = Math.max(1, sunlessLevelWidth >> 1);
          const nextHeight = Math.max(1, sunlessLevelHeight >> 1);
          if (level + 1 < sunlessLevels) {
            sunlessPixels = await downsampleLinearRgbaBoxAsync(
              sunlessPixels,
              sunlessLevelWidth,
              sunlessLevelHeight,
              nextWidth,
              nextHeight,
              work
            );
          }
          sunlessLevelWidth = nextWidth;
          sunlessLevelHeight = nextHeight;
        }
        replacementSunlessGpuBytes = estimateMipBytes(sunlessWidth, sunlessHeight, 8, 1);
      }
      let width = dimensions.width;
      let height = dimensions.height;
      let pixels = basePixels;
      for (let level = 0; level < levels; level += 1) {
        this.#assertLoadCurrent(generation, device, controller.signal);
        await writeLinearRgba16Async(device.queue, replacement, level, width, height, pixels, work);
        const nextWidth = Math.max(1, width >> 1);
        const nextHeight = Math.max(1, height >> 1);
        if (level + 1 < levels) {
          pixels = await downsampleLinearRgbaBoxAsync(
            pixels,
            width,
            height,
            nextWidth,
            nextHeight,
            work
          );
        }
        width = nextWidth;
        height = nextHeight;
      }

      const previousTexture = this.#environmentTexture;
      const previousView = this.#environmentView;
      const previousSunlessTexture = this.#sunlessEnvironmentTexture;
      const previousSunlessView = this.#sunlessEnvironmentView;
      const previousIrradianceSh = this.#environmentIrradianceSh;
      const previousSunlessIrradianceSh = this.#environmentSunlessIrradianceSh;
      const previousCapturedSunProfile = this.#capturedSunProfile;
      const previousCapturedSunState = this.#capturedSunState;
      const previousCapturedSunReason = this.#capturedSunReason;
      this.#environmentTexture = replacement;
      this.#environmentView = replacementView;
      this.#sunlessEnvironmentTexture = replacementSunless;
      this.#sunlessEnvironmentView = replacementSunlessView;
      this.#environmentIrradianceSh = new Float32Array(replacementIrradianceSh);
      this.#environmentSunlessIrradianceSh = new Float32Array(replacementSunlessIrradianceSh);
      this.#capturedSunProfile = capturedSunAnalysis.profile;
      this.#capturedSunState = decoded.kind !== 'float'
        ? 'unavailable'
        : capturedSunAnalysis.profile === null
          ? 'not-detected'
          : 'ready';
      this.#capturedSunReason = capturedSunAnalysis.reason;
      try {
        this.#onEnvironmentBindingChanged();
      } catch (error) {
        this.#environmentTexture = previousTexture;
        this.#environmentView = previousView;
        this.#sunlessEnvironmentTexture = previousSunlessTexture;
        this.#sunlessEnvironmentView = previousSunlessView;
        this.#environmentIrradianceSh = previousIrradianceSh;
        this.#environmentSunlessIrradianceSh = previousSunlessIrradianceSh;
        this.#capturedSunProfile = previousCapturedSunProfile;
        this.#capturedSunState = previousCapturedSunState;
        this.#capturedSunReason = previousCapturedSunReason;
        throw error;
      }
      replacement = null;
      replacementSunless = null;
      safeDestroy(previousTexture);
      safeDestroy(previousSunlessTexture);
      this.#environmentState = 'ready';
      this.#environmentWidth = dimensions.width;
      this.#environmentHeight = dimensions.height;
      this.#environmentSourceWidth = decoded.width;
      this.#environmentSourceHeight = decoded.height;
      this.#environmentMipLevelCount = levels;
      this.#sunlessEnvironmentGpuBytes = replacementSunlessGpuBytes;
      this.#environmentGpuBytes = estimateMipBytes(dimensions.width, dimensions.height, 8, 1)
        + replacementSunlessGpuBytes;
      this.#environmentDynamicRange = decoded.kind === 'float' ? decoded.dynamicRange : 'srgb';
      this.#environmentMessage = capturedSunAnalysis.profile === null
        ? `Environment map ready (${dimensions.width}x${dimensions.height}); no matchable captured sun was measured.`
        : `Environment map ready (${dimensions.width}x${dimensions.height}); a pre-half captured-sun profile is cached.`;
      this.#environmentIntensity = intensity;
      this.#environmentRotationDegrees = rotation;
      this.#environmentPitchDegrees = pitch;
      this.#lastError = null;
      return this.getEnvironmentMapStatus();
    } catch (error) {
      safeDestroy(replacement);
      safeDestroy(replacementSunless);
      if (!controller.signal.aborted || this.#environmentController === controller) {
        this.#environmentState = this.#environmentTexture === null ? 'error' : 'ready';
        this.#environmentMessage = `Environment map load failed: ${errorMessage(error)}`;
        this.#lastError = errorMessage(error);
      }
      throw error;
    } finally {
      decoded?.close();
      if (this.#environmentController === controller) this.#environmentController = null;
      stopRelayingAbort();
    }
  }

  async loadBackplateMap(
    source: BackplateMapSource,
    options: BackplateMapLoadOptions = {}
  ): Promise<BackplateMapStatus> {
    const device = this.#requireReady();
    const intensity = options.intensity === undefined
      ? this.#backplateIntensity
      : requireFiniteRange(options.intensity, 0, 1_000, 'Backplate intensity');
    const rotation = options.rotationDegrees === undefined
      ? this.#backplateRotationDegrees
      : normalizeRotation(options.rotationDegrees);
    const pitch = options.pitchDegrees === undefined
      ? this.#backplatePitchDegrees
      : normalizePitch(options.pitchDegrees);
    const generation = this.#generation;
    this.#backplateController?.abort();
    const controller = new AbortController();
    const stopRelayingAbort = relayAbort(options.signal, controller);
    this.#backplateController = controller;
    this.#backplateState = 'loading';
    this.#backplateMessage = 'Loading camera backplate.';
    let decoded: DecodedTextureImage | null = null;
    let replacement: GPUTexture | null = null;
    try {
      decoded = isFloatEnvironmentSource(source)
        ? validateFloatEnvironmentSource(source)
        : await this.#processor.decode(source, options, controller.signal);
      this.#assertLoadCurrent(generation, device, controller.signal);
      const work = this.#loadWork(generation, device, controller.signal);
      const dimensions = fitEnvironmentDimensions(
        decoded.width,
        decoded.height,
        device.limits.maxTextureDimension2D
      );
      const levels = mipLevelCount(dimensions.width, dimensions.height);
      const basePixels = decoded.kind === 'float'
        ? decoded.width === dimensions.width && decoded.height === dimensions.height
          ? decoded.data
          : await downsampleLinearRgbaBoxAsync(
            decoded.data,
            decoded.width,
            decoded.height,
            dimensions.width,
            dimensions.height,
            work
          )
        : this.#processor.resampleLinearRgbaAsync === undefined
          ? this.#processor.resampleLinearRgba(decoded, dimensions.width, dimensions.height)
          : await this.#processor.resampleLinearRgbaAsync(
              decoded,
              dimensions.width,
              dimensions.height,
              work
            );
      this.#assertLoadCurrent(generation, device, controller.signal);
      requireRgbaLength(basePixels.length, dimensions.width, dimensions.height, 'Resampled camera backplate');

      replacement = device.createTexture({
        label: `PrioSDK camera backplate (${decoded.label})`,
        size: {width: dimensions.width, height: dimensions.height, depthOrArrayLayers: 1},
        mipLevelCount: levels,
        dimension: '2d',
        format: 'rgba16float',
        usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
      });
      const replacementView = replacement.createView({
        label: 'PrioSDK camera backplate view',
        dimension: '2d',
        format: 'rgba16float',
        baseMipLevel: 0,
        mipLevelCount: levels
      });
      let width = dimensions.width;
      let height = dimensions.height;
      let pixels = basePixels;
      for (let level = 0; level < levels; level += 1) {
        this.#assertLoadCurrent(generation, device, controller.signal);
        await writeLinearRgba16Async(device.queue, replacement, level, width, height, pixels, work);
        const nextWidth = Math.max(1, width >> 1);
        const nextHeight = Math.max(1, height >> 1);
        if (level + 1 < levels) {
          pixels = await downsampleLinearRgbaBoxAsync(
            pixels,
            width,
            height,
            nextWidth,
            nextHeight,
            work
          );
        }
        width = nextWidth;
        height = nextHeight;
      }

      const previousTexture = this.#backplateTexture;
      const previousView = this.#backplateView;
      this.#backplateTexture = replacement;
      this.#backplateView = replacementView;
      try {
        this.#onEnvironmentBindingChanged();
      } catch (error) {
        this.#backplateTexture = previousTexture;
        this.#backplateView = previousView;
        throw error;
      }
      replacement = null;
      safeDestroy(previousTexture);
      this.#backplateState = 'ready';
      this.#backplateWidth = dimensions.width;
      this.#backplateHeight = dimensions.height;
      this.#backplateSourceWidth = decoded.width;
      this.#backplateSourceHeight = decoded.height;
      this.#backplateMipLevelCount = levels;
      this.#backplateGpuBytes = estimateMipBytes(dimensions.width, dimensions.height, 8, 1);
      this.#backplateDynamicRange = decoded.kind === 'float' ? decoded.dynamicRange : 'srgb';
      this.#backplateMessage = `Camera backplate ready (${dimensions.width}x${dimensions.height}); it is excluded from lighting and reflections.`;
      this.#backplateIntensity = intensity;
      this.#backplateRotationDegrees = rotation;
      this.#backplatePitchDegrees = pitch;
      this.#lastError = null;
      return this.getBackplateMapStatus();
    } catch (error) {
      safeDestroy(replacement);
      if (!controller.signal.aborted || this.#backplateController === controller) {
        this.#backplateState = this.#backplateTexture === null ? 'error' : 'ready';
        this.#backplateMessage = `Camera backplate load failed: ${errorMessage(error)}`;
        this.#lastError = errorMessage(error);
      }
      throw error;
    } finally {
      decoded?.close();
      if (this.#backplateController === controller) this.#backplateController = null;
      stopRelayingAbort();
    }
  }

  clearBackplateMap(): void {
    this.#requireReady();
    this.#backplateController?.abort();
    this.#backplateController = null;
    const previousTexture = this.#backplateTexture;
    const previousView = this.#backplateView;
    this.#backplateTexture = null;
    this.#backplateView = null;
    try {
      this.#onEnvironmentBindingChanged();
    } catch (error) {
      this.#backplateTexture = previousTexture;
      this.#backplateView = previousView;
      throw error;
    }
    safeDestroy(previousTexture);
    this.#backplateState = 'empty';
    this.#backplateWidth = 0;
    this.#backplateHeight = 0;
    this.#backplateSourceWidth = 0;
    this.#backplateSourceHeight = 0;
    this.#backplateMipLevelCount = 1;
    this.#backplateGpuBytes = 0;
    this.#backplateDynamicRange = 'none';
    this.#backplateMessage = 'No camera backplate is loaded; camera rays use the physical environment.';
  }

  setBackplateIntensity(intensity: number): void {
    this.#backplateIntensity = requireFiniteRange(intensity, 0, 1_000, 'Backplate intensity');
  }

  setBackplateRotation(rotationDegrees: number): void {
    this.#backplateRotationDegrees = normalizeRotation(rotationDegrees);
  }

  setBackplateOrientation(rotationDegrees: number, pitchDegrees: number): void {
    this.#backplateRotationDegrees = normalizeRotation(rotationDegrees);
    this.#backplatePitchDegrees = normalizePitch(pitchDegrees);
  }

  getBackplateMapStatus(): BackplateMapStatus {
    return {
      state: this.#state === 'destroyed'
        ? 'destroyed'
        : this.#state !== 'ready'
          ? 'uninitialized'
          : this.#backplateState,
      format: 'rgba16float',
      width: this.#backplateWidth,
      height: this.#backplateHeight,
      sourceWidth: this.#backplateSourceWidth,
      sourceHeight: this.#backplateSourceHeight,
      aspectRatio: this.#backplateHeight > 0
        ? this.#backplateWidth / this.#backplateHeight
        : 0,
      mipLevelCount: this.#backplateMipLevelCount,
      intensity: this.#backplateIntensity,
      rotationDegrees: this.#backplateRotationDegrees,
      pitchDegrees: this.#backplatePitchDegrees,
      gpuBytes: this.#backplateGpuBytes,
      dynamicRange: this.#backplateDynamicRange,
      visibilitySemantics: 'Camera-visible rays and chains of near-delta transmission only; excluded from diffuse lighting, glossy lighting, reflections, rough transmission, and volumetric illumination.',
      message: this.#backplateMessage
    };
  }

  getBackplateUniformParameters(): readonly [number, number, number, 0] {
    return [
      this.#backplateTexture === null ? 0 : 1,
      this.#backplateIntensity,
      this.#backplateRotationDegrees * Math.PI / 180,
      0
    ];
  }

  getBackplateOrientationUniformParameters(): readonly [number, number, number, 0] {
    const pitchRadians = this.#backplatePitchDegrees * Math.PI / 180;
    return [pitchRadians, Math.cos(pitchRadians), Math.sin(pitchRadians), 0];
  }

  getBackplateTextureView(): GPUTextureView {
    const view = this.#backplateView ?? this.#fallbackEnvironmentView;
    if (view === null) throw new Error('Camera backplate texture is not initialized.');
    return view;
  }

  clearEnvironmentMap(): void {
    this.#requireReady();
    this.#environmentController?.abort();
    this.#environmentController = null;
    const previousTexture = this.#environmentTexture;
    const previousView = this.#environmentView;
    const previousSunlessTexture = this.#sunlessEnvironmentTexture;
    const previousSunlessView = this.#sunlessEnvironmentView;
    this.#environmentTexture = null;
    this.#environmentView = null;
    this.#sunlessEnvironmentTexture = null;
    this.#sunlessEnvironmentView = null;
    try {
      this.#onEnvironmentBindingChanged();
    } catch (error) {
      this.#environmentTexture = previousTexture;
      this.#environmentView = previousView;
      this.#sunlessEnvironmentTexture = previousSunlessTexture;
      this.#sunlessEnvironmentView = previousSunlessView;
      throw error;
    }
    safeDestroy(previousTexture);
    safeDestroy(previousSunlessTexture);
    this.#environmentState = 'empty';
    this.#environmentWidth = 0;
    this.#environmentHeight = 0;
    this.#environmentSourceWidth = 0;
    this.#environmentSourceHeight = 0;
    this.#environmentMipLevelCount = 1;
    this.#environmentGpuBytes = 0;
    this.#sunlessEnvironmentGpuBytes = 0;
    this.#environmentDynamicRange = 'none';
    this.#environmentIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
    this.#environmentSunlessIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
    this.#capturedSunProfile = null;
    this.#capturedSunState = 'unavailable';
    this.#capturedSunReason = 'No scene-linear float environment is loaded.';
    this.#environmentMessage = 'No environment map is loaded; procedural environment lighting remains active.';
  }

  setEnvironmentIntensity(intensity: number): void {
    this.#environmentIntensity = requireFiniteRange(intensity, 0, 1_000, 'Environment intensity');
  }

  setEnvironmentRotation(rotationDegrees: number): void {
    this.#environmentRotationDegrees = normalizeRotation(rotationDegrees);
  }

  setEnvironmentOrientation(rotationDegrees: number, pitchDegrees: number): void {
    const rotation = normalizeRotation(rotationDegrees);
    const pitch = normalizePitch(pitchDegrees);
    this.#environmentRotationDegrees = rotation;
    this.#environmentPitchDegrees = pitch;
  }

  getEnvironmentMapStatus(options: {
    readonly sunMatchingEnabled?: boolean;
    readonly sunMatchingActive?: boolean;
  } = {}): EnvironmentMapStatus {
    const profile = this.#capturedSunProfile;
    const sunMatchingEnabled = options.sunMatchingEnabled === true;
    const sunMatchingActive = sunMatchingEnabled
      && options.sunMatchingActive === true
      && profile !== null;
    return {
      state: this.#state === 'destroyed'
        ? 'destroyed'
        : this.#state !== 'ready'
          ? 'uninitialized'
          : this.#environmentState,
      format: 'rgba16float',
      width: this.#environmentWidth,
      height: this.#environmentHeight,
      sourceWidth: this.#environmentSourceWidth,
      sourceHeight: this.#environmentSourceHeight,
      mipLevelCount: this.#environmentMipLevelCount,
      intensity: this.#environmentIntensity,
      rotationDegrees: this.#environmentRotationDegrees,
      pitchDegrees: this.#environmentPitchDegrees,
      gpuBytes: this.#environmentGpuBytes,
      sunlessGpuBytes: this.#sunlessEnvironmentGpuBytes,
      dynamicRange: this.#environmentDynamicRange,
      sunMatchingEnabled,
      sunMatchingActive,
      sunMatchingSemantics: sunMatchingActive
        ? 'Active: the aligned primary directional light uses the original pre-RGBA16F captured-sun RGB irradiance; its color and intensity are explicit multipliers. Diffuse and rough environment transport use the complementary sunless partition.'
        : sunMatchingEnabled
          ? 'Enabled but inactive: load a scene-linear float HDR with a detected compact sun and align the primary directional light after environment yaw and pitch.'
          : 'Disabled: directional-light color and intensity keep their existing absolute-radiance meaning, and the environment is not partitioned.',
      capturedSun: {
        state: this.#capturedSunState,
        reason: this.#capturedSunReason,
        sourceDirection: profile === null ? null : [...profile.direction],
        worldDirection: profile === null
          ? null
          : [...rotateEnvironmentDirectionToWorld(
              profile.direction,
              this.#environmentRotationDegrees,
              this.#environmentPitchDegrees
            )],
        sourceIntegratedIrradiance: profile === null ? null : [...profile.sourceIntegratedIrradiance],
        halfFloatMip0IntegratedIrradiance: profile === null
          ? null
          : [...profile.halfFloatMip0IntegratedIrradiance],
        localBackground: profile === null ? null : [...profile.localBackground],
        peakRadiance: profile === null ? null : [...profile.peakRadiance],
        peakLuminance: profile?.peakLuminance ?? 0,
        coreRadiusDegrees: (profile?.coreRadiusRadians ?? 0) * 180 / Math.PI,
        extractionRadiusDegrees: (profile?.extractionRadiusRadians ?? 0) * 180 / Math.PI,
        backgroundRadiusDegrees: (profile?.backgroundRadiusRadians ?? 0) * 180 / Math.PI,
        alignmentToleranceDegrees: (profile?.alignmentToleranceRadians ?? 0) * 180 / Math.PI,
        energySemantics: 'sourceIntegratedIrradiance is measured from original scene-linear Float32 texels before RGBA16F conversion; halfFloatMip0IntegratedIrradiance reports the energy remaining after component-wise 65504 clipping.'
      },
      message: this.#environmentMessage
    };
  }

  getEnvironmentUniformParameters(): readonly [number, number, number, 0] {
    return [
      this.#environmentTexture === null ? 0 : 1,
      this.#environmentIntensity,
      this.#environmentRotationDegrees * Math.PI / 180,
      0
    ];
  }

  getEnvironmentOrientationUniformParameters(): readonly [number, number, number, 0] {
    const pitchRadians = this.#environmentPitchDegrees * Math.PI / 180;
    return [pitchRadians, Math.cos(pitchRadians), Math.sin(pitchRadians), 0];
  }

  getEnvironmentIrradianceSh(): Float32Array {
    return this.#environmentIrradianceSh;
  }

  getEnvironmentSunlessIrradianceSh(): Float32Array {
    return this.#environmentSunlessIrradianceSh;
  }

  getCapturedSunUniforms(active: boolean): Float32Array {
    const values = new Float32Array(16);
    const profile = this.#capturedSunProfile;
    if (profile === null) return values;
    values.set([
      ...rotateEnvironmentDirectionToWorld(
        profile.direction,
        this.#environmentRotationDegrees,
        this.#environmentPitchDegrees
      ),
      1
    ], 0);
    values.set([...profile.sourceIntegratedIrradiance, profile.peakLuminance], 4);
    values.set([...profile.localBackground, profile.coreRadiusRadians], 8);
    values.set([
      profile.extractionRadiusRadians,
      profile.backgroundRadiusRadians,
      Math.cos(profile.alignmentToleranceRadians),
      active ? 1 : 0
    ], 12);
    return values;
  }

  capturedSunAlignsWithDirection(directionToLight: readonly [number, number, number]): boolean {
    return capturedSunAlignsWithDirectionalLight(
      this.#capturedSunProfile,
      directionToLight,
      this.#environmentRotationDegrees,
      this.#environmentPitchDegrees
    );
  }

  getMaterialTextureView(): GPUTextureView {
    if (this.#materialView === null) throw new Error('Material texture array is not initialized.');
    return this.#materialView;
  }

  getMaterialLinearTextureView(): GPUTextureView {
    if (this.#materialLinearView === null) throw new Error('Linear material texture array is not initialized.');
    return this.#materialLinearView;
  }

  setMaxAnisotropy(value: TextureAnisotropyLevel): TextureRegistryStatus {
    if (this.#state === 'destroyed') {
      throw new Error('GPU texture resources have been destroyed.');
    }
    const requested = requireTextureAnisotropyLevel(value);
    if (requested === this.#requestedMaxAnisotropy) return this.getTextureStatus();
    const device = this.#device;
    if (this.#state !== 'ready' || device === null) {
      this.#requestedMaxAnisotropy = requested;
      this.#lastError = null;
      return this.getTextureStatus();
    }

    let replacement: FilteringSamplerSelection;
    try {
      replacement = createFilteringSampler(device, requested, mipLevelCount(MATERIAL_TEXTURE_SIZE, MATERIAL_TEXTURE_SIZE));
    } catch (error) {
      this.#lastError = errorMessage(error);
      throw error;
    }
    const previousSampler = this.#sampler;
    const previousRequested = this.#requestedMaxAnisotropy;
    const previousSubmitted = this.#submittedMaxAnisotropy;
    const previousReported = this.#reportedMaxAnisotropy;
    const previousFallback = this.#anisotropyFallbackActive;
    this.#sampler = replacement.sampler;
    this.#requestedMaxAnisotropy = requested;
    this.#submittedMaxAnisotropy = replacement.submittedMaxAnisotropy;
    this.#reportedMaxAnisotropy = replacement.reportedMaxAnisotropy;
    this.#anisotropyFallbackActive = replacement.fallbackActive;
    try {
      this.#onEnvironmentBindingChanged();
    } catch (error) {
      this.#sampler = previousSampler;
      this.#requestedMaxAnisotropy = previousRequested;
      this.#submittedMaxAnisotropy = previousSubmitted;
      this.#reportedMaxAnisotropy = previousReported;
      this.#anisotropyFallbackActive = previousFallback;
      this.#lastError = errorMessage(error);
      throw error;
    }
    this.#lastError = null;
    return this.getTextureStatus();
  }

  getSampler(): GPUSampler {
    if (this.#sampler === null) throw new Error('Texture sampler is not initialized.');
    return this.#sampler;
  }

  getEnvironmentTextureView(): GPUTextureView {
    const view = this.#environmentView ?? this.#fallbackEnvironmentView;
    if (view === null) throw new Error('Environment texture is not initialized.');
    return view;
  }

  getSunlessEnvironmentTextureView(): GPUTextureView {
    const view = this.#sunlessEnvironmentView
      ?? this.#environmentView
      ?? this.#fallbackEnvironmentView;
    if (view === null) throw new Error('Sunless environment texture is not initialized.');
    return view;
  }

  releaseDevice(): void {
    this.#generation += 1;
    for (const controller of this.#loads) controller.abort();
    this.#loads.clear();
    this.#environmentController?.abort();
    this.#environmentController = null;
    this.#backplateController?.abort();
    this.#backplateController = null;
    this.#textures.clear();
    safeDestroy(this.#environmentTexture);
    safeDestroy(this.#backplateTexture);
    safeDestroy(this.#sunlessEnvironmentTexture);
    safeDestroy(this.#fallbackEnvironmentTexture);
    safeDestroy(this.#materialTexture);
    this.#environmentTexture = null;
    this.#environmentView = null;
    this.#backplateTexture = null;
    this.#backplateView = null;
    this.#sunlessEnvironmentTexture = null;
    this.#sunlessEnvironmentView = null;
    this.#fallbackEnvironmentTexture = null;
    this.#fallbackEnvironmentView = null;
    this.#materialTexture = null;
    this.#materialView = null;
    this.#materialLinearView = null;
    this.#sampler = null;
    this.#submittedMaxAnisotropy = 0;
    this.#reportedMaxAnisotropy = null;
    this.#anisotropyFallbackActive = false;
    this.#device = null;
    this.#environmentState = this.#state === 'destroyed' ? 'destroyed' : 'uninitialized';
    this.#environmentWidth = 0;
    this.#environmentHeight = 0;
    this.#environmentSourceWidth = 0;
    this.#environmentSourceHeight = 0;
    this.#environmentMipLevelCount = 1;
    this.#environmentGpuBytes = 0;
    this.#sunlessEnvironmentGpuBytes = 0;
    this.#environmentDynamicRange = 'none';
    this.#environmentIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
    this.#environmentSunlessIrradianceSh = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
    this.#capturedSunProfile = null;
    this.#capturedSunState = 'unavailable';
    this.#capturedSunReason = 'Texture resources are not initialized.';
    this.#environmentMessage = 'Environment texture resources are not initialized.';
    this.#backplateState = this.#state === 'destroyed' ? 'destroyed' : 'uninitialized';
    this.#backplateWidth = 0;
    this.#backplateHeight = 0;
    this.#backplateSourceWidth = 0;
    this.#backplateSourceHeight = 0;
    this.#backplateMipLevelCount = 1;
    this.#backplateGpuBytes = 0;
    this.#backplateDynamicRange = 'none';
    this.#backplateMessage = 'Camera backplate texture resources are not initialized.';
    if (this.#state !== 'destroyed') this.#state = 'uninitialized';
  }

  destroy(): void {
    if (this.#state === 'destroyed') return;
    this.releaseDevice();
    this.#state = 'destroyed';
    this.#environmentState = 'destroyed';
    this.#environmentMessage = 'Environment texture resources have been destroyed.';
    this.#backplateState = 'destroyed';
    this.#backplateMessage = 'Camera backplate texture resources have been destroyed.';
  }

  #requireReady(): GPUDevice {
    if (this.#state === 'destroyed') throw new Error('GPU texture resources have been destroyed.');
    if (this.#state !== 'ready' || this.#device === null) {
      throw new Error('GPU texture resources require an initialized WebGPU renderer.');
    }
    return this.#device;
  }

  #assertLoadCurrent(generation: number, device: GPUDevice, signal: AbortSignal): void {
    if (signal.aborted || generation !== this.#generation || this.#device !== device || this.#state !== 'ready') {
      throw new DOMException('Texture loading was cancelled because GPU resources changed.', 'AbortError');
    }
  }

  #loadWork(
    generation: number,
    device: GPUDevice,
    signal: AbortSignal
  ): CooperativeTextureWorkOptions {
    return {
      signal,
      checkCurrent: () => this.#assertLoadCurrent(generation, device, signal)
    };
  }

  #nextFreeLayer(): number {
    const used = new Set(this.#textures.entries().map(({value}) => value.layer));
    for (let layer = 1; layer < MATERIAL_TEXTURE_ARRAY_LAYERS; layer += 1) {
      if (!used.has(layer)) return layer;
    }
    throw new RangeError(`The material texture array is full (${MAX_USER_MATERIAL_TEXTURES} user textures).`);
  }

}

function isFloatEnvironmentSource(source: EnvironmentMapSource): source is FloatEnvironmentSource {
  return typeof source === 'object'
    && source !== null
    && !(source instanceof URL)
    && !(source instanceof Blob)
    && 'kind' in source
    && source.kind === 'float-rgba';
}

function validateFloatEnvironmentSource(source: FloatEnvironmentSource): DecodedFloatImage {
  if (!Number.isSafeInteger(source.width) || !Number.isSafeInteger(source.height) || source.width < 1 || source.height < 1) {
    throw new RangeError('Float environment dimensions must be positive safe integers.');
  }
  if (source.width * source.height > 8_388_608) {
    throw new RangeError('Float environment data exceeds the 8,388,608-pixel limit.');
  }
  requireRgbaLength(source.data.length, source.width, source.height, 'Float environment data');
  return {
    kind: 'float',
    data: source.data,
    width: source.width,
    height: source.height,
    label: source.label?.trim() || 'float environment',
    dynamicRange: 'float',
    close(): void {}
  };
}

function fitEnvironmentDimensions(
  width: number,
  height: number,
  deviceMaximumDimension: number
): {readonly width: number; readonly height: number} {
  if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width < 1 || height < 1) {
    throw new RangeError('Environment image dimensions must be positive safe integers.');
  }
  const safeDeviceMaximum = Math.max(1, Math.floor(deviceMaximumDimension));
  const maximumWidth = Math.min(MAX_ENVIRONMENT_MAP_WIDTH, safeDeviceMaximum);
  const maximumHeight = Math.min(MAX_ENVIRONMENT_MAP_HEIGHT, safeDeviceMaximum);
  const scale = Math.min(1, maximumWidth / width, maximumHeight / height);
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale))
  };
}

function mipLevelCount(width: number, height: number): number {
  return Math.floor(Math.log2(Math.max(width, height))) + 1;
}

function estimateMipBytes(width: number, height: number, bytesPerPixel: number, layers: number): number {
  let total = 0;
  while (true) {
    total += width * height * bytesPerPixel * layers;
    if (width === 1 && height === 1) break;
    width = Math.max(1, width >> 1);
    height = Math.max(1, height >> 1);
  }
  return total;
}

function writeLinearRgba16(
  queue: GPUQueue,
  texture: GPUTexture,
  mipLevel: number,
  width: number,
  height: number,
  values: Float32Array
): void {
  requireRgbaLength(values.length, width, height, 'Linear RGBA16 upload');
  const rowComponents = width * 4;
  const rowsPerUpload = Math.max(1, Math.floor(MAX_LINEAR_UPLOAD_BYTES / (width * 8)));
  for (let firstRow = 0; firstRow < height; firstRow += rowsPerUpload) {
    const rowCount = Math.min(rowsPerUpload, height - firstRow);
    const firstComponent = firstRow * rowComponents;
    const componentCount = rowCount * rowComponents;
    const halves = new Uint16Array(componentCount);
    for (let index = 0; index < componentCount; index += 1) {
      halves[index] = floatToHalf(Math.max(0, Math.min(65_504, finiteNumber(values[firstComponent + index]))));
    }
    writeTextureBytes(
      queue,
      texture,
      mipLevel,
      0,
      width,
      rowCount,
      8,
      new Uint8Array(halves.buffer),
      firstRow
    );
  }
}

async function writeLinearRgba16Async(
  queue: GPUQueue,
  texture: GPUTexture,
  mipLevel: number,
  width: number,
  height: number,
  values: Float32Array,
  options: CooperativeTextureWorkOptions
): Promise<void> {
  requireRgbaLength(values.length, width, height, 'Linear RGBA16 upload');
  const work = new CooperativeTextureWork(options);
  const rowComponents = width * 4;
  const rowsPerUpload = Math.max(1, Math.floor(MAX_LINEAR_UPLOAD_BYTES / (width * 8)));
  await work.checkpoint(true);
  for (let firstRow = 0; firstRow < height; firstRow += rowsPerUpload) {
    const rowCount = Math.min(rowsPerUpload, height - firstRow);
    const firstComponent = firstRow * rowComponents;
    const componentCount = rowCount * rowComponents;
    const halves = new Uint16Array(componentCount);
    for (let row = 0; row < rowCount; row += 1) {
      const rowOffset = row * rowComponents;
      for (let component = 0; component < rowComponents; component += 1) {
        const index = rowOffset + component;
        halves[index] = floatToHalf(Math.max(
          0,
          Math.min(65_504, finiteNumber(values[firstComponent + index]))
        ));
      }
      if (work.shouldYield()) await work.checkpoint(true);
    }
    work.assertCurrent();
    writeTextureBytes(
      queue,
      texture,
      mipLevel,
      0,
      width,
      rowCount,
      8,
      new Uint8Array(halves.buffer),
      firstRow
    );
    if (work.shouldYield()) await work.checkpoint(true);
  }
  work.assertCurrent();
}

function writeTextureBytes(
  queue: GPUQueue,
  texture: GPUTexture,
  mipLevel: number,
  layer: number,
  width: number,
  height: number,
  bytesPerPixel: number,
  source: Uint8Array,
  originY = 0
): void {
  const unpaddedBytesPerRow = width * bytesPerPixel;
  if (source.byteLength !== unpaddedBytesPerRow * height) {
    throw new RangeError('Texture upload byte length does not match its dimensions.');
  }
  const bytesPerRow = align(unpaddedBytesPerRow, 256);
  let upload = source;
  if (bytesPerRow !== unpaddedBytesPerRow) {
    upload = new Uint8Array(bytesPerRow * height);
    for (let row = 0; row < height; row += 1) {
      upload.set(source.subarray(row * unpaddedBytesPerRow, (row + 1) * unpaddedBytesPerRow), row * bytesPerRow);
    }
  }
  queue.writeTexture(
    {texture, mipLevel, origin: {x: 0, y: originY, z: layer}},
    upload,
    {offset: 0, bytesPerRow, rowsPerImage: height},
    {width, height, depthOrArrayLayers: 1}
  );
}

function solidRgba8(
  width: number,
  height: number,
  red: number,
  green: number,
  blue: number,
  alpha: number
): Uint8Array {
  const output = new Uint8Array(width * height * 4);
  for (let index = 0; index < output.length; index += 4) {
    output[index] = red;
    output[index + 1] = green;
    output[index + 2] = blue;
    output[index + 3] = alpha;
  }
  return output;
}

function requireRgbaLength(length: number, width: number, height: number, label: string): void {
  if (length !== width * height * 4) {
    throw new RangeError(`${label} must contain exactly width * height * 4 components.`);
  }
}

function normalizeRotation(value: number): number {
  if (!Number.isFinite(value)) throw new RangeError('Environment rotation must be finite degrees.');
  const normalized = value % 360;
  return normalized < 0 ? normalized + 360 : normalized;
}

function createFilteringSampler(
  device: GPUDevice,
  requestedMaxAnisotropy: TextureAnisotropyLevel,
  materialMipLevels: number
): FilteringSamplerSelection {
  const reportedMaxAnisotropy = reportedSamplerAnisotropyLimit(device);
  const submittedMaxAnisotropy = Math.max(
    1,
    Math.min(requestedMaxAnisotropy, reportedMaxAnisotropy ?? requestedMaxAnisotropy)
  );
  const descriptor = (maxAnisotropy: number): GPUSamplerDescriptor => ({
    label: 'PrioSDK repeating texture sampler',
    addressModeU: 'repeat',
    addressModeV: 'repeat',
    addressModeW: 'repeat',
    magFilter: 'linear',
    minFilter: 'linear',
    mipmapFilter: 'linear',
    maxAnisotropy,
    lodMinClamp: 0,
    lodMaxClamp: Math.max(
      materialMipLevels,
      mipLevelCount(MAX_ENVIRONMENT_MAP_WIDTH, MAX_ENVIRONMENT_MAP_HEIGHT)
    ) - 1
  });
  try {
    return {
      sampler: device.createSampler(descriptor(submittedMaxAnisotropy)),
      submittedMaxAnisotropy,
      reportedMaxAnisotropy,
      fallbackActive: submittedMaxAnisotropy < requestedMaxAnisotropy
    };
  } catch (error) {
    if (submittedMaxAnisotropy <= 1) throw error;
    return {
      sampler: device.createSampler(descriptor(1)),
      submittedMaxAnisotropy: 1,
      reportedMaxAnisotropy,
      fallbackActive: true
    };
  }
}

function reportedSamplerAnisotropyLimit(device: GPUDevice): number | null {
  const value = (device.limits as unknown as {readonly maxSamplerAnisotropy?: unknown})
    .maxSamplerAnisotropy;
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return Math.max(1, Math.min(16, Math.floor(value)));
}

function requireTextureAnisotropyLevel(value: number): TextureAnisotropyLevel {
  if (!(TEXTURE_ANISOTROPY_LEVELS as readonly number[]).includes(value)) {
    throw new RangeError('Texture anisotropy must be one of 2, 4, 6, 8, 10, 12, 14, or 16.');
  }
  return value as TextureAnisotropyLevel;
}

function normalizePitch(value: number): number {
  if (!Number.isFinite(value)) throw new RangeError('Environment pitch must be finite degrees.');
  const normalized = ((value + 180) % 360 + 360) % 360 - 180;
  return Object.is(normalized, -0) ? 0 : normalized;
}

function requireFiniteRange(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isFinite(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be from ${minimum} through ${maximum}.`);
  }
  return value;
}

function finiteNumber(value: number | undefined): number {
  return Number.isFinite(value) ? value! : 0;
}

function relayAbort(source: AbortSignal | undefined, target: AbortController): () => void {
  if (source === undefined) return () => {};
  if (source.aborted) {
    target.abort(source.reason);
    return () => {};
  }
  const abort = (): void => target.abort(source.reason);
  source.addEventListener('abort', abort, {once: true});
  return () => source.removeEventListener('abort', abort);
}

function floatToHalf(value: number): number {
  if (value === 0) return 0;
  if (value >= 65_504) return 0x7bff;
  const exponent = Math.floor(Math.log2(value));
  if (exponent < -14) return Math.min(0x03ff, Math.round(value / 2 ** -24));
  const biasedExponent = exponent + 15;
  const mantissa = Math.round((value / 2 ** exponent - 1) * 1024);
  if (mantissa === 1024) return (biasedExponent + 1) << 10;
  return (biasedExponent << 10) | (mantissa & 0x03ff);
}

function align(value: number, alignment: number): number {
  return Math.ceil(value / alignment) * alignment;
}

function safeDestroy(texture: GPUTexture | null): void {
  if (texture === null) return;
  try {
    texture.destroy();
  } catch {
    // A lost device already owns no live texture allocation.
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
