const DISPLAY_UNIFORM_BYTES = 80;
const EXPOSURE_UNIFORM_BYTES = 32;
const EXPOSURE_STATE_BYTES = 16;
const TEMPORAL_UNIFORM_BYTES = 48;
const FRAME_INTERPOLATION_UNIFORM_BYTES = 48;
const FSR1_EASU_UNIFORM_BYTES = 64;
const FSR1_RCAS_UNIFORM_BYTES = 16;
const DENOISE_UNIFORM_BYTES = 48;
const PHOTOGRAPHIC_UNIFORM_BYTES = 64;
const LEARNED_ENHANCEMENT_UNIFORM_BYTES = 80;

/** Scene-linear camera-latitude response used only before the SDR ACES transform. */
export const SDR_ACES_CAMERA_LATITUDE = Object.freeze({
  shadowLiftToeFloor: 0.52,
  shadowLiftToeStartLuminance: 0.004,
  shadowLiftToeEndLuminance: 0.025,
  shadowLiftFalloffStartLuminance: 0.04,
  shadowLiftEndLuminance: 0.65,
  highlightStartLuminance: 0.6,
  highlightCurveRate: 4
});

export const CAMERA_LATITUDE_LIMITS = Object.freeze({
  shadowLiftStops: Object.freeze({minimum: 0, maximum: 3}),
  highlightProtection: Object.freeze({minimum: 0, maximum: 1})
});

const DISPLAY_TONE_MAP_FUNCTION_ANCHOR = 'fn tone_map(color: vec3<f32>, mode: f32) -> vec3<f32> {';
const DISPLAY_TONE_MAP_CALL_ANCHOR = '  let mapped = tone_map(exposed, parameters.controls.y);';
const CAMERA_LATITUDE_WGSL = /* wgsl */ `
fn apply_camera_latitude(
  color: vec3<f32>,
  shadow_lift_stops: f32,
  highlight_protection: f32
) -> vec3<f32> {
  let safe_color = max(color, vec3<f32>(0.0));
  let scene_luminance = luminance(safe_color);
  let shadow_toe = mix(
    ${SDR_ACES_CAMERA_LATITUDE.shadowLiftToeFloor.toFixed(2)},
    1.0,
    smoothstep(
    ${SDR_ACES_CAMERA_LATITUDE.shadowLiftToeStartLuminance.toFixed(3)},
    ${SDR_ACES_CAMERA_LATITUDE.shadowLiftToeEndLuminance.toFixed(3)},
    scene_luminance
    )
  );
  let shadow_falloff = 1.0 - smoothstep(
    ${SDR_ACES_CAMERA_LATITUDE.shadowLiftFalloffStartLuminance.toFixed(3)},
    ${SDR_ACES_CAMERA_LATITUDE.shadowLiftEndLuminance.toFixed(2)},
    scene_luminance
  );
  let shadow_weight = shadow_toe * shadow_falloff;
  let lifted_luminance = scene_luminance * exp2(
    clamp(shadow_lift_stops, 0.0, 3.0) * shadow_weight
  );
  let shoulder_start = ${SDR_ACES_CAMERA_LATITUDE.highlightStartLuminance.toFixed(1)};
  let shoulder_distance = max(lifted_luminance - shoulder_start, 0.0);
  let protected_luminance = shoulder_start
    + log(1.0 + shoulder_distance * ${SDR_ACES_CAMERA_LATITUDE.highlightCurveRate.toFixed(1)})
      / ${SDR_ACES_CAMERA_LATITUDE.highlightCurveRate.toFixed(1)};
  let shoulder_luminance = select(
    lifted_luminance,
    protected_luminance,
    lifted_luminance > shoulder_start
  );
  let developed_luminance = mix(
    lifted_luminance,
    shoulder_luminance,
    clamp(highlight_protection, 0.0, 1.0)
  );
  return safe_color * (developed_luminance / max(scene_luminance, 0.000001));
}
`;

export function buildCameraDisplayPostProcessShader(
  source = DISPLAY_POST_PROCESS_SHADER
): string {
  if (
    source.split(DISPLAY_TONE_MAP_FUNCTION_ANCHOR).length !== 2
    || source.split(DISPLAY_TONE_MAP_CALL_ANCHOR).length !== 2
  ) {
    throw new Error('Display shader camera-response anchors are missing or ambiguous.');
  }
  return source
    .replace(
      DISPLAY_TONE_MAP_FUNCTION_ANCHOR,
      `${CAMERA_LATITUDE_WGSL}\n${DISPLAY_TONE_MAP_FUNCTION_ANCHOR}`
    )
    .replace(
      DISPLAY_TONE_MAP_CALL_ANCHOR,
      `  var tone_input = exposed;\n`
        + `  if (parameters.controls.y < 0.5\n`
        + `    && (parameters.camera_latitude.x > 0.0 || parameters.camera_latitude.y > 0.0)) {\n`
        + `    tone_input = apply_camera_latitude(\n`
        + `      exposed, parameters.camera_latitude.x, parameters.camera_latitude.y\n`
        + `    );\n`
        + `  }\n`
        + '  let mapped = tone_map(tone_input, parameters.controls.y);'
    );
}

export const CAMERA_DISPLAY_POST_PROCESS_SHADER = buildCameraDisplayPostProcessShader();

export const PHOTOGRAPHIC_EFFECT_LIMITS = Object.freeze({
  filmGrainStrength: Object.freeze({minimum: 0, maximum: 0.25}),
  filmGrainScale: Object.freeze({minimum: 0.5, maximum: 8}),
  chromaticAberrationPixels: Object.freeze({minimum: 0, maximum: 32}),
  chromaticAberrationEdgeStart: Object.freeze({minimum: 0, maximum: 1}),
  chromaticAberrationFalloff: Object.freeze({minimum: 0.01, maximum: 1})
});

export interface PhotographicEffectOptions {
  /** Fractional midtone modulation in `[0, 0.25]`; zero disables film grain. */
  readonly filmGrainStrength?: number;
  /** Approximate grain-cell size in output pixels, clamped to `[0.5, 8]`. */
  readonly filmGrainScale?: number;
  /** Maximum red/blue radial displacement in output pixels, clamped to `[0, 32]`. */
  readonly chromaticAberrationPixels?: number;
  /** Normalized diagonal radius at which chromatic separation begins, in `[0, 1]`. */
  readonly chromaticAberrationEdgeStart?: number;
  /** Normalized radial distance over which separation reaches full strength, in `[0.01, 1]`. */
  readonly chromaticAberrationFalloff?: number;
}

export interface NormalizedPhotographicEffects {
  readonly filmGrainStrength: number;
  readonly filmGrainScale: number;
  readonly chromaticAberrationPixels: number;
  readonly chromaticAberrationEdgeStart: number;
  readonly chromaticAberrationFalloff: number;
}

export const DEFAULT_PHOTOGRAPHIC_EFFECTS: Readonly<NormalizedPhotographicEffects> = Object.freeze({
  filmGrainStrength: 0,
  filmGrainScale: 1,
  chromaticAberrationPixels: 0,
  chromaticAberrationEdgeStart: 0.35,
  chromaticAberrationFalloff: 0.65
});

interface PipelineSet {
  readonly denoise: GPUComputePipeline;
  readonly learnedEnhancement: GPUComputePipeline;
  readonly temporal: GPUComputePipeline;
  readonly fsr1Easu: GPUComputePipeline;
  readonly fsr1Rcas: GPUComputePipeline;
  readonly exposure: GPUComputePipeline;
  readonly display: GPUComputePipeline;
  readonly outputStyle: GPUComputePipeline;
  readonly photographic: GPUComputePipeline;
  readonly opticalFlow: GPUComputePipeline;
  readonly frameInterpolation: GPUComputePipeline;
}

interface TexturePair {
  readonly textures: readonly [GPUTexture, GPUTexture];
  readonly views: readonly [GPUTextureView, GPUTextureView];
}

interface LearnedEnhancementTarget {
  readonly texture: GPUTexture;
  readonly view: GPUTextureView;
  readonly width: number;
  readonly height: number;
}

interface PostTargets {
  destroy(): void;
  readonly denoise: TexturePair;
  readonly temporal: TexturePair;
  readonly toneMappedRender: GPUTexture;
  readonly toneMappedRenderView: GPUTextureView;
  readonly fsrIntermediate: GPUTexture;
  readonly fsrIntermediateView: GPUTextureView;
  readonly display: TexturePair;
  readonly opticalFlow: GPUTexture;
  readonly opticalFlowView: GPUTextureView;
  readonly interpolation: GPUTexture;
  readonly interpolationView: GPUTextureView;
  readonly photographicGenerated: GPUTexture;
  readonly photographicGeneratedView: GPUTextureView;
  readonly disocclusion: GPUTexture;
  readonly disocclusionView: GPUTextureView;
}

export interface PostFrameInputs extends PhotographicEffectOptions {
  readonly encoder: GPUCommandEncoder;
  readonly hdrView: GPUTextureView;
  readonly currentNormalDepthView: GPUTextureView;
  readonly previousNormalDepthView: GPUTextureView;
  readonly albedoRoughnessView: GPUTextureView;
  readonly motionReactiveView: GPUTextureView;
  readonly settings: RenderSettings;
  readonly frameIndex: number;
  readonly accumulatedSamples?: number;
  readonly deltaSeconds: number;
  readonly hdrOutputActive: boolean;
  /** Display-referred finish. Omitted or `photoreal` preserves the existing output exactly. */
  readonly outputStyle?: OutputStyleOptions;
}

export interface PostFrameResult {
  readonly presentationView: GPUTextureView;
  readonly currentDisplayView: GPUTextureView;
  readonly generated: boolean;
  readonly learnedEnhancementDispatched: boolean;
}

export interface FramePipelineCreateOptions {
  readonly onProgress?: (label: string) => void;
  readonly signal?: AbortSignal;
}

export function normalizePhotographicEffects(
  options: PhotographicEffectOptions = {}
): NormalizedPhotographicEffects {
  return {
    filmGrainStrength: finiteClampedOption(
      options.filmGrainStrength,
      PHOTOGRAPHIC_EFFECT_LIMITS.filmGrainStrength,
      DEFAULT_PHOTOGRAPHIC_EFFECTS.filmGrainStrength
    ),
    filmGrainScale: finiteClampedOption(
      options.filmGrainScale,
      PHOTOGRAPHIC_EFFECT_LIMITS.filmGrainScale,
      DEFAULT_PHOTOGRAPHIC_EFFECTS.filmGrainScale
    ),
    chromaticAberrationPixels: finiteClampedOption(
      options.chromaticAberrationPixels,
      PHOTOGRAPHIC_EFFECT_LIMITS.chromaticAberrationPixels,
      DEFAULT_PHOTOGRAPHIC_EFFECTS.chromaticAberrationPixels
    ),
    chromaticAberrationEdgeStart: finiteClampedOption(
      options.chromaticAberrationEdgeStart,
      PHOTOGRAPHIC_EFFECT_LIMITS.chromaticAberrationEdgeStart,
      DEFAULT_PHOTOGRAPHIC_EFFECTS.chromaticAberrationEdgeStart
    ),
    chromaticAberrationFalloff: finiteClampedOption(
      options.chromaticAberrationFalloff,
      PHOTOGRAPHIC_EFFECT_LIMITS.chromaticAberrationFalloff,
      DEFAULT_PHOTOGRAPHIC_EFFECTS.chromaticAberrationFalloff
    )
  };
}

export function shouldApplyPhotographicEffects(effects: PhotographicEffectOptions): boolean {
  const normalized = normalizePhotographicEffects(effects);
  return normalized.filmGrainStrength > 0 || normalized.chromaticAberrationPixels > 0;
}

export function buildPhotographicEffectsConstants(
  outputWidth: number,
  outputHeight: number,
  frameIndex: number,
  hdrOutputActive: boolean,
  options: PhotographicEffectOptions = {}
): ArrayBuffer {
  const width = finitePositiveInteger(outputWidth);
  const height = finitePositiveInteger(outputHeight);
  const effects = normalizePhotographicEffects(options);
  const storage = new ArrayBuffer(PHOTOGRAPHIC_UNIFORM_BYTES);
  const floats = new Float32Array(storage);
  floats.set([width, height, 1 / width, 1 / height], 0);
  floats.set([effects.filmGrainStrength, effects.filmGrainScale, 0, 0], 4);
  floats.set([
    effects.chromaticAberrationPixels,
    effects.chromaticAberrationEdgeStart,
    effects.chromaticAberrationFalloff,
    0
  ], 8);
  const unsigned = new Uint32Array(storage);
  unsigned[12] = stableFrameSeed(frameIndex);
  unsigned[13] = hdrOutputActive ? 1 : 0;
  return storage;
}

export function buildDisplayPostProcessConstants(
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  settings: RenderSettings,
  hdrOutputActive: boolean
): ArrayBuffer {
  const storage = new Float32Array(DISPLAY_UNIFORM_BYTES / Float32Array.BYTES_PER_ELEMENT);
  storage.set([
    finitePositiveInteger(sourceWidth),
    finitePositiveInteger(sourceHeight),
    finitePositiveInteger(destinationWidth),
    finitePositiveInteger(destinationHeight),
    settings.exposure,
    toneMappingIndex(settings.toneMapping),
    settings.bloomStrength,
    settings.bloomThreshold,
    settings.autoExposure ? 1 : 0,
    hdrOutputActive && !settings.upscaling.startsWith('fsr1-') ? 1 : 0,
    settings.cameraWhiteBalance[0],
    settings.cameraWhiteBalance[1],
    Math.max(settings.bloomThreshold * 0.5, 0.05),
    2,
    settings.cameraWhiteBalance[2],
    0,
    finiteClampedOption(
      settings.cameraShadowLiftStops,
      CAMERA_LATITUDE_LIMITS.shadowLiftStops,
      0
    ),
    finiteClampedOption(
      settings.cameraHighlightProtection,
      CAMERA_LATITUDE_LIMITS.highlightProtection,
      0
    ),
    0,
    0
  ]);
  return storage.buffer;
}

export function selectAtrousDenoiseQuality(
  denoising: RenderSettings['denoising']
): AtrousDenoiseQuality {
  return denoising === 'quality' ? 'quality' : 'balanced';
}

export class FramePipeline {
  readonly #device: GPUDevice;
  readonly #pipelines: PipelineSet;
  readonly #sampler: GPUSampler;
  readonly #denoiseUniforms: readonly GPUBuffer[];
  readonly #learnedEnhancementUniform: GPUBuffer;
  readonly #temporalUniform: GPUBuffer;
  readonly #fsr1EasuUniform: GPUBuffer;
  readonly #fsr1RcasUniform: GPUBuffer;
  readonly #exposureUniform: GPUBuffer;
  readonly #exposureState: GPUBuffer;
  readonly #displayUniform: GPUBuffer;
  readonly #outputStyleUniforms: readonly [GPUBuffer, GPUBuffer];
  readonly #photographicUniforms: readonly [GPUBuffer, GPUBuffer];
  readonly #frameInterpolationUniform: GPUBuffer;

  #targets: PostTargets | null = null;
  #learnedEnhancementTarget: LearnedEnhancementTarget | null = null;
  #outputStyleTargets: TexturePair | null = null;
  #renderWidth = 1;
  #renderHeight = 1;
  #outputWidth = 1;
  #outputHeight = 1;
  #temporalActive: 0 | 1 = 0;
  #displayActive: 0 | 1 = 0;
  #temporalHistoryValid = false;
  #displayHistoryValid = false;

  private constructor(device: GPUDevice, pipelines: PipelineSet) {
    this.#device = device;
    this.#pipelines = pipelines;
    this.#sampler = device.createSampler({
      label: 'PrioSDK post-process linear sampler',
      magFilter: 'linear',
      minFilter: 'linear',
      addressModeU: 'clamp-to-edge',
      addressModeV: 'clamp-to-edge'
    });
    this.#denoiseUniforms = Array.from(
      {length: ATROUS_DENOISE_ITERATIONS},
      (_, iteration) => createUniformBuffer(
        device,
        `PrioSDK denoise iteration ${iteration}`,
        DENOISE_UNIFORM_BYTES
      )
    );
    this.#learnedEnhancementUniform = createUniformBuffer(
      device,
      'PrioSDK experimental learned enhancement parameters',
      LEARNED_ENHANCEMENT_UNIFORM_BYTES
    );
    this.#temporalUniform = createUniformBuffer(device, 'PrioSDK temporal upscale parameters', TEMPORAL_UNIFORM_BYTES);
    this.#fsr1EasuUniform = createUniformBuffer(device, 'PrioSDK FSR 1 EASU parameters', FSR1_EASU_UNIFORM_BYTES);
    this.#fsr1RcasUniform = createUniformBuffer(device, 'PrioSDK FSR 1 RCAS parameters', FSR1_RCAS_UNIFORM_BYTES);
    this.#exposureUniform = createUniformBuffer(device, 'PrioSDK automatic exposure parameters', EXPOSURE_UNIFORM_BYTES);
    this.#exposureState = device.createBuffer({
      label: 'PrioSDK automatic exposure state',
      size: EXPOSURE_STATE_BYTES,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST
    });
    this.#displayUniform = createUniformBuffer(device, 'PrioSDK HDR display parameters', DISPLAY_UNIFORM_BYTES);
    this.#outputStyleUniforms = [
      createUniformBuffer(device, 'PrioSDK output style parameters 0', OUTPUT_STYLE_UNIFORM_BYTES),
      createUniformBuffer(device, 'PrioSDK output style parameters 1', OUTPUT_STYLE_UNIFORM_BYTES)
    ];
    this.#photographicUniforms = [
      createUniformBuffer(device, 'PrioSDK photographic effects parameters 0', PHOTOGRAPHIC_UNIFORM_BYTES),
      createUniformBuffer(device, 'PrioSDK photographic effects parameters 1', PHOTOGRAPHIC_UNIFORM_BYTES)
    ];
    this.#frameInterpolationUniform = createUniformBuffer(
      device,
      'PrioSDK experimental frame interpolation parameters',
      FRAME_INTERPOLATION_UNIFORM_BYTES
    );
    this.#resetExposure();
  }

  static async create(device: GPUDevice, options: FramePipelineCreateOptions = {}): Promise<FramePipeline> {
    const entries = [
      ['denoise', ATROUS_DENOISE_SHADER],
      ['learnedEnhancement', LEARNED_ENHANCEMENT_SHADER],
      ['temporal', TEMPORAL_REPROJECTION_UPSCALE_SHADER],
      ['fsr1Easu', FSR1_EASU_RGBA16FLOAT_SHADER],
      ['fsr1Rcas', FSR1_RCAS_RGBA16FLOAT_SHADER],
      ['exposure', AUTO_EXPOSURE_SHADER],
      ['display', CAMERA_DISPLAY_POST_PROCESS_SHADER],
      ['outputStyle', OUTPUT_STYLE_SHADER],
      ['photographic', PHOTOGRAPHIC_EFFECTS_SHADER],
      ['opticalFlow', EXPERIMENTAL_OPTICAL_FLOW_FALLBACK_SHADER],
      ['frameInterpolation', EXPERIMENTAL_FRAME_INTERPOLATION_RGBA16FLOAT_SHADER]
    ] as const;
    const pipelines: Partial<PipelineSet> = {};
    for (const [index, [name, code]] of entries.entries()) {
      assertCreationActive(options.signal);
      options.onProgress?.(`Validating image processing ${index + 1}/${entries.length}: ${name}`);
      assertCreationActive(options.signal);
      const module = device.createShaderModule({label: `PrioSDK ${name} shader`, code});
      await abortableCreation(assertShaderCompiles(module, name), options.signal);
      assertCreationActive(options.signal);
      options.onProgress?.(`Compiling image processing ${index + 1}/${entries.length}: ${name}`);
      assertCreationActive(options.signal);
      const pipeline = await abortableCreation(device.createComputePipelineAsync({
        label: `PrioSDK ${name} pipeline`,
        layout: 'auto',
        compute: {module, entryPoint: 'main'}
      }), options.signal);
      Object.assign(pipelines, {[name]: pipeline});
    }
    assertCreationActive(options.signal);
    return new FramePipeline(device, pipelines as PipelineSet);
  }

  resize(renderWidth: number, renderHeight: number, outputWidth: number, outputHeight: number): void {
    if (
      this.#targets !== null
      && renderWidth === this.#renderWidth
      && renderHeight === this.#renderHeight
      && outputWidth === this.#outputWidth
      && outputHeight === this.#outputHeight
    ) {
      return;
    }
    const nextTargets = createPostTargets(
      this.#device,
      renderWidth,
      renderHeight,
      outputWidth,
      outputHeight
    );
    const previousTargets = this.#targets;
    const previousOutputStyleTargets = this.#outputStyleTargets;
    const previousLearnedEnhancementTarget = this.#learnedEnhancementTarget;
    this.#targets = nextTargets;
    this.#outputStyleTargets = null;
    this.#learnedEnhancementTarget = null;
    this.#renderWidth = renderWidth;
    this.#renderHeight = renderHeight;
    this.#outputWidth = outputWidth;
    this.#outputHeight = outputHeight;
    if (previousTargets !== null) {
      destroyPostTargets(previousTargets);
    }
    if (previousOutputStyleTargets !== null) {
      destroyPair(previousOutputStyleTargets);
    }
    previousLearnedEnhancementTarget?.texture.destroy();
    this.resetHistory();
  }

  encodePreview(inputs: PostFrameInputs): GPUTextureView {
    const targets = this.#targets;
    if (targets === null) throw new Error('Post-process targets have not been sized.');
    const destination = targets.display.views[this.#displayActive === 0 ? 1 : 0];
    // An incomplete sample is never fed into restoration or temporal history.
    // The next complete frame overwrites this same inactive display target.
    this.#encodeDisplay(
      {...inputs, settings: {...inputs.settings, autoExposure: false}},
      inputs.hdrView,
      destination,
      this.#renderWidth,
      this.#renderHeight,
      this.#outputWidth,
      this.#outputHeight
    );
    return destination;
  }

  encode(inputs: PostFrameInputs): PostFrameResult {
    const targets = this.#targets;
    if (targets === null) {
      throw new Error('Post-process targets have not been sized.');
    }
    let hdrView = inputs.hdrView;
    let hdrWidth = this.#renderWidth;
    let hdrHeight = this.#renderHeight;
    let learnedEnhancementDispatched = false;
    const learnedEnhancementMode = inputs.settings.mode === 'raster'
      ? 'off'
      : mapLearnedEnhancementMode(inputs.settings.experimentalLearnedEnhancement);
    if (inputs.settings.mode !== 'raster' && inputs.settings.denoising !== 'off') {
      hdrView = this.#encodeDenoise(inputs, targets, hdrView);
    }
    if (learnedEnhancementMode !== 'off') {
      const learned = this.#encodeLearnedEnhancement(
        inputs,
        hdrView,
        learnedEnhancementMode
      );
      hdrView = learned.view;
      hdrWidth = learned.width;
      hdrHeight = learned.height;
      learnedEnhancementDispatched = true;
    }

    const fsr1Enabled = learnedEnhancementMode !== 'reconstruct-2x'
      && inputs.settings.upscaling.startsWith('fsr1-');
    const nativeQualitySpatialReconstruction = shouldApplyNativeQualitySpatialReconstruction(
      inputs.settings,
      this.#renderWidth,
      this.#renderHeight,
      this.#outputWidth,
      this.#outputHeight,
      inputs.hdrOutputActive
    );
    const photographicEffects = normalizePhotographicEffects(inputs);
    const outputStyle = normalizeOutputStyle(inputs.outputStyle);
    const outputStyleEnabled = shouldApplyOutputStyle(outputStyle);
    // Grain and chromatic separation introduce unapproved colors and break the
    // logical pixel grid, so the strict pixel-art finish owns the final image.
    const photographicEffectsEnabled = outputStyle.mode !== 'pixel-art'
      && shouldApplyPhotographicEffects(photographicEffects);
    const temporalEnabled = learnedEnhancementMode !== 'reconstruct-2x'
      && shouldApplyTemporalPostProcess(inputs.settings);
    if (temporalEnabled) {
      hdrView = this.#encodeTemporal(inputs, targets, hdrView);
      hdrWidth = this.#outputWidth;
      hdrHeight = this.#outputHeight;
    } else {
      this.#temporalHistoryValid = false;
    }

    if (inputs.settings.autoExposure) {
      this.#encodeExposure(inputs.encoder, hdrView, inputs.deltaSeconds);
    }

    const displayDestination: 0 | 1 = this.#displayActive === 0 ? 1 : 0;
    const cleanCurrentDisplayView = targets.display.views[displayDestination];
    if (fsr1Enabled) {
      this.#encodeDisplay(
        inputs,
        hdrView,
        targets.toneMappedRenderView,
        hdrWidth,
        hdrHeight,
        this.#renderWidth,
        this.#renderHeight
      );
      this.#encodeFsr1(
        inputs.encoder,
        targets.toneMappedRenderView,
        targets.fsrIntermediateView,
        cleanCurrentDisplayView
      );
    } else if (nativeQualitySpatialReconstruction) {
      this.#encodeDisplay(
        inputs,
        hdrView,
        targets.toneMappedRenderView,
        hdrWidth,
        hdrHeight,
        this.#renderWidth,
        this.#renderHeight
      );
      this.#encodeFsr1Easu(
        inputs.encoder,
        targets.toneMappedRenderView,
        cleanCurrentDisplayView,
        this.#renderWidth,
        this.#renderHeight,
        'native quality EASU'
      );
    } else {
      this.#encodeDisplay(
        inputs,
        hdrView,
        cleanCurrentDisplayView,
        hdrWidth,
        hdrHeight,
        this.#outputWidth,
        this.#outputHeight
      );
    }

    let cleanPresentationView = cleanCurrentDisplayView;
    let generated = false;
    if (inputs.settings.frameGeneration === 'fsr3-experimental' && this.#displayHistoryValid) {
      this.#encodeFrameInterpolation(
        inputs,
        targets,
        targets.display.views[this.#displayActive],
        cleanCurrentDisplayView
      );
      cleanPresentationView = targets.interpolationView;
      generated = true;
    }

    let presentationView = cleanPresentationView;
    let currentDisplayView = cleanCurrentDisplayView;
    if (outputStyleEnabled) {
      const outputStyleTargets = this.#ensureOutputStyleTargets();
      this.#encodeOutputStyle(
        inputs.encoder,
        cleanCurrentDisplayView,
        inputs.currentNormalDepthView,
        outputStyleTargets.views[0],
        outputStyle,
        0,
        'current'
      );
      currentDisplayView = outputStyleTargets.views[0];
      if (generated) {
        this.#encodeOutputStyle(
          inputs.encoder,
          cleanPresentationView,
          inputs.currentNormalDepthView,
          outputStyleTargets.views[1],
          outputStyle,
          1,
          'generated'
        );
        presentationView = outputStyleTargets.views[1];
      } else {
        presentationView = currentDisplayView;
      }
    }
    if (photographicEffectsEnabled) {
      // Optical flow and display history remain lens-effect free so seeded grain
      // cannot masquerade as motion and radial color offsets are applied once.
      const generatedCadence = inputs.settings.frameGeneration === 'fsr3-experimental';
      const currentEffectFrameIndex = generatedCadence
        ? inputs.frameIndex * 2 + 1
        : inputs.frameIndex;
      const photographicHdrOutputActive = inputs.hdrOutputActive && !fsr1Enabled;
      this.#encodePhotographicEffects(
        inputs.encoder,
        currentDisplayView,
        targets.fsrIntermediateView,
        currentEffectFrameIndex,
        photographicHdrOutputActive,
        photographicEffects,
        0
      );
      currentDisplayView = targets.fsrIntermediateView;
      if (generated) {
        this.#encodePhotographicEffects(
          inputs.encoder,
          presentationView,
          targets.photographicGeneratedView,
          inputs.frameIndex * 2,
          photographicHdrOutputActive,
          photographicEffects,
          1
        );
        presentationView = targets.photographicGeneratedView;
      } else {
        presentationView = currentDisplayView;
      }
    }
    this.#displayActive = displayDestination;
    this.#displayHistoryValid = true;
    return {presentationView, currentDisplayView, generated, learnedEnhancementDispatched};
  }

  resetHistory(resetExposure = true): void {
    this.#temporalActive = 0;
    this.#displayActive = 0;
    this.#temporalHistoryValid = false;
    this.#displayHistoryValid = false;
    if (resetExposure) {
      this.#resetExposure();
    }
  }

  destroy(): void {
    this.#destroyTargets();
    for (const buffer of this.#denoiseUniforms) buffer.destroy();
    this.#learnedEnhancementUniform.destroy();
    this.#temporalUniform.destroy();
    this.#fsr1EasuUniform.destroy();
    this.#fsr1RcasUniform.destroy();
    this.#exposureUniform.destroy();
    this.#exposureState.destroy();
    this.#displayUniform.destroy();
    for (const buffer of this.#outputStyleUniforms) buffer.destroy();
    for (const buffer of this.#photographicUniforms) buffer.destroy();
    this.#frameInterpolationUniform.destroy();
  }

  #encodeDenoise(inputs: PostFrameInputs, targets: PostTargets, initialView: GPUTextureView): GPUTextureView {
    const quality = selectAtrousDenoiseQuality(inputs.settings.denoising);
    const preset = getAtrousDenoiseSettings(quality);
    const fallbackSamples = Math.max(
      1,
      (Math.max(0, inputs.frameIndex) + 1) * Math.max(1, inputs.settings.samplesPerFrame)
    );
    const accumulatedSamples = inputs.accumulatedSamples !== undefined
      && Number.isFinite(inputs.accumulatedSamples)
      && inputs.accumulatedSamples > 0
      ? inputs.accumulatedSamples
      : fallbackSamples;
    const passCount = getAtrousDenoisePassCount(quality, accumulatedSamples);
    let source = initialView;
    for (let iteration = 0; iteration < passCount; iteration += 1) {
      const destination = targets.denoise.views[(iteration % 2) as 0 | 1];
      const uniform = this.#denoiseUniforms[iteration];
      if (uniform === undefined) throw new Error('Denoise pass exceeds the allocated iteration count.');
      this.#device.queue.writeBuffer(
        uniform,
        0,
        buildAtrousDenoiseConstants(
          this.#renderWidth,
          this.#renderHeight,
          iteration,
          preset,
          accumulatedSamples
        )
      );
      const bindGroup = this.#device.createBindGroup({
        label: `PrioSDK denoise bind group ${iteration}`,
        layout: this.#pipelines.denoise.getBindGroupLayout(0),
        entries: [
          {binding: 0, resource: {buffer: uniform}},
          {binding: 1, resource: source},
          {binding: 2, resource: inputs.currentNormalDepthView},
          {binding: 3, resource: inputs.currentNormalDepthView},
          {binding: 4, resource: inputs.albedoRoughnessView},
          {binding: 5, resource: destination}
        ]
      });
      dispatch(this.#pipelines.denoise, bindGroup, inputs.encoder, this.#renderWidth, this.#renderHeight, `denoise ${iteration}`);
      source = destination;
    }
    return source;
  }

  #encodeLearnedEnhancement(
    inputs: PostFrameInputs,
    fallbackView: GPUTextureView,
    mode: Exclude<LearnedEnhancementMode, 'off'>
  ): LearnedEnhancementTarget {
    const extent = learnedEnhancementOutputExtent(this.#renderWidth, this.#renderHeight, mode);
    const target = this.#ensureLearnedEnhancementTarget(extent.outputWidth, extent.outputHeight);
    const accumulatedSamples = Math.max(1, Math.floor(inputs.accumulatedSamples ?? 1));
    this.#device.queue.writeBuffer(
      this.#learnedEnhancementUniform,
      0,
      buildLearnedEnhancementPresetConstants(
        this.#renderWidth,
        this.#renderHeight,
        mode,
        inputs.settings.experimentalLearnedEnhancementPreset,
        {accumulatedSamples}
      )
    );
    const bindGroup = this.#device.createBindGroup({
      label: 'PrioSDK experimental learned enhancement bind group',
      layout: this.#pipelines.learnedEnhancement.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#learnedEnhancementUniform}},
        {binding: 1, resource: fallbackView},
        {binding: 2, resource: inputs.currentNormalDepthView},
        {binding: 3, resource: inputs.albedoRoughnessView},
        {binding: 4, resource: inputs.hdrView},
        {binding: 5, resource: target.view}
      ]
    });
    dispatch(
      this.#pipelines.learnedEnhancement,
      bindGroup,
      inputs.encoder,
      extent.outputWidth,
      extent.outputHeight,
      'experimental learned enhancement'
    );
    return target;
  }

  #encodeTemporal(inputs: PostFrameInputs, targets: PostTargets, currentHdrView: GPUTextureView): GPUTextureView {
    const quality = temporalQuality(inputs.settings);
    const constants = buildTemporalUpscaleConstants(
      this.#renderWidth,
      this.#renderHeight,
      this.#outputWidth,
      this.#outputHeight,
      getTemporalUpscaleSettings(quality)
    );
    constants[11] = this.#temporalHistoryValid ? 1 : 0;
    this.#device.queue.writeBuffer(this.#temporalUniform, 0, constants);
    const destination: 0 | 1 = this.#temporalActive === 0 ? 1 : 0;
    const bindGroup = this.#device.createBindGroup({
      label: 'PrioSDK temporal reprojection bind group',
      layout: this.#pipelines.temporal.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#temporalUniform}},
        {binding: 1, resource: this.#sampler},
        {binding: 2, resource: currentHdrView},
        {binding: 3, resource: targets.temporal.views[this.#temporalActive]},
        {binding: 4, resource: inputs.motionReactiveView},
        {binding: 5, resource: inputs.currentNormalDepthView},
        {binding: 6, resource: inputs.previousNormalDepthView},
        {binding: 7, resource: targets.temporal.views[destination]}
      ]
    });
    dispatch(
      this.#pipelines.temporal,
      bindGroup,
      inputs.encoder,
      this.#outputWidth,
      this.#outputHeight,
      'temporal reprojection'
    );
    this.#temporalActive = destination;
    this.#temporalHistoryValid = true;
    return targets.temporal.views[destination];
  }

  #encodeExposure(encoder: GPUCommandEncoder, hdrView: GPUTextureView, deltaSeconds: number): void {
    this.#device.queue.writeBuffer(this.#exposureUniform, 0, new Float32Array([
      this.#outputWidth, this.#outputHeight, clamp(deltaSeconds, 0, 0.25), 0,
      0.18, 1.6, 0.05, 20
    ]));
    const bindGroup = this.#device.createBindGroup({
      label: 'PrioSDK automatic exposure bind group',
      layout: this.#pipelines.exposure.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#exposureUniform}},
        {binding: 1, resource: hdrView},
        {binding: 2, resource: {buffer: this.#exposureState}}
      ]
    });
    const pass = encoder.beginComputePass({label: 'PrioSDK automatic exposure pass'});
    pass.setPipeline(this.#pipelines.exposure);
    pass.setBindGroup(0, bindGroup);
    pass.dispatchWorkgroups(1);
    pass.end();
  }

  #encodeDisplay(
    inputs: PostFrameInputs,
    hdrView: GPUTextureView,
    destination: GPUTextureView,
    sourceWidth: number,
    sourceHeight: number,
    destinationWidth: number,
    destinationHeight: number
  ): void {
    this.#device.queue.writeBuffer(
      this.#displayUniform,
      0,
      buildDisplayPostProcessConstants(
        sourceWidth,
        sourceHeight,
        destinationWidth,
        destinationHeight,
        inputs.settings,
        inputs.hdrOutputActive
      )
    );
    const bindGroup = this.#device.createBindGroup({
      label: 'PrioSDK HDR display processing bind group',
      layout: this.#pipelines.display.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#displayUniform}},
        {binding: 1, resource: this.#sampler},
        {binding: 2, resource: hdrView},
        {binding: 3, resource: {buffer: this.#exposureState}},
        {binding: 4, resource: destination}
      ]
    });
    dispatch(
      this.#pipelines.display,
      bindGroup,
      inputs.encoder,
      destinationWidth,
      destinationHeight,
      'HDR display processing'
    );
  }

  #encodeFsr1(
    encoder: GPUCommandEncoder,
    inputView: GPUTextureView,
    easuOutputView: GPUTextureView,
    rcasOutputView: GPUTextureView
  ): void {
    this.#encodeFsr1Easu(
      encoder,
      inputView,
      easuOutputView,
      this.#renderWidth,
      this.#renderHeight,
      'FSR 1 EASU'
    );
    this.#device.queue.writeBuffer(this.#fsr1RcasUniform, 0, buildFsr1RcasConstants(0.2));
    const rcasBindGroup = this.#device.createBindGroup({
      label: 'PrioSDK FSR 1 RCAS bind group',
      layout: this.#pipelines.fsr1Rcas.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#fsr1RcasUniform}},
        {binding: 1, resource: easuOutputView},
        {binding: 2, resource: rcasOutputView}
      ]
    });
    dispatch(this.#pipelines.fsr1Rcas, rcasBindGroup, encoder, this.#outputWidth, this.#outputHeight, 'FSR 1 RCAS');
  }

  #encodeFsr1Easu(
    encoder: GPUCommandEncoder,
    inputView: GPUTextureView,
    outputView: GPUTextureView,
    sourceWidth: number,
    sourceHeight: number,
    label: string
  ): void {
    this.#device.queue.writeBuffer(
      this.#fsr1EasuUniform,
      0,
      buildFsr1EasuConstants(
        sourceWidth,
        sourceHeight,
        sourceWidth,
        sourceHeight,
        this.#outputWidth,
        this.#outputHeight
      )
    );
    const easuBindGroup = this.#device.createBindGroup({
      label: `PrioSDK ${label} bind group`,
      layout: this.#pipelines.fsr1Easu.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#fsr1EasuUniform}},
        {binding: 1, resource: inputView},
        {binding: 2, resource: outputView}
      ]
    });
    dispatch(this.#pipelines.fsr1Easu, easuBindGroup, encoder, this.#outputWidth, this.#outputHeight, label);
  }

  #encodeOutputStyle(
    encoder: GPUCommandEncoder,
    inputView: GPUTextureView,
    normalDepthView: GPUTextureView,
    outputView: GPUTextureView,
    style: OutputStyleOptions,
    uniformIndex: 0 | 1,
    cadence: 'current' | 'generated'
  ): void {
    const uniform = this.#outputStyleUniforms[uniformIndex];
    this.#device.queue.writeBuffer(
      uniform,
      0,
      buildOutputStyleConstants(
        this.#outputWidth,
        this.#outputHeight,
        this.#renderWidth,
        this.#renderHeight,
        style
      )
    );
    const bindGroup = this.#device.createBindGroup({
      label: `PrioSDK output style ${cadence} bind group`,
      layout: this.#pipelines.outputStyle.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: uniform}},
        {binding: 1, resource: inputView},
        {binding: 2, resource: normalDepthView},
        {binding: 3, resource: outputView}
      ]
    });
    dispatch(
      this.#pipelines.outputStyle,
      bindGroup,
      encoder,
      this.#outputWidth,
      this.#outputHeight,
      `output style ${cadence}`
    );
  }

  #encodePhotographicEffects(
    encoder: GPUCommandEncoder,
    inputView: GPUTextureView,
    outputView: GPUTextureView,
    frameIndex: number,
    hdrOutputActive: boolean,
    effects: NormalizedPhotographicEffects,
    uniformIndex: 0 | 1
  ): void {
    const uniform = this.#photographicUniforms[uniformIndex];
    this.#device.queue.writeBuffer(
      uniform,
      0,
      buildPhotographicEffectsConstants(
        this.#outputWidth,
        this.#outputHeight,
        frameIndex,
        hdrOutputActive,
        effects
      )
    );
    const bindGroup = this.#device.createBindGroup({
      label: 'PrioSDK photographic effects bind group',
      layout: this.#pipelines.photographic.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: uniform}},
        {binding: 1, resource: this.#sampler},
        {binding: 2, resource: inputView},
        {binding: 3, resource: outputView}
      ]
    });
    dispatch(
      this.#pipelines.photographic,
      bindGroup,
      encoder,
      this.#outputWidth,
      this.#outputHeight,
      'photographic effects'
    );
  }

  #encodeFrameInterpolation(
    inputs: PostFrameInputs,
    targets: PostTargets,
    previousDisplayView: GPUTextureView,
    currentDisplayView: GPUTextureView
  ): void {
    const quality: ExperimentalFrameInterpolationQuality = 'balanced';
    this.#device.queue.writeBuffer(
      this.#frameInterpolationUniform,
      0,
      buildExperimentalFrameInterpolationConstants(
        this.#outputWidth,
        this.#outputHeight,
        0.5,
        getExperimentalFrameInterpolationSettings(quality)
      )
    );
    const opticalFlowBindGroup = this.#device.createBindGroup({
      label: 'PrioSDK experimental optical-flow bind group',
      layout: this.#pipelines.opticalFlow.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#frameInterpolationUniform}},
        {binding: 1, resource: previousDisplayView},
        {binding: 2, resource: currentDisplayView},
        {binding: 3, resource: targets.opticalFlowView},
        {binding: 4, resource: targets.disocclusionView}
      ]
    });
    dispatch(
      this.#pipelines.opticalFlow,
      opticalFlowBindGroup,
      inputs.encoder,
      this.#outputWidth,
      this.#outputHeight,
      'experimental optical flow'
    );
    const interpolationBindGroup = this.#device.createBindGroup({
      label: 'PrioSDK experimental frame-interpolation bind group',
      layout: this.#pipelines.frameInterpolation.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.#frameInterpolationUniform}},
        {binding: 1, resource: this.#sampler},
        {binding: 2, resource: previousDisplayView},
        {binding: 3, resource: currentDisplayView},
        {binding: 4, resource: inputs.motionReactiveView},
        {binding: 5, resource: targets.opticalFlowView},
        {binding: 6, resource: inputs.previousNormalDepthView},
        {binding: 7, resource: inputs.currentNormalDepthView},
        {binding: 8, resource: targets.disocclusionView},
        {binding: 9, resource: targets.interpolationView}
      ]
    });
    dispatch(
      this.#pipelines.frameInterpolation,
      interpolationBindGroup,
      inputs.encoder,
      this.#outputWidth,
      this.#outputHeight,
      'experimental frame interpolation'
    );
  }

  #resetExposure(): void {
    this.#device.queue.writeBuffer(this.#exposureState, 0, new Float32Array([1, 0.18, 1, 0]));
  }

  #ensureOutputStyleTargets(): TexturePair {
    if (this.#outputStyleTargets === null) {
      this.#outputStyleTargets = createTexturePair(
        this.#device,
        'PrioSDK output style',
        this.#outputWidth,
        this.#outputHeight,
        'rgba16float'
      );
    }
    return this.#outputStyleTargets;
  }

  #ensureLearnedEnhancementTarget(width: number, height: number): LearnedEnhancementTarget {
    const current = this.#learnedEnhancementTarget;
    if (current !== null && current.width === width && current.height === height) {
      return current;
    }
    const texture = createPostTexture(
      this.#device,
      'PrioSDK experimental learned enhancement output',
      width,
      height,
      'rgba16float'
    );
    const replacement = {texture, view: texture.createView(), width, height};
    this.#learnedEnhancementTarget = replacement;
    current?.texture.destroy();
    return replacement;
  }

  #destroyTargets(): void {
    if (this.#targets !== null) {
      destroyPostTargets(this.#targets);
      this.#targets = null;
    }
    if (this.#outputStyleTargets !== null) {
      destroyPair(this.#outputStyleTargets);
      this.#outputStyleTargets = null;
    }
    this.#learnedEnhancementTarget?.texture.destroy();
    this.#learnedEnhancementTarget = null;
  }
}

export function shouldApplyTemporalPostProcess(settings: RenderSettings): boolean {
  // Native progressive path tracing already accumulates temporally jittered
  // samples. Reprojecting that running average would recursively overweight
  // its earliest, noisiest frames.
  if (settings.mode === 'path-trace' && settings.upscaling === 'native') {
    return false;
  }
  const fsr1Enabled = settings.upscaling.startsWith('fsr1-');
  return settings.upscaling.startsWith('fsr3-experimental')
    || (settings.antiAliasing === 'temporal' && !fsr1Enabled);
}

export function shouldApplyNativeQualitySpatialReconstruction(
  settings: RenderSettings,
  renderWidth: number,
  renderHeight: number,
  outputWidth: number,
  outputHeight: number,
  hdrOutputActive: boolean
): boolean {
  return settings.mode === 'path-trace'
    && settings.experimentalLearnedEnhancement !== 'quality-gated-2x'
    && settings.denoising === 'quality'
    && settings.upscaling === 'native'
    && settings.frameGeneration === 'off'
    && !hdrOutputActive
    && renderWidth <= outputWidth
    && renderHeight <= outputHeight
    && (renderWidth < outputWidth || renderHeight < outputHeight);
}

export function mapLearnedEnhancementMode(
  mode: RenderSettings['experimentalLearnedEnhancement']
): LearnedEnhancementMode {
  if (mode === 'quality-gated') return 'same-resolution';
  if (mode === 'quality-gated-2x') return 'reconstruct-2x';
  return 'off';
}

function createUniformBuffer(device: GPUDevice, label: string, size: number): GPUBuffer {
  return device.createBuffer({label, size, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST});
}

function assertCreationActive(signal?: AbortSignal): void {
  if (signal?.aborted) {
    throw signal.reason ?? new DOMException('Image-processing compilation was cancelled.', 'AbortError');
  }
}

function abortableCreation<T>(operation: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (signal === undefined) return operation;
  return new Promise<T>((resolve, reject) => {
    const abort = (): void => {
      signal.removeEventListener('abort', abort);
      reject(signal.reason ?? new DOMException('Image-processing compilation was cancelled.', 'AbortError'));
    };
    signal.addEventListener('abort', abort, {once: true});
    void operation.then(value => {
      signal.removeEventListener('abort', abort);
      if (signal.aborted) abort();
      else resolve(value);
    }, error => {
      signal.removeEventListener('abort', abort);
      reject(error);
    });
    if (signal.aborted) abort();
  });
}

function createPostTexture(
  device: GPUDevice,
  label: string,
  width: number,
  height: number,
  format: GPUTextureFormat
): GPUTexture {
  return device.createTexture({
    label,
    size: {width, height, depthOrArrayLayers: 1},
    format,
    usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.STORAGE_BINDING
  });
}

function createTexturePair(
  device: GPUDevice,
  label: string,
  width: number,
  height: number,
  format: GPUTextureFormat
): TexturePair {
  const first = createPostTexture(device, `${label} A`, width, height, format);
  let second: GPUTexture | null = null;
  try {
    second = createPostTexture(device, `${label} B`, width, height, format);
    return {textures: [first, second], views: [first.createView(), second.createView()]};
  } catch (error) {
    first.destroy();
    second?.destroy();
    throw error;
  }
}

function destroyPair(pair: TexturePair): void {
  pair.textures[0].destroy();
  pair.textures[1].destroy();
}

function createPostTargets(
  device: GPUDevice,
  renderWidth: number,
  renderHeight: number,
  outputWidth: number,
  outputHeight: number
): PostTargets {
  const createdTextures: GPUTexture[] = [];
  let destroyed = false;
  const assertAvailable = (): void => {
    if (destroyed) throw new Error('Post-process targets have been released.');
  };
  const lazyTexture = (
    label: string,
    width: number,
    height: number,
    format: GPUTextureFormat = 'rgba16float'
  ): (() => {texture: GPUTexture; view: GPUTextureView}) => {
    let cached: {texture: GPUTexture; view: GPUTextureView} | null = null;
    return () => {
      assertAvailable();
      if (cached === null) {
        const texture = createPostTexture(device, label, width, height, format);
        try {
          cached = {texture, view: texture.createView()};
          createdTextures.push(texture);
        } catch (error) {
          texture.destroy();
          throw error;
        }
      }
      return cached;
    };
  };
  const lazyPair = (
    label: string,
    width: number,
    height: number
  ): (() => TexturePair) => {
    let cached: TexturePair | null = null;
    return () => {
      assertAvailable();
      if (cached === null) {
        cached = createTexturePair(device, label, width, height, 'rgba16float');
        createdTextures.push(...cached.textures);
      }
      return cached;
    };
  };
  const denoise = lazyPair('PrioSDK denoise', renderWidth, renderHeight);
  const temporal = lazyPair('PrioSDK temporal HDR history', outputWidth, outputHeight);
  const toneMappedRender = lazyTexture('PrioSDK tone-mapped render-resolution color', renderWidth, renderHeight);
  const fsrIntermediate = lazyTexture('PrioSDK FSR 1 EASU intermediate', outputWidth, outputHeight);
  const display = lazyPair('PrioSDK display history', outputWidth, outputHeight);
  const opticalFlow = lazyTexture('PrioSDK experimental optical flow', outputWidth, outputHeight);
  const interpolation = lazyTexture('PrioSDK experimental interpolated frame', outputWidth, outputHeight);
  const photographicGenerated = lazyTexture('PrioSDK photographic generated-frame output', outputWidth, outputHeight);
  const disocclusion = lazyTexture('PrioSDK disocclusion mask', outputWidth, outputHeight, 'rgba8unorm');
  const destroy = (): void => {
    if (destroyed) return;
    destroyed = true;
    for (const texture of createdTextures) texture.destroy();
    createdTextures.length = 0;
  };
  try {
    // Both clean display histories are required by every route. Optional targets
    // retain their exact formats but are created only on the first matching pass.
    const displayTargets = display();
    return {
      destroy,
      get denoise() { return denoise(); },
      get temporal() { return temporal(); },
      get toneMappedRender() { return toneMappedRender().texture; },
      get toneMappedRenderView() { return toneMappedRender().view; },
      get fsrIntermediate() { return fsrIntermediate().texture; },
      get fsrIntermediateView() { return fsrIntermediate().view; },
      display: displayTargets,
      get opticalFlow() { return opticalFlow().texture; },
      get opticalFlowView() { return opticalFlow().view; },
      get interpolation() { return interpolation().texture; },
      get interpolationView() { return interpolation().view; },
      get photographicGenerated() { return photographicGenerated().texture; },
      get photographicGeneratedView() { return photographicGenerated().view; },
      get disocclusion() { return disocclusion().texture; },
      get disocclusionView() { return disocclusion().view; }
    };
  } catch (error) {
    destroy();
    throw error;
  }
}

function destroyPostTargets(targets: PostTargets): void {
  targets.destroy();
}

function dispatch(
  pipeline: GPUComputePipeline,
  bindGroup: GPUBindGroup,
  encoder: GPUCommandEncoder,
  width: number,
  height: number,
  label: string
): void {
  const size = postDispatchSize(width, height);
  const pass = encoder.beginComputePass({label: `PrioSDK ${label} pass`});
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(size.x, size.y);
  pass.end();
}

function temporalQuality(settings: RenderSettings): TemporalUpscaleQuality {
  if (settings.upscaling.endsWith('performance')) return 'performance';
  if (settings.upscaling.endsWith('balanced')) return 'balanced';
  return 'quality';
}

function toneMappingIndex(mode: RenderSettings['toneMapping']): number {
  return mode === 'aces' ? 0 : mode === 'reinhard' ? 1 : 2;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(maximum, Math.max(minimum, value));
}

function finiteClampedOption(
  value: number | undefined,
  limits: Readonly<{minimum: number; maximum: number}>,
  fallback: number
): number {
  return value === undefined || !Number.isFinite(value)
    ? fallback
    : clamp(value, limits.minimum, limits.maximum);
}

function finitePositiveInteger(value: number): number {
  return Number.isFinite(value) && value >= 1
    ? Math.max(1, Math.floor(value))
    : 1;
}

function stableFrameSeed(frameIndex: number): number {
  if (!Number.isFinite(frameIndex) || frameIndex <= 0) return 0;
  return Math.min(0xffff_ffff, Math.floor(frameIndex)) >>> 0;
}

async function assertShaderCompiles(module: GPUShaderModule, label: string): Promise<void> {
  const compilation = await module.getCompilationInfo();
  const errors = compilation.messages.filter(message => message.type === 'error');
  if (errors.length === 0) return;
  const details = errors.slice(0, 4).map(message => `${message.lineNum}:${message.linePos} ${message.message}`).join('; ');
  throw new Error(`WebGPU ${label} shader failed to compile: ${details}`);
}
