import {
  PhysicsWorld,
  type PhysicsBodyDefinition,
  type PhysicsBodyHandle,
  type PhysicsBodyType,
  type PhysicsQualityMode,
  type PhysicsTransform,
  type Quaternion,
  type Vec3
} from '../physics';
import type {ObjectHandle} from '../renderer/scene';
import {WebGPURenderer} from '../renderer/webgpu-renderer';

export type PhysicsRenderBinding =
  | {readonly kind: 'sphere'; readonly sphereIndex: number}
  | {readonly kind: 'object'; readonly objectHandle: string; readonly scale: Vec3}
  | {readonly kind: 'none'};

export interface PhysicsSphereOptions {
  readonly type: PhysicsBodyType;
  readonly position: Vec3;
  readonly radius: number;
  readonly density: number;
  readonly friction: number;
  readonly restitution: number;
  readonly linearDamping: number;
  readonly angularDamping: number;
  readonly ccd: boolean;
  readonly color: Vec3;
  readonly roughness: number;
  readonly metallic: number;
  readonly emission: number;
}

export interface PhysicsObjectOptions {
  readonly objectHandle: string;
  readonly type: PhysicsBodyType;
  readonly shape:
    | {readonly kind: 'box'; readonly halfExtents: Vec3}
    | {readonly kind: 'capsule'; readonly halfHeight: number; readonly radius: number};
  readonly density: number;
  readonly friction: number;
  readonly restitution: number;
  readonly linearDamping: number;
  readonly angularDamping: number;
  readonly ccd: boolean;
}

const DEFAULT_GROUND_HALF_EXTENTS: Vec3 = [1_000, 0.05, 1_000];

export class PhysicsController {
  private readonly renderer: WebGPURenderer;
  private world: PhysicsWorld<PhysicsRenderBinding> | null = null;
  private initialization: Promise<void> | null = null;
  private animationFrame: number | null = null;
  private lastFrameTime: number | null = null;
  private running = false;
  private externallyDriven = false;
  private destroyed = false;
  private defaultGroundHandle: PhysicsBodyHandle | null = null;

  constructor(renderer: WebGPURenderer) {
    this.renderer = renderer;
  }

  async initialize(mode: PhysicsQualityMode = 'balanced', addDefaultGround = true): Promise<void> {
    this.assertNotDestroyed();
    if (this.world !== null) {
      this.world.setQualityMode(mode);
      if (addDefaultGround) this.ensureDefaultGround();
      return;
    }
    if (this.initialization !== null) {
      await this.initialization;
      this.requireWorld().setQualityMode(mode);
      if (addDefaultGround) this.ensureDefaultGround();
      return;
    }

    const operation = PhysicsWorld.create<PhysicsRenderBinding>({
      gravity: [0, -9.81, 0],
      quality: mode,
      lengthUnit: 1
    }).then(world => {
      if (this.destroyed) {
        world.destroy();
        throw new Error('Physics controller was destroyed during initialization.');
      }
      this.world = world;
      if (addDefaultGround) this.ensureDefaultGround();
    });
    this.initialization = operation;
    try {
      await operation;
    } finally {
      if (this.initialization === operation) this.initialization = null;
    }
  }

  isInitialized(): boolean {
    return this.world !== null;
  }

  isRunning(): boolean {
    return this.running;
  }

  isExternallyDriven(): boolean {
    return this.externallyDriven;
  }

  setQualityMode(mode: PhysicsQualityMode): void {
    this.requireWorld().setQualityMode(mode);
  }

  setGravity(gravity: Vec3): void {
    this.requireWorld().setGravity(gravity);
  }

  start(): void {
    this.requireWorld();
    if (this.running) return;
    this.running = true;
    this.lastFrameTime = null;
    if (!this.externallyDriven) this.scheduleFrame();
  }

  stop(): void {
    this.running = false;
    this.lastFrameTime = null;
    this.cancelFrame();
  }

  setExternallyDriven(enabled: boolean): void {
    this.externallyDriven = enabled;
    this.lastFrameTime = null;
    if (enabled) {
      this.cancelFrame();
    } else if (this.running) {
      this.scheduleFrame();
    }
  }

  advanceRealtimeAt(nowMilliseconds: number): void {
    if (!this.running) return;
    if (!Number.isFinite(nowMilliseconds)) {
      throw new RangeError('Physics frame time must be finite.');
    }
    const previous = this.lastFrameTime;
    this.lastFrameTime = nowMilliseconds;
    if (previous === null) {
      this.syncAll(true);
      return;
    }
    const deltaSeconds = Math.max(0, (nowMilliseconds - previous) / 1_000);
    this.requireWorld().advanceRealtime(deltaSeconds);
    this.syncAll(true);
  }

  stepExact(durationSeconds: number): void {
    this.requireWorld().stepExact(durationSeconds);
    this.lastFrameTime = this.now();
    this.syncAll(false);
  }

  createGround(y: number, friction = 0.7, restitution = 0.05): PhysicsBodyHandle {
    const world = this.requireWorld();
    return world.createBody({
      type: 'fixed',
      shape: {kind: 'box', halfExtents: DEFAULT_GROUND_HALF_EXTENTS},
      position: [0, y - DEFAULT_GROUND_HALF_EXTENTS[1], 0],
      friction,
      restitution,
      binding: {kind: 'none'}
    });
  }

  createSphere(options: PhysicsSphereOptions): PhysicsBodyHandle {
    const world = this.requireWorld();
    const definition: PhysicsBodyDefinition<PhysicsRenderBinding> = {
      type: options.type,
      shape: {kind: 'sphere', radius: options.radius},
      position: options.position,
      density: options.density,
      friction: options.friction,
      restitution: options.restitution,
      linearDamping: options.linearDamping,
      angularDamping: options.angularDamping,
      ccd: options.ccd
    };
    const body = world.createBody(definition);
    try {
      const sphereIndex = this.renderer.addSphere({
        center: options.position,
        radius: options.radius,
        color: options.color,
        roughness: options.roughness,
        metallic: options.metallic,
        emission: options.emission
      });
      world.setBinding(body, {kind: 'sphere', sphereIndex});
      return body;
    } catch (error) {
      world.removeBody(body);
      throw error;
    }
  }

  attachObject(options: PhysicsObjectOptions): PhysicsBodyHandle {
    const world = this.requireWorld();
    const objectHandle = options.objectHandle as ObjectHandle;
    const transform = this.renderer.getObjectTransform(objectHandle);
    return world.createBody({
      type: options.type,
      shape: options.shape,
      position: transform.translation,
      rotation: eulerDegreesToQuaternion(transform.rotation),
      density: options.density,
      friction: options.friction,
      restitution: options.restitution,
      linearDamping: options.linearDamping,
      angularDamping: options.angularDamping,
      ccd: options.ccd,
      binding: {
        kind: 'object',
        objectHandle: options.objectHandle,
        scale: [transform.scale[0], transform.scale[1], transform.scale[2]]
      }
    });
  }

  setBodyPosition(handle: string, position: Vec3): void {
    const world = this.requireWorld();
    const body = this.requireBody(handle);
    world.setTransform(body, {position});
    this.syncBody(body, false);
  }

  setBodyLinearVelocity(handle: string, velocity: Vec3): void {
    this.requireWorld().setLinearVelocity(this.requireBody(handle), velocity);
  }

  setBodyAngularVelocity(handle: string, velocity: Vec3): void {
    this.requireWorld().setAngularVelocity(this.requireBody(handle), velocity);
  }

  setBodyDamping(handle: string, linear: number, angular: number): void {
    this.requireWorld().setDamping(this.requireBody(handle), linear, angular);
  }

  setBodyGravityScale(handle: string, scale: number): void {
    this.requireWorld().setGravityScale(this.requireBody(handle), scale);
  }

  addForce(handle: string, force: Vec3): void {
    this.requireWorld().addForce(this.requireBody(handle), force);
  }

  applyImpulse(handle: string, impulse: Vec3): void {
    this.requireWorld().applyImpulse(this.requireBody(handle), impulse);
  }

  applyTorqueImpulse(handle: string, impulse: Vec3): void {
    this.requireWorld().applyTorqueImpulse(this.requireBody(handle), impulse);
  }

  removeBody(handle: string): void {
    const world = this.requireWorld();
    world.removeBody(this.requireBody(handle));
  }

  bodyPosition(handle: string): Vec3 {
    return this.requireWorld().getCurrentTransform(this.requireBody(handle)).position;
  }

  bodyLinearVelocity(handle: string): Vec3 {
    return this.requireWorld().getBodyState(this.requireBody(handle)).linearVelocity;
  }

  removeRendererBindings(kind: 'sphere' | 'object'): void {
    const world = this.world;
    if (world === null) return;
    for (const handle of world.listBodyHandles()) {
      if (world.getBinding(handle)?.kind === kind) world.removeBody(handle);
    }
  }

  removeObjectBinding(objectHandle: string): void {
    const world = this.world;
    if (world === null) return;
    for (const handle of world.listBodyHandles()) {
      const binding = world.getBinding(handle);
      if (binding?.kind === 'object' && binding.objectHandle === objectHandle) {
        world.removeBody(handle);
      }
    }
  }

  clear(): void {
    this.stop();
    const world = this.world;
    if (world === null) return;
    world.clear();
    this.defaultGroundHandle = null;
  }

  status(): object {
    if (this.destroyed) {
      return {state: 'destroyed', running: false, externallyDriven: false};
    }
    if (this.world === null) {
      return {state: 'uninitialized', running: false, externallyDriven: this.externallyDriven};
    }
    return {
      state: this.running ? 'running' : 'ready',
      running: this.running,
      externallyDriven: this.externallyDriven,
      defaultGround: this.defaultGroundHandle !== null && this.world.hasBody(this.defaultGroundHandle),
      ...this.world.status
    };
  }

  destroy(): void {
    if (this.destroyed) return;
    this.stop();
    this.destroyed = true;
    this.world?.destroy();
    this.world = null;
    this.defaultGroundHandle = null;
  }

  private ensureDefaultGround(): void {
    const world = this.requireWorld();
    if (this.defaultGroundHandle !== null && world.hasBody(this.defaultGroundHandle)) return;
    this.defaultGroundHandle = this.createGround(0, 0.72, 0.08);
  }

  private syncAll(interpolated: boolean): void {
    const world = this.requireWorld();
    for (const handle of world.listBodyHandles()) this.syncBody(handle, interpolated);
  }

  private syncBody(handle: PhysicsBodyHandle, interpolated: boolean): void {
    const world = this.requireWorld();
    const binding = world.getBinding(handle);
    if (binding === undefined || binding.kind === 'none') return;
    const transform = interpolated
      ? world.getInterpolatedTransform(handle)
      : world.getCurrentTransform(handle);
    try {
      if (binding.kind === 'sphere') {
        this.renderer.updateSphere(binding.sphereIndex, {center: transform.position});
      } else {
        this.renderer.updateObject(binding.objectHandle as ObjectHandle, {
          transform: {
            translation: transform.position,
            rotation: quaternionToEulerDegrees(transform.rotation),
            scale: binding.scale
          }
        });
      }
    } catch (error) {
      if (world.hasBody(handle)) world.removeBody(handle);
      throw error;
    }
  }

  private requireWorld(): PhysicsWorld<PhysicsRenderBinding> {
    this.assertNotDestroyed();
    if (this.world === null) {
      throw new Error('Initialize physics before using physics blocks.');
    }
    return this.world;
  }

  private requireBody(handle: string): PhysicsBodyHandle {
    const world = this.requireWorld();
    if (!world.hasBody(handle)) {
      throw new TypeError('Physics body handle is invalid, stale, or belongs to another world.');
    }
    return handle;
  }

  private scheduleFrame(): void {
    if (!this.running || this.externallyDriven || this.animationFrame !== null) return;
    const ownerWindow = this.ownerWindow();
    if (ownerWindow === null) {
      throw new Error('Physics real-time mode requires a browser window.');
    }
    this.animationFrame = ownerWindow.requestAnimationFrame(now => {
      this.animationFrame = null;
      if (!this.running || this.externallyDriven) return;
      try {
        this.advanceRealtimeAt(now);
        if (this.running && !this.externallyDriven) this.scheduleFrame();
      } catch (error) {
        this.stop();
        throw error;
      }
    });
  }

  private cancelFrame(): void {
    if (this.animationFrame === null) return;
    this.ownerWindow()?.cancelAnimationFrame(this.animationFrame);
    this.animationFrame = null;
  }

  private ownerWindow(): Window | null {
    return this.renderer.getOutputCanvas()?.ownerDocument?.defaultView
      ?? (typeof window === 'undefined' ? null : window);
  }

  private now(): number {
    return this.ownerWindow()?.performance.now() ?? performance.now();
  }

  private assertNotDestroyed(): void {
    if (this.destroyed) throw new Error('Physics controller has been destroyed.');
  }
}

export function eulerDegreesToQuaternion(rotation: Vec3): Quaternion {
  const halfX = rotation[0] * Math.PI / 360;
  const halfY = rotation[1] * Math.PI / 360;
  const halfZ = rotation[2] * Math.PI / 360;
  const sx = Math.sin(halfX);
  const cx = Math.cos(halfX);
  const sy = Math.sin(halfY);
  const cy = Math.cos(halfY);
  const sz = Math.sin(halfZ);
  const cz = Math.cos(halfZ);
  return [
    sx * cy * cz - cx * sy * sz,
    cx * sy * cz + sx * cy * sz,
    cx * cy * sz - sx * sy * cz,
    cx * cy * cz + sx * sy * sz
  ];
}

export function quaternionToEulerDegrees(rotation: Quaternion): Vec3 {
  const [x, y, z, w] = rotation;
  const sinXCosY = 2 * (w * x + y * z);
  const cosXCosY = 1 - 2 * (x * x + y * y);
  const xAngle = Math.atan2(sinXCosY, cosXCosY);
  const sinY = Math.max(-1, Math.min(1, 2 * (w * y - z * x)));
  const yAngle = Math.asin(sinY);
  const sinZCosY = 2 * (w * z + x * y);
  const cosZCosY = 1 - 2 * (y * y + z * z);
  const zAngle = Math.atan2(sinZCosY, cosZCosY);
  const radiansToDegrees = 180 / Math.PI;
  return [xAngle * radiansToDegrees, yAngle * radiansToDegrees, zAngle * radiansToDegrees];
}
