const PI = Math.PI;
const MAX_RADIANCE = 65_504;

export const ENVIRONMENT_SH_COEFFICIENT_COUNT = 9;
export const ENVIRONMENT_SH_FLOAT_COUNT = ENVIRONMENT_SH_COEFFICIENT_COUNT * 3;

export const ENVIRONMENT_SH_BAND_CONVOLUTION = [
  PI,
  2 * PI / 3,
  2 * PI / 3,
  2 * PI / 3,
  PI / 4,
  PI / 4,
  PI / 4,
  PI / 4,
  PI / 4
] as const;

export function projectDiffuseIrradianceSh(
  rgba: Float32Array,
  width: number,
  height: number
): Float32Array {
  requireDimension(width, 'environment width');
  requireDimension(height, 'environment height');
  if (rgba.length !== width * height * 4) {
    throw new RangeError('Environment pixels must contain exactly width * height RGBA values.');
  }

  const coefficients = new Float64Array(ENVIRONMENT_SH_FLOAT_COUNT);
  const longitudeStep = 2 * PI / width;
  const latitudeStep = PI / height;
  for (let row = 0; row < height; row += 1) {
    const theta = (row + 0.5) * latitudeStep;
    const sinTheta = Math.sin(theta);
    const y = Math.cos(theta);
    const solidAngle = longitudeStep * latitudeStep * sinTheta;
    for (let column = 0; column < width; column += 1) {
      const phi = ((column + 0.5) / width - 0.5) * 2 * PI;
      const x = Math.cos(phi) * sinTheta;
      const z = Math.sin(phi) * sinTheta;
      const basis = shBasis(x, y, z);
      const pixelOffset = (row * width + column) * 4;
      const red = finiteRadiance(rgba[pixelOffset]);
      const green = finiteRadiance(rgba[pixelOffset + 1]);
      const blue = finiteRadiance(rgba[pixelOffset + 2]);
      for (let coefficient = 0; coefficient < ENVIRONMENT_SH_COEFFICIENT_COUNT; coefficient += 1) {
        const scale = (basis[coefficient] ?? 0) * solidAngle;
        const target = coefficient * 3;
        coefficients[target] = (coefficients[target] ?? 0) + red * scale;
        coefficients[target + 1] = (coefficients[target + 1] ?? 0) + green * scale;
        coefficients[target + 2] = (coefficients[target + 2] ?? 0) + blue * scale;
      }
    }
  }

  return convolveDiffuseCoefficients(coefficients);
}

export async function projectDiffuseIrradianceShAsync(
  rgba: Float32Array,
  width: number,
  height: number,
  options: CooperativeTextureWorkOptions = {}
): Promise<Float32Array> {
  requireDimension(width, 'environment width');
  requireDimension(height, 'environment height');
  if (rgba.length !== width * height * 4) {
    throw new RangeError('Environment pixels must contain exactly width * height RGBA values.');
  }
  const work = new CooperativeTextureWork(options);
  const coefficients = new Float64Array(ENVIRONMENT_SH_FLOAT_COUNT);
  const longitudeStep = 2 * PI / width;
  const latitudeStep = PI / height;
  await work.checkpoint(true);
  for (let row = 0; row < height; row += 1) {
    const theta = (row + 0.5) * latitudeStep;
    const sinTheta = Math.sin(theta);
    const y = Math.cos(theta);
    const solidAngle = longitudeStep * latitudeStep * sinTheta;
    for (let column = 0; column < width; column += 1) {
      const phi = ((column + 0.5) / width - 0.5) * 2 * PI;
      const x = Math.cos(phi) * sinTheta;
      const z = Math.sin(phi) * sinTheta;
      const basis = shBasis(x, y, z);
      const pixelOffset = (row * width + column) * 4;
      const red = finiteRadiance(rgba[pixelOffset]);
      const green = finiteRadiance(rgba[pixelOffset + 1]);
      const blue = finiteRadiance(rgba[pixelOffset + 2]);
      for (let coefficient = 0; coefficient < ENVIRONMENT_SH_COEFFICIENT_COUNT; coefficient += 1) {
        const scale = (basis[coefficient] ?? 0) * solidAngle;
        const target = coefficient * 3;
        coefficients[target] = (coefficients[target] ?? 0) + red * scale;
        coefficients[target + 1] = (coefficients[target + 1] ?? 0) + green * scale;
        coefficients[target + 2] = (coefficients[target + 2] ?? 0) + blue * scale;
      }
    }
    if (work.shouldYield()) await work.checkpoint(true);
  }

  work.assertCurrent();
  return convolveDiffuseCoefficients(coefficients);
}

export function subtractDirectionalIrradianceSh(
  irradianceCoefficients: Float32Array,
  direction: readonly [number, number, number],
  integratedRadiance: readonly [number, number, number]
): Float32Array {
  if (irradianceCoefficients.length !== ENVIRONMENT_SH_FLOAT_COUNT) {
    throw new RangeError(`Environment SH requires exactly ${ENVIRONMENT_SH_FLOAT_COUNT} values.`);
  }
  const length = Math.hypot(direction[0], direction[1], direction[2]);
  if (!Number.isFinite(length) || length <= 1e-12) {
    throw new RangeError('Directional SH subtraction requires a finite nonzero direction.');
  }
  const basis = shBasis(direction[0] / length, direction[1] / length, direction[2] / length);
  const output = new Float32Array(ENVIRONMENT_SH_FLOAT_COUNT);
  for (let coefficient = 0; coefficient < ENVIRONMENT_SH_COEFFICIENT_COUNT; coefficient += 1) {
    const directionalScale = (basis[coefficient] ?? 0)
      * (ENVIRONMENT_SH_BAND_CONVOLUTION[coefficient] ?? 0);
    for (let channel = 0; channel < 3; channel += 1) {
      const index = coefficient * 3 + channel;
      const source = irradianceCoefficients[index] ?? 0;
      const removed = finiteSigned(integratedRadiance[channel]) * directionalScale;
      const value = source - removed;
      output[index] = Number.isFinite(value) ? Math.fround(value) : 0;
    }
  }
  return output;
}

export function packEnvironmentShVec4(coefficients: Float32Array): Float32Array {
  if (coefficients.length !== ENVIRONMENT_SH_FLOAT_COUNT) {
    throw new RangeError(`Environment SH requires exactly ${ENVIRONMENT_SH_FLOAT_COUNT} values.`);
  }
  const packed = new Float32Array(ENVIRONMENT_SH_COEFFICIENT_COUNT * 4);
  for (let coefficient = 0; coefficient < ENVIRONMENT_SH_COEFFICIENT_COUNT; coefficient += 1) {
    for (let channel = 0; channel < 3; channel += 1) {
      const value = coefficients[coefficient * 3 + channel];
      packed[coefficient * 4 + channel] = Number.isFinite(value)
        ? Math.fround(Math.min(MAX_RADIANCE, Math.max(-MAX_RADIANCE, value!)))
        : 0;
    }
  }
  return packed;
}

function shBasis(x: number, y: number, z: number): readonly number[] {
  return [
    0.2820947918,
    0.4886025119 * y,
    0.4886025119 * z,
    0.4886025119 * x,
    1.0925484306 * x * y,
    1.0925484306 * y * z,
    0.3153915653 * (3 * z * z - 1),
    1.0925484306 * x * z,
    0.5462742153 * (x * x - y * y)
  ];
}

function convolveDiffuseCoefficients(coefficients: Float64Array): Float32Array {
  const output = new Float32Array(ENVIRONMENT_SH_FLOAT_COUNT);
  for (let coefficient = 0; coefficient < ENVIRONMENT_SH_COEFFICIENT_COUNT; coefficient += 1) {
    const convolution = ENVIRONMENT_SH_BAND_CONVOLUTION[coefficient] ?? 0;
    for (let channel = 0; channel < 3; channel += 1) {
      const index = coefficient * 3 + channel;
      const value = (coefficients[index] ?? 0) * convolution;
      output[index] = Number.isFinite(value) ? Math.fround(value) : 0;
    }
  }
  return output;
}

function finiteRadiance(value: number | undefined): number {
  return Number.isFinite(value) ? Math.min(MAX_RADIANCE, Math.max(0, value!)) : 0;
}

function finiteSigned(value: number | undefined): number {
  return Number.isFinite(value) ? value! : 0;
}

function requireDimension(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 1 || value > 32_768) {
    throw new RangeError(`${label} must be an integer from 1 through 32768.`);
  }
}
import {
  CooperativeTextureWork,
  type CooperativeTextureWorkOptions
} from './cooperative-work';
