function hashString(value: string): number {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

export function normalizeSeed(seed: number | string): number {
  if (typeof seed === 'string') return hashString(seed) || 0x6d2b79f5;
  if (!Number.isFinite(seed)) throw new RangeError('environment seed must be finite');
  return (Math.trunc(seed) >>> 0) || 0x6d2b79f5;
}

export class SeededRandom {
  private state: number;

  constructor(seed: number | string) {
    this.state = normalizeSeed(seed);
  }

  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let value = this.state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 0x1_0000_0000;
  }

  range(minimum: number, maximum: number): number {
    if (!Number.isFinite(minimum) || !Number.isFinite(maximum) || maximum < minimum) {
      throw new RangeError('random range must contain finite ordered bounds');
    }
    return minimum + (maximum - minimum) * this.next();
  }

  integer(minimum: number, maximumInclusive: number): number {
    if (!Number.isSafeInteger(minimum) || !Number.isSafeInteger(maximumInclusive) || maximumInclusive < minimum) {
      throw new RangeError('random integer range must contain ordered safe integers');
    }
    return minimum + Math.floor(this.next() * (maximumInclusive - minimum + 1));
  }

  fork(label: string): SeededRandom {
    return new SeededRandom((this.state ^ normalizeSeed(label)) >>> 0);
  }
}
