import type {Collider, RigidBody, Rotation, Vector, World as RapierWorld} from '@dimforge/rapier3d-compat';

import {initializePhysics, type RapierModule} from './runtime';
import {
  PHYSICS_QUALITY_PRESETS,
  type ColliderShape,
  type ExactStepResult,
  type PhysicsBodyDefinition,
  type PhysicsBodyHandle,
  type PhysicsBodyState,
  type PhysicsBodyType,
  type PhysicsQualityMode,
  type PhysicsQualityPreset,
  type PhysicsTransform,
  type PhysicsTransformUpdate,
  type PhysicsWorldOptions,
  type PhysicsWorldStatus,
  type Quaternion,
  type RealtimeStepResult,
  type RendererBinding,
  type Vec3
} from './types';

interface MutableTransform {
  position: [number, number, number];
  rotation: [number, number, number, number];
}

interface BodyRecord<TBinding> {
  readonly body: RigidBody;
  readonly collider: Collider;
  readonly type: PhysicsBodyType;
  readonly shape: ColliderShape;
  binding: TBinding | undefined;
  previous: MutableTransform;
  current: MutableTransform;
  pendingKinematic: MutableTransform | undefined;
}

interface HandleSlot<T> {
  generation: number;
  value: T | null;
}

interface HandleEntry<T> {
  readonly handle: PhysicsBodyHandle;
  readonly value: T;
}

const ID_PATTERN = /^physics-body:([a-z0-9]+):(\d+):(\d+)$/;
const DEFAULT_POSITION: Vec3 = Object.freeze([0, 0, 0]);
const IDENTITY_ROTATION: Quaternion = Object.freeze([0, 0, 0, 1]);
const DEFAULT_GRAVITY: Vec3 = Object.freeze([0, -9.81, 0]);
const STEP_EPSILON = 1e-12;
let nextWorldId = 1;

class BodyRegistry<T> {
  readonly #owner: string;
  readonly #slots: HandleSlot<T>[] = [];
  #size = 0;

  constructor(owner: string) {
    this.#owner = owner;
  }

  get size(): number {
    return this.#size;
  }

  create(value: T): PhysicsBodyHandle {
    let slotIndex = this.#slots.findIndex(slot => slot.value === null);
    if (slotIndex < 0) {
      slotIndex = this.#slots.length;
      this.#slots.push({generation: 1, value});
    } else {
      const slot = this.#slots[slotIndex];
      if (!slot) throw new Error('Physics handle registry invariant failed');
      slot.value = value;
    }
    this.#size += 1;
    const slot = this.#slots[slotIndex];
    if (!slot) throw new Error('Physics handle registry invariant failed');
    return this.#format(slotIndex, slot.generation);
  }

  has(handle: unknown): handle is PhysicsBodyHandle {
    const parsed = this.#parse(handle);
    if (!parsed) return false;
    const slot = this.#slots[parsed.slot];
    return slot !== undefined && slot.value !== null && slot.generation === parsed.generation;
  }

  get(handle: PhysicsBodyHandle): T {
    const parsed = this.#parse(handle);
    const slot = parsed ? this.#slots[parsed.slot] : undefined;
    if (!parsed || !slot || slot.value === null || slot.generation !== parsed.generation) {
      throw new RangeError(`Invalid, stale, or foreign physics body handle: ${String(handle)}`);
    }
    return slot.value;
  }

  remove(handle: PhysicsBodyHandle): void {
    const parsed = this.#parse(handle);
    const slot = parsed ? this.#slots[parsed.slot] : undefined;
    if (!parsed || !slot || slot.value === null || slot.generation !== parsed.generation) {
      throw new RangeError(`Invalid, stale, or foreign physics body handle: ${String(handle)}`);
    }
    slot.value = null;
    slot.generation = slot.generation === Number.MAX_SAFE_INTEGER ? 1 : slot.generation + 1;
    this.#size -= 1;
  }

  clear(): void {
    for (const slot of this.#slots) {
      if (slot.value !== null) {
        slot.value = null;
        slot.generation = slot.generation === Number.MAX_SAFE_INTEGER ? 1 : slot.generation + 1;
      }
    }
    this.#size = 0;
  }

  entries(): HandleEntry<T>[] {
    const result: HandleEntry<T>[] = [];
    for (let index = 0; index < this.#slots.length; index += 1) {
      const slot = this.#slots[index];
      if (slot?.value !== null && slot?.value !== undefined) {
        result.push({handle: this.#format(index, slot.generation), value: slot.value});
      }
    }
    return result;
  }

  handles(): PhysicsBodyHandle[] {
    return this.entries().map(entry => entry.handle);
  }

  #format(slot: number, generation: number): PhysicsBodyHandle {
    return `physics-body:${this.#owner}:${slot}:${generation}` as PhysicsBodyHandle;
  }

  #parse(handle: unknown): {slot: number; generation: number} | null {
    if (typeof handle !== 'string') return null;
    const match = ID_PATTERN.exec(handle);
    if (!match || match[1] !== this.#owner) return null;
    const slot = Number(match[2]);
    const generation = Number(match[3]);
    if (!Number.isSafeInteger(slot) || !Number.isSafeInteger(generation) || slot < 0 || generation < 1) return null;
    return {slot, generation};
  }
}

const assertFinite = (value: number, label: string): number => {
  if (!Number.isFinite(value)) throw new TypeError(`${label} must be finite`);
  return value;
};

const assertNonNegative = (value: number, label: string): number => {
  assertFinite(value, label);
  if (value < 0) throw new RangeError(`${label} must be greater than or equal to zero`);
  return value;
};

const assertPositive = (value: number, label: string): number => {
  assertFinite(value, label);
  if (value <= 0) throw new RangeError(`${label} must be greater than zero`);
  return value;
};

const assertIterationCount = (value: number, label: string): number => {
  if (!Number.isSafeInteger(value) || value < 0) throw new RangeError(`${label} must be a non-negative safe integer`);
  return value;
};

const copyVec3 = (value: Vec3, label: string): [number, number, number] => [
  assertFinite(value[0], `${label}[0]`),
  assertFinite(value[1], `${label}[1]`),
  assertFinite(value[2], `${label}[2]`)
];

const normalizeQuaternion = (value: Quaternion, label: string): [number, number, number, number] => {
  const x = assertFinite(value[0], `${label}[0]`);
  const y = assertFinite(value[1], `${label}[1]`);
  const z = assertFinite(value[2], `${label}[2]`);
  const w = assertFinite(value[3], `${label}[3]`);
  const length = Math.hypot(x, y, z, w);
  if (length <= Number.EPSILON) throw new RangeError(`${label} must be a non-zero quaternion`);
  return [x / length, y / length, z / length, w / length];
};

const cloneTransform = (transform: MutableTransform): MutableTransform => ({
  position: [...transform.position],
  rotation: [...transform.rotation]
});

const readTransform = (body: RigidBody): MutableTransform => {
  const position = body.translation();
  const rotation = body.rotation();
  return {
    position: [position.x, position.y, position.z],
    rotation: normalizeQuaternion([rotation.x, rotation.y, rotation.z, rotation.w], 'body rotation')
  };
};

const publicTransform = (transform: MutableTransform): PhysicsTransform => ({
  position: [...transform.position],
  rotation: [...transform.rotation]
});

const vectorToTuple = (value: Vector): Vec3 => [value.x, value.y, value.z];

const slerp = (from: Quaternion, to: Quaternion, alpha: number): [number, number, number, number] => {
  let bx = to[0];
  let by = to[1];
  let bz = to[2];
  let bw = to[3];
  let cosine = from[0] * bx + from[1] * by + from[2] * bz + from[3] * bw;

  if (cosine < 0) {
    cosine = -cosine;
    bx = -bx;
    by = -by;
    bz = -bz;
    bw = -bw;
  }

  if (cosine > 0.9995) {
    return normalizeQuaternion([
      from[0] + alpha * (bx - from[0]),
      from[1] + alpha * (by - from[1]),
      from[2] + alpha * (bz - from[2]),
      from[3] + alpha * (bw - from[3])
    ], 'interpolated rotation');
  }

  const angle = Math.acos(Math.min(1, cosine));
  const denominator = Math.sin(angle);
  const fromWeight = Math.sin((1 - alpha) * angle) / denominator;
  const toWeight = Math.sin(alpha * angle) / denominator;
  return [
    from[0] * fromWeight + bx * toWeight,
    from[1] * fromWeight + by * toWeight,
    from[2] * fromWeight + bz * toWeight,
    from[3] * fromWeight + bw * toWeight
  ];
};

const interpolateTransform = (from: MutableTransform, to: MutableTransform, alpha: number): MutableTransform => ({
  position: [
    from.position[0] + (to.position[0] - from.position[0]) * alpha,
    from.position[1] + (to.position[1] - from.position[1]) * alpha,
    from.position[2] + (to.position[2] - from.position[2]) * alpha
  ],
  rotation: slerp(from.rotation, to.rotation, alpha)
});

const validateShape = (shape: ColliderShape): ColliderShape => {
  if (!shape || typeof shape !== 'object') throw new TypeError('shape must be a collider shape');
  switch (shape.kind) {
    case 'sphere':
      return Object.freeze({kind: 'sphere', radius: assertPositive(shape.radius, 'shape.radius')});
    case 'box': {
      const halfExtents = copyVec3(shape.halfExtents, 'shape.halfExtents');
      halfExtents.forEach((extent, index) => assertPositive(extent, `shape.halfExtents[${index}]`));
      return Object.freeze({kind: 'box', halfExtents: Object.freeze(halfExtents)});
    }
    case 'capsule':
      return Object.freeze({
        kind: 'capsule',
        halfHeight: assertNonNegative(shape.halfHeight, 'shape.halfHeight'),
        radius: assertPositive(shape.radius, 'shape.radius')
      });
    default:
      throw new RangeError(`Unsupported collider shape: ${String((shape as {kind?: unknown}).kind)}`);
  }
};

const validateBodyType = (type: PhysicsBodyType): PhysicsBodyType => {
  if (type === 'dynamic' || type === 'fixed' || type === 'kinematic-position' || type === 'kinematic-velocity') {
    return type;
  }
  throw new RangeError(`Unsupported physics body type: ${String(type)}`);
};

const validateQualityMode = (mode: PhysicsQualityMode): PhysicsQualityMode => {
  if (Object.hasOwn(PHYSICS_QUALITY_PRESETS, mode)) return mode;
  throw new RangeError(`Unsupported physics quality mode: ${String(mode)}`);
};

const monotonicNow = (): number => globalThis.performance?.now() ?? Date.now();

/** A deterministic rigid-body world backed by Rapier's real WebAssembly solver. */
export class PhysicsWorld<TBinding = RendererBinding> {
  readonly #rapier: RapierModule;
  readonly #world: RapierWorld;
  readonly #registry: BodyRegistry<BodyRecord<TBinding>>;
  readonly #profiling: boolean;
  #quality: PhysicsQualityMode;
  #destroyed = false;
  #accumulator = 0;
  #simulationTime = 0;
  #totalSimulationSteps = 0;
  #totalSimulationSubsteps = 0;
  #totalRealtimeUpdates = 0;
  #totalDroppedSeconds = 0;
  #lastStepMilliseconds = 0;

  private constructor(rapier: RapierModule, options: PhysicsWorldOptions) {
    this.#rapier = rapier;
    this.#quality = validateQualityMode(options.quality ?? 'balanced');
    this.#profiling = options.profiling ?? false;
    const gravity = copyVec3(options.gravity ?? DEFAULT_GRAVITY, 'gravity');
    this.#world = new rapier.World({x: gravity[0], y: gravity[1], z: gravity[2]});
    this.#world.profilerEnabled = this.#profiling;
    if (options.lengthUnit !== undefined) this.#world.lengthUnit = assertPositive(options.lengthUnit, 'lengthUnit');
    this.#registry = new BodyRegistry((nextWorldId++).toString(36));
    this.#applyQualityPreset();
  }

  static async create<TBinding = RendererBinding>(options: PhysicsWorldOptions = {}): Promise<PhysicsWorld<TBinding>> {
    const rapier = await initializePhysics();
    return new PhysicsWorld<TBinding>(rapier, options);
  }

  get bodyCount(): number {
    return this.#registry.size;
  }

  get qualityMode(): PhysicsQualityMode {
    return this.#quality;
  }

  get interpolationAlpha(): number {
    return this.#destroyed ? 0 : Math.min(1, this.#accumulator / this.#preset.fixedStep);
  }

  get status(): PhysicsWorldStatus {
    const entries = this.#registry.entries();
    let dynamicBodyCount = 0;
    let fixedBodyCount = 0;
    let kinematicBodyCount = 0;
    let activeBodyCount = 0;
    let sleepingBodyCount = 0;
    for (const {value: record} of entries) {
      if (record.type === 'dynamic') dynamicBodyCount += 1;
      else if (record.type === 'fixed') fixedBodyCount += 1;
      else kinematicBodyCount += 1;
      if (record.type === 'dynamic' && record.body.isSleeping()) sleepingBodyCount += 1;
      if (record.type !== 'fixed' && record.body.isEnabled() && !record.body.isSleeping()) activeBodyCount += 1;
    }

    const preset = this.#preset;
    const gravity: Vec3 = this.#destroyed ? [0, 0, 0] : vectorToTuple(this.#world.gravity);
    const rapierTimings = !this.#destroyed && this.#profiling ? {
      stepMilliseconds: this.#world.timingStep(),
      collisionDetectionMilliseconds: this.#world.timingCollisionDetection(),
      solverMilliseconds: this.#world.timingSolver(),
      ccdMilliseconds: this.#world.timingCcd()
    } : null;

    return {
      initialized: true,
      destroyed: this.#destroyed,
      engineVersion: this.#rapier.version(),
      quality: this.#quality,
      gravity,
      fixedStep: preset.fixedStep,
      substeps: preset.substeps,
      solverIterations: preset.solverIterations,
      internalPgsIterations: preset.internalPgsIterations,
      ccdSubsteps: preset.ccdSubsteps,
      bodyCount: entries.length,
      dynamicBodyCount,
      fixedBodyCount,
      kinematicBodyCount,
      activeBodyCount,
      sleepingBodyCount,
      accumulatorSeconds: this.#destroyed ? 0 : this.#accumulator,
      interpolationAlpha: this.interpolationAlpha,
      simulationTimeSeconds: this.#simulationTime,
      totalSimulationSteps: this.#totalSimulationSteps,
      totalSimulationSubsteps: this.#totalSimulationSubsteps,
      totalRealtimeUpdates: this.#totalRealtimeUpdates,
      totalDroppedSeconds: this.#totalDroppedSeconds,
      lastStepMilliseconds: this.#lastStepMilliseconds,
      profiling: this.#profiling,
      rapierTimings
    };
  }

  /** Alias for `status`, convenient for render-loop telemetry collection. */
  get stats(): PhysicsWorldStatus {
    return this.status;
  }

  setQualityMode(mode: PhysicsQualityMode): void {
    this.#assertAlive();
    this.#quality = validateQualityMode(mode);
    this.#accumulator = 0;
    this.#applyQualityPreset();
  }

  setGravity(gravity: Vec3): void {
    this.#assertAlive();
    const [x, y, z] = copyVec3(gravity, 'gravity');
    this.#world.gravity = {x, y, z};
  }

  createBody(definition: PhysicsBodyDefinition<TBinding>): PhysicsBodyHandle {
    this.#assertAlive();
    const type = validateBodyType(definition.type ?? 'dynamic');
    const shape = validateShape(definition.shape);
    if (definition.mass !== undefined && definition.density !== undefined) {
      throw new RangeError('mass and density are mutually exclusive');
    }

    const position = copyVec3(definition.position ?? DEFAULT_POSITION, 'position');
    const rotation = normalizeQuaternion(definition.rotation ?? IDENTITY_ROTATION, 'rotation');
    const linearVelocity = copyVec3(definition.linearVelocity ?? DEFAULT_POSITION, 'linearVelocity');
    const angularVelocity = copyVec3(definition.angularVelocity ?? DEFAULT_POSITION, 'angularVelocity');
    const gravityScale = assertFinite(definition.gravityScale ?? 1, 'gravityScale');
    const linearDamping = assertNonNegative(definition.linearDamping ?? 0, 'linearDamping');
    const angularDamping = assertNonNegative(definition.angularDamping ?? 0, 'angularDamping');
    const softCcdPrediction = assertNonNegative(definition.softCcdPrediction ?? 0, 'softCcdPrediction');
    const additionalSolverIterations = assertIterationCount(
      definition.additionalSolverIterations ?? 0,
      'additionalSolverIterations'
    );

    let bodyDesc;
    switch (type) {
      case 'dynamic': bodyDesc = this.#rapier.RigidBodyDesc.dynamic(); break;
      case 'fixed': bodyDesc = this.#rapier.RigidBodyDesc.fixed(); break;
      case 'kinematic-position': bodyDesc = this.#rapier.RigidBodyDesc.kinematicPositionBased(); break;
      case 'kinematic-velocity': bodyDesc = this.#rapier.RigidBodyDesc.kinematicVelocityBased(); break;
    }
    bodyDesc
      .setTranslation(position[0], position[1], position[2])
      .setRotation({x: rotation[0], y: rotation[1], z: rotation[2], w: rotation[3]})
      .setLinvel(linearVelocity[0], linearVelocity[1], linearVelocity[2])
      .setAngvel({x: angularVelocity[0], y: angularVelocity[1], z: angularVelocity[2]})
      .setGravityScale(gravityScale)
      .setLinearDamping(linearDamping)
      .setAngularDamping(angularDamping)
      .setCanSleep(definition.canSleep ?? true)
      .setSleeping(definition.startSleeping ?? false)
      .setCcdEnabled(definition.ccd ?? false)
      .setSoftCcdPrediction(softCcdPrediction)
      .setAdditionalSolverIterations(additionalSolverIterations)
      .setEnabled(definition.enabled ?? true);

    const colliderDesc = this.#createColliderDescriptor(shape);
    if (definition.density !== undefined) colliderDesc.setDensity(assertNonNegative(definition.density, 'density'));
    if (definition.mass !== undefined) colliderDesc.setMass(assertNonNegative(definition.mass, 'mass'));
    if (definition.friction !== undefined) colliderDesc.setFriction(assertNonNegative(definition.friction, 'friction'));
    if (definition.restitution !== undefined) {
      const restitution = assertNonNegative(definition.restitution, 'restitution');
      if (restitution > 1) throw new RangeError('restitution must be between zero and one');
      colliderDesc.setRestitution(restitution);
    }

    const body = this.#world.createRigidBody(bodyDesc);
    try {
      const collider = this.#world.createCollider(colliderDesc, body);
      const initial = readTransform(body);
      const record: BodyRecord<TBinding> = {
        body,
        collider,
        type,
        shape,
        binding: definition.binding,
        previous: cloneTransform(initial),
        current: initial,
        pendingKinematic: undefined
      };
      const handle = this.#registry.create(record);
      body.userData = {physicsBodyHandle: handle};
      return handle;
    } catch (error) {
      this.#world.removeRigidBody(body);
      throw error;
    }
  }

  hasBody(handle: unknown): handle is PhysicsBodyHandle {
    return !this.#destroyed && this.#registry.has(handle);
  }

  listBodyHandles(): PhysicsBodyHandle[] {
    this.#assertAlive();
    return this.#registry.handles();
  }

  getBinding(handle: PhysicsBodyHandle): TBinding | undefined {
    this.#assertAlive();
    return this.#registry.get(handle).binding;
  }

  setBinding(handle: PhysicsBodyHandle, binding: TBinding | undefined): void {
    this.#assertAlive();
    this.#registry.get(handle).binding = binding;
  }

  getCurrentTransform(handle: PhysicsBodyHandle): PhysicsTransform {
    this.#assertAlive();
    return publicTransform(this.#registry.get(handle).current);
  }

  getInterpolatedTransform(handle: PhysicsBodyHandle, alpha = this.interpolationAlpha): PhysicsTransform {
    this.#assertAlive();
    assertFinite(alpha, 'alpha');
    if (alpha < 0 || alpha > 1) throw new RangeError('alpha must be between zero and one');
    const record = this.#registry.get(handle);
    return publicTransform(interpolateTransform(record.previous, record.current, alpha));
  }

  getBodyState(handle: PhysicsBodyHandle): PhysicsBodyState<TBinding> {
    this.#assertAlive();
    const record = this.#registry.get(handle);
    return {
      handle,
      type: record.type,
      shape: record.shape,
      transform: publicTransform(record.current),
      linearVelocity: vectorToTuple(record.body.linvel()),
      angularVelocity: vectorToTuple(record.body.angvel()),
      mass: record.body.mass(),
      density: record.collider.density(),
      friction: record.collider.friction(),
      restitution: record.collider.restitution(),
      linearDamping: record.body.linearDamping(),
      angularDamping: record.body.angularDamping(),
      gravityScale: record.body.gravityScale(),
      sleeping: record.body.isSleeping(),
      enabled: record.body.isEnabled(),
      ccd: record.body.isCcdEnabled(),
      binding: record.binding
    };
  }

  setTransform(handle: PhysicsBodyHandle, update: PhysicsTransformUpdate, wakeUp = true): void {
    this.#assertAlive();
    const record = this.#registry.get(handle);
    const next: MutableTransform = {
      position: update.position ? copyVec3(update.position, 'position') : [...record.current.position],
      rotation: update.rotation ? normalizeQuaternion(update.rotation, 'rotation') : [...record.current.rotation]
    };
    record.body.setTranslation({x: next.position[0], y: next.position[1], z: next.position[2]}, wakeUp);
    record.body.setRotation({x: next.rotation[0], y: next.rotation[1], z: next.rotation[2], w: next.rotation[3]}, wakeUp);
    this.#world.propagateModifiedBodyPositionsToColliders();
    record.previous = cloneTransform(next);
    record.current = next;
    record.pendingKinematic = undefined;
  }

  /** Schedules a pose reached over the next wrapper step by a position-based kinematic body. */
  setNextKinematicTransform(handle: PhysicsBodyHandle, update: PhysicsTransformUpdate): void {
    this.#assertAlive();
    const record = this.#registry.get(handle);
    if (record.type !== 'kinematic-position') {
      throw new TypeError('setNextKinematicTransform requires a position-based kinematic body');
    }
    const base = record.pendingKinematic ?? record.current;
    record.pendingKinematic = {
      position: update.position ? copyVec3(update.position, 'position') : [...base.position],
      rotation: update.rotation ? normalizeQuaternion(update.rotation, 'rotation') : [...base.rotation]
    };
  }

  setLinearVelocity(handle: PhysicsBodyHandle, velocity: Vec3, wakeUp = true): void {
    this.#assertAlive();
    const [x, y, z] = copyVec3(velocity, 'linearVelocity');
    this.#registry.get(handle).body.setLinvel({x, y, z}, wakeUp);
  }

  setAngularVelocity(handle: PhysicsBodyHandle, velocity: Vec3, wakeUp = true): void {
    this.#assertAlive();
    const [x, y, z] = copyVec3(velocity, 'angularVelocity');
    this.#registry.get(handle).body.setAngvel({x, y, z}, wakeUp);
  }

  addForce(handle: PhysicsBodyHandle, force: Vec3, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.addForce(this.#vector(force, 'force'), wakeUp);
  }

  clearForces(handle: PhysicsBodyHandle, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.resetForces(wakeUp);
  }

  addTorque(handle: PhysicsBodyHandle, torque: Vec3, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.addTorque(this.#vector(torque, 'torque'), wakeUp);
  }

  clearTorques(handle: PhysicsBodyHandle, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.resetTorques(wakeUp);
  }

  applyImpulse(handle: PhysicsBodyHandle, impulse: Vec3, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.applyImpulse(this.#vector(impulse, 'impulse'), wakeUp);
  }

  applyImpulseAtPoint(handle: PhysicsBodyHandle, impulse: Vec3, point: Vec3, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.applyImpulseAtPoint(
      this.#vector(impulse, 'impulse'),
      this.#vector(point, 'point'),
      wakeUp
    );
  }

  applyTorqueImpulse(handle: PhysicsBodyHandle, impulse: Vec3, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.applyTorqueImpulse(this.#vector(impulse, 'torqueImpulse'), wakeUp);
  }

  setDamping(handle: PhysicsBodyHandle, linear: number, angular: number): void {
    this.#assertAlive();
    const body = this.#registry.get(handle).body;
    body.setLinearDamping(assertNonNegative(linear, 'linearDamping'));
    body.setAngularDamping(assertNonNegative(angular, 'angularDamping'));
  }

  setGravityScale(handle: PhysicsBodyHandle, scale: number, wakeUp = true): void {
    this.#assertAlive();
    this.#registry.get(handle).body.setGravityScale(assertFinite(scale, 'gravityScale'), wakeUp);
  }

  setCcd(handle: PhysicsBodyHandle, enabled: boolean, softPrediction = 0): void {
    this.#assertAlive();
    const body = this.#registry.get(handle).body;
    body.enableCcd(enabled);
    body.setSoftCcdPrediction(assertNonNegative(softPrediction, 'softCcdPrediction'));
  }

  setColliderMaterial(
    handle: PhysicsBodyHandle,
    update: {friction?: number; restitution?: number; density?: number; mass?: number},
    wakeUp = true
  ): void {
    this.#assertAlive();
    if (update.mass !== undefined && update.density !== undefined) {
      throw new RangeError('mass and density are mutually exclusive');
    }
    const record = this.#registry.get(handle);
    if (update.friction !== undefined) record.collider.setFriction(assertNonNegative(update.friction, 'friction'));
    if (update.restitution !== undefined) {
      const restitution = assertNonNegative(update.restitution, 'restitution');
      if (restitution > 1) throw new RangeError('restitution must be between zero and one');
      record.collider.setRestitution(restitution);
    }
    if (update.density !== undefined) record.collider.setDensity(assertNonNegative(update.density, 'density'));
    if (update.mass !== undefined) record.collider.setMass(assertNonNegative(update.mass, 'mass'));
    if (update.density !== undefined || update.mass !== undefined) {
      record.body.recomputeMassPropertiesFromColliders();
      if (wakeUp) record.body.wakeUp();
    }
  }

  setEnabled(handle: PhysicsBodyHandle, enabled: boolean): void {
    this.#assertAlive();
    this.#registry.get(handle).body.setEnabled(enabled);
  }

  sleep(handle: PhysicsBodyHandle): void {
    this.#assertAlive();
    this.#registry.get(handle).body.sleep();
  }

  wake(handle: PhysicsBodyHandle): void {
    this.#assertAlive();
    this.#registry.get(handle).body.wakeUp();
  }

  /**
   * Advances an interactive simulation through fixed ticks and returns the render interpolation fraction.
   * Excess elapsed time is deliberately dropped after the preset's catch-up budget is exhausted.
   */
  advanceRealtime(deltaSeconds: number): RealtimeStepResult {
    this.#assertAlive();
    assertNonNegative(deltaSeconds, 'deltaSeconds');
    this.#totalRealtimeUpdates += 1;
    const preset = this.#preset;
    const maximumAccepted = preset.fixedStep * preset.maxCatchUpSteps;
    const accepted = Math.min(deltaSeconds, maximumAccepted);
    let droppedSeconds = deltaSeconds - accepted;
    this.#accumulator += accepted;

    let simulatedSteps = 0;
    while (this.#accumulator + STEP_EPSILON >= preset.fixedStep && simulatedSteps < preset.maxCatchUpSteps) {
      this.#runFrame(preset.fixedStep);
      this.#accumulator = Math.max(0, this.#accumulator - preset.fixedStep);
      simulatedSteps += 1;
    }

    if (this.#accumulator + STEP_EPSILON >= preset.fixedStep) {
      const retained = this.#accumulator % preset.fixedStep;
      droppedSeconds += this.#accumulator - retained;
      this.#accumulator = retained;
    }
    this.#totalDroppedSeconds += droppedSeconds;

    return {
      simulatedSteps,
      simulatedSubsteps: simulatedSteps * preset.substeps,
      simulatedSeconds: simulatedSteps * preset.fixedStep,
      interpolationAlpha: this.interpolationAlpha,
      accumulatorSeconds: this.#accumulator,
      droppedSeconds
    };
  }

  /** Advances by exactly one offline frame duration, without time clamping or accumulation. */
  stepExact(durationSeconds: number): ExactStepResult {
    this.#assertAlive();
    assertPositive(durationSeconds, 'durationSeconds');
    this.#accumulator = 0;
    this.#runFrame(durationSeconds);
    return {
      simulatedSteps: 1,
      simulatedSubsteps: this.#preset.substeps,
      simulatedSeconds: durationSeconds
    };
  }

  /** Advances an exact integer number of configured fixed ticks. */
  stepFixed(stepCount = 1): void {
    this.#assertAlive();
    if (!Number.isSafeInteger(stepCount) || stepCount < 1) {
      throw new RangeError('stepCount must be a positive safe integer');
    }
    this.#accumulator = 0;
    for (let step = 0; step < stepCount; step += 1) this.#runFrame(this.#preset.fixedStep);
  }

  removeBody(handle: PhysicsBodyHandle): void {
    this.#assertAlive();
    const record = this.#registry.get(handle);
    this.#world.removeRigidBody(record.body);
    this.#registry.remove(handle);
  }

  clear(): void {
    this.#assertAlive();
    for (const {handle, value} of this.#registry.entries()) {
      this.#world.removeRigidBody(value.body);
      this.#registry.remove(handle);
    }
    this.#resetClock();
  }

  destroy(): void {
    if (this.#destroyed) return;
    this.#registry.clear();
    this.#world.free();
    this.#destroyed = true;
    this.#accumulator = 0;
  }

  get #preset(): PhysicsQualityPreset {
    return PHYSICS_QUALITY_PRESETS[this.#quality];
  }

  #assertAlive(): void {
    if (this.#destroyed) throw new Error('Physics world has been destroyed');
  }

  #applyQualityPreset(): void {
    const preset = this.#preset;
    this.#world.timestep = preset.fixedStep / preset.substeps;
    this.#world.numSolverIterations = preset.solverIterations;
    this.#world.numInternalPgsIterations = preset.internalPgsIterations;
    this.#world.maxCcdSubsteps = preset.ccdSubsteps;
  }

  #createColliderDescriptor(shape: ColliderShape) {
    switch (shape.kind) {
      case 'sphere': return this.#rapier.ColliderDesc.ball(shape.radius);
      case 'box': return this.#rapier.ColliderDesc.cuboid(...shape.halfExtents);
      case 'capsule': return this.#rapier.ColliderDesc.capsule(shape.halfHeight, shape.radius);
    }
  }

  #vector(value: Vec3, label: string): Vector {
    const [x, y, z] = copyVec3(value, label);
    return {x, y, z};
  }

  #runFrame(durationSeconds: number): void {
    const startedAt = monotonicNow();
    const entries = this.#registry.entries();
    for (const {value: record} of entries) record.previous = cloneTransform(record.current);

    const substeps = this.#preset.substeps;
    this.#world.timestep = durationSeconds / substeps;
    for (let substep = 0; substep < substeps; substep += 1) {
      const progress = (substep + 1) / substeps;
      for (const {value: record} of entries) {
        if (!record.pendingKinematic) continue;
        const pose = interpolateTransform(record.previous, record.pendingKinematic, progress);
        record.body.setNextKinematicTranslation({
          x: pose.position[0],
          y: pose.position[1],
          z: pose.position[2]
        });
        record.body.setNextKinematicRotation({
          x: pose.rotation[0],
          y: pose.rotation[1],
          z: pose.rotation[2],
          w: pose.rotation[3]
        });
      }
      this.#world.step();
    }

    for (const {value: record} of entries) {
      record.current = readTransform(record.body);
      record.pendingKinematic = undefined;
    }
    this.#simulationTime += durationSeconds;
    this.#totalSimulationSteps += 1;
    this.#totalSimulationSubsteps += substeps;
    this.#lastStepMilliseconds = monotonicNow() - startedAt;
  }

  #resetClock(): void {
    this.#accumulator = 0;
    this.#simulationTime = 0;
    this.#totalSimulationSteps = 0;
    this.#totalSimulationSubsteps = 0;
    this.#totalRealtimeUpdates = 0;
    this.#totalDroppedSeconds = 0;
    this.#lastStepMilliseconds = 0;
  }
}
