import type {
  NormalizedVideoRecordingOptions,
  SelectedVideoEncoderConfig,
  VideoCodecCapability,
  VideoConfigurationRequest,
  VideoEncoderCapabilities,
  VideoEncoderHandle,
  VideoFrameHandle,
  VideoFrameTiming,
  VideoRecordingMode,
  WebCodecsBackend,
  WebMVideoCodec
} from './types';
import {normalizeVideoRecordingOptions} from './timing';

const CODECS: Readonly<Record<WebMVideoCodec, string>> = {
  vp9: 'vp09.00.10.08',
  vp8: 'vp8'
};

function validateDimension(name: string, value: number): number {
  if (!Number.isSafeInteger(value) || value <= 0 || value > 65_535) {
    throw new RangeError(`${name} must be an integer from 1 through 65535`);
  }
  return value;
}

function codecOrder(preference: NormalizedVideoRecordingOptions['codec']): WebMVideoCodec[] {
  return preference === 'auto' ? ['vp9', 'vp8'] : [preference];
}

function encoderConfig(
  codec: WebMVideoCodec,
  width: number,
  height: number,
  options: NormalizedVideoRecordingOptions,
  hardwareAcceleration: HardwareAcceleration,
  includeBitrateMode: boolean
): VideoEncoderConfig {
  const config: VideoEncoderConfig = {
    codec: CODECS[codec],
    width,
    height,
    displayWidth: width,
    displayHeight: height,
    framerate: options.fps,
    bitrate: options.bitrate,
    hardwareAcceleration,
    latencyMode: options.mode === 'realtime' ? 'realtime' : 'quality',
    alpha: 'discard',
    contentHint: options.mode === 'realtime' ? 'motion' : 'detail'
  };
  if (includeBitrateMode) config.bitrateMode = 'variable';
  return config;
}

function configCandidates(
  codec: WebMVideoCodec,
  width: number,
  height: number,
  options: NormalizedVideoRecordingOptions
): Array<{
  config: VideoEncoderConfig;
  hardwareAcceleration: HardwareAcceleration;
}> {
  const candidates: Array<{
    config: VideoEncoderConfig;
    hardwareAcceleration: HardwareAcceleration;
  }> = [];
  for (const hardwareAcceleration of [
    'prefer-hardware',
    'no-preference'
  ] as const) {
    candidates.push({
      config: encoderConfig(
        codec,
        width,
        height,
        options,
        hardwareAcceleration,
        true
      ),
      hardwareAcceleration
    });
    candidates.push({
      config: encoderConfig(
        codec,
        width,
        height,
        options,
        hardwareAcceleration,
        false
      ),
      hardwareAcceleration
    });
  }
  return candidates;
}

async function supports(
  backend: WebCodecsBackend,
  config: VideoEncoderConfig
): Promise<boolean> {
  try {
    return (await backend.isConfigSupported(config)).supported === true;
  } catch {
    return false;
  }
}

export async function negotiateVideoEncoderConfig(
  request: VideoConfigurationRequest,
  backend: WebCodecsBackend
): Promise<SelectedVideoEncoderConfig> {
  const width = validateDimension('width', request.width);
  const height = validateDimension('height', request.height);
  const options = normalizeVideoRecordingOptions(request);

  for (const codec of codecOrder(options.codec)) {
    for (const candidate of configCandidates(codec, width, height, options)) {
      if (await supports(backend, candidate.config)) {
        return {
          codec,
          codecString: CODECS[codec],
          config: candidate.config,
          hardwareAcceleration: candidate.hardwareAcceleration
        };
      }
    }
  }

  const requested = options.codec === 'auto' ? 'VP9 or VP8' : options.codec.toUpperCase();
  throw new Error(`No supported WebCodecs ${requested} encoder configuration was found`);
}

export async function queryVideoEncoderCapabilities(
  request: Omit<VideoConfigurationRequest, 'codec'>,
  backend: WebCodecsBackend | null = createBrowserWebCodecsBackend()
): Promise<VideoEncoderCapabilities> {
  if (!backend) {
    return {
      webCodecs: false,
      vp9: false,
      vp8: false,
      codecs: [],
      unavailableReason: 'This browser does not expose VideoEncoder and VideoFrame'
    };
  }

  const codecs: VideoCodecCapability[] = [];
  for (const codec of ['vp9', 'vp8'] as const) {
    try {
      const selected = await negotiateVideoEncoderConfig({...request, codec}, backend);
      codecs.push({
        codec,
        codecString: selected.codecString,
        supported: true,
        hardwareAcceleration: selected.hardwareAcceleration
      });
    } catch {
      codecs.push({
        codec,
        codecString: CODECS[codec],
        supported: false,
        hardwareAcceleration: null
      });
    }
  }

  const vp9 = codecs.some(capability => capability.codec === 'vp9' && capability.supported);
  const vp8 = codecs.some(capability => capability.codec === 'vp8' && capability.supported);
  return {
    webCodecs: true,
    vp9,
    vp8,
    codecs,
    unavailableReason: vp9 || vp8 ? null : 'Neither VP9 nor VP8 is supported for this configuration'
  };
}

export function createBrowserWebCodecsBackend(): WebCodecsBackend | null {
  const browser = globalThis as typeof globalThis & {
    VideoEncoder?: typeof VideoEncoder;
    VideoFrame?: typeof VideoFrame;
  };
  const Encoder = browser.VideoEncoder;
  const Frame = browser.VideoFrame;
  if (!Encoder || !Frame) return null;

  return {
    isConfigSupported: config => Encoder.isConfigSupported(config),
    createEncoder: callbacks => {
      const encoder = new Encoder({
        output: chunk => callbacks.output(chunk),
        error: error => callbacks.error(error)
      });
      const handle: VideoEncoderHandle = {
        get encodeQueueSize() {
          return encoder.encodeQueueSize;
        },
        get state() {
          return encoder.state;
        },
        configure: config => encoder.configure(config),
        encode: (frame, options) => encoder.encode(frame as VideoFrame, options),
        flush: () => encoder.flush(),
        reset: () => encoder.reset(),
        close: () => encoder.close()
      };
      return handle;
    },
    createFrame: (canvas: CanvasImageSource, timing: VideoFrameTiming): VideoFrameHandle =>
      new Frame(canvas, {
        timestamp: timing.timestamp,
        duration: timing.duration,
        alpha: 'discard'
      })
  };
}

export function latencyModeForRecording(mode: VideoRecordingMode): LatencyMode {
  return mode === 'realtime' ? 'realtime' : 'quality';
}
