export const GUIDED_RECONSTRUCTION_INPUT_CHANNELS = 16;
export const GUIDED_RECONSTRUCTION_TILE_SIZE = 128;
export const GUIDED_RECONSTRUCTION_HALO = 16;

export type GuidedReconstructionMode = 'native' | '2x';
export type GuidedGraphOperation = 'conv' | 'add' | 'concat' | 'nearest-2x';

export interface GuidedGraphNode {
  readonly name: string;
  readonly operation: GuidedGraphOperation;
  readonly inputs: readonly string[];
  readonly channels: number;
  readonly kernel: number;
  readonly stride: number;
  readonly groups: number;
  readonly relu: boolean;
  readonly weightOffset: number;
  readonly biasOffset: number;
}

export interface GuidedReconstructionGraph {
  readonly schema: 'priosdk-guided-graph-v1';
  readonly layout: 'nchw';
  readonly inputChannels: 16;
  readonly halo: 16;
  readonly nodes: readonly GuidedGraphNode[];
  readonly outputs: Readonly<Record<GuidedReconstructionMode, string>>;
  readonly parameterCount: number;
}

export interface GuidedModelProvenance {
  readonly source: 'renderer-paired' | 'test-fixture';
  readonly datasetSha256: string;
  readonly weightsSha256: string;
  readonly trainingSeed: number;
  readonly trainingScenes: readonly string[];
  readonly validationScenes: readonly string[];
  readonly testScenes: readonly string[];
  readonly qualityGatePassed: boolean;
}

export interface GuidedReconstructionModel {
  readonly graph: GuidedReconstructionGraph;
  readonly weights: Float32Array;
  readonly provenance: GuidedModelProvenance;
}

export interface GuidedTensor {
  readonly channels: number;
  readonly width: number;
  readonly height: number;
  readonly data: Float32Array;
}

export interface GuidedTile {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly inputX: number;
  readonly inputY: number;
  readonly inputSize: number;
  readonly halo: number;
}

export function createGuidedReconstructionGraph(): GuidedReconstructionGraph {
  const nodes: GuidedGraphNode[] = [];
  const channels = new Map<string, number>([['input', GUIDED_RECONSTRUCTION_INPUT_CHANNELS]]);
  let parameterCount = 0;
  const append = (
    name: string, operation: GuidedGraphOperation, inputs: readonly string[], outputChannels: number,
    kernel = 1, stride = 1, groups = 1, relu = false
  ): string => {
    const inputChannels = channels.get(inputs[0] ?? '');
    if (inputChannels === undefined) throw new Error('Graph references an unknown input.');
    const weightOffset = parameterCount;
    if (operation === 'conv') parameterCount += outputChannels * (inputChannels / groups) * kernel * kernel;
    const biasOffset = parameterCount;
    if (operation === 'conv') parameterCount += outputChannels;
    nodes.push(Object.freeze({
      name, operation, inputs: Object.freeze([...inputs]), channels: outputChannels,
      kernel, stride, groups, relu, weightOffset, biasOffset
    }));
    channels.set(name, outputChannels);
    return name;
  };
  const residual = (prefix: string, input: string, count: number): string => {
    const depthwise = append(`${prefix}.depthwise`, 'conv', [input], count, 3, 1, count, true);
    const pointwise = append(`${prefix}.pointwise`, 'conv', [depthwise], count);
    return append(`${prefix}.residual`, 'add', [input, pointwise], count, 1, 1, 1, true);
  };
  let full = append('stem', 'conv', ['input'], 32, 3, 1, 1, true);
  for (let index = 0; index < 3; index++) full = residual(`full.${index}`, full, 32);
  const down = append('down.depthwise', 'conv', [full], 32, 3, 2, 32, true);
  let half = append('down.pointwise', 'conv', [down], 48, 1, 1, 1, true);
  for (let index = 0; index < 2; index++) half = residual(`half.${index}`, half, 48);
  const up = append('up', 'nearest-2x', [half], 48);
  const skip = append('skip', 'concat', [full, up], 80);
  let fused = append('fuse', 'conv', [skip], 32, 1, 1, 1, true);
  for (let index = 0; index < 2; index++) fused = residual(`final.${index}`, fused, 32);
  const native = append('head.native', 'conv', [fused], 4);
  const doubled = append('head.2x', 'conv', [fused], 16);
  return Object.freeze({
    schema: 'priosdk-guided-graph-v1', layout: 'nchw', inputChannels: 16, halo: 16,
    nodes: Object.freeze(nodes), outputs: Object.freeze({native, '2x': doubled}), parameterCount
  });
}

export function assertGuidedModel(model: GuidedReconstructionModel, allowFixture = false): void {
  const expected = createGuidedReconstructionGraph();
  if (JSON.stringify(model.graph) !== JSON.stringify(expected)) {
    throw new Error('Unsupported guided reconstruction graph.');
  }
  if (model.weights.length !== expected.parameterCount || !model.weights.every(Number.isFinite)) {
    throw new Error('Guided reconstruction weights are missing or invalid.');
  }
  const source = model.provenance;
  if (allowFixture && source.source === 'test-fixture') return;
  if (source.source !== 'renderer-paired' || !source.qualityGatePassed
      || !/^[a-f0-9]{64}$/i.test(source.datasetSha256)
      || !/^[a-f0-9]{64}$/i.test(source.weightsSha256)
      || !Number.isSafeInteger(source.trainingSeed)) {
    throw new Error('Guided reconstruction requires verified paired-render training and quality evidence.');
  }
  const groups = [source.trainingScenes, source.validationScenes, source.testScenes];
  if (groups.some(group => group.length === 0)) throw new Error('All scene partitions are required.');
  const names = groups.flat();
  if (new Set(names).size !== names.length) throw new Error('Training and held-out scenes overlap.');
}

export async function verifyGuidedModel(model: GuidedReconstructionModel): Promise<void> {
  assertGuidedModel(model);
  const bytes = new ArrayBuffer(model.weights.length * 4);
  const view = new DataView(bytes);
  model.weights.forEach((weight, index) => view.setFloat32(index * 4, weight, true));
  const digest = new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256', bytes));
  const fingerprint = Array.from(digest, value => value.toString(16).padStart(2, '0')).join('');
  if (fingerprint !== model.provenance.weightsSha256.toLowerCase()) {
    throw new Error('Guided reconstruction model fingerprint does not match its weights.');
  }
}

export function assertGuidedTensor(tensor: GuidedTensor): void {
  for (const value of [tensor.channels, tensor.width, tensor.height]) {
    if (!Number.isSafeInteger(value) || value < 1 || value > 16_384) {
      throw new RangeError('Guided tensor dimensions must be positive bounded integers.');
    }
  }
  if (tensor.data.length !== tensor.channels * tensor.width * tensor.height) {
    throw new RangeError('Guided tensor storage does not match its shape.');
  }
}

export function guidedNodesForMode(
  graph: GuidedReconstructionGraph, mode: GuidedReconstructionMode
): readonly GuidedGraphNode[] {
  const output = graph.outputs[mode];
  if (output === undefined) throw new Error('Unknown guided reconstruction mode.');
  const required = new Set([output]);
  for (let index = graph.nodes.length - 1; index >= 0; index--) {
    const node = graph.nodes[index]!;
    if (required.has(node.name)) for (const input of node.inputs) required.add(input);
  }
  return graph.nodes.filter(node => required.has(node.name));
}

export function guidedNodeShape(node: GuidedGraphNode, input: GuidedTensor): [number, number, number] {
  const factor = node.operation === 'nearest-2x' ? 2 : 1;
  return [node.channels, Math.ceil(input.height / node.stride) * factor, Math.ceil(input.width / node.stride) * factor];
}

export function runGuidedNodeCpu(
  node: GuidedGraphNode, input: GuidedTensor, second: GuidedTensor | undefined, weights: Float32Array
): GuidedTensor {
  assertGuidedTensor(input);
  if (second !== undefined) assertGuidedTensor(second);
  const [channels, height, width] = guidedNodeShape(node, input);
  const data = new Float32Array(channels * height * width);
  const sourcePlane = input.width * input.height;
  const outputPlane = width * height;
  if (node.operation === 'add' || node.operation === 'concat') {
    if (second === undefined || second.width !== input.width || second.height !== input.height
        || (node.operation === 'add' && second.channels !== input.channels)) {
      throw new Error('Guided graph skip connection shapes do not match.');
    }
  }
  if (node.operation === 'conv') {
    const inputsPerGroup = input.channels / node.groups;
    const outputsPerGroup = channels / node.groups;
    if (!Number.isInteger(inputsPerGroup) || !Number.isInteger(outputsPerGroup)
        || node.biasOffset + channels > weights.length) throw new Error('Invalid grouped convolution weights.');
    const padding = Math.floor(node.kernel / 2);
    for (let channel = 0; channel < channels; channel++) {
      const firstChannel = Math.floor(channel / outputsPerGroup) * inputsPerGroup;
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        let sum = weights[node.biasOffset + channel]!;
        for (let local = 0; local < inputsPerGroup; local++) {
          for (let ky = 0; ky < node.kernel; ky++) for (let kx = 0; kx < node.kernel; kx++) {
            const sx = x * node.stride + kx - padding;
            const sy = y * node.stride + ky - padding;
            if (sx < 0 || sy < 0 || sx >= input.width || sy >= input.height) continue;
            const weightIndex = node.weightOffset
              + ((channel * inputsPerGroup + local) * node.kernel + ky) * node.kernel + kx;
            const value = input.data[(firstChannel + local) * sourcePlane + sy * input.width + sx]!;
            sum = Math.fround(sum + Math.fround(value * weights[weightIndex]!));
          }
        }
        data[channel * outputPlane + y * width + x] = node.relu ? Math.max(0, sum) : sum;
      }
    }
  } else {
    for (let channel = 0; channel < channels; channel++) {
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        const index = channel * outputPlane + y * width + x;
        let value: number;
        if (node.operation === 'nearest-2x') {
          value = input.data[channel * sourcePlane + Math.floor(y / 2) * input.width + Math.floor(x / 2)]!;
        } else if (node.operation === 'concat') {
          value = channel < input.channels ? input.data[index]!
            : second!.data[(channel - input.channels) * sourcePlane + y * width + x]!;
        } else {
          value = Math.fround(input.data[index]! + second!.data[index]!);
        }
        data[index] = node.relu ? Math.max(0, value) : value;
      }
    }
  }
  return {channels, width, height, data};
}

export function runGuidedGraphCpu(
  graph: GuidedReconstructionGraph, weights: Float32Array, input: GuidedTensor, mode: GuidedReconstructionMode
): GuidedTensor {
  if (input.channels !== graph.inputChannels || input.width % 2 || input.height % 2) {
    throw new Error('Guided graph requires 16-channel, even-sized input tensors.');
  }
  const nodes = guidedNodesForMode(graph, mode);
  const tensors = new Map<string, GuidedTensor>([['input', input]]);
  const uses = new Map<string, number>();
  for (const node of nodes) for (const name of node.inputs) uses.set(name, (uses.get(name) ?? 0) + 1);
  for (const node of nodes) {
    const first = tensors.get(node.inputs[0]!);
    if (first === undefined) throw new Error('Guided graph input is unavailable.');
    const second = node.inputs.length > 1 ? tensors.get(node.inputs[1]!) : undefined;
    tensors.set(node.name, runGuidedNodeCpu(node, first, second, weights));
    for (const name of node.inputs) {
      const remaining = (uses.get(name) ?? 1) - 1;
      uses.set(name, remaining);
      if (remaining === 0) tensors.delete(name);
    }
  }
  return tensors.get(graph.outputs[mode])!;
}

export function planGuidedTiles(width: number, height: number, coreSize = GUIDED_RECONSTRUCTION_TILE_SIZE): GuidedTile[] {
  if (![width, height, coreSize].every(value => Number.isSafeInteger(value) && value > 0 && value <= 16_384)
      || coreSize % 2 !== 0 || coreSize > 512) throw new RangeError('Invalid guided reconstruction tile extent.');
  const halo = GUIDED_RECONSTRUCTION_HALO;
  const tiles: GuidedTile[] = [];
  for (let y = 0; y < height; y += coreSize) for (let x = 0; x < width; x += coreSize) {
    tiles.push({x, y, width: Math.min(coreSize, width - x), height: Math.min(coreSize, height - y),
      inputX: x - halo, inputY: y - halo, inputSize: coreSize + halo * 2, halo});
  }
  return tiles;
}

export function extractGuidedTile(input: GuidedTensor, tile: GuidedTile): GuidedTensor {
  assertGuidedTensor(input);
  const size = tile.inputSize;
  const data = new Float32Array(input.channels * size * size);
  for (let channel = 0; channel < input.channels; channel++) {
    for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
      const sx = Math.min(input.width - 1, Math.max(0, tile.inputX + x));
      const sy = Math.min(input.height - 1, Math.max(0, tile.inputY + y));
      data[channel * size * size + y * size + x] = input.data[channel * input.width * input.height + sy * input.width + sx]!;
    }
  }
  return {channels: input.channels, width: size, height: size, data};
}

export function runGuidedTiledCpu(
  graph: GuidedReconstructionGraph, weights: Float32Array, input: GuidedTensor,
  mode: GuidedReconstructionMode, coreSize = GUIDED_RECONSTRUCTION_TILE_SIZE
): GuidedTensor {
  const channels = mode === 'native' ? 4 : 16;
  const data = new Float32Array(channels * input.width * input.height);
  for (const tile of planGuidedTiles(input.width, input.height, coreSize)) {
    const result = runGuidedGraphCpu(graph, weights, extractGuidedTile(input, tile), mode);
    for (let channel = 0; channel < channels; channel++) {
      for (let y = 0; y < tile.height; y++) for (let x = 0; x < tile.width; x++) {
        data[channel * input.width * input.height + (tile.y + y) * input.width + tile.x + x]
          = result.data[channel * result.width * result.height + (y + tile.halo) * result.width + x + tile.halo]!;
      }
    }
  }
  return {channels, width: input.width, height: input.height, data};
}
