declare const physicsBodyHandleBrand: unique symbol;

export type PhysicsBodyHandle = string & {readonly [physicsBodyHandleBrand]: 'PhysicsBodyHandle'};

export type Vec3 = readonly [number, number, number];
export type Quaternion = readonly [number, number, number, number];

export interface PhysicsTransform {
  readonly position: Vec3;
  /** Unit quaternion in `[x, y, z, w]` order. */
  readonly rotation: Quaternion;
}

export interface PhysicsTransformUpdate {
  readonly position?: Vec3;
  readonly rotation?: Quaternion;
}

export interface RendererBinding {
  /** Dense analytic-sphere index used by the renderer, when applicable. */
  sphereIndex?: number;
  /** Opaque renderer scene-object handle, when applicable. */
  objectHandle?: string;
  [key: string]: unknown;
}

export type PhysicsQualityMode = 'performance' | 'balanced' | 'quality' | 'ultra';

export interface PhysicsQualityPreset {
  /** Duration of one fixed simulation tick in seconds. */
  readonly fixedStep: number;
  /** Discrete Rapier steps performed inside each fixed simulation tick. */
  readonly substeps: number;
  readonly solverIterations: number;
  readonly internalPgsIterations: number;
  readonly ccdSubsteps: number;
  /** Maximum fixed ticks processed by one real-time update. */
  readonly maxCatchUpSteps: number;
}

export const PHYSICS_QUALITY_PRESETS: Readonly<Record<PhysicsQualityMode, PhysicsQualityPreset>> = Object.freeze({
  performance: Object.freeze({
    fixedStep: 1 / 60,
    substeps: 1,
    solverIterations: 4,
    internalPgsIterations: 1,
    ccdSubsteps: 1,
    maxCatchUpSteps: 4
  }),
  balanced: Object.freeze({
    fixedStep: 1 / 60,
    substeps: 2,
    solverIterations: 6,
    internalPgsIterations: 1,
    ccdSubsteps: 2,
    maxCatchUpSteps: 6
  }),
  quality: Object.freeze({
    fixedStep: 1 / 120,
    substeps: 2,
    solverIterations: 8,
    internalPgsIterations: 2,
    ccdSubsteps: 4,
    maxCatchUpSteps: 8
  }),
  ultra: Object.freeze({
    fixedStep: 1 / 120,
    substeps: 4,
    solverIterations: 12,
    internalPgsIterations: 2,
    ccdSubsteps: 8,
    maxCatchUpSteps: 12
  })
});

export type PhysicsBodyType = 'dynamic' | 'fixed' | 'kinematic-position' | 'kinematic-velocity';

export interface SphereColliderShape {
  readonly kind: 'sphere';
  readonly radius: number;
}

export interface BoxColliderShape {
  readonly kind: 'box';
  /** Positive half-extents on each axis. */
  readonly halfExtents: Vec3;
}

export interface CapsuleColliderShape {
  readonly kind: 'capsule';
  /** Half the length of the capsule's straight segment along its local Y axis. */
  readonly halfHeight: number;
  readonly radius: number;
}

export type ColliderShape = SphereColliderShape | BoxColliderShape | CapsuleColliderShape;

export interface PhysicsBodyDefinition<TBinding = RendererBinding> {
  readonly type?: PhysicsBodyType;
  readonly shape: ColliderShape;
  readonly position?: Vec3;
  readonly rotation?: Quaternion;
  readonly linearVelocity?: Vec3;
  readonly angularVelocity?: Vec3;
  readonly gravityScale?: number;
  /** Shape-derived mass in kg/m^3. Mutually exclusive with `mass`. */
  readonly density?: number;
  /** Exact collider mass in kg. Mutually exclusive with `density`. */
  readonly mass?: number;
  readonly friction?: number;
  /** Coefficient in the inclusive range `[0, 1]`. */
  readonly restitution?: number;
  readonly linearDamping?: number;
  readonly angularDamping?: number;
  readonly canSleep?: boolean;
  readonly startSleeping?: boolean;
  readonly ccd?: boolean;
  readonly softCcdPrediction?: number;
  readonly additionalSolverIterations?: number;
  readonly enabled?: boolean;
  /** Application-owned metadata retained unchanged by the physics world. */
  readonly binding?: TBinding;
}

export interface PhysicsBodyState<TBinding = RendererBinding> {
  readonly handle: PhysicsBodyHandle;
  readonly type: PhysicsBodyType;
  readonly shape: ColliderShape;
  readonly transform: PhysicsTransform;
  readonly linearVelocity: Vec3;
  readonly angularVelocity: Vec3;
  readonly mass: number;
  readonly density: number;
  readonly friction: number;
  readonly restitution: number;
  readonly linearDamping: number;
  readonly angularDamping: number;
  readonly gravityScale: number;
  readonly sleeping: boolean;
  readonly enabled: boolean;
  readonly ccd: boolean;
  readonly binding: TBinding | undefined;
}

export interface PhysicsWorldOptions {
  readonly gravity?: Vec3;
  readonly quality?: PhysicsQualityMode;
  /** World units per meter; use `1` for meter-based scenes. */
  readonly lengthUnit?: number;
  /** Enables Rapier's detailed step profiler. */
  readonly profiling?: boolean;
}

export interface RealtimeStepResult {
  readonly simulatedSteps: number;
  readonly simulatedSubsteps: number;
  readonly simulatedSeconds: number;
  readonly interpolationAlpha: number;
  readonly accumulatorSeconds: number;
  /** Wall-clock time discarded to prevent an unrecoverable catch-up spiral. */
  readonly droppedSeconds: number;
}

export interface ExactStepResult {
  readonly simulatedSteps: 1;
  readonly simulatedSubsteps: number;
  readonly simulatedSeconds: number;
}

export interface PhysicsWorldStatus {
  readonly initialized: true;
  readonly destroyed: boolean;
  readonly engineVersion: string;
  readonly quality: PhysicsQualityMode;
  readonly gravity: Vec3;
  readonly fixedStep: number;
  readonly substeps: number;
  readonly solverIterations: number;
  readonly internalPgsIterations: number;
  readonly ccdSubsteps: number;
  readonly bodyCount: number;
  readonly dynamicBodyCount: number;
  readonly fixedBodyCount: number;
  readonly kinematicBodyCount: number;
  readonly activeBodyCount: number;
  readonly sleepingBodyCount: number;
  readonly accumulatorSeconds: number;
  readonly interpolationAlpha: number;
  readonly simulationTimeSeconds: number;
  readonly totalSimulationSteps: number;
  readonly totalSimulationSubsteps: number;
  readonly totalRealtimeUpdates: number;
  readonly totalDroppedSeconds: number;
  readonly lastStepMilliseconds: number;
  readonly profiling: boolean;
  readonly rapierTimings: {
    readonly stepMilliseconds: number;
    readonly collisionDetectionMilliseconds: number;
    readonly solverMilliseconds: number;
    readonly ccdMilliseconds: number;
  } | null;
}
