export const DEFAULT_TEXTURE_WORK_SLICE_MS = 8;

export interface CooperativeTextureWorkOptions {
  readonly signal?: AbortSignal;
  readonly checkCurrent?: () => void;
  readonly sliceMs?: number;
  readonly onYield?: () => void;
}

export class CooperativeTextureWork {
  readonly #signal: AbortSignal | undefined;
  readonly #checkCurrent: (() => void) | undefined;
  readonly #sliceMs: number;
  readonly #onYield: (() => void) | undefined;
  #deadline: number;

  constructor(options: CooperativeTextureWorkOptions = {}) {
    this.#signal = options.signal;
    this.#checkCurrent = options.checkCurrent;
    this.#sliceMs = normalizeSliceMs(options.sliceMs);
    this.#onYield = options.onYield;
    this.#deadline = monotonicNow() + this.#sliceMs;
    this.assertCurrent();
  }

  assertCurrent(): void {
    if (this.#signal?.aborted === true) throw abortError();
    this.#checkCurrent?.();
  }

  shouldYield(): boolean {
    this.assertCurrent();
    return monotonicNow() >= this.#deadline;
  }

  async checkpoint(force = false): Promise<void> {
    this.assertCurrent();
    if (!force && monotonicNow() < this.#deadline) return;
    await macrotaskYield();
    this.#onYield?.();
    this.assertCurrent();
    this.#deadline = monotonicNow() + this.#sliceMs;
  }
}

function normalizeSliceMs(value: number | undefined): number {
  if (value === undefined) return DEFAULT_TEXTURE_WORK_SLICE_MS;
  if (!Number.isFinite(value) || value < 0 || value > 100) {
    throw new RangeError('Texture work slice must be from 0 through 100 milliseconds.');
  }
  return value;
}

function monotonicNow(): number {
  return globalThis.performance?.now() ?? Date.now();
}

function macrotaskYield(): Promise<void> {
  return new Promise(resolve => globalThis.setTimeout(resolve, 0));
}

function abortError(): DOMException {
  return new DOMException('Texture processing was aborted.', 'AbortError');
}
