export type PostStorageFormat = 'rgba16float' | 'rgba8unorm';

export interface PostExtent {
  readonly width: number;
  readonly height: number;
}

export interface PostDispatchSize {
  readonly x: number;
  readonly y: number;
  readonly z: 1;
}

export const POST_WORKGROUP_SIZE = 8;

export function assertPostExtent(width: number, height: number, label = 'extent'): PostExtent {
  if (!Number.isInteger(width) || width <= 0 || !Number.isInteger(height) || height <= 0) {
    throw new RangeError(`${label} width and height must be positive integers.`);
  }
  return {width, height};
}

export function postDispatchSize(
  width: number,
  height: number,
  workgroupSize = POST_WORKGROUP_SIZE
): PostDispatchSize {
  assertPostExtent(width, height);
  if (!Number.isInteger(workgroupSize) || workgroupSize <= 0) {
    throw new RangeError('workgroupSize must be a positive integer.');
  }
  return {
    x: Math.ceil(width / workgroupSize),
    y: Math.ceil(height / workgroupSize),
    z: 1
  };
}

export function finiteNumber(value: number, label: string): number {
  if (!Number.isFinite(value)) {
    throw new RangeError(`${label} must be finite.`);
  }
  return value;
}

export function positiveNumber(value: number, label: string): number {
  finiteNumber(value, label);
  if (value <= 0) {
    throw new RangeError(`${label} must be greater than zero.`);
  }
  return value;
}

export function clampNumber(value: number, minimum: number, maximum: number, label: string): number {
  finiteNumber(value, label);
  return Math.min(maximum, Math.max(minimum, value));
}
