import type {CloudDensityVolume} from './model';
import type {Vec3} from './scene';

export type CloudRenderingMode = 'off' | 'sheet-2d' | 'volumetric-3d';

export interface CloudRenderingSettings {
  readonly mode: CloudRenderingMode;
  /** Primary view-ray samples. Ignored by sheet mode. */
  readonly steps: number;
  /** Density samples used to estimate cloud self-shadowing toward the sun. */
  readonly lightSteps: number;
  /** Additional artist-controlled multiplier applied to the stored physical density. */
  readonly densityMultiplier: number;
}

export interface CloudRenderingStatus {
  readonly state: 'empty' | 'cpu-ready' | 'gpu-ready';
  readonly active: boolean;
  readonly mode: CloudRenderingMode;
  readonly steps: number;
  readonly lightSteps: number;
  readonly densityMultiplier: number;
  readonly resolution: readonly [number, number, number];
  readonly minimum: Vec3;
  readonly maximum: Vec3;
  readonly voxelCount: number;
  readonly gpuBytes: number;
}

export const DEFAULT_CLOUD_RENDERING_SETTINGS: CloudRenderingSettings = Object.freeze({
  mode: 'off',
  steps: 32,
  lightSteps: 4,
  densityMultiplier: 1
});

export interface GpuCloudResourcesOptions {
  readonly onBindingChanged?: () => void;
}

const MAX_CLOUD_STEPS = 96;
const MAX_CLOUD_LIGHT_STEPS = 16;
const MAX_DENSITY_MULTIPLIER = 64;

/**
 * Owns the renderer's optional R8 cloud volume. A zero-density 1x1x1 texture
 * remains bound when no volume is present so cloud mode can be disabled through
 * uniforms without changing the shader or bind-group ABI.
 */
export class GpuCloudResources {
  readonly #onBindingChanged: () => void;
  #device: GPUDevice | null = null;
  #texture: GPUTexture | null = null;
  #view: GPUTextureView | null = null;
  #sampler: GPUSampler | null = null;
  #volume: CloudDensityVolume | null = null;
  #uploaded = false;
  #destroyed = false;

  constructor(options: GpuCloudResourcesOptions = {}) {
    this.#onBindingChanged = options.onBindingChanged ?? (() => {});
  }

  initialize(device: GPUDevice): void {
    if (this.#destroyed) throw new Error('Cannot initialize destroyed GPU cloud resources.');
    this.releaseDevice();
    try {
      this.#device = device;
      this.#sampler = device.createSampler({
        label: 'PrioSDK cloud density sampler',
        addressModeU: 'clamp-to-edge',
        addressModeV: 'clamp-to-edge',
        addressModeW: 'clamp-to-edge',
        magFilter: 'linear',
        minFilter: 'linear'
      });
      this.#replaceTexture(this.#volume);
    } catch (error) {
      this.releaseDevice();
      throw error;
    }
  }

  setVolume(volume: CloudDensityVolume | null): void {
    if (this.#destroyed) throw new Error('Cannot modify destroyed GPU cloud resources.');
    const next = volume === null ? null : cloneCloudVolume(volume);
    if (this.#device === null) {
      this.#volume = next;
      return;
    }
    const previous = this.#volume;
    this.#volume = next;
    try {
      this.#replaceTexture(next);
    } catch (error) {
      this.#volume = previous;
      throw error;
    }
  }

  clearVolume(): void {
    this.setVolume(null);
  }

  getVolume(): CloudDensityVolume | null {
    return this.#volume;
  }

  getTextureView(): GPUTextureView {
    if (this.#view === null) throw new Error('GPU cloud resources are not initialized.');
    return this.#view;
  }

  getSampler(): GPUSampler {
    if (this.#sampler === null) throw new Error('GPU cloud resources are not initialized.');
    return this.#sampler;
  }

  getStatus(settings: CloudRenderingSettings): CloudRenderingStatus {
    const volume = this.#volume;
    const gpuReady = volume !== null && this.#uploaded && this.#device !== null;
    return {
      state: volume === null ? 'empty' : gpuReady ? 'gpu-ready' : 'cpu-ready',
      active: gpuReady && settings.mode !== 'off',
      mode: settings.mode,
      steps: settings.steps,
      lightSteps: settings.lightSteps,
      densityMultiplier: settings.densityMultiplier,
      resolution: volume?.resolution ?? [0, 0, 0],
      minimum: volume === null ? [0, 0, 0] : [...volume.minimum],
      maximum: volume === null ? [0, 0, 0] : [...volume.maximum],
      voxelCount: volume?.density.length ?? 0,
      gpuBytes: gpuReady ? volume!.density.byteLength : 0
    };
  }

  getUniformParameters(settings: CloudRenderingSettings): Float32Array {
    const volume = this.#volume;
    const active = volume !== null && this.#uploaded && settings.mode !== 'off';
    const mode = !active ? 0 : settings.mode === 'sheet-2d' ? 1 : 2;
    if (volume === null) {
      return new Float32Array([
        0, 0, 0, 0,
        0, 0, 0, settings.steps,
        1, 1, 1, 0,
        0, 0, settings.lightSteps, 0
      ]);
    }
    return new Float32Array([
      volume.minimum[0], volume.minimum[1], volume.minimum[2], mode,
      volume.maximum[0], volume.maximum[1], volume.maximum[2], settings.steps,
      volume.scatteringAlbedo[0], volume.scatteringAlbedo[1], volume.scatteringAlbedo[2], volume.extinction,
      volume.densityScale * settings.densityMultiplier, volume.anisotropy, settings.lightSteps, active ? 1 : 0
    ]);
  }

  releaseDevice(): void {
    this.#texture?.destroy();
    this.#texture = null;
    this.#view = null;
    this.#sampler = null;
    this.#device = null;
    this.#uploaded = false;
  }

  destroy(): void {
    if (this.#destroyed) return;
    this.releaseDevice();
    this.#volume = null;
    this.#destroyed = true;
  }

  #replaceTexture(volume: CloudDensityVolume | null): void {
    const device = this.#device;
    if (device === null) return;
    const resolution = volume?.resolution ?? [1, 1, 1];
    if (
      resolution[0] > device.limits.maxTextureDimension3D
      || resolution[1] > device.limits.maxTextureDimension3D
      || resolution[2] > device.limits.maxTextureDimension3D
    ) {
      throw new RangeError(
        `Cloud density resolution ${resolution.join('x')} exceeds this GPU's 3D texture limit of ${device.limits.maxTextureDimension3D}.`
      );
    }
    const replacement = device.createTexture({
      label: volume === null ? 'PrioSDK empty cloud density' : 'PrioSDK cloud density volume',
      size: {
        width: resolution[0],
        height: resolution[1],
        depthOrArrayLayers: resolution[2]
      },
      dimension: '3d',
      format: 'r8unorm',
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
    });
    try {
      const bytes = volume?.density ?? new Uint8Array(1);
      writeR8Volume(device.queue, replacement, resolution, bytes);
      const replacementView = replacement.createView({
        label: 'PrioSDK cloud density 3D view',
        dimension: '3d',
        format: 'r8unorm'
      });
      const previousTexture = this.#texture;
      const previousView = this.#view;
      const previousUploaded = this.#uploaded;
      this.#texture = replacement;
      this.#view = replacementView;
      this.#uploaded = volume !== null;
      try {
        this.#onBindingChanged();
      } catch (error) {
        this.#texture = previousTexture;
        this.#view = previousView;
        this.#uploaded = previousUploaded;
        throw error;
      }
      previousTexture?.destroy();
    } catch (error) {
      replacement.destroy();
      throw error;
    }
  }
}

export function sanitizeCloudRenderingSettings(
  current: CloudRenderingSettings,
  patch: Partial<CloudRenderingSettings>
): CloudRenderingSettings {
  const mode = patch.mode ?? current.mode;
  if (mode !== 'off' && mode !== 'sheet-2d' && mode !== 'volumetric-3d') {
    throw new RangeError(`Unknown cloud rendering mode: ${String(mode)}`);
  }
  return {
    mode,
    steps: boundedInteger(patch.steps ?? current.steps, 1, MAX_CLOUD_STEPS, 'Cloud steps'),
    lightSteps: boundedInteger(
      patch.lightSteps ?? current.lightSteps,
      0,
      MAX_CLOUD_LIGHT_STEPS,
      'Cloud light steps'
    ),
    densityMultiplier: finiteRange(
      patch.densityMultiplier ?? current.densityMultiplier,
      0,
      MAX_DENSITY_MULTIPLIER,
      'Cloud density multiplier'
    )
  };
}

function cloneCloudVolume(volume: CloudDensityVolume): CloudDensityVolume {
  if (
    volume?.kind !== 'cloud-density-volume'
    || volume.format !== 'r8unorm'
    || volume.axisOrder !== 'x-y-z'
  ) {
    throw new TypeError('Cloud volume must be an R8 cloud density volume.');
  }
  const center = finiteVec3(volume.center, 'Cloud center');
  const size = finiteVec3(volume.size, 'Cloud size');
  if (size.some(component => component <= 0)) {
    throw new RangeError('Cloud size components must be greater than zero.');
  }
  const requestedResolution = validateResolution(volume.requestedResolution);
  const resolution = validateResolution(volume.resolution);
  const expectedLength = resolution[0] * resolution[1] * resolution[2];
  if (!(volume.density instanceof Uint8Array) || volume.density.length !== expectedLength) {
    throw new RangeError(`Cloud density must contain exactly ${expectedLength} R8 voxels.`);
  }
  const minimum = finiteVec3(volume.minimum, 'Cloud minimum');
  const maximum = finiteVec3(volume.maximum, 'Cloud maximum');
  for (const axis of [0, 1, 2] as const) {
    if (maximum[axis] <= minimum[axis]) {
      throw new RangeError('Cloud maximum bounds must be greater than minimum bounds on every axis.');
    }
  }
  const scatteringAlbedo = finiteVec3(volume.scatteringAlbedo, 'Cloud scattering albedo');
  for (const channel of scatteringAlbedo) {
    if (channel < 0 || channel > 1) throw new RangeError('Cloud scattering albedo must be from zero through one.');
  }
  const densityScale = finiteRange(volume.densityScale, 0, 64, 'Cloud density scale');
  const extinction = finiteRange(volume.extinction, 0, 1_000, 'Cloud extinction');
  const anisotropy = finiteRange(volume.anisotropy, -0.95, 0.95, 'Cloud anisotropy');
  return {
    ...volume,
    center,
    size,
    minimum,
    maximum,
    requestedResolution,
    resolution,
    density: new Uint8Array(volume.density),
    densityScale,
    scatteringAlbedo,
    extinction,
    anisotropy,
    stats: {...volume.stats}
  };
}

function validateResolution(value: readonly [number, number, number]): [number, number, number] {
  if (!value || value.length !== 3) throw new TypeError('Cloud resolution must have three components.');
  return value.map((component, axis) => {
    if (!Number.isSafeInteger(component) || component < 1 || component > 512) {
      throw new RangeError(`Cloud resolution axis ${axis} must be an integer from 1 through 512.`);
    }
    return component;
  }) as [number, number, number];
}

function finiteVec3(value: Vec3, label: string): [number, number, number] {
  if (!value || value.length !== 3) throw new TypeError(`${label} must have three components.`);
  return value.map((component, axis) => {
    if (!Number.isFinite(component) || !Number.isFinite(Math.fround(component))) {
      throw new RangeError(`${label} axis ${axis} must be finite.`);
    }
    return component;
  }) as [number, number, number];
}

function boundedInteger(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be an integer from ${minimum} through ${maximum}.`);
  }
  return value;
}

function finiteRange(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value)) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be from ${minimum} through ${maximum}.`);
  }
  return value;
}

function writeR8Volume(
  queue: GPUQueue,
  texture: GPUTexture,
  resolution: readonly [number, number, number],
  source: Uint8Array
): void {
  const [width, height, depth] = resolution;
  const bytesPerRow = Math.ceil(width / 256) * 256;
  const upload = bytesPerRow === width
    ? source
    : padRows(source, width, height, depth, bytesPerRow);
  queue.writeTexture(
    {texture},
    upload,
    {offset: 0, bytesPerRow, rowsPerImage: height},
    {width, height, depthOrArrayLayers: depth}
  );
}

function padRows(
  source: Uint8Array,
  width: number,
  height: number,
  depth: number,
  bytesPerRow: number
): Uint8Array {
  const result = new Uint8Array(bytesPerRow * height * depth);
  const rowCount = height * depth;
  for (let row = 0; row < rowCount; row += 1) {
    result.set(source.subarray(row * width, (row + 1) * width), row * bytesPerRow);
  }
  return result;
}
