import {
  assertGuidedTensor, guidedNodeShape, guidedNodesForMode,
  type GuidedReconstructionMode, type GuidedReconstructionModel, type GuidedTensor
} from './guided-reconstruction-graph';
import {awaitGuidedOperation, throwIfGuidedAborted, type GuidedTileBackend} from './inference-backends-types';

export interface GuidedMlOperand {readonly shape: readonly number[]}
export interface GuidedMlTensor {destroy(): void}
export interface GuidedMlGraph {readonly devices?: readonly string[]; destroy(): void}
export interface GuidedMlDescriptor {
  readonly dataType: 'float32'; readonly shape: readonly number[];
  readonly readable?: boolean; readonly writable?: boolean;
}
export interface GuidedMlContext {
  readonly accelerated?: boolean;
  readonly lost?: Promise<{message: string}>;
  opSupportLimits(): Record<string, unknown>;
  createTensor(descriptor: GuidedMlDescriptor): Promise<GuidedMlTensor>;
  createExportableTensor?(descriptor: GuidedMlDescriptor, device: GPUDevice): Promise<GuidedMlTensor>;
  exportToGPU?(tensor: GuidedMlTensor): GPUBuffer | Promise<GPUBuffer>;
  writeTensor(tensor: GuidedMlTensor, values: Float32Array): void;
  dispatch(graph: GuidedMlGraph, inputs: Record<string, GuidedMlTensor>, outputs: Record<string, GuidedMlTensor>): void;
  readTensor(tensor: GuidedMlTensor): Promise<ArrayBuffer>;
  destroy(): void;
}
export interface GuidedMlBuilder {
  input(name: string, descriptor: GuidedMlDescriptor): GuidedMlOperand;
  constant(descriptor: GuidedMlDescriptor, values: Float32Array): GuidedMlOperand;
  conv2d(input: GuidedMlOperand, weights: GuidedMlOperand, options: {
    inputLayout: 'nchw'; filterLayout: 'oihw'; padding: number[]; strides: number[]; groups: number; bias: GuidedMlOperand;
  }): GuidedMlOperand;
  add(first: GuidedMlOperand, second: GuidedMlOperand): GuidedMlOperand;
  concat(inputs: GuidedMlOperand[], axis: number): GuidedMlOperand;
  relu(input: GuidedMlOperand): GuidedMlOperand;
  resample2d(input: GuidedMlOperand, options: {mode: 'nearest-neighbor'; scales: number[]; axes: number[]}): GuidedMlOperand;
  build(outputs: Record<string, GuidedMlOperand>): Promise<GuidedMlGraph>;
}
export interface GuidedWebNnEnvironment {
  readonly ml: {createContext(options: {
    powerPreference: 'high-performance'; accelerated: true; deviceType: 'gpu' | 'npu';
  }): Promise<GuidedMlContext>};
  readonly MLGraphBuilder: new(context: GuidedMlContext) => GuidedMlBuilder;
}

export function getGuidedWebNnEnvironment(): GuidedWebNnEnvironment | undefined {
  const environment = globalThis as unknown as {
    navigator?: {ml?: GuidedWebNnEnvironment['ml']};
    MLGraphBuilder?: GuidedWebNnEnvironment['MLGraphBuilder'];
  };
  if (typeof environment.navigator?.ml?.createContext !== 'function' || typeof environment.MLGraphBuilder !== 'function') {
    return undefined;
  }
  return {ml: environment.navigator.ml, MLGraphBuilder: environment.MLGraphBuilder};
}

export function assertGuidedWebNnOperators(context: GuidedMlContext, builder: GuidedMlBuilder): void {
  for (const name of ['createTensor', 'writeTensor', 'dispatch', 'readTensor', 'opSupportLimits', 'destroy'] as const) {
    if (typeof context[name] !== 'function') throw new Error(`WebNN context does not expose ${name}.`);
  }
  const limits = context.opSupportLimits();
  for (const name of ['conv2d', 'add', 'concat', 'relu', 'resample2d'] as const) {
    if (typeof builder[name] !== 'function' || !(name in limits)) throw new Error(`WebNN does not support required ${name}.`);
    const visit = (value: unknown): void => {
      if (typeof value !== 'object' || value === null) return;
      const record = value as Record<string, unknown>;
      if (Array.isArray(record.dataTypes) && !record.dataTypes.includes('float32')) {
        throw new Error(`WebNN ${name} does not support the model's float32 tensors.`);
      }
      for (const [key, child] of Object.entries(record)) if (key !== 'dataTypes') visit(child);
    };
    visit(limits[name]);
  }
}

export function buildGuidedWebNnGraph(
  builder: GuidedMlBuilder, model: GuidedReconstructionModel, width: number, height: number,
  mode: GuidedReconstructionMode
): Promise<GuidedMlGraph> {
  if (width % 2 || height % 2 || width < 2 || height < 2 || width > 160 || height > 160) {
    throw new RangeError('WebNN reconstruction tiles require even extents no larger than 160.');
  }
  const input = builder.input('input', {dataType: 'float32', shape: [1, 16, height, width]});
  const operands = new Map<string, GuidedMlOperand>([['input', input]]);
  const shapes = new Map<string, {channels: number; width: number; height: number}>([['input', {channels: 16, width, height}]]);
  for (const node of guidedNodesForMode(model.graph, mode)) {
    const first = operands.get(node.inputs[0]!)!;
    const inputShape = shapes.get(node.inputs[0]!)!;
    let output: GuidedMlOperand;
    if (node.operation === 'conv') {
      const weights = builder.constant({dataType: 'float32', shape: [node.channels, inputShape.channels / node.groups, node.kernel, node.kernel]},
        model.weights.slice(node.weightOffset, node.biasOffset));
      const bias = builder.constant({dataType: 'float32', shape: [node.channels]},
        model.weights.slice(node.biasOffset, node.biasOffset + node.channels));
      const padding = Math.floor(node.kernel / 2);
      output = builder.conv2d(first, weights, {inputLayout: 'nchw', filterLayout: 'oihw',
        padding: [padding, padding, padding, padding], strides: [node.stride, node.stride], groups: node.groups, bias});
    } else if (node.operation === 'add') {
      output = builder.add(first, operands.get(node.inputs[1]!)!);
    } else if (node.operation === 'concat') {
      output = builder.concat(node.inputs.map(name => operands.get(name)!), 1);
    } else {
      output = builder.resample2d(first, {mode: 'nearest-neighbor', scales: [2, 2], axes: [2, 3]});
    }
    if (node.relu) output = builder.relu(output);
    const [channels, outputHeight, outputWidth] = guidedNodeShape(node, {...inputShape, data: new Float32Array(0)});
    const expected = [1, channels, outputHeight, outputWidth];
    if (output.shape.length !== expected.length || output.shape.some((value, index) => value !== expected[index])) {
      throw new Error(`WebNN graph shape mismatch at ${node.name}.`);
    }
    shapes.set(node.name, {channels, width: outputWidth, height: outputHeight});
    operands.set(node.name, output);
  }
  return builder.build({output: operands.get(model.graph.outputs[mode])!});
}

interface WebNnPlan {
  readonly key: string; readonly channels: number; readonly width: number; readonly height: number;
  readonly input: GuidedMlTensor; readonly output: GuidedMlTensor; readonly graph: GuidedMlGraph;
}

export class GuidedWebNnBackend implements GuidedTileBackend {
  readonly kind = 'webnn';
  private context: GuidedMlContext | undefined;
  private plan: WebNnPlan | undefined;
  private disposed = false;
  private lostReason: string | undefined;

  constructor(
    private readonly environment: GuidedWebNnEnvironment,
    private readonly model: GuidedReconstructionModel,
    private readonly preferNpu: boolean,
    private readonly timeoutMs: number
  ) {}

  get accelerated(): boolean | undefined {return this.context?.accelerated;}
  get reportedDevices(): readonly ('cpu' | 'gpu' | 'npu')[] | undefined {
    const devices = this.plan?.graph.devices;
    if (devices === undefined) return undefined;
    return devices.filter((value): value is 'cpu' | 'gpu' | 'npu' => value === 'cpu' || value === 'gpu' || value === 'npu');
  }

  private async initialize(signal?: AbortSignal): Promise<GuidedMlContext> {
    throwIfGuidedAborted(signal);
    if (this.disposed || this.lostReason !== undefined) throw new Error(this.lostReason ?? 'WebNN backend was disposed.');
    if (this.context !== undefined) return this.context;
    const context = await awaitGuidedOperation(this.environment.ml.createContext({
      powerPreference: 'high-performance', accelerated: true,
      deviceType: this.preferNpu ? 'npu' : 'gpu'
    }), this.timeoutMs, signal, value => value.destroy());
    if (this.disposed || signal?.aborted) {context.destroy(); throwIfGuidedAborted(signal); throw new Error('WebNN backend was disposed.');}
    try {assertGuidedWebNnOperators(context, new this.environment.MLGraphBuilder(context));}
    catch (error) {context.destroy(); throw error;}
    this.context = context;
    void context.lost?.then(info => {
      this.lostReason = `WebNN context was lost: ${info.message.slice(0, 256)}`;
      this.dispose();
    }, () => {this.lostReason = 'WebNN context was lost.'; this.dispose();});
    return context;
  }

  private releasePlan(): void {
    if (this.plan !== undefined) {
      this.plan.input.destroy(); this.plan.output.destroy(); this.plan.graph.destroy(); this.plan = undefined;
    }
  }

  private async getPlan(input: GuidedTensor, mode: GuidedReconstructionMode, signal?: AbortSignal, device?: GPUDevice): Promise<WebNnPlan> {
    const context = await this.initialize(signal);
    const key = `${mode}:${input.width}:${input.height}:${device === undefined ? 'host' : 'gpu'}`;
    if (this.plan?.key === key) return this.plan;
    this.releasePlan();
    const tensors: GuidedMlTensor[] = [];
    let graph: GuidedMlGraph | undefined;
    try {
      graph = await awaitGuidedOperation(buildGuidedWebNnGraph(new this.environment.MLGraphBuilder(context),
        this.model, input.width, input.height, mode), this.timeoutMs, signal, value => value.destroy());
      const channels = mode === 'native' ? 4 : 16;
      for (const descriptor of [
        {dataType: 'float32' as const, shape: [1, 16, input.height, input.width], writable: true},
        {dataType: 'float32' as const, shape: [1, channels, input.height, input.width], readable: true}
      ]) {
        const created = device === undefined ? context.createTensor(descriptor)
          : context.createExportableTensor!(descriptor, device);
        tensors.push(await awaitGuidedOperation(created, this.timeoutMs, signal, value => value.destroy()));
      }
      throwIfGuidedAborted(signal);
      if (this.disposed) throw new Error('WebNN context became unavailable.');
      this.plan = {key, channels, width: input.width, height: input.height, input: tensors[0]!, output: tensors[1]!, graph};
      return this.plan;
    } catch (error) {
      for (const tensor of tensors) tensor.destroy();
      graph?.destroy();
      throw error;
    }
  }

  async inferTile(input: GuidedTensor, mode: GuidedReconstructionMode, signal?: AbortSignal): Promise<GuidedTensor> {
    assertGuidedTensor(input);
    if (input.channels !== 16) throw new RangeError('WebNN reconstruction requires 16 feature channels.');
    const plan = await this.getPlan(input, mode, signal);
    const context = this.context!;
    try {
      context.writeTensor(plan.input, input.data);
      context.dispatch(plan.graph, {input: plan.input}, {output: plan.output});
      const bytes = await awaitGuidedOperation(context.readTensor(plan.output), this.timeoutMs, signal);
      throwIfGuidedAborted(signal);
      if (this.disposed) throw new Error('WebNN context became unavailable.');
      if (bytes.byteLength !== plan.channels * plan.width * plan.height * 4) throw new Error('WebNN output byte count is invalid.');
      const data = new Float32Array(bytes);
      if (!data.every(Number.isFinite)) throw new Error('WebNN produced a non-finite reconstruction.');
      return {channels: plan.channels, width: plan.width, height: plan.height, data};
    } catch (error) {
      this.dispose();
      throw error;
    }
  }

  async assertGpuInterop(signal?: AbortSignal): Promise<void> {
    const context = await this.initialize(signal);
    if (typeof context.createExportableTensor !== 'function' || typeof context.exportToGPU !== 'function') {
      throw new Error('WebNN GPU tensor import/export is not exposed by this browser.');
    }
  }

  async inferGpuTile(
    input: import('./inference-backends-types').GuidedGpuTensor,
    output: import('./inference-backends-types').GuidedGpuTensor,
    tile: import('./guided-reconstruction-graph').GuidedTile,
    mode: GuidedReconstructionMode, device: GPUDevice,
    transfer: Pick<import('./inference-backends-webgpu').GuidedWebGpuBackend, 'gatherGpuTile' | 'scatterGpuTile'>,
    signal?: AbortSignal
  ): Promise<void> {
    await this.assertGpuInterop(signal);
    const plan = await this.getPlan({channels: 16, width: tile.inputSize, height: tile.inputSize,
      data: new Float32Array(0)}, mode, signal, device);
    const context = this.context!;
    let exported: GPUBuffer | undefined;
    try {
      exported = await awaitGuidedOperation(Promise.resolve(context.exportToGPU!(plan.input)),
        this.timeoutMs, signal, buffer => buffer.destroy());
      await transfer.gatherGpuTile(input, exported, tile, signal);
      exported.destroy(); exported = undefined;
      context.dispatch(plan.graph, {input: plan.input}, {output: plan.output});
      exported = await awaitGuidedOperation(Promise.resolve(context.exportToGPU!(plan.output)),
        this.timeoutMs, signal, buffer => buffer.destroy());
      await transfer.scatterGpuTile(exported, output, tile, signal);
      exported.destroy(); exported = undefined;
      throwIfGuidedAborted(signal);
      if (this.disposed) throw new Error('WebNN context became unavailable.');
    } catch (error) {
      exported?.destroy(); this.dispose(); throw error;
    }
  }

  dispose(): void {
    this.disposed = true; this.releasePlan(); this.context?.destroy(); this.context = undefined;
  }
}
