export type RapierModule = typeof import('@dimforge/rapier3d-compat').default;

export type PhysicsModuleLoader = () => Promise<RapierModule>;

const importModule = (specifier: string): Promise<typeof import('@dimforge/rapier3d-compat')> => import(specifier);

const defaultModuleLoader: PhysicsModuleLoader = async () => {
  const packageSpecifier = ['@dimforge', 'rapier3d-compat'].join('/');
  const namespace = await importModule(packageSpecifier);
  await namespace.init();
  return namespace.default;
};

let moduleLoader: PhysicsModuleLoader = defaultModuleLoader;
let initializationPromise: Promise<RapierModule> | undefined;
let initializedModule: RapierModule | undefined;

/** Installs the source used by the next physics initialization. */
export const configurePhysicsModuleLoader = (loader: PhysicsModuleLoader): boolean => {
  if (typeof loader !== 'function') throw new TypeError('The physics module loader must be a function.');
  if (initializedModule !== undefined || initializationPromise !== undefined) return false;
  moduleLoader = loader;
  return true;
};

/** Initializes the configured Rapier module exactly once, including under concurrent calls. */
export const initializePhysics = (): Promise<RapierModule> => {
  if (initializationPromise !== undefined) return initializationPromise;

  initializationPromise = moduleLoader()
    .then(module => {
      if (typeof module !== 'object' || module === null || typeof module.version !== 'function') {
        throw new TypeError('The loaded physics module is not a compatible Rapier module.');
      }
      initializedModule = module;
      return module;
    })
    .catch((error: unknown) => {
      initializationPromise = undefined;
      throw error;
    });

  return initializationPromise;
};

export const isPhysicsInitialized = (): boolean => initializedModule !== undefined;
