import type {AntiAliasingMode, RenderSettings, UpscalingMode} from '../../contracts';

export const DEFAULT_GPU_TEXTURE_BUDGET_BYTES = 512 * 1024 * 1024;
export const CINEMATIC_SSAA_4X_GPU_TEXTURE_BUDGET_BYTES = 1024 * 1024 * 1024;
export const MAX_OUTPUT_PIXELS = 8_294_400;

export interface ResolutionRequest {
  cssWidth: number;
  cssHeight: number;
  devicePixelRatio: number;
  outputWidth?: number;
  outputHeight?: number;
  maxTextureDimension2D: number;
  maxComputeWorkgroupsPerDimension: number;
  workgroupSize: number;
  settings: Pick<
    RenderSettings,
    'mode' | 'antiAliasing' | 'renderScale' | 'upscaling' | 'experimentalLearnedEnhancement'
  >;
  textureBudgetBytes?: number;
  renderBytesPerPixel?: number;
  outputBytesPerPixel?: number;
}

export interface ResolutionPlan {
  renderWidth: number;
  renderHeight: number;
  outputWidth: number;
  outputHeight: number;
  requestedOutputWidth: number;
  requestedOutputHeight: number;
  explicitOutputSize: boolean;
  requestedRenderScale: number;
  effectiveRenderScale: number;
  upscaleRatio: number;
  supersampleAxisScale: number;
  estimatedTextureBytes: number;
  constrained: boolean;
}

export function upscalingRatio(mode: UpscalingMode): number {
  switch (mode) {
    case 'fsr1-quality':
    case 'fsr3-experimental-quality':
      return 1.5;
    case 'fsr1-balanced':
    case 'fsr3-experimental-balanced':
      return 1.7;
    case 'fsr1-performance':
    case 'fsr3-experimental-performance':
      return 2;
    case 'fsr3-experimental-native-aa':
    case 'native':
      return 1;
  }
}

export function supersampleAxisScale(mode: AntiAliasingMode): number {
  switch (mode) {
    case 'ssaa-2x':
      return Math.SQRT2;
    case 'ssaa-4x':
      return 2;
    default:
      return 1;
  }
}

export function calculateResolutionPlan(request: ResolutionRequest): ResolutionPlan {
  const hasExplicitOutputWidth = request.outputWidth !== undefined;
  const hasExplicitOutputHeight = request.outputHeight !== undefined;
  if (hasExplicitOutputWidth !== hasExplicitOutputHeight) {
    throw new RangeError('outputWidth and outputHeight must be provided together');
  }

  const explicitOutputSize = hasExplicitOutputWidth && hasExplicitOutputHeight;
  const cssWidth = positive(request.cssWidth);
  const cssHeight = positive(request.cssHeight);
  const dpr = clamp(request.devicePixelRatio, 1, 2);
  const maxDimension = Math.max(
    1,
    Math.min(
      integer(request.maxTextureDimension2D, 8192),
      integer(request.maxComputeWorkgroupsPerDimension, 65_535) * Math.max(1, integer(request.workgroupSize, 8))
    )
  );
  const budget = Math.max(16 * 1024 * 1024, request.textureBudgetBytes ?? DEFAULT_GPU_TEXTURE_BUDGET_BYTES);
  const outputBytes = Math.max(4, request.outputBytesPerPixel ?? 72);
  const requestedScale = clamp(request.settings.renderScale, 0.25, 4);
  const learnedRatio = request.settings.mode !== 'raster'
    && request.settings.experimentalLearnedEnhancement === 'quality-gated-2x'
    ? 2
    : 1;
  const maxRenderDimension = Math.floor(maxDimension / learnedRatio);
  if (maxRenderDimension < 1) {
    throw new RangeError('The device dimension limit cannot fit the requested 2x learned reconstruction.');
  }
  const renderBytes = Math.max(8, request.renderBytesPerPixel ?? 96)
    + 8 * (learnedRatio * learnedRatio - 1);
  const ratio = upscalingRatio(request.settings.upscaling) * learnedRatio;
  const ssaaScale = supersampleAxisScale(request.settings.antiAliasing);
  const requestedRenderPerOutputAxis = requestedScale * ssaaScale / ratio;

  const rawOutputWidth = explicitOutputSize
    ? explicitOutputDimension(request.outputWidth, 'outputWidth')
    : cssWidth * dpr;
  const rawOutputHeight = explicitOutputSize
    ? explicitOutputDimension(request.outputHeight, 'outputHeight')
    : cssHeight * dpr;
  const combinedBytesPerOutputPixel = outputBytes
    + renderBytes * requestedRenderPerOutputAxis * requestedRenderPerOutputAxis;
  const outputFit = Math.min(
    1,
    maxDimension / rawOutputWidth,
    maxDimension / rawOutputHeight,
    Math.sqrt(MAX_OUTPUT_PIXELS / (rawOutputWidth * rawOutputHeight)),
    Math.sqrt(budget / (rawOutputWidth * rawOutputHeight * combinedBytesPerOutputPixel))
  );
  const outputWidth = Math.max(1, Math.floor(rawOutputWidth * outputFit));
  const outputHeight = Math.max(1, Math.floor(rawOutputHeight * outputFit));

  const rawRenderWidth = outputWidth * requestedRenderPerOutputAxis;
  const rawRenderHeight = outputHeight * requestedRenderPerOutputAxis;
  const outputAllocation = outputWidth * outputHeight * outputBytes;
  const renderBudget = Math.max(1, budget - outputAllocation);
  const renderFit = Math.min(
    1,
    maxRenderDimension / rawRenderWidth,
    maxRenderDimension / rawRenderHeight,
    Math.sqrt(renderBudget / (rawRenderWidth * rawRenderHeight * renderBytes))
  );
  const renderWidth = Math.max(1, Math.floor(rawRenderWidth * renderFit));
  const renderHeight = Math.max(1, Math.floor(rawRenderHeight * renderFit));
  const estimatedTextureBytes = Math.ceil(
    renderWidth * renderHeight * renderBytes + outputAllocation
  );
  const effectiveRenderScale = renderWidth / outputWidth;

  return {
    renderWidth,
    renderHeight,
    outputWidth,
    outputHeight,
    requestedOutputWidth: rawOutputWidth,
    requestedOutputHeight: rawOutputHeight,
    explicitOutputSize,
    requestedRenderScale: requestedScale,
    effectiveRenderScale,
    upscaleRatio: ratio,
    supersampleAxisScale: ssaaScale,
    estimatedTextureBytes,
    constrained: outputFit < 0.9999 || renderFit < 0.9999
  };
}

export function buildPostPassSequence(
  settings: Pick<
    RenderSettings,
    | 'mode'
    | 'antiAliasing'
    | 'autoExposure'
    | 'bloomStrength'
    | 'denoising'
    | 'experimentalLearnedEnhancement'
    | 'filmGrainStrength'
    | 'fogDensity'
    | 'frameGeneration'
    | 'chromaticAberrationPixels'
    | 'upscaling'
  >
): readonly string[] {
  const traceMode = settings.mode !== 'raster';
  const passes = [traceMode ? 'trace' : 'raster'];
  if (traceMode && settings.fogDensity > 0) {
    passes.push('volumetric-raymarch');
  }
  if (traceMode && settings.denoising !== 'off') {
    passes.push('atrous-denoise');
  }
  if (traceMode && settings.experimentalLearnedEnhancement !== 'off') {
    passes.push(settings.experimentalLearnedEnhancement === 'quality-gated-2x'
      ? 'learned-quality-gated-reconstruct-2x'
      : 'learned-quality-gated-filter');
  }
  const fsr1 = settings.upscaling.startsWith('fsr1-');
  const learnedOwnsReconstruction = traceMode
    && settings.experimentalLearnedEnhancement === 'quality-gated-2x';
  const temporal = !learnedOwnsReconstruction
    && (settings.upscaling.startsWith('fsr3-')
      || (settings.antiAliasing === 'temporal' && !fsr1));
  if (temporal) {
    passes.push(settings.upscaling.startsWith('fsr3-')
      ? 'fsr3-experimental-temporal-resolve'
      : 'temporal-reprojection-upscale');
  }
  if (settings.autoExposure) {
    passes.push('auto-exposure-reduce');
  }
  if (settings.bloomStrength > 0) {
    passes.push('display-bloom-filter');
  }
  passes.push('tone-map');
  if (fsr1) {
    passes.push('fsr1-easu', 'fsr1-rcas');
  }
  if (settings.frameGeneration === 'fsr3-experimental') {
    passes.push('fsr3-experimental-interpolate');
  }
  if (settings.filmGrainStrength > 0 || settings.chromaticAberrationPixels > 0) {
    if (settings.frameGeneration === 'fsr3-experimental') {
      passes.push('photographic-effects-current', 'photographic-effects-generated');
    } else {
      passes.push('photographic-effects');
    }
  }
  if (settings.antiAliasing === 'fxaa') {
    passes.push('fxaa');
  }
  passes.push('present');
  return passes;
}

function positive(value: number): number {
  return Number.isFinite(value) && value > 0 ? value : 1;
}

function explicitOutputDimension(value: number | undefined, name: string): number {
  if (!Number.isSafeInteger(value) || (value ?? 0) <= 0) {
    throw new RangeError(`${name} must be a positive safe integer`);
  }
  return value as number;
}

function integer(value: number, fallback: number): number {
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : fallback;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(maximum, Math.max(minimum, Number.isFinite(value) ? value : minimum));
}
