export function rendererTextureBudgetBytes(
  outputResolution: OutputResolutionSettings,
  settings: Pick<RenderSettings, 'antiAliasing' | 'mode'>
): number | undefined {
  return outputResolution.mode === 'custom'
    && outputResolution.width === 1920
    && outputResolution.height === 1080
    && settings.mode === 'path-trace'
    && settings.antiAliasing === 'ssaa-4x'
    ? CINEMATIC_SSAA_4X_GPU_TEXTURE_BUDGET_BYTES
    : undefined;
}

export interface OfflineTraceTile {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface OfflineTraceWorkload {
  readonly samplesPerDispatch: number;
  readonly maxBounces: number;
  readonly lightSamples: number;
  readonly sceneLightCount: number;
  readonly sceneTriangleCount: number;
  readonly fogDensity: number;
  readonly rayVolumeWeight: number;
  readonly volumetricSteps: number;
  readonly cloudActive?: boolean;
  readonly cloudSteps?: number;
  readonly cloudLightSteps?: number;
}

export interface OfflineTraceSchedule {
  readonly tiles: readonly OfflineTraceTile[];
  readonly tilesPerFence: number;
  readonly tilesPerPaint: number;
  readonly activePixelsPerTile: number;
  readonly workloadScale: number;
}

export function planOfflineTraceTiles(
  width: number,
  height: number,
  samplesPerDispatch = 1,
  activePixelsPerTile = Math.floor(
    OFFLINE_TRACE_ACTIVE_PIXELS_PER_SAMPLE
      / Math.min(8, Math.max(1, Math.floor(samplesPerDispatch)))
  ),
  tileHeight = OFFLINE_TRACE_TILE_HEIGHT
): readonly OfflineTraceTile[] {
  const boundedSamples = Math.min(8, Math.max(1, Math.floor(samplesPerDispatch)));
  const boundedTileHeight = [1, 2, OFFLINE_TRACE_HIGH_COST_TILE_HEIGHT].includes(tileHeight)
    ? tileHeight
    : OFFLINE_TRACE_TILE_HEIGHT;
  const minimumTileWidth = boundedTileHeight < OFFLINE_TRACE_TILE_HEIGHT
    ? Math.min(WORKGROUP_SIZE, Math.max(1, Math.floor(activePixelsPerTile / boundedTileHeight)))
    : OFFLINE_TRACE_TILE_MIN_WIDTH;
  const widthAlignment = Math.min(WORKGROUP_SIZE, minimumTileWidth);
  const boundedActivePixels = Math.max(
    minimumTileWidth * boundedTileHeight,
    Math.min(
      Math.floor(OFFLINE_TRACE_ACTIVE_PIXELS_PER_SAMPLE / boundedSamples),
      Math.floor(activePixelsPerTile)
    )
  );
  const tileWidth = Math.max(
    minimumTileWidth,
    Math.floor(boundedActivePixels / boundedTileHeight / widthAlignment)
      * widthAlignment
  );
  const tiles: OfflineTraceTile[] = [];
  for (let y = 0; y < height; y += boundedTileHeight) {
    for (let x = 0; x < width; x += tileWidth) {
      tiles.push({
        x,
        y,
        width: Math.min(tileWidth, width - x),
        height: Math.min(boundedTileHeight, height - y)
      });
    }
  }
  return tiles;
}

export function planOfflineTraceSchedule(
  width: number,
  height: number,
  workload: OfflineTraceWorkload
): OfflineTraceSchedule {
  const samplesPerDispatch = Math.min(8, Math.max(1, Math.floor(workload.samplesPerDispatch)));
  const maxBounces = Math.min(16, Math.max(1, Math.floor(workload.maxBounces)));
  const lightSamples = Math.min(8, Math.max(1, Math.floor(workload.lightSamples)));
  const sceneLightCount = Math.min(MAX_SCENE_LIGHTS, Math.max(1, Math.floor(workload.sceneLightCount)));
  const triangleRatio = Math.max(1, workload.sceneTriangleCount / DEFAULT_REALTIME_TRIANGLE_BUDGET);
  const triangleFactor = 1 + Math.min(0.75, Math.max(0, Math.log2(triangleRatio)) * 0.25);
  const fogFactor = workload.fogDensity > 0 && workload.rayVolumeWeight > 0
    ? 1 + Math.min(1, Math.max(1, Math.floor(workload.volumetricSteps)) / 32)
    : 1;
  const cloudFactor = workload.cloudActive
    ? 1 + Math.min(
      3,
      Math.max(1, Math.floor(workload.cloudSteps ?? 1))
        * (1 + Math.max(0, Math.floor(workload.cloudLightSteps ?? 0)))
        / 32
    )
    : 1;
  const referencePathCost = DEFAULT_RENDER_SETTINGS.maxBounces
    * DEFAULT_RENDER_SETTINGS.lightSamples;
  const pathCost = maxBounces * lightSamples * sceneLightCount * triangleFactor * fogFactor * cloudFactor;
  // A fence bounds queued work, but cannot preempt one expensive dispatch.
  // Shrink high-cost packets as well, including the nested shadow and volume
  // work. Partial workgroups exit at the tile extent before tracing a ray.
  const workloadScale = Math.min(
    OFFLINE_TRACE_MAX_WORKLOAD_SCALE,
    Math.max(1, Math.sqrt(pathCost / referencePathCost))
  );
  const heavyWorkload = workloadScale >= 4;
  const heavyPixelBudget = Math.floor(OFFLINE_TRACE_HEAVY_SAMPLE_PIXELS / samplesPerDispatch);
  const tileHeight = heavyWorkload
    ? Math.max(1, Math.min(OFFLINE_TRACE_HIGH_COST_TILE_HEIGHT, Math.floor(heavyPixelBudget / WORKGROUP_SIZE)))
    : OFFLINE_TRACE_TILE_HEIGHT;
  const minimumTileWidth = tileHeight < OFFLINE_TRACE_TILE_HEIGHT
    ? Math.min(WORKGROUP_SIZE, Math.max(1, Math.floor(heavyPixelBudget / tileHeight)))
    : OFFLINE_TRACE_TILE_MIN_WIDTH;
  const activePixelsPerTile = Math.max(
    minimumTileWidth * tileHeight,
    heavyWorkload ? heavyPixelBudget : Math.floor(OFFLINE_TRACE_ACTIVE_PIXELS_PER_SAMPLE / samplesPerDispatch / workloadScale)
  );
  const tilesPerFence = workloadScale >= 2
    ? OFFLINE_TRACE_MIN_TILES_PER_FENCE
    : workloadScale > 1
      ? 4
      : OFFLINE_TRACE_TILES_PER_FENCE;
  return {
    tiles: planOfflineTraceTiles(width, height, samplesPerDispatch, activePixelsPerTile, tileHeight),
    tilesPerFence,
    tilesPerPaint: Math.max(4, tilesPerFence),
    activePixelsPerTile,
    workloadScale
  };
}

