  removeTexture(handle: TextureHandle): void {
    this.ensureMutable();
    const layer = this.textureResources.resolveTextureLayer(handle);
    let detachedMaterial = false;
    for (const materialHandle of this.scene.listMaterialHandles()) {
      const material = this.scene.getMaterial(materialHandle);
      const patch: Partial<SceneMaterialDefinition> = {};
      let textureFlags = material.textureFlags;
      if (material.textureLayer === layer) {
        patch.textureLayer = NO_TEXTURE_LAYER;
        textureFlags &= ~(
          MATERIAL_TEXTURE_FLAG_BASE_COLOR
          | MATERIAL_TEXTURE_FLAG_LUMINANCE_NORMAL
          | MATERIAL_TEXTURE_FLAG_LUMINANCE_ROUGHNESS
        );
      }
      if (material.normalTextureLayer === layer) {
        patch.normalTextureLayer = NO_TEXTURE_LAYER;
        textureFlags &= ~MATERIAL_TEXTURE_FLAG_INDEPENDENT_NORMAL;
      }
      if (material.roughnessTextureLayer === layer) {
        patch.roughnessTextureLayer = NO_TEXTURE_LAYER;
        textureFlags &= ~(MATERIAL_TEXTURE_FLAG_INDEPENDENT_ROUGHNESS | MATERIAL_TEXTURE_FLAG_PACKED_METALLIC_ROUGHNESS);
      }
      if (Object.keys(patch).length === 0) continue;
      patch.textureFlags = textureFlags >>> 0;
      this.scene.updateMaterial(materialHandle, patch);
      detachedMaterial = true;
    }
    this.textureResources.removeTexture(handle);
    if (detachedMaterial) this.markSceneDirty();
    else this.resetPathAccumulation();
  }

  resolveTextureLayer(handle: TextureHandle | null | undefined): number {
    this.ensureMutable();
    return this.textureResources.resolveTextureLayer(handle);
  }

  getTextureStatus(): TextureRegistryStatus;
