import type {SceneHandle} from './types';

export type HandleKind = 'material' | 'mesh' | 'object' | 'light';

interface Slot<T> {
  generation: number;
  value: T | null;
}

export interface SlotEntry<T, H extends SceneHandle> {
  readonly slot: number;
  readonly handle: H;
  readonly value: T;
}

const HANDLE_PATTERN = /^(material|mesh|object|light):([a-z0-9]+):(\d+):(\d+)$/;

export class HandleRegistry<T, H extends SceneHandle> {
  readonly #kind: HandleKind;
  readonly #owner: string;
  readonly #slots: Slot<T>[] = [];
  #size = 0;

  constructor(kind: HandleKind, owner: string) {
    this.#kind = kind;
    this.#owner = owner;
  }

  get size(): number {
    return this.#size;
  }

  create(value: T): H {
    let slotIndex = this.#slots.findIndex(slot => slot.value === null);
    if (slotIndex < 0) {
      slotIndex = this.#slots.length;
      this.#slots.push({generation: 1, value});
    } else {
      const slot = this.#slots[slotIndex];
      if (!slot) throw new Error('Internal handle slot invariant failed');
      slot.value = value;
    }
    this.#size += 1;
    const slot = this.#slots[slotIndex];
    if (!slot) throw new Error('Internal handle slot invariant failed');
    return this.#format(slotIndex, slot.generation);
  }

  has(handle: unknown): handle is H {
    const parsed = this.#parse(handle);
    if (!parsed) return false;
    const slot = this.#slots[parsed.slot];
    return slot !== undefined && slot.value !== null && slot.generation === parsed.generation;
  }

  get(handle: H): T {
    const parsed = this.#require(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null) throw this.#invalidHandle(handle);
    return slot.value;
  }

  set(handle: H, value: T): void {
    const parsed = this.#require(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null) throw this.#invalidHandle(handle);
    slot.value = value;
  }

  remove(handle: H): void {
    const parsed = this.#require(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null) throw this.#invalidHandle(handle);
    slot.value = null;
    slot.generation = slot.generation === Number.MAX_SAFE_INTEGER ? 1 : slot.generation + 1;
    this.#size -= 1;
  }

  clear(): void {
    for (const slot of this.#slots) {
      if (slot.value !== null) {
        slot.value = null;
        slot.generation = slot.generation === Number.MAX_SAFE_INTEGER ? 1 : slot.generation + 1;
      }
    }
    this.#size = 0;
  }

  entries(): SlotEntry<T, H>[] {
    const entries: SlotEntry<T, H>[] = [];
    for (let slotIndex = 0; slotIndex < this.#slots.length; slotIndex += 1) {
      const slot = this.#slots[slotIndex];
      if (slot?.value !== null && slot?.value !== undefined) {
        entries.push({slot: slotIndex, handle: this.#format(slotIndex, slot.generation), value: slot.value});
      }
    }
    return entries;
  }

  handles(): H[] {
    return this.entries().map(entry => entry.handle);
  }

  #format(slot: number, generation: number): H {
    return `${this.#kind}:${this.#owner}:${slot}:${generation}` as H;
  }

  #parse(handle: unknown): {slot: number; generation: number} | null {
    if (typeof handle !== 'string') return null;
    const match = HANDLE_PATTERN.exec(handle);
    if (!match || match[1] !== this.#kind || match[2] !== this.#owner) return null;
    const slot = Number(match[3]);
    const generation = Number(match[4]);
    if (!Number.isSafeInteger(slot) || !Number.isSafeInteger(generation) || slot < 0 || generation < 1) return null;
    return {slot, generation};
  }

  #require(handle: H): {slot: number; generation: number} {
    const parsed = this.#parse(handle);
    if (!parsed) throw this.#invalidHandle(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null || slot.generation !== parsed.generation) throw this.#invalidHandle(handle);
    return parsed;
  }

  #invalidHandle(handle: unknown): RangeError {
    return new RangeError(`Invalid or stale ${this.#kind} handle: ${String(handle)}`);
  }
}
