import {
  assertGuidedModel, assertGuidedTensor, createGuidedReconstructionGraph, extractGuidedTile, planGuidedTiles,
  runGuidedGraphCpu, verifyGuidedModel,
  type GuidedReconstructionMode, type GuidedReconstructionModel, type GuidedTensor, type GuidedTile
} from './guided-reconstruction-graph';
import {GuidedWebGpuBackend} from './inference-backends-webgpu';
import {getGuidedWebNnEnvironment, GuidedWebNnBackend, type GuidedWebNnEnvironment} from './inference-backends-webnn';
import {
  assertGuidedParity, awaitGuidedOperation, throwIfGuidedAborted,
  type GuidedGpuInferenceResult, type GuidedGpuTensor, type GuidedInferenceBackend,
  type GuidedInferenceOptions, type GuidedInferencePreference, type GuidedInferenceReport,
  type GuidedInferenceResult, type GuidedTileBackend
} from './inference-backends-types';

export type {
  GuidedGpuInferenceResult, GuidedGpuTensor, GuidedInferenceBackend, GuidedInferenceOptions,
  GuidedInferencePreference, GuidedInferenceProgress, GuidedInferenceReport, GuidedInferenceResult
} from './inference-backends-types';
export type {GuidedWebNnEnvironment} from './inference-backends-webnn';

export interface GuidedInferenceConfiguration {
  readonly device: GPUDevice;
  readonly requestedBackend?: GuidedInferencePreference;
  readonly webnn?: GuidedWebNnEnvironment | null;
  readonly coreSize?: number;
  readonly timeoutMs?: number;
}

export interface GuidedInferenceStatus {
  readonly modelReady: boolean;
  readonly busy: boolean;
  readonly requestedBackend: GuidedInferencePreference;
  readonly report?: GuidedInferenceReport;
  readonly error?: string;
}

interface Selection {
  readonly backend: GuidedTileBackend;
  readonly fallbackReason?: string;
  readonly benchmarkMilliseconds?: Readonly<Partial<Record<GuidedInferenceBackend, number>>>;
}

function errorText(error: unknown): string {
  return (error instanceof Error ? error.message : String(error)).slice(0, 512);
}

function copyTile(result: GuidedTensor, output: GuidedTensor, tile: GuidedTile): void {
  for (let channel = 0; channel < output.channels; channel++) for (let y = 0; y < tile.height; y++) {
    const start = channel * result.width * result.height + (y + tile.halo) * result.width + tile.halo;
    const destination = channel * output.width * output.height + (tile.y + y) * output.width + tile.x;
    output.data.set(result.data.subarray(start, start + tile.width), destination);
  }
}

function median(values: readonly number[]): number {
  return [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)]!;
}

function probeInput(): GuidedTensor {
  const input: GuidedTensor = {channels: 16, width: 8, height: 8, data: new Float32Array(16 * 8 * 8)};
  for (let index = 0; index < input.data.length; index++) {
    input.data[index] = Math.sin(index * .173) * .37 + Math.cos(index * .071) * .19 + .4;
  }
  return input;
}

export class GuidedInferenceService {
  private readonly device: GPUDevice;
  private readonly requested: GuidedInferencePreference;
  private readonly environment: GuidedWebNnEnvironment | undefined;
  private readonly coreSize: number;
  private readonly timeoutMs: number;
  private model: GuidedReconstructionModel | undefined;
  private gpu: GuidedWebGpuBackend | undefined;
  private webnn: GuidedWebNnBackend | undefined;
  private readonly probed = new Set<string>();
  private readonly selections = new Map<GuidedReconstructionMode, Selection>();
  private readonly gpuSelections = new Map<GuidedReconstructionMode, Selection>();
  private tail: Promise<void> = Promise.resolve();
  private active: AbortController | undefined;
  private report: GuidedInferenceReport | undefined;
  private error: string | undefined;
  private disposed = false;

  constructor(configuration: GuidedInferenceConfiguration) {
    this.device = configuration.device;
    this.requested = configuration.requestedBackend ?? 'auto';
    this.environment = configuration.webnn === null ? undefined : configuration.webnn ?? getGuidedWebNnEnvironment();
    this.coreSize = configuration.coreSize ?? 128;
    this.timeoutMs = configuration.timeoutMs ?? 30_000;
    if (!['auto', 'webgpu', 'webnn', 'webnn-npu'].includes(this.requested)) throw new Error('Unknown inference backend preference.');
    if (!Number.isSafeInteger(this.coreSize) || this.coreSize < 2 || this.coreSize > 128 || this.coreSize % 2) {
      throw new RangeError('Inference tile cores must be even integers from 2 to 128.');
    }
    if (!Number.isFinite(this.timeoutMs) || this.timeoutMs < 100 || this.timeoutMs > 120_000) {
      throw new RangeError('Inference operation timeout must be between 100 and 120000 milliseconds.');
    }
    void this.device.lost.then(info => {
      if (!this.disposed) {
        this.error = `Reconstruction GPU device was lost: ${info.message.slice(0, 256)}`;
        this.dispose();
      }
    }, () => {if (!this.disposed) {this.error = 'Reconstruction GPU device was lost.'; this.dispose();}});
  }

  get status(): GuidedInferenceStatus {
    return {modelReady: this.model !== undefined && !this.disposed, busy: this.active !== undefined,
      requestedBackend: this.requested,
      ...(this.report === undefined ? {} : {report: this.report}),
      ...(this.error === undefined ? {} : {error: this.error})};
  }

  private enqueue<T>(operation: (signal: AbortSignal) => Promise<T>, external?: AbortSignal): Promise<T> {
    if (this.disposed) return Promise.reject(new Error('Reconstruction service was disposed.'));
    this.cancel();
    const controller = new AbortController();
    const abort = (): void => controller.abort();
    external?.addEventListener('abort', abort, {once: true});
    if (external?.aborted) controller.abort();
    this.active = controller;
    const job = this.tail.then(async () => {
      throwIfGuidedAborted(controller.signal);
      if (this.disposed) throw new Error('Reconstruction service was disposed.');
      try {return await operation(controller.signal);}
      catch (error) {
        if (!controller.signal.aborted) this.error = errorText(error);
        throw error;
      }
    });
    this.tail = job.then(() => undefined, () => undefined);
    return job.finally(() => {
      external?.removeEventListener('abort', abort);
      if (this.active === controller) this.active = undefined;
    });
  }

  setModel(model: GuidedReconstructionModel): Promise<void> {
    if (!this.disposed && this.model !== undefined && model.weights.length === this.model.weights.length
        && JSON.stringify(model.graph) === JSON.stringify(this.model.graph)
        && JSON.stringify(model.provenance) === JSON.stringify(this.model.provenance)
        && model.weights.every((value, index) => value === this.model!.weights[index])) return Promise.resolve();
    return this.enqueue(async signal => {
      assertGuidedModel(model);
      const snapshot: GuidedReconstructionModel = {
        graph: createGuidedReconstructionGraph(), weights: model.weights.slice(),
        provenance: {...model.provenance,
          trainingScenes: [...model.provenance.trainingScenes], validationScenes: [...model.provenance.validationScenes],
          testScenes: [...model.provenance.testScenes]}
      };
      await awaitGuidedOperation(verifyGuidedModel(snapshot), this.timeoutMs, signal);
      throwIfGuidedAborted(signal);
      this.gpu?.dispose(); this.webnn?.dispose(); this.probed.clear(); this.selections.clear(); this.gpuSelections.clear();
      this.model = snapshot; this.gpu = new GuidedWebGpuBackend(this.device, snapshot, this.timeoutMs);
      this.webnn = undefined; this.error = undefined; this.report = undefined;
    });
  }

  private async probe(backend: GuidedTileBackend, mode: GuidedReconstructionMode, signal: AbortSignal): Promise<void> {
    const key = `${backend.kind}:${mode}`;
    if (this.probed.has(key)) return;
    const input = probeInput();
    const expected = runGuidedGraphCpu(this.model!.graph, this.model!.weights, input, mode);
    const actual = await backend.inferTile(input, mode, signal);
    assertGuidedParity(actual.data, expected.data);
    throwIfGuidedAborted(signal);
    this.probed.add(key);
  }

  private async select(firstTile: GuidedTensor, mode: GuidedReconstructionMode, signal: AbortSignal): Promise<Selection> {
    const gpu = this.gpu!;
    await this.probe(gpu, mode, signal);
    const existing = this.selections.get(mode);
    if (existing !== undefined) return existing;
    const fallback = (reason?: string): Selection => {
      const value: Selection = {backend: gpu, ...(reason === undefined ? {} : {fallbackReason: reason})};
      this.selections.set(mode, value); return value;
    };
    if (this.requested === 'webgpu') return fallback();
    if (this.environment === undefined) return fallback('WebNN is not exposed by this browser; using ordinary WebGPU compute.');
    try {
      this.webnn ??= new GuidedWebNnBackend(this.environment, this.model!, this.requested === 'webnn-npu', this.timeoutMs);
      await this.probe(this.webnn, mode, signal);
      const gpuWarm = await gpu.inferTile(firstTile, mode, signal);
      const webnnWarm = await this.webnn.inferTile(firstTile, mode, signal);
      assertGuidedParity(webnnWarm.data, gpuWarm.data);
      const timings: Record<GuidedInferenceBackend, number[]> = {webgpu: [], webnn: []};
      for (let iteration = 0; iteration < 3; iteration++) {
        for (const backend of iteration % 2 ? [this.webnn, gpu] : [gpu, this.webnn]) {
          const start = performance.now();
          const result = await backend.inferTile(firstTile, mode, signal);
          timings[backend.kind].push(performance.now() - start);
          assertGuidedParity(result.data, gpuWarm.data);
        }
      }
      const benchmarkMilliseconds = {webgpu: median(timings.webgpu), webnn: median(timings.webnn)};
      const useWebnn = this.requested !== 'auto' || benchmarkMilliseconds.webnn < benchmarkMilliseconds.webgpu * .9;
      const selection: Selection = {backend: useWebnn ? this.webnn : gpu, benchmarkMilliseconds,
        ...(!useWebnn ? {fallbackReason: 'WebNN including tensor transfers did not beat WebGPU by 10%; retained WebGPU.'} : {})};
      this.selections.set(mode, selection);
      return selection;
    } catch (error) {
      throwIfGuidedAborted(signal);
      this.webnn?.dispose(); this.webnn = undefined;
      for (const [key, selected] of this.selections) if (selected.backend.kind === 'webnn') this.selections.delete(key);
      this.gpuSelections.clear();
      this.probed.delete('webnn:native'); this.probed.delete('webnn:2x');
      return fallback(`WebNN probe or transfer failed: ${errorText(error)} Using WebGPU.`);
    }
  }

  private runGpuTile(
    selection: Selection, input: GuidedGpuTensor, output: GuidedGpuTensor, tile: GuidedTile,
    mode: GuidedReconstructionMode, signal: AbortSignal
  ): Promise<void> {
    return selection.backend.kind === 'webnn'
      ? (selection.backend as GuidedWebNnBackend).inferGpuTile(input, output, tile, mode, this.device, this.gpu!, signal)
      : this.gpu!.inferGpuTile(input, output, tile, mode, signal);
  }

  private async selectGpu(
    input: GuidedGpuTensor, output: GuidedGpuTensor, tile: GuidedTile, mode: GuidedReconstructionMode, signal: AbortSignal
  ): Promise<Selection> {
    const existing = this.gpuSelections.get(mode);
    if (existing !== undefined) return existing;
    const fallback = (reason?: string): Selection => {
      const value: Selection = {backend: this.gpu!, ...(reason === undefined ? {} : {fallbackReason: reason})};
      this.gpuSelections.set(mode, value); return value;
    };
    if (this.requested === 'webgpu') return fallback();
    if (this.environment === undefined) return fallback('WebNN is not exposed; retained WebGPU without downloading the frame.');
    try {
      this.webnn ??= new GuidedWebNnBackend(this.environment, this.model!, this.requested === 'webnn-npu', this.timeoutMs);
      await this.webnn.assertGpuInterop(signal);
      const candidate: Selection = {backend: this.webnn};
      const key = `webnn-gpu:${mode}`;
      if (!this.probed.has(key)) {
        const source = probeInput();
        const probe = this.gpu!.createInput(source);
        const result = this.gpu!.createOutput(probe, mode);
        try {
          await this.runGpuTile(candidate, probe, result,
            {x: 0, y: 0, inputX: 0, inputY: 0, width: 8, height: 8, inputSize: 8, halo: 0}, mode, signal);
          const readback = await this.gpu!.readProbe(result, signal);
          assertGuidedParity(readback.data, runGuidedGraphCpu(this.model!.graph, this.model!.weights, source, mode).data);
          this.probed.add(key);
        } finally {this.gpu!.releaseOutput(probe); this.gpu!.releaseOutput(result);}
      }
      const baseline: Selection = {backend: this.gpu!};
      await this.runGpuTile(baseline, input, output, tile, mode, signal);
      await this.runGpuTile(candidate, input, output, tile, mode, signal);
      const timings: Record<GuidedInferenceBackend, number[]> = {webgpu: [], webnn: []};
      for (let iteration = 0; iteration < 3; iteration++) {
        for (const selected of iteration % 2 ? [candidate, baseline] : [baseline, candidate]) {
          const start = performance.now();
          await this.runGpuTile(selected, input, output, tile, mode, signal);
          timings[selected.backend.kind].push(performance.now() - start);
        }
      }
      const benchmarkMilliseconds = {webgpu: median(timings.webgpu), webnn: median(timings.webnn)};
      const useWebnn = this.requested !== 'auto' || benchmarkMilliseconds.webnn < benchmarkMilliseconds.webgpu * .9;
      const selected: Selection = {backend: useWebnn ? this.webnn : this.gpu!, benchmarkMilliseconds,
        ...(!useWebnn ? {fallbackReason: 'WebNN including GPU tensor transfers did not beat WebGPU by 10%; retained WebGPU.'} : {})};
      this.gpuSelections.set(mode, selected); return selected;
    } catch (error) {
      throwIfGuidedAborted(signal);
      this.webnn?.dispose(); this.webnn = undefined; this.selections.clear(); this.gpuSelections.clear();
      for (const key of this.probed) if (key.startsWith('webnn')) this.probed.delete(key);
      return fallback(`WebNN GPU interoperability probe failed: ${errorText(error)} Retained WebGPU without downloading the frame.`);
    }
  }

  private createReport(selection: Selection, start: number, tileCount: number, hostTransfers: boolean): GuidedInferenceReport {
    const accelerated = selection.backend.kind === 'webnn' ? this.webnn?.accelerated : undefined;
    const reportedDevices = selection.backend.kind === 'webnn' ? this.webnn?.reportedDevices : undefined;
    return Object.freeze({requestedBackend: this.requested, executedBackend: selection.backend.kind,
      hardwareUnits: 'unverified', milliseconds: performance.now() - start, tileCount, hostTransfers,
      ...(selection.fallbackReason === undefined ? {} : {fallbackReason: selection.fallbackReason}),
      ...(selection.benchmarkMilliseconds === undefined ? {} : {benchmarkMilliseconds: selection.benchmarkMilliseconds}),
      ...(accelerated === undefined ? {} : {webnnAccelerated: accelerated}),
      ...(reportedDevices === undefined ? {} : {reportedDevices: Object.freeze([...reportedDevices])})});
  }

  /** New jobs supersede pending work; input storage must remain unchanged until the promise settles. */
  infer(input: GuidedTensor, mode: GuidedReconstructionMode, options: GuidedInferenceOptions = {}): Promise<GuidedInferenceResult> {
    return this.enqueue(async signal => {
      const start = performance.now();
      this.validateInput(input, mode);
      if (!input.data.every(Number.isFinite)) throw new Error('Reconstruction input contains non-finite features.');
      const tiles = planGuidedTiles(input.width, input.height, this.coreSize);
      const channels = mode === 'native' ? 4 : 16;
      const output: GuidedTensor = {...input, channels, data: new Float32Array(channels * input.width * input.height)};
      options.onProgress?.({phase: 'probing', completedTiles: 0, totalTiles: tiles.length});
      let selection = await this.select(extractGuidedTile(input, tiles[0]!), mode, signal);
      for (let index = 0; index < tiles.length; index++) {
        throwIfGuidedAborted(signal);
        const tile = tiles[index]!;
        const extracted = extractGuidedTile(input, tile);
        let result: GuidedTensor;
        try {result = await selection.backend.inferTile(extracted, mode, signal);}
        catch (error) {
          throwIfGuidedAborted(signal);
          if (selection.backend.kind !== 'webnn') throw error;
          this.webnn?.dispose(); this.webnn = undefined;
          selection = {backend: this.gpu!, fallbackReason: `WebNN inference failed: ${errorText(error)} Recomputed every tile with WebGPU.`};
          this.selections.clear(); this.selections.set(mode, selection); this.gpuSelections.clear();
          this.probed.delete('webnn:native'); this.probed.delete('webnn:2x');
          index = -1;
          continue;
        }
        if (!result.data.every(Number.isFinite)) throw new Error('Reconstruction produced non-finite values.');
        copyTile(result, output, tile);
        options.onProgress?.({phase: 'restoring', completedTiles: index + 1, totalTiles: tiles.length});
      }
      throwIfGuidedAborted(signal);
      this.report = this.createReport(selection, start, tiles.length, true); this.error = undefined;
      return {tensor: output, report: this.report};
    }, options.signal);
  }

  private validateInput(input: {channels: number; width: number; height: number}, mode: GuidedReconstructionMode): void {
    if (this.model === undefined || this.gpu === undefined) throw new Error('A quality-verified guided model must be loaded before inference.');
    if (mode !== 'native' && mode !== '2x') throw new Error('Unknown reconstruction mode.');
    if (input.channels !== 16 || ![input.width, input.height].every(value => Number.isSafeInteger(value) && value > 0 && value <= 16_384)) {
      throw new RangeError('Reconstruction requires bounded 16-channel image features.');
    }
    if (input.width * input.height * 16 * 4 > this.device.limits.maxStorageBufferBindingSize) {
      throw new RangeError('Reconstruction image exceeds the selected GPU storage limit; use an explicitly smaller render resolution.');
    }
    if ('data' in input) assertGuidedTensor(input as GuidedTensor);
  }

  /** The caller owns the input buffer and must release the returned buffer after final compositing. */
  inferGpu(input: GuidedGpuTensor, mode: GuidedReconstructionMode, options: GuidedInferenceOptions = {}): Promise<GuidedGpuInferenceResult> {
    return this.enqueue(async signal => {
      const start = performance.now();
      this.validateInput(input, mode);
      if (!(input.buffer.usage & GPUBufferUsage.STORAGE)
          || input.buffer.size < input.channels * input.width * input.height * 4) {
        throw new Error('GPU reconstruction input must be a correctly sized storage buffer.');
      }
      const tiles = planGuidedTiles(input.width, input.height, this.coreSize);
      options.onProgress?.({phase: 'probing', completedTiles: 0, totalTiles: tiles.length});
      await this.probe(this.gpu!, mode, signal);
      const output = this.gpu!.createOutput(input, mode);
      let success = false;
      try {
        let selection = await this.selectGpu(input, output, tiles[0]!, mode, signal);
        for (let index = 0; index < tiles.length; index++) {
          throwIfGuidedAborted(signal);
          try {await this.runGpuTile(selection, input, output, tiles[index]!, mode, signal);}
          catch (error) {
            throwIfGuidedAborted(signal);
            if (selection.backend.kind !== 'webnn') throw error;
            this.webnn?.dispose(); this.webnn = undefined;
            selection = {backend: this.gpu!, fallbackReason: `WebNN GPU inference failed: ${errorText(error)} Recomputed every tile with WebGPU.`};
            this.selections.clear(); this.gpuSelections.clear(); this.gpuSelections.set(mode, selection);
            for (const key of this.probed) if (key.startsWith('webnn')) this.probed.delete(key);
            index = -1; continue;
          }
          options.onProgress?.({phase: 'restoring', completedTiles: index + 1, totalTiles: tiles.length});
        }
        throwIfGuidedAborted(signal);
        this.report = this.createReport(selection, start, tiles.length, false); this.error = undefined;
        const backend = this.gpu!;
        success = true;
        return {tensor: output, report: this.report, release: () => backend.releaseOutput(output)};
      } finally {
        if (!success) this.gpu?.releaseOutput(output);
      }
    }, options.signal);
  }

  cancel(): void {this.active?.abort();}

  dispose(): void {
    this.disposed = true; this.cancel(); this.gpu?.dispose(); this.webnn?.dispose();
    this.model = undefined; this.selections.clear(); this.gpuSelections.clear(); this.probed.clear();
  }
}
