import {LIGHT_FLAG_CAST_SHADOW, LIGHT_GPU_STRIDE} from './scene/packing';
import {MAX_WIND_DISPLACEMENT} from './scene/limits';
import type {Aabb, Vec3} from './scene/types';

export type RasterShadowResolution = 0 | 1024 | 2048 | 4096;
export const RASTER_SHADOW_UNIFORM_BYTES = 80;

export function rasterShadowParameters(bounds: Aabb | undefined, lights: ArrayBuffer, resolution: RasterShadowResolution): Float32Array {
  const result = new Float32Array(RASTER_SHADOW_UNIFORM_BYTES / 4);
  result[0] = result[5] = result[10] = result[15] = 1;
  if (!bounds || resolution === 0) return result;
  if (![1024, 2048, 4096].includes(resolution)) throw new RangeError('Unsupported raster shadow resolution.');
  if (lights.byteLength % LIGHT_GPU_STRIDE !== 0) throw new RangeError('Invalid packed light buffer.');
  const values = new DataView(lights);
  let index = -1;
  for (let offset = 0; offset < lights.byteLength; offset += LIGHT_GPU_STRIDE) {
    if (values.getUint32(offset + 12, true) !== 0
      && (values.getUint32(offset + 40, true) & LIGHT_FLAG_CAST_SHADOW) !== 0) {
      index = offset / LIGHT_GPU_STRIDE;
      break;
    }
  }
  if (index < 0) return result;
  const direction = [0, 1, 2].map(axis => values.getFloat32(index * LIGHT_GPU_STRIDE + axis * 4, true));
  const length = Math.hypot(...direction);
  if (!Number.isFinite(length) || length < 1e-8) throw new RangeError('Invalid shadow light direction.');
  const forward = direction.map(value => value / length) as [number, number, number];
  const axis: Vec3 = Math.abs(forward[1]) > 0.95 ? [0, 0, 1] : [0, 1, 0];
  const right = cross(axis, forward);
  const rightLength = Math.hypot(...right);
  for (let i = 0; i < 3; i++) right[i] = right[i]! / rightLength;
  const up = cross(forward, right);
  const center: [number, number, number] = [0, 0, 0];
  const extent: [number, number, number] = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    const low = bounds.min[i]!;
    const high = bounds.max[i]!;
    if (!Number.isFinite(low) || !Number.isFinite(high) || low > high) throw new RangeError('Invalid shadow scene bounds.');
    center[i] = (low + high) * 0.5;
    extent[i] = Math.max(0.01, (high - low) * 0.5) + MAX_WIND_DISPLACEMENT;
  }
  const projectionExtent = (basis: Vec3): number => Math.abs(basis[0]) * extent[0]
    + Math.abs(basis[1]) * extent[1] + Math.abs(basis[2]) * extent[2] + 0.01;
  const halfX = projectionExtent(right);
  const halfY = projectionExtent(up);
  const depth = projectionExtent(forward) * 2;
  const stepX = 2 * halfX / resolution;
  const stepY = 2 * halfY / resolution;
  const snappedX = Math.round(dot(right, center) / stepX) * stepX;
  const snappedY = Math.round(dot(up, center) / stepY) * stepY;
  for (let i = 0; i < 3; i++) {
    result[i * 4] = right[i]! / halfX;
    result[i * 4 + 1] = up[i]! / halfY;
    result[i * 4 + 2] = forward[i]! / depth;
  }
  result[12] = -snappedX / halfX;
  result[13] = -snappedY / halfY;
  result[14] = 0.5 - dot(forward, center) / depth;
  result[16] = 1;
  result[17] = index;
  result[18] = 1 / resolution;
  result[19] = Math.max(0.00002, Math.max(stepX, stepY) * 0.15 / depth);
  if (result.some(value => !Number.isFinite(value))) throw new RangeError('Shadow projection exceeds finite GPU range.');
  return result;
}

function dot(a: Vec3, b: Vec3): number {return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];}
function cross(a: Vec3, b: Vec3): [number, number, number] {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
