import type {MeshDefinition} from '../scene';
import {resolveModelBudget} from './budget';
import type {ObjMaterialGroup, ObjParseOptions, ObjParseResult} from './types';

interface Corner {
  position: number;
  texture: number | null;
  normal: number | null;
}

interface ParseState {
  objectName: string | null;
  groupName: string | null;
  materialName: string | null;
  smoothingGroup: string | null;
}

interface BuiltVertex {
  position: readonly [number, number, number];
  texture: readonly [number, number] | null;
  explicitNormal: readonly [number, number, number] | null;
  accumulatedNormal: [number, number, number];
}

function parseFinite(token: string | undefined, label: string): number {
  if (token === undefined || token.trim() === '') throw new SyntaxError(`${label} is missing`);
  const value = Number(token);
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value))) throw new SyntaxError(`${label} must be a finite 32-bit number`);
  return value;
}

function resolveIndex(token: string | undefined, length: number, label: string): number {
  if (token === undefined || token === '') throw new SyntaxError(`${label} is missing`);
  const raw = Number(token);
  if (!Number.isSafeInteger(raw) || raw === 0) throw new SyntaxError(`${label} must be a non-zero integer`);
  const resolved = raw > 0 ? raw - 1 : length + raw;
  if (resolved < 0 || resolved >= length) throw new RangeError(`${label} ${raw} is outside the available range of ${length} entries`);
  return resolved;
}

function sameState(a: ObjMaterialGroup, b: ParseState): boolean {
  return a.objectName === b.objectName && a.groupName === b.groupName && a.materialName === b.materialName && a.smoothingGroup === b.smoothingGroup;
}

function directiveName(line: string): string {
  const split = line.search(/\s/);
  return split < 0 ? line : line.slice(0, split);
}

export function parseObj(source: string, options: ObjParseOptions = {}): ObjParseResult {
  if (typeof source !== 'string') throw new TypeError('OBJ source must be a string');
  const budget = resolveModelBudget(options.budget);
  const sourceBytes = new TextEncoder().encode(source).byteLength;
  if (sourceBytes > budget.maxSourceBytes) {
    throw new RangeError(`OBJ source is ${sourceBytes} bytes, exceeding the budget of ${budget.maxSourceBytes}`);
  }
  const scale = options.scale ?? 1;
  if (!Number.isFinite(scale) || !Number.isFinite(Math.fround(scale)) || scale === 0) {
    throw new RangeError('OBJ scale must be a finite non-zero 32-bit number');
  }
  const flipV = options.flipV ?? false;
  if (typeof flipV !== 'boolean') throw new TypeError('OBJ flipV must be a boolean');

  const sourcePositions: Array<readonly [number, number, number]> = [];
  const sourceTextures: Array<readonly [number, number]> = [];
  const sourceNormals: Array<readonly [number, number, number]> = [];
  const vertices: BuiltVertex[] = [];
  const indices: number[] = [];
  const vertexMap = new Map<string, number>();
  const groups: ObjMaterialGroup[] = [];
  const materialLibraries: string[] = [];
  const ignoredDirectives = new Set<string>();
  const state: ParseState = {objectName: null, groupName: null, materialName: null, smoothingGroup: null};
  let faceSerial = 0;

  const logicalSource = source.replace(/\\\r?\n/g, ' ');
  const lines = logicalSource.split(/\r?\n/);
  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const withoutComment = (lines[lineIndex] ?? '').split('#', 1)[0]?.trim() ?? '';
    if (withoutComment === '') continue;
    const tokens = withoutComment.split(/\s+/);
    const directive = tokens.shift() ?? '';
    const lineLabel = `OBJ line ${lineIndex + 1}`;
    if (directive === 'v') {
      if (sourcePositions.length >= budget.maxVertices) {
        throw new RangeError(`${lineLabel} would exceed the OBJ source-position budget of ${budget.maxVertices}`);
      }
      sourcePositions.push([
        parseFinite(tokens[0], `${lineLabel} vertex x`) * scale,
        parseFinite(tokens[1], `${lineLabel} vertex y`) * scale,
        parseFinite(tokens[2], `${lineLabel} vertex z`) * scale
      ]);
      continue;
    }
    if (directive === 'vt') {
      if (sourceTextures.length >= budget.maxVertices) {
        throw new RangeError(`${lineLabel} would exceed the OBJ texture-coordinate budget of ${budget.maxVertices}`);
      }
      const u = parseFinite(tokens[0], `${lineLabel} texture u`);
      const v = tokens[1] === undefined ? 0 : parseFinite(tokens[1], `${lineLabel} texture v`);
      sourceTextures.push([u, flipV ? 1 - v : v]);
      continue;
    }
    if (directive === 'vn') {
      if (sourceNormals.length >= budget.maxVertices) {
        throw new RangeError(`${lineLabel} would exceed the OBJ source-normal budget of ${budget.maxVertices}`);
      }
      const x = parseFinite(tokens[0], `${lineLabel} normal x`);
      const y = parseFinite(tokens[1], `${lineLabel} normal y`);
      const z = parseFinite(tokens[2], `${lineLabel} normal z`);
      const length = Math.hypot(x, y, z);
      if (length <= 1e-10) throw new RangeError(`${lineLabel} normal must have non-zero length`);
      sourceNormals.push([x / length, y / length, z / length]);
      continue;
    }
    if (directive === 'o') {
      state.objectName = tokens.join(' ') || null;
      continue;
    }
    if (directive === 'g') {
      state.groupName = tokens.join(' ') || null;
      continue;
    }
    if (directive === 'usemtl') {
      state.materialName = tokens.join(' ') || null;
      continue;
    }
    if (directive === 'mtllib') {
      const library = tokens.join(' ');
      if (library !== '') materialLibraries.push(library);
      continue;
    }
    if (directive === 's') {
      const value = tokens.join(' ').toLowerCase();
      state.smoothingGroup = value === '' || value === 'off' || value === '0' ? null : value;
      continue;
    }
    if (directive !== 'f') {
      ignoredDirectives.add(directiveName(withoutComment));
      continue;
    }

    if (tokens.length < 3) throw new SyntaxError(`${lineLabel} face must contain at least three vertices`);
    if (tokens.length > budget.maxPolygonVertices) {
      throw new RangeError(`${lineLabel} face has ${tokens.length} vertices, exceeding the polygon budget of ${budget.maxPolygonVertices}`);
    }
    const addedTriangles = tokens.length - 2;
    if (indices.length / 3 + addedTriangles > budget.maxTriangles) {
      throw new RangeError(`${lineLabel} would exceed the OBJ triangle budget of ${budget.maxTriangles}`);
    }
    const corners: Corner[] = tokens.map((token, cornerIndex) => {
      const fields = token.split('/');
      if (fields.length > 3) throw new SyntaxError(`${lineLabel} face corner ${cornerIndex + 1} has too many slash-separated fields`);
      return {
        position: resolveIndex(fields[0], sourcePositions.length, `${lineLabel} position index`),
        texture: fields[1] ? resolveIndex(fields[1], sourceTextures.length, `${lineLabel} texture index`) : null,
        normal: fields[2] ? resolveIndex(fields[2], sourceNormals.length, `${lineLabel} normal index`) : null
      };
    });

    for (let triangleInFace = 0; triangleInFace < corners.length - 2; triangleInFace += 1) {
      const triangleCorners = [corners[0], corners[triangleInFace + 1], corners[triangleInFace + 2]] as const;
      const triangleIndices: number[] = [];
      for (let cornerIndex = 0; cornerIndex < 3; cornerIndex += 1) {
        const corner = triangleCorners[cornerIndex];
        if (!corner) throw new Error('Internal OBJ corner invariant failed');
        const normalScope = corner.normal === null
          ? state.smoothingGroup === null ? `flat:${faceSerial}:${triangleInFace}` : `smooth:${state.smoothingGroup}`
          : `normal:${corner.normal}`;
        const key = `${corner.position}/${corner.texture ?? ''}/${normalScope}`;
        let outputIndex = vertexMap.get(key);
        if (outputIndex === undefined) {
          if (vertices.length >= budget.maxVertices) throw new RangeError(`${lineLabel} would exceed the OBJ vertex budget of ${budget.maxVertices}`);
          const position = sourcePositions[corner.position];
          if (!position) throw new Error('Internal OBJ position invariant failed');
          const texture = corner.texture === null ? null : sourceTextures[corner.texture] ?? null;
          const explicitNormal = corner.normal === null ? null : sourceNormals[corner.normal] ?? null;
          outputIndex = vertices.length;
          vertices.push({position, texture, explicitNormal, accumulatedNormal: [0, 0, 0]});
          vertexMap.set(key, outputIndex);
        }
        triangleIndices.push(outputIndex);
      }
      const ia = triangleIndices[0];
      const ib = triangleIndices[1];
      const ic = triangleIndices[2];
      if (ia === undefined || ib === undefined || ic === undefined) throw new Error('Internal OBJ triangle invariant failed');
      const a = vertices[ia]?.position;
      const b = vertices[ib]?.position;
      const c = vertices[ic]?.position;
      if (!a || !b || !c) throw new Error('Internal OBJ vertex invariant failed');
      const e1x = b[0] - a[0];
      const e1y = b[1] - a[1];
      const e1z = b[2] - a[2];
      const e2x = c[0] - a[0];
      const e2y = c[1] - a[1];
      const e2z = c[2] - a[2];
      const nx = e1y * e2z - e1z * e2y;
      const ny = e1z * e2x - e1x * e2z;
      const nz = e1x * e2y - e1y * e2x;
      if (nx * nx + ny * ny + nz * nz <= 1e-20) throw new RangeError(`${lineLabel} produces a degenerate triangle`);
      for (const outputIndex of triangleIndices) {
        const output = vertices[outputIndex];
        if (!output) throw new Error('Internal OBJ output invariant failed');
        if (output.explicitNormal === null) {
          output.accumulatedNormal[0] += nx;
          output.accumulatedNormal[1] += ny;
          output.accumulatedNormal[2] += nz;
        }
      }
      indices.push(ia, ib, ic);
      const triangleIndex = indices.length / 3 - 1;
      const previous = groups[groups.length - 1];
      if (previous && sameState(previous, state) && previous.firstTriangle + previous.triangleCount === triangleIndex) {
        groups[groups.length - 1] = {...previous, triangleCount: previous.triangleCount + 1};
      } else {
        groups.push({...state, firstTriangle: triangleIndex, triangleCount: 1});
      }
    }
    faceSerial += 1;
  }

  if (indices.length === 0) throw new RangeError('OBJ source does not contain any renderable faces');
  const positions = new Float32Array(vertices.length * 3);
  const normals = new Float32Array(vertices.length * 3);
  const hasAnyTexture = vertices.some((vertex) => vertex.texture !== null);
  const hasCompleteTextureCoordinates = hasAnyTexture && vertices.every((vertex) => vertex.texture !== null);
  const textureCoordinates = hasAnyTexture ? new Float32Array(vertices.length * 2) : null;
  for (let index = 0; index < vertices.length; index += 1) {
    const vertex = vertices[index];
    if (!vertex) throw new Error('Internal OBJ vertex invariant failed');
    positions.set(vertex.position, index * 3);
    const normal = vertex.explicitNormal ?? vertex.accumulatedNormal;
    const normalLength = Math.hypot(normal[0], normal[1], normal[2]);
    if (normalLength <= 1e-10) throw new RangeError(`OBJ output vertex ${index} has no usable normal`);
    normals[index * 3] = normal[0] / normalLength;
    normals[index * 3 + 1] = normal[1] / normalLength;
    normals[index * 3 + 2] = normal[2] / normalLength;
    if (textureCoordinates && vertex.texture) textureCoordinates.set(vertex.texture, index * 2);
  }
  const mesh: MeshDefinition = hasCompleteTextureCoordinates && textureCoordinates !== null
    ? {positions, indices: Uint32Array.from(indices), normals, uvs: textureCoordinates}
    : {positions, indices: Uint32Array.from(indices), normals};
  return {
    mesh,
    textureCoordinates,
    hasCompleteTextureCoordinates,
    groups,
    materialLibraries,
    ignoredDirectives: [...ignoredDirectives].sort(),
    sourcePositionCount: sourcePositions.length,
    sourceNormalCount: sourceNormals.length,
    sourceTextureCoordinateCount: sourceTextures.length
  };
}
