import {DEFAULT_CAMERA, type CameraSettings, type Vec3} from '../contracts';

export interface FreeCameraRenderer {
  getOutputCanvas(): HTMLCanvasElement | null;
  setCamera(camera: CameraSettings): void;
  getCamera?(): CameraSettings;
}

export interface FreeCameraConfig {
  /** Normal translation speed in world units per second. */
  moveSpeed: number;
  /** Translation speed while Shift is held, in world units per second. */
  sprintSpeed: number;
  /** Mouse-look sensitivity in degrees per CSS pixel. */
  lookSensitivity: number;
  /** Whether either Shift key enables sprinting. */
  shiftSprint: boolean;
  /** Pointer button used to begin a look drag. Zero is the primary button. */
  dragButton: number;
  /** Maximum movement delta accepted from one animation frame. */
  maxDeltaSeconds: number;
}

export interface GroundedWalkingConfig {
  /** Standing camera height above the supporting floor in world units. */
  eyeHeight: number;
  /** Horizontal collision radius in world units. */
  radius: number;
  /** Downward acceleration in world units per second squared. */
  gravity: number;
  /** Normal planar walking speed in world units per second. */
  walkSpeed: number;
  /** Planar walking speed while Shift is held. */
  sprintSpeed: number;
  /** Initial upward velocity applied by an edge-triggered Space press. */
  jumpSpeed: number;
  /** Maximum obstacle height that can be stepped over while grounded. */
  stepHeight: number;
}

export interface WalkingRoomBounds {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
  floorY: number;
  ceilingY: number;
}

export interface WalkingObstacle {
  readonly handle: string;
  readonly min: Vec3;
  readonly max: Vec3;
}

export interface FreeCameraControllerOptions extends Partial<FreeCameraConfig> {
  initialCamera?: CameraSettings;
  groundedWalking?: Partial<GroundedWalkingConfig>;
  walkingBounds?: WalkingRoomBounds;
  pointerTarget?: EventTarget;
  keyTarget?: EventTarget;
  visibilityTarget?: EventTarget;
  requestAnimationFrame?: (callback: FrameRequestCallback) => number;
  cancelAnimationFrame?: (handle: number) => void;
  /** Disable only when another deterministic loop calls updateAt or step. */
  autoFrameLoop?: boolean;
}

export interface FreeCameraStatus {
  enabled: boolean;
  destroyed: boolean;
  dragging: boolean;
  moving: boolean;
  sprinting: boolean;
  position: Vec3;
  target: Vec3;
  yawDegrees: number;
  pitchDegrees: number;
  lastDeltaSeconds: number;
  pressedKeys: readonly string[];
  config: Readonly<FreeCameraConfig>;
  walking: GroundedWalkingStatus;
}

export interface GroundedWalkingStatus {
  enabled: boolean;
  grounded: boolean;
  crouching: boolean;
  verticalVelocity: number;
  currentEyeHeight: number;
  obstacleCount: number;
  config: Readonly<GroundedWalkingConfig>;
  bounds: Readonly<WalkingRoomBounds>;
}

const DEFAULT_CONFIG: Readonly<FreeCameraConfig> = Object.freeze({
  moveSpeed: 4.5,
  sprintSpeed: 10,
  lookSensitivity: 0.12,
  shiftSprint: true,
  dragButton: 0,
  maxDeltaSeconds: 0.1
});

const DEFAULT_GROUNDED_WALKING_CONFIG: Readonly<GroundedWalkingConfig> = Object.freeze({
  eyeHeight: 1.65,
  radius: 0.28,
  gravity: 18,
  walkSpeed: 4.5,
  sprintSpeed: 8.5,
  jumpSpeed: 5.5,
  stepHeight: 0.32
});

const DEFAULT_WALKING_BOUNDS: Readonly<WalkingRoomBounds> = Object.freeze({
  minX: -1_000_000,
  maxX: 1_000_000,
  minZ: -1_000_000,
  maxZ: 1_000_000,
  floorY: 0,
  ceilingY: 1_000_000
});

const MOVEMENT_KEYS = new Set([
  'KeyW',
  'KeyA',
  'KeyS',
  'KeyD',
  'Space',
  'ControlLeft',
  'ControlRight'
]);

const SPRINT_KEYS = new Set(['ShiftLeft', 'ShiftRight']);
const CROUCH_KEYS = new Set(['ControlLeft', 'ControlRight']);
const ALL_CAPTURED_KEYS = new Set([...MOVEMENT_KEYS, ...SPRINT_KEYS]);
const MIN_LOOK_DISTANCE = 0.001;
const MAX_PITCH_RADIANS = (89 * Math.PI) / 180;
const COLLISION_EPSILON = 1e-6;

interface MutableStyle {
  pointerEvents: string;
  cursor: string;
  touchAction: string;
}

interface PointerCaptureTarget extends EventTarget {
  setPointerCapture?(pointerId: number): void;
  releasePointerCapture?(pointerId: number): void;
  hasPointerCapture?(pointerId: number): boolean;
  focus?(options?: FocusOptions): void;
  style?: MutableStyle;
  ownerDocument?: Document;
}

export class FreeCameraController {
  private readonly renderer: FreeCameraRenderer;
  private readonly options: FreeCameraControllerOptions;
  private config: FreeCameraConfig;
  private groundedWalkingConfig: GroundedWalkingConfig;
  private walkingBounds: WalkingRoomBounds;
  private camera: CameraSettings;
  private yawRadians = 0;
  private pitchRadians = 0;
  private lookDistance = 1;
  private enabled = false;
  private destroyed = false;
  private dragging = false;
  private activePointerId: number | null = null;
  private pointerCaptured = false;
  private lastPointerX = 0;
  private lastPointerY = 0;
  private lastTimestampMilliseconds: number | null = null;
  private lastDeltaSeconds = 0;
  private frameHandle: number | null = null;
  private pointerTarget: PointerCaptureTarget | null = null;
  private keyTarget: EventTarget | null = null;
  private visibilityTarget: EventTarget | null = null;
  private requestFrame: ((callback: FrameRequestCallback) => number) | null = null;
  private cancelFrame: ((handle: number) => void) | null = null;
  private originalStyle: MutableStyle | null = null;
  private readonly pressedKeys = new Set<string>();
  private groundedWalkingEnabled = false;
  private grounded = false;
  private crouching = false;
  private currentEyeHeight: number;
  private verticalVelocity = 0;
  private jumpWasPressed = false;
  private nextWalkingObstacleId = 1;
  private readonly walkingObstacles = new Map<string, WalkingObstacle>();

  private readonly handleKeyDown = (rawEvent: Event): void => {
    const event = rawEvent as KeyboardEvent;
    if (!this.enabled || !ALL_CAPTURED_KEYS.has(event.code)) return;
    if (eventTargetsEditableControl(event)) {
      this.clearKeys();
      return;
    }
    this.pressedKeys.add(event.code);
    event.preventDefault();
  };

  private readonly handleKeyUp = (rawEvent: Event): void => {
    const event = rawEvent as KeyboardEvent;
    if (!ALL_CAPTURED_KEYS.has(event.code)) return;
    this.pressedKeys.delete(event.code);
    if (this.enabled && !eventTargetsEditableControl(event)) event.preventDefault();
  };

  private readonly handlePointerDown = (rawEvent: Event): void => {
    const event = rawEvent as PointerEvent;
    if (!this.enabled || event.button !== this.config.dragButton || eventTargetsEditableControl(event)) {
      return;
    }
    const pointerId = finiteNumber(event.pointerId, 1);
    this.dragging = true;
    this.activePointerId = pointerId;
    this.lastPointerX = finiteNumber(event.clientX, 0);
    this.lastPointerY = finiteNumber(event.clientY, 0);
    this.pointerCaptured = false;
    try {
      const capturePointer = this.pointerTarget?.setPointerCapture;
      if (capturePointer !== undefined && this.pointerTarget !== null) {
        capturePointer.call(this.pointerTarget, pointerId);
        this.pointerCaptured = this.pointerTarget.hasPointerCapture?.(pointerId) ?? true;
      }
    } catch {
      this.pointerCaptured = false;
    }
    if (this.pointerTarget?.style !== undefined) this.pointerTarget.style.cursor = 'grabbing';
    try {
      this.pointerTarget?.focus?.({preventScroll: true});
    } catch {
      this.pointerTarget?.focus?.();
    }
    event.preventDefault();
  };

  private readonly handlePointerMove = (rawEvent: Event): void => {
    const event = rawEvent as PointerEvent;
    if (!this.dragging || !this.matchesActivePointer(event)) return;
    if (typeof event.buttons === 'number' && event.buttons === 0) {
      this.endDrag();
      return;
    }

    const clientX = finiteNumber(event.clientX, this.lastPointerX);
    const clientY = finiteNumber(event.clientY, this.lastPointerY);
    const movementX = Number.isFinite(event.movementX)
      ? event.movementX
      : clientX - this.lastPointerX;
    const movementY = Number.isFinite(event.movementY)
      ? event.movementY
      : clientY - this.lastPointerY;
    this.lastPointerX = clientX;
    this.lastPointerY = clientY;

    if (movementX !== 0 || movementY !== 0) {
      const radiansPerPixel = (this.config.lookSensitivity * Math.PI) / 180;
      this.yawRadians = wrapRadians(this.yawRadians + movementX * radiansPerPixel);
      this.pitchRadians = clamp(
        this.pitchRadians - movementY * radiansPerPixel,
        -MAX_PITCH_RADIANS,
        MAX_PITCH_RADIANS
      );
      this.rebuildTarget();
      this.applyCamera();
    }
    event.preventDefault();
  };

  private readonly handlePointerEnd = (rawEvent: Event): void => {
    const event = rawEvent as PointerEvent;
    if (this.matchesActivePointer(event)) this.endDrag();
  };

  private readonly handlePointerLeave = (rawEvent: Event): void => {
    if (!this.dragging || !this.matchesActivePointer(rawEvent as PointerEvent)) return;
    if (!this.pointerCaptured) this.endDrag();
  };

  private readonly handleFocusLoss = (): void => {
    this.clearInput();
  };

  private readonly handleFocusIn = (event: Event): void => {
    if (eventTargetsEditableControl(event)) this.clearInput();
  };

  private readonly handleVisibilityChange = (): void => {
    const target = this.visibilityTarget as (Document & {hidden?: boolean}) | null;
    if (target?.hidden === true || target?.visibilityState === 'hidden') this.clearInput();
  };

  private readonly frameLoop = (timestampMilliseconds: number): void => {
    this.frameHandle = null;
    if (!this.enabled) return;
    this.updateAt(timestampMilliseconds);
    this.scheduleNextFrame();
  };

  constructor(renderer: FreeCameraRenderer, options: FreeCameraControllerOptions = {}) {
    this.renderer = renderer;
    this.options = options;
    this.config = sanitizeConfig(DEFAULT_CONFIG, options);
    this.groundedWalkingConfig = sanitizeGroundedWalkingConfig(
      DEFAULT_GROUNDED_WALKING_CONFIG,
      options.groundedWalking ?? {}
    );
    this.walkingBounds = sanitizeWalkingBounds(options.walkingBounds ?? DEFAULT_WALKING_BOUNDS);
    validateWalkingSpace(this.groundedWalkingConfig, this.walkingBounds);
    this.currentEyeHeight = this.groundedWalkingConfig.eyeHeight;
    const rendererCamera = renderer.getCamera?.();
    this.camera = cloneAndValidateCamera(options.initialCamera ?? rendererCamera ?? DEFAULT_CAMERA);
    this.updateOrientationFromCamera();
  }

  enable(): void {
    this.assertNotDestroyed();
    if (this.enabled) return;

    const outputCanvas = this.renderer.getOutputCanvas();
    const pointerTarget = (this.options.pointerTarget ?? outputCanvas) as PointerCaptureTarget | null;
    if (pointerTarget === null) {
      throw new Error('Free camera controls require an initialized renderer output canvas.');
    }
    const ownerDocument = pointerTarget.ownerDocument ?? outputCanvas?.ownerDocument;
    const ownerWindow = ownerDocument?.defaultView ?? null;
    const keyTarget = this.options.keyTarget ?? ownerWindow;
    if (keyTarget === null) {
      throw new Error('Free camera controls require a browser window or an injected key target.');
    }

    this.pointerTarget = pointerTarget;
    this.keyTarget = keyTarget;
    this.visibilityTarget = this.options.visibilityTarget ?? ownerDocument ?? null;
    this.requestFrame = this.options.requestAnimationFrame
      ?? ownerWindow?.requestAnimationFrame.bind(ownerWindow)
      ?? null;
    this.cancelFrame = this.options.cancelAnimationFrame
      ?? ownerWindow?.cancelAnimationFrame.bind(ownerWindow)
      ?? null;

    this.installListeners();
    this.activatePointerSurface();
    this.enabled = true;
    this.lastTimestampMilliseconds = null;
    this.lastDeltaSeconds = 0;
    if (this.groundedWalkingEnabled && this.reconcileWalkingPosition()) this.applyCamera();
    if (this.options.autoFrameLoop !== false) this.scheduleNextFrame();
  }

  disable(): void {
    if (!this.enabled && this.pointerTarget === null) return;
    this.enabled = false;
    this.cancelScheduledFrame();
    this.clearInput();
    this.removeListeners();
    this.restorePointerSurface();
    this.pointerTarget = null;
    this.keyTarget = null;
    this.visibilityTarget = null;
    this.requestFrame = null;
    this.cancelFrame = null;
    this.lastTimestampMilliseconds = null;
    this.lastDeltaSeconds = 0;
  }

  destroy(): void {
    if (this.destroyed) return;
    this.disable();
    this.destroyed = true;
  }

  configure(patch: Partial<FreeCameraConfig>): void {
    this.assertNotDestroyed();
    this.config = sanitizeConfig(this.config, patch);
  }

  setGroundedWalkingEnabled(enabled: boolean): void {
    this.assertNotDestroyed();
    if (this.groundedWalkingEnabled === enabled) return;
    this.groundedWalkingEnabled = enabled;
    this.verticalVelocity = 0;
    this.grounded = false;
    this.crouching = false;
    this.currentEyeHeight = this.groundedWalkingConfig.eyeHeight;
    this.jumpWasPressed = this.pressedKeys.has('Space');
    if (enabled && this.reconcileWalkingPosition() && this.enabled) this.applyCamera();
  }

  configureGroundedWalking(patch: Partial<GroundedWalkingConfig>): void {
    this.assertNotDestroyed();
    const previousEyeHeight = this.currentEyeHeight;
    const next = sanitizeGroundedWalkingConfig(this.groundedWalkingConfig, patch);
    validateWalkingSpace(next, this.walkingBounds);
    this.groundedWalkingConfig = next;
    this.currentEyeHeight = this.crouching ? crouchedEyeHeight(next) : next.eyeHeight;
    if (this.groundedWalkingEnabled) {
      const feetY = this.camera.position[1] - previousEyeHeight;
      this.translateCamera([0, feetY + this.currentEyeHeight - this.camera.position[1], 0]);
      this.reconcileWalkingPosition();
      if (this.enabled) this.applyCamera();
    }
  }

  setWalkingRoomBounds(bounds: WalkingRoomBounds): void {
    this.assertNotDestroyed();
    const next = sanitizeWalkingBounds(bounds);
    validateWalkingSpace(this.groundedWalkingConfig, next);
    this.walkingBounds = next;
    if (this.groundedWalkingEnabled && this.reconcileWalkingPosition() && this.enabled) {
      this.applyCamera();
    }
  }

  addWalkingObstacle(minimum: Vec3, maximum: Vec3): string {
    this.assertNotDestroyed();
    const min = finiteVec3(minimum, 'Walking obstacle minimum');
    const max = finiteVec3(maximum, 'Walking obstacle maximum');
    if (min.some((value, axis) => value >= max[axis]!)) {
      throw new RangeError('Walking obstacle minimum values must be less than maximum values.');
    }
    const handle = `walking-obstacle:${this.nextWalkingObstacleId++}`;
    this.walkingObstacles.set(handle, {handle, min, max});
    if (this.groundedWalkingEnabled && this.reconcileWalkingPosition() && this.enabled) {
      this.applyCamera();
    }
    return handle;
  }

  removeWalkingObstacle(handle: string): void {
    this.assertNotDestroyed();
    if (!this.walkingObstacles.delete(handle)) {
      throw new RangeError(`Unknown or stale walking obstacle handle: ${handle}`);
    }
  }

  clearWalkingObstacles(): void {
    this.assertNotDestroyed();
    this.walkingObstacles.clear();
  }

  getGroundedWalkingStatus(): GroundedWalkingStatus {
    return {
      enabled: this.groundedWalkingEnabled,
      grounded: this.grounded,
      crouching: this.crouching,
      verticalVelocity: this.verticalVelocity,
      currentEyeHeight: this.currentEyeHeight,
      obstacleCount: this.walkingObstacles.size,
      config: {...this.groundedWalkingConfig},
      bounds: {...this.walkingBounds}
    };
  }

  getCamera(): CameraSettings {
    return cloneCamera(this.camera);
  }

  setCamera(camera: CameraSettings): void {
    this.assertNotDestroyed();
    this.camera = cloneAndValidateCamera(camera);
    this.updateOrientationFromCamera();
    this.verticalVelocity = 0;
    this.grounded = false;
    if (this.groundedWalkingEnabled) this.reconcileWalkingPosition();
    this.applyCamera();
  }

  /**
   * Advances keyboard motion using an explicit elapsed time. Movement deltas are
   * clamped to avoid a large jump after a suspended/backgrounded browser frame.
   */
  step(deltaSeconds: number): boolean {
    this.assertNotDestroyed();
    if (!this.enabled) return false;
    if (!Number.isFinite(deltaSeconds) || deltaSeconds < 0) {
      throw new RangeError('Camera delta time must be a finite non-negative number.');
    }
    const delta = Math.min(deltaSeconds, this.config.maxDeltaSeconds);
    this.lastDeltaSeconds = delta;
    if (delta === 0) return false;

    if (this.groundedWalkingEnabled) return this.stepGroundedWalking(delta);

    const direction = this.movementDirection();
    if (direction === null) return false;
    const sprinting = this.config.shiftSprint && this.hasAnyPressed(SPRINT_KEYS);
    const distance = (sprinting ? this.config.sprintSpeed : this.config.moveSpeed) * delta;
    const displacement = scale(direction, distance);
    this.camera = {
      ...this.camera,
      position: add(this.camera.position, displacement),
      target: add(this.camera.target, displacement)
    };
    this.applyCamera();
    return true;
  }

  /** Advances movement from a monotonically increasing animation timestamp. */
  updateAt(timestampMilliseconds: number): boolean {
    this.assertNotDestroyed();
    if (!this.enabled || !Number.isFinite(timestampMilliseconds)) return false;
    const previous = this.lastTimestampMilliseconds;
    this.lastTimestampMilliseconds = timestampMilliseconds;
    if (previous === null) return false;
    return this.step(Math.max(0, timestampMilliseconds - previous) / 1000);
  }

  getStatus(): FreeCameraStatus {
    const movement = this.groundedWalkingEnabled
      ? this.planarMovementDirection()
      : this.movementDirection();
    const moving = movement !== null
      || (this.groundedWalkingEnabled && (!this.grounded || this.verticalVelocity !== 0));
    const sprinting =
      movement !== null && this.config.shiftSprint && this.hasAnyPressed(SPRINT_KEYS);
    return {
      enabled: this.enabled,
      destroyed: this.destroyed,
      dragging: this.dragging,
      moving,
      sprinting,
      position: [...this.camera.position],
      target: [...this.camera.target],
      yawDegrees: (this.yawRadians * 180) / Math.PI,
      pitchDegrees: (this.pitchRadians * 180) / Math.PI,
      lastDeltaSeconds: this.lastDeltaSeconds,
      pressedKeys: [...this.pressedKeys].sort(),
      config: {...this.config},
      walking: this.getGroundedWalkingStatus()
    };
  }

  private installListeners(): void {
    this.pointerTarget?.addEventListener('pointerdown', this.handlePointerDown);
    this.pointerTarget?.addEventListener('pointermove', this.handlePointerMove);
    this.pointerTarget?.addEventListener('pointerup', this.handlePointerEnd);
    this.pointerTarget?.addEventListener('pointercancel', this.handlePointerEnd);
    this.pointerTarget?.addEventListener('lostpointercapture', this.handlePointerEnd);
    this.pointerTarget?.addEventListener('pointerleave', this.handlePointerLeave);
    this.keyTarget?.addEventListener('keydown', this.handleKeyDown);
    this.keyTarget?.addEventListener('keyup', this.handleKeyUp);
    this.keyTarget?.addEventListener('blur', this.handleFocusLoss);
    this.keyTarget?.addEventListener('focusin', this.handleFocusIn);
    this.visibilityTarget?.addEventListener('visibilitychange', this.handleVisibilityChange);
  }

  private removeListeners(): void {
    this.pointerTarget?.removeEventListener('pointerdown', this.handlePointerDown);
    this.pointerTarget?.removeEventListener('pointermove', this.handlePointerMove);
    this.pointerTarget?.removeEventListener('pointerup', this.handlePointerEnd);
    this.pointerTarget?.removeEventListener('pointercancel', this.handlePointerEnd);
    this.pointerTarget?.removeEventListener('lostpointercapture', this.handlePointerEnd);
    this.pointerTarget?.removeEventListener('pointerleave', this.handlePointerLeave);
    this.keyTarget?.removeEventListener('keydown', this.handleKeyDown);
    this.keyTarget?.removeEventListener('keyup', this.handleKeyUp);
    this.keyTarget?.removeEventListener('blur', this.handleFocusLoss);
    this.keyTarget?.removeEventListener('focusin', this.handleFocusIn);
    this.visibilityTarget?.removeEventListener('visibilitychange', this.handleVisibilityChange);
  }

  private activatePointerSurface(): void {
    const style = this.pointerTarget?.style;
    if (style === undefined) return;
    this.originalStyle = {
      pointerEvents: style.pointerEvents,
      cursor: style.cursor,
      touchAction: style.touchAction
    };
    style.pointerEvents = 'auto';
    style.cursor = 'grab';
    style.touchAction = 'none';
  }

  private restorePointerSurface(): void {
    if (this.pointerTarget?.style !== undefined && this.originalStyle !== null) {
      Object.assign(this.pointerTarget.style, this.originalStyle);
    }
    this.originalStyle = null;
  }

  private scheduleNextFrame(): void {
    if (!this.enabled || this.requestFrame === null || this.frameHandle !== null) return;
    this.frameHandle = this.requestFrame(this.frameLoop);
  }

  private cancelScheduledFrame(): void {
    if (this.frameHandle !== null) this.cancelFrame?.(this.frameHandle);
    this.frameHandle = null;
  }

  private clearKeys(): void {
    this.pressedKeys.clear();
  }

  private clearInput(): void {
    this.clearKeys();
    this.jumpWasPressed = false;
    this.endDrag();
    this.lastTimestampMilliseconds = null;
  }

  private endDrag(): void {
    const pointerId = this.activePointerId;
    if (pointerId !== null && this.pointerCaptured) {
      try {
        this.pointerTarget?.releasePointerCapture?.(pointerId);
      } catch {
        // Losing focus or DOM removal may release capture before this cleanup runs.
      }
    }
    this.dragging = false;
    this.activePointerId = null;
    this.pointerCaptured = false;
    if (this.pointerTarget?.style !== undefined) this.pointerTarget.style.cursor = 'grab';
  }

  private matchesActivePointer(event: PointerEvent): boolean {
    return this.activePointerId !== null
      && finiteNumber(event.pointerId, this.activePointerId) === this.activePointerId;
  }

  private stepGroundedWalking(deltaSeconds: number): boolean {
    const before = this.camera.position;
    this.updateCrouch(this.hasAnyPressed(CROUCH_KEYS));

    const jumpPressed = this.pressedKeys.has('Space');
    if (jumpPressed && !this.jumpWasPressed && this.grounded && !this.crouching) {
      this.verticalVelocity = this.groundedWalkingConfig.jumpSpeed;
      this.grounded = false;
    }
    this.jumpWasPressed = jumpPressed;

    const direction = this.planarMovementDirection();
    if (direction !== null) {
      const sprinting = this.config.shiftSprint && this.hasAnyPressed(SPRINT_KEYS);
      const speed = sprinting
        ? this.groundedWalkingConfig.sprintSpeed
        : this.groundedWalkingConfig.walkSpeed;
      this.moveWalkingHorizontally(
        direction[0] * speed * deltaSeconds,
        direction[2] * speed * deltaSeconds
      );
    }

    this.verticalVelocity -= this.groundedWalkingConfig.gravity * deltaSeconds;
    this.moveWalkingVertically(this.verticalVelocity * deltaSeconds);
    const changed = !sameVec3(before, this.camera.position);
    if (changed) this.applyCamera();
    return changed;
  }

  private updateCrouch(wantsCrouch: boolean): void {
    if (wantsCrouch === this.crouching) return;
    const feetY = this.camera.position[1] - this.currentEyeHeight;
    if (wantsCrouch) {
      const nextEyeHeight = crouchedEyeHeight(this.groundedWalkingConfig);
      this.translateCamera([0, feetY + nextEyeHeight - this.camera.position[1], 0]);
      this.currentEyeHeight = nextEyeHeight;
      this.crouching = true;
      return;
    }

    const standingEyeY = feetY + this.groundedWalkingConfig.eyeHeight;
    if (!this.canOccupy(this.camera.position[0], standingEyeY, this.camera.position[2], this.groundedWalkingConfig.eyeHeight)) {
      return;
    }
    this.translateCamera([0, standingEyeY - this.camera.position[1], 0]);
    this.currentEyeHeight = this.groundedWalkingConfig.eyeHeight;
    this.crouching = false;
  }

  private moveWalkingHorizontally(deltaX: number, deltaZ: number): void {
    if (deltaX !== 0) this.moveWalkingAxis(0, deltaX);
    if (deltaZ !== 0) this.moveWalkingAxis(2, deltaZ);
  }

  private moveWalkingAxis(axis: 0 | 2, delta: number): void {
    const otherAxis = axis === 0 ? 2 : 0;
    const start = this.camera.position[axis];
    let target = start + delta;
    const radius = this.groundedWalkingConfig.radius;
    const roomMinimum = axis === 0 ? this.walkingBounds.minX : this.walkingBounds.minZ;
    const roomMaximum = axis === 0 ? this.walkingBounds.maxX : this.walkingBounds.maxZ;
    target = clamp(target, roomMinimum + radius, roomMaximum - radius);

    const contacts = [...this.walkingObstacles.values()].flatMap(obstacle => {
      const other = this.camera.position[otherAxis];
      if (
        other <= obstacle.min[otherAxis] - radius + COLLISION_EPSILON
        || other >= obstacle.max[otherAxis] + radius - COLLISION_EPSILON
      ) return [];

      const near = obstacle.min[axis] - radius;
      const far = obstacle.max[axis] + radius;
      const crossesNear = delta > 0 && start <= near + COLLISION_EPSILON && target > near;
      const crossesFar = delta < 0 && start >= far - COLLISION_EPSILON && target < far;
      if (!crossesNear && !crossesFar) return [];
      const coordinate = crossesNear ? near : far;
      return [{
        obstacle,
        coordinate,
        distance: Math.abs(coordinate - start)
      }];
    }).sort((left, right) => (
      left.distance - right.distance
      || compareObstacleGeometry(left.obstacle, right.obstacle)
    ));

    for (const contact of contacts) {
      const reachesContact = delta > 0
        ? target > contact.coordinate + COLLISION_EPSILON
        : target < contact.coordinate - COLLISION_EPSILON;
      if (!reachesContact || !this.bodyVerticallyOverlaps(contact.obstacle)) continue;
      const other = this.camera.position[otherAxis];
      if (this.tryStepOnto(contact.obstacle, axis, contact.coordinate, other)) continue;
      target = delta > 0
        ? Math.min(target, contact.coordinate)
        : Math.max(target, contact.coordinate);
    }

    const displacement: Vec3 = axis === 0 ? [target - start, 0, 0] : [0, 0, target - start];
    this.translateCamera(displacement);
  }

  private tryStepOnto(obstacle: WalkingObstacle, axis: 0 | 2, axisTarget: number, other: number): boolean {
    if (!this.grounded) return false;
    const feetY = this.camera.position[1] - this.currentEyeHeight;
    const rise = obstacle.max[1] - feetY;
    if (rise < -COLLISION_EPSILON || rise > this.groundedWalkingConfig.stepHeight + COLLISION_EPSILON) {
      return false;
    }
    const x = axis === 0 ? axisTarget : other;
    const z = axis === 2 ? axisTarget : other;
    const eyeY = obstacle.max[1] + this.currentEyeHeight;
    if (!this.canOccupy(x, eyeY, z, this.currentEyeHeight, obstacle.handle)) return false;
    this.translateCamera([0, eyeY - this.camera.position[1], 0]);
    this.verticalVelocity = 0;
    this.grounded = true;
    return true;
  }

  private moveWalkingVertically(deltaY: number): void {
    const startEyeY = this.camera.position[1];
    let targetEyeY = startEyeY + deltaY;
    const radius = this.groundedWalkingConfig.radius;

    if (deltaY <= 0) {
      const startFeetY = startEyeY - this.currentEyeHeight;
      const targetFeetY = targetEyeY - this.currentEyeHeight;
      let supportY = this.walkingBounds.floorY;
      for (const obstacle of this.walkingObstacles.values()) {
        if (!this.horizontalFootprintOverlaps(obstacle, this.camera.position[0], this.camera.position[2])) continue;
        const top = obstacle.max[1];
        if (
          top <= startFeetY + COLLISION_EPSILON
          && top >= targetFeetY - COLLISION_EPSILON
          && top > supportY
        ) supportY = top;
      }
      if (targetFeetY <= supportY + COLLISION_EPSILON) {
        targetEyeY = supportY + this.currentEyeHeight;
        this.verticalVelocity = 0;
        this.grounded = true;
      } else {
        this.grounded = false;
      }
    } else {
      const startHeadY = startEyeY + radius;
      const targetHeadY = targetEyeY + radius;
      let ceilingY = this.walkingBounds.ceilingY;
      for (const obstacle of this.walkingObstacles.values()) {
        if (!this.horizontalFootprintOverlaps(obstacle, this.camera.position[0], this.camera.position[2])) continue;
        const underside = obstacle.min[1];
        if (
          underside >= startHeadY - COLLISION_EPSILON
          && underside <= targetHeadY + COLLISION_EPSILON
          && underside < ceilingY
        ) ceilingY = underside;
      }
      if (targetHeadY >= ceilingY - COLLISION_EPSILON) {
        targetEyeY = ceilingY - radius;
        this.verticalVelocity = 0;
      }
      this.grounded = false;
    }

    this.translateCamera([0, targetEyeY - startEyeY, 0]);
  }

  private reconcileWalkingPosition(): boolean {
    const before = this.camera.position;
    const radius = this.groundedWalkingConfig.radius;
    const clampedX = clamp(
      this.camera.position[0],
      this.walkingBounds.minX + radius,
      this.walkingBounds.maxX - radius
    );
    const clampedZ = clamp(
      this.camera.position[2],
      this.walkingBounds.minZ + radius,
      this.walkingBounds.maxZ - radius
    );
    const minimumEyeY = this.walkingBounds.floorY + this.currentEyeHeight;
    const maximumEyeY = this.walkingBounds.ceilingY - radius;
    const clampedY = clamp(this.camera.position[1], minimumEyeY, maximumEyeY);
    this.translateCamera([
      clampedX - this.camera.position[0],
      clampedY - this.camera.position[1],
      clampedZ - this.camera.position[2]
    ]);

    for (let pass = 0; pass < this.walkingObstacles.size + 1; pass += 1) {
      let resolved = true;
      for (const obstacle of this.walkingObstacles.values()) {
        if (!this.bodyVerticallyOverlaps(obstacle)) continue;
        const x = this.camera.position[0];
        const z = this.camera.position[2];
        const minX = obstacle.min[0] - radius;
        const maxX = obstacle.max[0] + radius;
        const minZ = obstacle.min[2] - radius;
        const maxZ = obstacle.max[2] + radius;
        if (x <= minX || x >= maxX || z <= minZ || z >= maxZ) continue;

        const feetY = this.camera.position[1] - this.currentEyeHeight;
        const rise = obstacle.max[1] - feetY;
        if (
          rise >= -COLLISION_EPSILON
          && rise <= this.groundedWalkingConfig.stepHeight + COLLISION_EPSILON
          && this.canOccupy(x, obstacle.max[1] + this.currentEyeHeight, z, this.currentEyeHeight, obstacle.handle)
        ) {
          this.translateCamera([0, obstacle.max[1] + this.currentEyeHeight - this.camera.position[1], 0]);
          this.grounded = true;
          this.verticalVelocity = 0;
          continue;
        }

        const candidates = [
          {distance: Math.abs(x - minX), displacement: [minX - x, 0, 0] as Vec3},
          {distance: Math.abs(maxX - x), displacement: [maxX - x, 0, 0] as Vec3},
          {distance: Math.abs(z - minZ), displacement: [0, 0, minZ - z] as Vec3},
          {distance: Math.abs(maxZ - z), displacement: [0, 0, maxZ - z] as Vec3}
        ].sort((left, right) => left.distance - right.distance);
        const candidate = candidates.find(({displacement}) => {
          const nextX = x + displacement[0];
          const nextZ = z + displacement[2];
          return nextX >= this.walkingBounds.minX + radius
            && nextX <= this.walkingBounds.maxX - radius
            && nextZ >= this.walkingBounds.minZ + radius
            && nextZ <= this.walkingBounds.maxZ - radius;
        });
        if (candidate !== undefined) this.translateCamera(candidate.displacement);
        resolved = false;
      }
      if (resolved) break;
    }

    this.updateGroundedState();
    return !sameVec3(before, this.camera.position);
  }

  private updateGroundedState(): void {
    const feetY = this.camera.position[1] - this.currentEyeHeight;
    if (Math.abs(feetY - this.walkingBounds.floorY) <= COLLISION_EPSILON) {
      this.grounded = true;
      this.verticalVelocity = 0;
      return;
    }
    for (const obstacle of this.walkingObstacles.values()) {
      if (
        Math.abs(feetY - obstacle.max[1]) <= COLLISION_EPSILON
        && this.horizontalFootprintOverlaps(obstacle, this.camera.position[0], this.camera.position[2])
      ) {
        this.grounded = true;
        this.verticalVelocity = 0;
        return;
      }
    }
    this.grounded = false;
  }

  private bodyVerticallyOverlaps(obstacle: WalkingObstacle): boolean {
    const bottom = this.camera.position[1] - this.currentEyeHeight;
    const top = this.camera.position[1] + this.groundedWalkingConfig.radius;
    return bottom < obstacle.max[1] - COLLISION_EPSILON
      && top > obstacle.min[1] + COLLISION_EPSILON;
  }

  private horizontalFootprintOverlaps(obstacle: WalkingObstacle, x: number, z: number): boolean {
    const radius = this.groundedWalkingConfig.radius;
    return x > obstacle.min[0] - radius + COLLISION_EPSILON
      && x < obstacle.max[0] + radius - COLLISION_EPSILON
      && z > obstacle.min[2] - radius + COLLISION_EPSILON
      && z < obstacle.max[2] + radius - COLLISION_EPSILON;
  }

  private canOccupy(
    x: number,
    eyeY: number,
    z: number,
    eyeHeight: number,
    ignoredObstacleHandle?: string
  ): boolean {
    const radius = this.groundedWalkingConfig.radius;
    if (
      x < this.walkingBounds.minX + radius
      || x > this.walkingBounds.maxX - radius
      || z < this.walkingBounds.minZ + radius
      || z > this.walkingBounds.maxZ - radius
      || eyeY - eyeHeight < this.walkingBounds.floorY - COLLISION_EPSILON
      || eyeY + radius > this.walkingBounds.ceilingY + COLLISION_EPSILON
    ) return false;
    const bottom = eyeY - eyeHeight;
    const top = eyeY + radius;
    for (const obstacle of this.walkingObstacles.values()) {
      if (obstacle.handle === ignoredObstacleHandle) continue;
      if (!this.horizontalFootprintOverlaps(obstacle, x, z)) continue;
      if (bottom < obstacle.max[1] - COLLISION_EPSILON && top > obstacle.min[1] + COLLISION_EPSILON) {
        return false;
      }
    }
    return true;
  }

  private translateCamera(displacement: Vec3): void {
    if (sameVec3(displacement, [0, 0, 0])) return;
    this.camera = {
      ...this.camera,
      position: add(this.camera.position, displacement),
      target: add(this.camera.target, displacement)
    };
  }

  private planarMovementDirection(): Vec3 | null {
    let x = 0;
    let z = 0;
    const forwardX = Math.sin(this.yawRadians);
    const forwardZ = -Math.cos(this.yawRadians);
    const rightX = Math.cos(this.yawRadians);
    const rightZ = Math.sin(this.yawRadians);

    if (this.pressedKeys.has('KeyW')) {
      x += forwardX;
      z += forwardZ;
    }
    if (this.pressedKeys.has('KeyS')) {
      x -= forwardX;
      z -= forwardZ;
    }
    if (this.pressedKeys.has('KeyD')) {
      x += rightX;
      z += rightZ;
    }
    if (this.pressedKeys.has('KeyA')) {
      x -= rightX;
      z -= rightZ;
    }

    const length = Math.hypot(x, z);
    return length > 0 ? [x / length, 0, z / length] : null;
  }

  private movementDirection(): Vec3 | null {
    let x = 0;
    let y = 0;
    let z = 0;
    const forwardX = Math.sin(this.yawRadians);
    const forwardZ = -Math.cos(this.yawRadians);
    const rightX = Math.cos(this.yawRadians);
    const rightZ = Math.sin(this.yawRadians);

    if (this.pressedKeys.has('KeyW')) {
      x += forwardX;
      z += forwardZ;
    }
    if (this.pressedKeys.has('KeyS')) {
      x -= forwardX;
      z -= forwardZ;
    }
    if (this.pressedKeys.has('KeyD')) {
      x += rightX;
      z += rightZ;
    }
    if (this.pressedKeys.has('KeyA')) {
      x -= rightX;
      z -= rightZ;
    }
    if (this.pressedKeys.has('Space')) y += 1;
    if (this.pressedKeys.has('ControlLeft') || this.pressedKeys.has('ControlRight')) y -= 1;

    const length = Math.hypot(x, y, z);
    return length > 0 ? [x / length, y / length, z / length] : null;
  }

  private hasAnyPressed(keys: ReadonlySet<string>): boolean {
    for (const key of keys) {
      if (this.pressedKeys.has(key)) return true;
    }
    return false;
  }

  private updateOrientationFromCamera(): void {
    const delta = subtract(this.camera.target, this.camera.position);
    const distance = Math.hypot(...delta);
    this.lookDistance = Math.max(distance, MIN_LOOK_DISTANCE);
    const forward = scale(delta, 1 / this.lookDistance);
    this.yawRadians = Math.atan2(forward[0], -forward[2]);
    this.pitchRadians = clamp(
      Math.asin(clamp(forward[1], -1, 1)),
      -MAX_PITCH_RADIANS,
      MAX_PITCH_RADIANS
    );
    this.rebuildTarget();
  }

  private rebuildTarget(): void {
    const cosPitch = Math.cos(this.pitchRadians);
    const forward: Vec3 = [
      Math.sin(this.yawRadians) * cosPitch,
      Math.sin(this.pitchRadians),
      -Math.cos(this.yawRadians) * cosPitch
    ];
    this.camera = {
      ...this.camera,
      target: add(this.camera.position, scale(forward, this.lookDistance))
    };
  }

  private applyCamera(): void {
    this.renderer.setCamera(cloneCamera(this.camera));
  }

  private assertNotDestroyed(): void {
    if (this.destroyed) throw new Error('Free camera controls have been destroyed.');
  }
}

function sanitizeConfig(
  current: Readonly<FreeCameraConfig>,
  patch: Partial<FreeCameraConfig>
): FreeCameraConfig {
  return {
    moveSpeed: positiveFinite(patch.moveSpeed ?? current.moveSpeed, 'Camera movement speed'),
    sprintSpeed: positiveFinite(patch.sprintSpeed ?? current.sprintSpeed, 'Camera sprint speed'),
    lookSensitivity: positiveFinite(
      patch.lookSensitivity ?? current.lookSensitivity,
      'Camera look sensitivity'
    ),
    shiftSprint: patch.shiftSprint ?? current.shiftSprint,
    dragButton: nonNegativeInteger(patch.dragButton ?? current.dragButton, 'Camera drag button'),
    maxDeltaSeconds: positiveFinite(
      patch.maxDeltaSeconds ?? current.maxDeltaSeconds,
      'Camera maximum delta time'
    )
  };
}

function sanitizeGroundedWalkingConfig(
  current: Readonly<GroundedWalkingConfig>,
  patch: Partial<GroundedWalkingConfig>
): GroundedWalkingConfig {
  const config = {
    eyeHeight: positiveFinite(patch.eyeHeight ?? current.eyeHeight, 'Walking eye height'),
    radius: positiveFinite(patch.radius ?? current.radius, 'Walking collision radius'),
    gravity: nonNegativeFinite(patch.gravity ?? current.gravity, 'Walking gravity'),
    walkSpeed: positiveFinite(patch.walkSpeed ?? current.walkSpeed, 'Walking speed'),
    sprintSpeed: positiveFinite(patch.sprintSpeed ?? current.sprintSpeed, 'Walking sprint speed'),
    jumpSpeed: nonNegativeFinite(patch.jumpSpeed ?? current.jumpSpeed, 'Walking jump speed'),
    stepHeight: nonNegativeFinite(patch.stepHeight ?? current.stepHeight, 'Walking step height')
  };
  if (config.eyeHeight <= config.radius) {
    throw new RangeError('Walking eye height must be greater than the collision radius.');
  }
  if (config.sprintSpeed < config.walkSpeed) {
    throw new RangeError('Walking sprint speed must be greater than or equal to walking speed.');
  }
  if (config.stepHeight > config.eyeHeight) {
    throw new RangeError('Walking step height must not exceed walking eye height.');
  }
  return config;
}

function sanitizeWalkingBounds(bounds: WalkingRoomBounds): WalkingRoomBounds {
  const sanitized = {
    minX: finiteValue(bounds.minX, 'Walking room minimum X'),
    maxX: finiteValue(bounds.maxX, 'Walking room maximum X'),
    minZ: finiteValue(bounds.minZ, 'Walking room minimum Z'),
    maxZ: finiteValue(bounds.maxZ, 'Walking room maximum Z'),
    floorY: finiteValue(bounds.floorY, 'Walking room floor Y'),
    ceilingY: finiteValue(bounds.ceilingY, 'Walking room ceiling Y')
  };
  if (sanitized.minX >= sanitized.maxX || sanitized.minZ >= sanitized.maxZ) {
    throw new RangeError('Walking room minimum X/Z must be less than maximum X/Z.');
  }
  if (sanitized.floorY >= sanitized.ceilingY) {
    throw new RangeError('Walking room floor Y must be less than ceiling Y.');
  }
  return sanitized;
}

function validateWalkingSpace(config: GroundedWalkingConfig, bounds: WalkingRoomBounds): void {
  if (bounds.maxX - bounds.minX < config.radius * 2) {
    throw new RangeError('Walking room X span must fit the collision diameter.');
  }
  if (bounds.maxZ - bounds.minZ < config.radius * 2) {
    throw new RangeError('Walking room Z span must fit the collision diameter.');
  }
  if (bounds.ceilingY - bounds.floorY < config.eyeHeight + config.radius) {
    throw new RangeError('Walking room height must fit the standing camera body.');
  }
}

function crouchedEyeHeight(config: GroundedWalkingConfig): number {
  return Math.max(config.radius + 0.05, config.eyeHeight * 0.62);
}

function cloneAndValidateCamera(camera: CameraSettings): CameraSettings {
  const position = finiteVec3(camera.position, 'Camera position');
  const target = finiteVec3(camera.target, 'Camera target');
  if (Math.hypot(...subtract(target, position)) < MIN_LOOK_DISTANCE) {
    throw new RangeError('Camera position and target must be different.');
  }
  if (!Number.isFinite(camera.verticalFovDegrees)) {
    throw new TypeError('Camera field of view must be finite.');
  }
  return {
    position,
    target,
    verticalFovDegrees: clamp(camera.verticalFovDegrees, 10, 150)
  };
}

function cloneCamera(camera: CameraSettings): CameraSettings {
  return {
    position: [...camera.position],
    target: [...camera.target],
    verticalFovDegrees: camera.verticalFovDegrees
  };
}

function finiteVec3(vector: Vec3, name: string): Vec3 {
  if (vector.length !== 3 || !vector.every(Number.isFinite)) {
    throw new TypeError(`${name} must contain three finite numbers.`);
  }
  return [vector[0], vector[1], vector[2]];
}

function eventTargetsEditableControl(event: Event): boolean {
  const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
  const candidates = path.length > 0 ? path : [event.target];
  return candidates.some(isEditableControl);
}

function isEditableControl(value: EventTarget | null): boolean {
  if (value === null || typeof value !== 'object') return false;
  const element = value as {
    tagName?: unknown;
    isContentEditable?: unknown;
    getAttribute?(name: string): string | null;
  };
  const tagName = typeof element.tagName === 'string' ? element.tagName.toUpperCase() : '';
  if (tagName === 'INPUT' || tagName === 'TEXTAREA' || tagName === 'SELECT') return true;
  if (element.isContentEditable === true) return true;
  const contentEditable = element.getAttribute?.('contenteditable');
  if (contentEditable === '' || contentEditable === 'true') return true;
  return element.getAttribute?.('role') === 'textbox';
}

function positiveFinite(value: number, name: string): number {
  if (!Number.isFinite(value) || value <= 0) throw new RangeError(`${name} must be greater than zero.`);
  return value;
}

function nonNegativeFinite(value: number, name: string): number {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be greater than or equal to zero.`);
  }
  return value;
}

function finiteValue(value: number, name: string): number {
  if (!Number.isFinite(value)) throw new TypeError(`${name} must be finite.`);
  return value;
}

function nonNegativeInteger(value: number, name: string): number {
  if (!Number.isInteger(value) || value < 0) throw new RangeError(`${name} must be a non-negative integer.`);
  return value;
}

function finiteNumber(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(maximum, Math.max(minimum, value));
}

function wrapRadians(value: number): number {
  return Math.atan2(Math.sin(value), Math.cos(value));
}

function add(a: Vec3, b: Vec3): Vec3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function subtract(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

function scale(vector: Vec3, scalar: number): Vec3 {
  return [vector[0] * scalar, vector[1] * scalar, vector[2] * scalar];
}

function sameVec3(left: Vec3, right: Vec3): boolean {
  return left[0] === right[0] && left[1] === right[1] && left[2] === right[2];
}

function compareObstacleGeometry(left: WalkingObstacle, right: WalkingObstacle): number {
  for (let axis = 0; axis < 3; axis += 1) {
    const minimumDifference = left.min[axis]! - right.min[axis]!;
    if (minimumDifference !== 0) return minimumDifference;
    const maximumDifference = left.max[axis]! - right.max[axis]!;
    if (maximumDifference !== 0) return maximumDifference;
  }
  return 0;
}
