import {
  assertGuidedTensor, guidedNodeShape, guidedNodesForMode,
  type GuidedReconstructionMode, type GuidedReconstructionModel, type GuidedTensor, type GuidedTile
} from './guided-reconstruction-graph';
import {buildGuidedNodeConstants, GUIDED_RECONSTRUCTION_GRAPH_SHADER} from './guided-reconstruction-shader';
import {
  awaitGuidedOperation, throwIfGuidedAborted, type GuidedGpuTensor, type GuidedTileBackend
} from './inference-backends-types';

const TRANSFER_SHADER = /* wgsl */ `
struct Parameters {
  frame: vec4<u32>,
  tile: vec4<u32>,
  extent: vec4<u32>,
}
@group(0) @binding(0) var<uniform> p: Parameters;
@group(0) @binding(1) var<storage, read> source: array<f32>;
@group(0) @binding(2) var<storage, read_write> destination: array<f32>;

@compute @workgroup_size(128)
fn gather(@builtin(global_invocation_id) id: vec3<u32>) {
  let plane = p.tile.z * p.tile.z;
  if (id.x >= p.frame.z * plane) { return; }
  let channel = id.x / plane;
  let x = id.x % p.tile.z;
  let y = (id.x % plane) / p.tile.z;
  let sx = u32(clamp(i32(p.tile.x + x) - i32(p.tile.w), 0, i32(p.frame.x) - 1));
  let sy = u32(clamp(i32(p.tile.y + y) - i32(p.tile.w), 0, i32(p.frame.y) - 1));
  destination[id.x] = source[channel * p.frame.x * p.frame.y + sy * p.frame.x + sx];
}

@compute @workgroup_size(128)
fn scatter(@builtin(global_invocation_id) id: vec3<u32>) {
  let plane = p.extent.x * p.extent.y;
  if (id.x >= p.frame.z * plane) { return; }
  let channel = id.x / plane;
  let x = id.x % p.extent.x;
  let y = (id.x % plane) / p.extent.x;
  let index = channel * p.frame.x * p.frame.y + (p.tile.y + y) * p.frame.x + p.tile.x + x;
  destination[index] = source[channel * p.tile.z * p.tile.z + (y + p.tile.w) * p.tile.z + x + p.tile.w];
}
`;

interface Shape {channels: number; width: number; height: number}
interface Slot {buffer: GPUBuffer; size: number; available: boolean}
interface Step {bindGroup: GPUBindGroup; workgroups: number}
interface Plan {
  readonly key: string;
  readonly input: GPUBuffer;
  readonly output: GPUBuffer;
  readonly shape: Shape;
  readonly readback: GPUBuffer;
  readonly buffers: readonly GPUBuffer[];
  readonly steps: readonly Step[];
}

function shapeTensor(shape: Shape): GuidedTensor {
  return {...shape, data: new Float32Array(0)};
}

export class GuidedWebGpuBackend implements GuidedTileBackend {
  readonly kind = 'webgpu';
  private readonly buffers = new Set<GPUBuffer>();
  private weights: GPUBuffer | undefined;
  private pipeline: GPUComputePipeline | undefined;
  private transfer: {gather: GPUComputePipeline; scatter: GPUComputePipeline} | undefined;
  private plan: Plan | undefined;
  private disposed = false;

  constructor(
    private readonly device: GPUDevice,
    private readonly model: GuidedReconstructionModel,
    private readonly timeoutMs: number
  ) {}

  private pushScopes(): void {
    this.device.pushErrorScope('out-of-memory');
    this.device.pushErrorScope('internal');
    this.device.pushErrorScope('validation');
  }

  private async popScopes(signal?: AbortSignal): Promise<GPUError | null> {
    const pending = [this.device.popErrorScope(), this.device.popErrorScope(), this.device.popErrorScope()];
    const errors = await awaitGuidedOperation(Promise.all(pending), this.timeoutMs, signal);
    return errors.find(error => error !== null) ?? null;
  }

  private createBuffer(size: number, usage: GPUBufferUsageFlags, label: string): GPUBuffer {
    if (this.disposed) throw new Error('Reconstruction GPU backend was disposed.');
    if (size > this.device.limits.maxBufferSize
        || ((usage & GPUBufferUsage.STORAGE) && size > this.device.limits.maxStorageBufferBindingSize)) {
      throw new RangeError('Reconstruction tensor exceeds the selected GPU buffer limits.');
    }
    const buffer = this.device.createBuffer({size: Math.max(4, size), usage, label});
    this.buffers.add(buffer);
    return buffer;
  }

  private destroyBuffer(buffer: GPUBuffer): void {
    this.buffers.delete(buffer);
    buffer.destroy();
  }

  private async initialize(signal?: AbortSignal): Promise<void> {
    throwIfGuidedAborted(signal);
    if (this.disposed) throw new Error('Reconstruction GPU backend is unavailable.');
    if (this.pipeline !== undefined) return;
    this.pushScopes();
    let failure: unknown;
    try {
      const module = this.device.createShaderModule({label: 'Guided reconstruction graph', code: GUIDED_RECONSTRUCTION_GRAPH_SHADER});
      const pipeline = await awaitGuidedOperation(this.device.createComputePipelineAsync({
        label: 'Guided reconstruction node', layout: 'auto', compute: {module, entryPoint: 'main'}
      }), this.timeoutMs, signal);
      throwIfGuidedAborted(signal);
      if (this.disposed) throw new Error('Reconstruction GPU backend was disposed.');
      this.weights = this.createBuffer(this.model.weights.byteLength,
        GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST, 'Guided reconstruction trained weights');
      this.device.queue.writeBuffer(this.weights, 0, this.model.weights as Float32Array<ArrayBuffer>);
      this.pipeline = pipeline;
    } catch (error) {
      failure = error;
    }
    const validation = await this.popScopes(signal);
    if (failure !== undefined) throw failure;
    if (validation !== null) {
      if (this.weights !== undefined) this.destroyBuffer(this.weights);
      this.weights = undefined; this.pipeline = undefined;
      throw new Error(`Reconstruction shader validation failed: ${validation.message}`);
    }
  }

  private releasePlan(): void {
    if (this.plan === undefined) return;
    for (const buffer of this.plan.buffers) this.destroyBuffer(buffer);
    this.plan = undefined;
  }

  private getPlan(input: Shape, mode: GuidedReconstructionMode): Plan {
    const key = `${mode}:${input.width}:${input.height}`;
    if (this.plan?.key === key) return this.plan;
    this.releasePlan();
    if (input.channels !== 16 || input.width % 2 || input.height % 2 || input.width > 160 || input.height > 160) {
      throw new RangeError('GPU reconstruction tiles require 16 channels and even extents no larger than 160.');
    }
    const buffers: GPUBuffer[] = [];
    const slots: Slot[] = [];
    const allocate = (size: number): GPUBuffer => {
      const reusable = slots.filter(slot => slot.available && slot.size >= size).sort((a, b) => a.size - b.size)[0];
      if (reusable !== undefined) {reusable.available = false; return reusable.buffer;}
      const buffer = this.createBuffer(size,
        GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST, 'Guided reconstruction activation');
      slots.push({buffer, size, available: false}); buffers.push(buffer);
      return buffer;
    };
    const release = (buffer: GPUBuffer): void => {slots.find(slot => slot.buffer === buffer)!.available = true;};
    const nodes = guidedNodesForMode(this.model.graph, mode);
    const uses = new Map<string, number>();
    for (const node of nodes) for (const name of node.inputs) uses.set(name, (uses.get(name) ?? 0) + 1);
    const inputBuffer = allocate(input.channels * input.width * input.height * 4);
    const values = new Map<string, {shape: Shape; buffer: GPUBuffer}>([['input', {shape: input, buffer: inputBuffer}]]);
    const steps: Step[] = [];
    try {
      for (const node of nodes) {
        const first = values.get(node.inputs[0]!)!;
        const second = values.get(node.inputs[1] ?? '') ?? first;
        const [channels, height, width] = guidedNodeShape(node, shapeTensor(first.shape));
        const workgroups = Math.ceil(channels * height * width / 128);
        if (workgroups > this.device.limits.maxComputeWorkgroupsPerDimension) {
          throw new RangeError('Reconstruction tile exceeds the GPU dispatch limit.');
        }
        const output = allocate(channels * height * width * 4);
        const constants = this.createBuffer(64, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST, 'Guided reconstruction node constants');
        buffers.push(constants);
        this.device.queue.writeBuffer(constants, 0, buildGuidedNodeConstants(node, shapeTensor(first.shape)) as Uint32Array<ArrayBuffer>);
        const bindGroup = this.device.createBindGroup({layout: this.pipeline!.getBindGroupLayout(0), entries: [
          {binding: 0, resource: {buffer: constants}}, {binding: 1, resource: {buffer: first.buffer}},
          {binding: 2, resource: {buffer: second.buffer}}, {binding: 3, resource: {buffer: this.weights!}},
          {binding: 4, resource: {buffer: output}}
        ]});
        steps.push({bindGroup, workgroups});
        values.set(node.name, {shape: {channels, width, height}, buffer: output});
        for (const name of node.inputs) {
          const remaining = (uses.get(name) ?? 1) - 1; uses.set(name, remaining);
          if (remaining === 0) {release(values.get(name)!.buffer); values.delete(name);}
        }
      }
      const final = values.get(this.model.graph.outputs[mode])!;
      const readback = this.createBuffer(final.shape.channels * final.shape.width * final.shape.height * 4,
        GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ, 'Guided reconstruction tile readback');
      buffers.push(readback);
      this.plan = {key, input: inputBuffer, output: final.buffer, shape: final.shape, readback, buffers, steps};
      return this.plan;
    } catch (error) {
      for (const buffer of buffers) this.destroyBuffer(buffer);
      throw error;
    }
  }

  private encodeGraph(encoder: GPUCommandEncoder, plan: Plan): void {
    const pass = encoder.beginComputePass({label: 'Guided reconstruction graph inference'});
    pass.setPipeline(this.pipeline!);
    for (const step of plan.steps) {
      pass.setBindGroup(0, step.bindGroup);
      pass.dispatchWorkgroups(step.workgroups);
    }
    pass.end();
  }

  async inferTile(input: GuidedTensor, mode: GuidedReconstructionMode, signal?: AbortSignal): Promise<GuidedTensor> {
    assertGuidedTensor(input);
    await this.initialize(signal);
    this.pushScopes();
    let failure: unknown;
    let result: GuidedTensor | undefined;
    try {
      const plan = this.getPlan(input, mode);
      this.device.queue.writeBuffer(plan.input, 0, input.data as Float32Array<ArrayBuffer>);
      const encoder = this.device.createCommandEncoder({label: 'Guided reconstruction tile'});
      this.encodeGraph(encoder, plan);
      encoder.copyBufferToBuffer(plan.output, 0, plan.readback, 0,
        plan.shape.channels * plan.shape.width * plan.shape.height * 4);
      this.device.queue.submit([encoder.finish()]);
      await awaitGuidedOperation(plan.readback.mapAsync(GPUMapMode.READ), this.timeoutMs, signal);
      throwIfGuidedAborted(signal);
      result = {...plan.shape, data: new Float32Array(plan.readback.getMappedRange().slice(0))};
      plan.readback.unmap();
    } catch (error) {
      failure = error;
      this.releasePlan();
    }
    const validation = await this.popScopes(signal);
    if (failure !== undefined) throw failure;
    if (validation !== null) throw new Error(`Reconstruction GPU execution failed: ${validation.message}`);
    return result!;
  }

  private async initializeTransfer(signal?: AbortSignal): Promise<void> {
    if (this.transfer !== undefined) return;
    const module = this.device.createShaderModule({label: 'Guided reconstruction tile transfer', code: TRANSFER_SHADER});
    const [gather, scatter] = await awaitGuidedOperation(Promise.all(['gather', 'scatter'].map(entryPoint =>
      this.device.createComputePipelineAsync({layout: 'auto', compute: {module, entryPoint}}))), this.timeoutMs, signal);
    this.transfer = {gather: gather!, scatter: scatter!};
  }

  createOutput(input: GuidedGpuTensor, mode: GuidedReconstructionMode): GuidedGpuTensor {
    const channels = mode === 'native' ? 4 : 16;
    return {channels, width: input.width, height: input.height,
      buffer: this.createBuffer(channels * input.width * input.height * 4,
        GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC, 'Guided reconstruction complete output')};
  }

  releaseOutput(tensor: GuidedGpuTensor): void {
    if (this.buffers.has(tensor.buffer)) this.destroyBuffer(tensor.buffer);
  }

  createInput(input: GuidedTensor): GuidedGpuTensor {
    assertGuidedTensor(input);
    const buffer = this.createBuffer(input.data.byteLength, GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
      'Guided reconstruction numerical probe input');
    this.device.queue.writeBuffer(buffer, 0, input.data as Float32Array<ArrayBuffer>);
    return {buffer, channels: input.channels, width: input.width, height: input.height};
  }

  async readProbe(tensor: GuidedGpuTensor, signal?: AbortSignal): Promise<GuidedTensor> {
    if (tensor.width > 8 || tensor.height > 8) throw new Error('Inference probe readback is restricted to 8 by 8 tensors.');
    const bytes = tensor.channels * tensor.width * tensor.height * 4;
    const readback = this.createBuffer(bytes, GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
      'Guided reconstruction interop numerical probe');
    try {
      const encoder = this.device.createCommandEncoder();
      encoder.copyBufferToBuffer(tensor.buffer, 0, readback, 0, bytes);
      this.device.queue.submit([encoder.finish()]);
      await awaitGuidedOperation(readback.mapAsync(GPUMapMode.READ), this.timeoutMs, signal);
      const data = new Float32Array(readback.getMappedRange().slice(0)); readback.unmap();
      return {channels: tensor.channels, width: tensor.width, height: tensor.height, data};
    } finally {this.destroyBuffer(readback);}
  }

  private async transferGpuTile(
    kind: 'gather' | 'scatter', input: GuidedGpuTensor, tiled: GPUBuffer, tile: GuidedTile, signal?: AbortSignal
  ): Promise<void> {
    await this.initializeTransfer(signal);
    this.pushScopes();
    let constants: GPUBuffer | undefined;
    let failure: unknown;
    try {
      constants = this.createBuffer(48, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        'Guided reconstruction interop tile bounds');
      this.device.queue.writeBuffer(constants, 0, new Uint32Array([
        input.width, input.height, input.channels, 0, tile.x, tile.y, tile.inputSize, tile.halo,
        tile.width, tile.height, 0, 0
      ]));
      const pipeline = this.transfer![kind];
      const whole = {buffer: input.buffer, size: input.channels * input.width * input.height * 4};
      const part = {buffer: tiled, size: input.channels * tile.inputSize * tile.inputSize * 4};
      const group = this.device.createBindGroup({layout: pipeline.getBindGroupLayout(0), entries: [
        {binding: 0, resource: {buffer: constants}}, {binding: 1, resource: kind === 'gather' ? whole : part},
        {binding: 2, resource: kind === 'gather' ? part : whole}
      ]});
      const encoder = this.device.createCommandEncoder({label: `Guided reconstruction interop ${kind}`});
      const pass = encoder.beginComputePass(); pass.setPipeline(pipeline); pass.setBindGroup(0, group);
      pass.dispatchWorkgroups(Math.ceil(input.channels * (kind === 'gather' ? tile.inputSize ** 2 : tile.width * tile.height) / 128));
      pass.end(); this.device.queue.submit([encoder.finish()]);
      await awaitGuidedOperation(this.device.queue.onSubmittedWorkDone(), this.timeoutMs, signal);
    } catch (error) {failure = error;}
    finally {if (constants !== undefined) this.destroyBuffer(constants);}
    const validation = await this.popScopes(signal);
    if (failure !== undefined) throw failure;
    if (validation !== null) throw new Error(`WebNN GPU tensor transfer failed: ${validation.message}`);
  }

  gatherGpuTile(input: GuidedGpuTensor, tileBuffer: GPUBuffer, tile: GuidedTile, signal?: AbortSignal): Promise<void> {
    return this.transferGpuTile('gather', input, tileBuffer, tile, signal);
  }

  scatterGpuTile(tileBuffer: GPUBuffer, output: GuidedGpuTensor, tile: GuidedTile, signal?: AbortSignal): Promise<void> {
    return this.transferGpuTile('scatter', output, tileBuffer, tile, signal);
  }

  async inferGpuTile(
    input: GuidedGpuTensor, output: GuidedGpuTensor, tile: GuidedTile,
    mode: GuidedReconstructionMode, signal?: AbortSignal
  ): Promise<void> {
    await this.initialize(signal);
    await this.initializeTransfer(signal);
    const constants: GPUBuffer[] = [];
    this.pushScopes();
    let failure: unknown;
    try {
      const plan = this.getPlan({channels: 16, width: tile.inputSize, height: tile.inputSize}, mode);
      const encoder = this.device.createCommandEncoder({label: 'GPU-resident guided reconstruction tile'});
      const transfer = (kind: 'gather' | 'scatter', source: GPUBuffer, destination: GPUBuffer, channels: number): void => {
        const buffer = this.createBuffer(48, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST, 'Guided reconstruction tile bounds');
        constants.push(buffer);
        this.device.queue.writeBuffer(buffer, 0, new Uint32Array([
          input.width, input.height, channels, 0, tile.x, tile.y, tile.inputSize, tile.halo,
          tile.width, tile.height, 0, 0
        ]));
        const pipeline = this.transfer![kind];
        const frameBytes = channels * input.width * input.height * 4;
        const tileBytes = channels * tile.inputSize * tile.inputSize * 4;
        const group = this.device.createBindGroup({layout: pipeline.getBindGroupLayout(0), entries: [
          {binding: 0, resource: {buffer}},
          {binding: 1, resource: {buffer: source, size: kind === 'gather' ? frameBytes : tileBytes}},
          {binding: 2, resource: {buffer: destination, size: kind === 'gather' ? tileBytes : frameBytes}}
        ]});
        const pass = encoder.beginComputePass({label: `Guided reconstruction ${kind}`});
        pass.setPipeline(pipeline); pass.setBindGroup(0, group);
        pass.dispatchWorkgroups(Math.ceil(channels * (kind === 'gather' ? tile.inputSize ** 2 : tile.width * tile.height) / 128));
        pass.end();
      };
      transfer('gather', input.buffer, plan.input, 16);
      this.encodeGraph(encoder, plan);
      transfer('scatter', plan.output, output.buffer, output.channels);
      this.device.queue.submit([encoder.finish()]);
      await awaitGuidedOperation(this.device.queue.onSubmittedWorkDone(), this.timeoutMs, signal);
    } catch (error) {
      failure = error;
      this.releasePlan();
    } finally {
      for (const buffer of constants) this.destroyBuffer(buffer);
    }
    const validation = await this.popScopes(signal);
    if (failure !== undefined) throw failure;
    if (validation !== null) throw new Error(`GPU-resident reconstruction failed: ${validation.message}`);
  }

  dispose(): void {
    this.disposed = true;
    for (const buffer of this.buffers) buffer.destroy();
    this.buffers.clear(); this.plan = undefined; this.weights = undefined;
    this.pipeline = undefined; this.transfer = undefined;
  }
}
