import {RASTER_COLOR_FORMATS} from '../raster-pipeline';
import {BVH_MAX_DEPTH} from '../scene/bvh';
import {MAX_SCENE_TRIANGLES} from '../scene/limits';
import {TRIANGLE_GPU_STRIDE} from '../scene/packing';
import {MATERIAL_TEXTURE_ARRAY_LAYERS, MATERIAL_TEXTURE_SIZE} from '../texture/gpu-texture-resources';

const RASTER_ATTACHMENT_BYTE_COST = {
  rgba16float: 8,
  rgba8unorm: 8
} as const;

export const RENDERER_MINIMUM_DEVICE_LIMITS = Object.freeze({
  maxTextureDimension2D: MATERIAL_TEXTURE_SIZE,
  maxTextureDimension3D: 1,
  maxTextureArrayLayers: MATERIAL_TEXTURE_ARRAY_LAYERS,
  maxBindGroups: 2,
  maxBindGroupsPlusVertexBuffers: 2,
  maxBindingsPerBindGroup: 23,
  maxSampledTexturesPerShaderStage: 8,
  maxSamplersPerShaderStage: 2,
  maxStorageBuffersPerShaderStage: 8,
  maxStorageBuffersInVertexStage: 1,
  maxStorageBuffersInFragmentStage: 2,
  maxStorageTexturesPerShaderStage: 4,
  maxUniformBuffersPerShaderStage: 2,
  maxUniformBufferBindingSize: 200 * Float32Array.BYTES_PER_ELEMENT,
  maxStorageBufferBindingSize: MAX_SCENE_TRIANGLES * TRIANGLE_GPU_STRIDE,
  maxBufferSize: MAX_SCENE_TRIANGLES * TRIANGLE_GPU_STRIDE,
  maxInterStageShaderVariables: 6,
  maxColorAttachments: RASTER_COLOR_FORMATS.length,
  // WebGPU charges eight render-target bytes for rgba8unorm as well as rgba16float.
  maxColorAttachmentBytesPerSample: RASTER_COLOR_FORMATS.reduce(
    (bytes, format) => bytes + RASTER_ATTACHMENT_BYTE_COST[format],
    0
  ),
  maxComputeWorkgroupStorageSize: 8 * 8 * (BVH_MAX_DEPTH + 1) * Uint32Array.BYTES_PER_ELEMENT,
  maxComputeInvocationsPerWorkgroup: 256,
  maxComputeWorkgroupSizeX: 256,
  maxComputeWorkgroupSizeY: 8,
  maxComputeWorkgroupSizeZ: 1,
  maxComputeWorkgroupsPerDimension: Math.ceil(MAX_SCENE_TRIANGLES / 64)
} satisfies Partial<Record<keyof GPUSupportedLimits, number>>);

export type RendererDeviceLimitName = keyof typeof RENDERER_MINIMUM_DEVICE_LIMITS;

export interface RendererDeviceLimitIssue {
  readonly limit: RendererDeviceLimitName;
  readonly required: number;
  readonly available: number | null;
  readonly message: string;
}

const REQUIREMENT_PURPOSES: Readonly<Record<RendererDeviceLimitName, string>> = {
  maxTextureDimension2D: 'the fixed material texture array',
  maxTextureDimension3D: 'the fallback cloud density texture',
  maxTextureArrayLayers: 'the material texture array including its fallback layer',
  maxBindGroups: 'the scene and raster shadow resource groups',
  maxBindGroupsPlusVertexBuffers: 'two resource groups with no vertex buffers',
  maxBindingsPerBindGroup: 'the complete tracing resource group',
  maxSampledTexturesPerShaderStage: 'tracing history, materials, environments, and cloud density',
  maxSamplersPerShaderStage: 'material and cloud sampling',
  maxStorageBuffersPerShaderStage: 'scene data and sun visibility history',
  maxStorageBuffersInVertexStage: 'raster triangle data',
  maxStorageBuffersInFragmentStage: 'raster materials and lights',
  maxStorageTexturesPerShaderStage: 'tracing radiance and three guide outputs',
  maxUniformBuffersPerShaderStage: 'frame and raster shadow parameters',
  maxUniformBufferBindingSize: 'the complete frame uniform buffer',
  maxStorageBufferBindingSize: 'the fixed triangle storage binding',
  maxBufferSize: 'the fixed triangle storage allocation',
  maxInterStageShaderVariables: 'five raster varyings and the front_facing builtin',
  maxColorAttachments: 'the four raster radiance and guide outputs',
  maxColorAttachmentBytesPerSample: 'the four raster output formats under WebGPU attachment accounting',
  maxComputeWorkgroupStorageSize: '64 independent BVH traversal stacks',
  maxComputeInvocationsPerWorkgroup: 'the exposure reduction workgroup',
  maxComputeWorkgroupSizeX: 'the exposure reduction workgroup',
  maxComputeWorkgroupSizeY: 'the tracing and post-processing workgroups',
  maxComputeWorkgroupSizeZ: 'the compute workgroups',
  maxComputeWorkgroupsPerDimension: 'animated deformation at the supported triangle budget'
};

const OPTIONAL_REPORTED_LIMITS: ReadonlySet<RendererDeviceLimitName> = new Set([
  'maxBindGroupsPlusVertexBuffers',
  'maxStorageBuffersInVertexStage',
  'maxStorageBuffersInFragmentStage'
]);

export function rendererDeviceLimitIssues(
  limits: Readonly<Partial<GPUSupportedLimits>>
): readonly RendererDeviceLimitIssue[] {
  const issues: RendererDeviceLimitIssue[] = [];
  for (const limit of Object.keys(RENDERER_MINIMUM_DEVICE_LIMITS) as RendererDeviceLimitName[]) {
    const reported = limits[limit];
    // Older core implementations predate the separate compatibility-stage limits.
    if (reported === undefined && OPTIONAL_REPORTED_LIMITS.has(limit)) continue;
    const required = RENDERER_MINIMUM_DEVICE_LIMITS[limit];
    const available = typeof reported === 'number' && Number.isFinite(reported) ? reported : null;
    if (available !== null && Number.isInteger(available) && available >= required) continue;
    const reportedText = available === null ? 'unreported or invalid' : String(available);
    issues.push({
      limit,
      required,
      available,
      message: `${limit} requires at least ${required} for ${REQUIREMENT_PURPOSES[limit]}; reported ${reportedText}`
    });
  }
  return issues;
}

export function assertRendererDeviceLimits(limits: Readonly<Partial<GPUSupportedLimits>>): void {
  const issues = rendererDeviceLimitIssues(limits);
  if (issues.length > 0) {
    throw new RangeError(`WebGPU renderer requirements are not met: ${issues.map(issue => issue.message).join('; ')}.`);
  }
}
