import {MAX_SCENE_TRIANGLES, type MeshDefinition, type Vec3, type Vec3ArrayInput} from '../scene';

export const HARD_MODEL_LIMITS = Object.freeze({
  maxVertices: MAX_SCENE_TRIANGLES * 3,
  maxTriangles: MAX_SCENE_TRIANGLES,
  maxSourceBytes: 128 * 1024 * 1024,
  maxPolygonVertices: 4_096
});

export type ModelDetailPreset = 'preview' | 'realtime' | 'quality' | 'cinematic';

export interface ModelDetailBudget {
  readonly maxVertices: number;
  readonly maxTriangles: number;
  readonly maxSourceBytes: number;
  readonly maxPolygonVertices: number;
}

export type ModelDetailBudgetInput = ModelDetailPreset | Partial<ModelDetailBudget>;

export interface ModelComplexity {
  readonly vertexCount: number;
  readonly triangleCount: number;
}

export interface ModelLodCandidate<T> extends ModelComplexity {
  readonly value: T;
  /** Zero is the cheapest level. Values must increase with detail. */
  readonly level: number;
  /** Furthest camera distance at which this level is desired. Infinity is allowed for the cheapest fallback. */
  readonly maxDistance: number;
}

export interface PlannedUvSphere extends ModelComplexity {
  readonly requestedSegments: number;
  readonly requestedRings: number;
  readonly segments: number;
  readonly rings: number;
  readonly reduced: boolean;
}

export interface PlannedGrid extends ModelComplexity {
  readonly requestedXSegments: number;
  readonly requestedZSegments: number;
  readonly xSegments: number;
  readonly zSegments: number;
  readonly reduced: boolean;
}

export type BudgetOverflowMode = 'error' | 'fit';

export interface UvSphereOptions {
  radius?: number;
  center?: Vec3;
  segments?: number;
  rings?: number;
  budget?: ModelDetailBudgetInput;
  overflow?: BudgetOverflowMode;
}

export type HeightSource = ArrayLike<number> | ((xIndex: number, zIndex: number) => number);

export interface HeightfieldOptions {
  width?: number;
  depth?: number;
  xSegments?: number;
  zSegments?: number;
  center?: Vec3;
  heights: HeightSource;
  budget?: ModelDetailBudgetInput;
  overflow?: BudgetOverflowMode;
}

export interface FractalTerrainOptions {
  width?: number;
  depth?: number;
  xSegments?: number;
  zSegments?: number;
  center?: Vec3;
  seed?: number | string;
  heightScale?: number;
  baseHeight?: number;
  frequency?: number;
  octaves?: number;
  persistence?: number;
  lacunarity?: number;
  budget?: ModelDetailBudgetInput;
  overflow?: BudgetOverflowMode;
}

export type CloudVolumeProfile = 'cumulus' | 'stratus' | 'cirrus';

export interface CloudDensityVolumeOptions {
  /** World-space volume size. Defaults to a broad, shallow cloud bank. */
  size?: Vec3;
  /** World-space center of the density volume. */
  center?: Vec3;
  /** Voxel dimensions in X, Y, Z order. X is the fastest-changing storage axis. */
  resolution?: readonly [number, number, number];
  seed?: number | string;
  profile?: CloudVolumeProfile;
  /** Fraction of the volume filled by cloud, in `[0, 1]`. */
  coverage?: number;
  /** Multiplier applied by a volume integrator after decoding the normalized density. */
  densityScale?: number;
  /** Large-scale coherent noise frequency across the volume. */
  baseFrequency?: number;
  /** Number of large-scale fractal-noise octaves, from one through eight. */
  octaves?: number;
  /** High-frequency edge breakup in `[0, 1]`. */
  erosion?: number;
  /** Width of the density fade at the X/Z volume boundary, in `[0, 0.5]`. */
  edgeFade?: number;
  /** Single-scattering albedo per color channel, in `[0, 1]`. */
  scatteringAlbedo?: Vec3;
  /** Extinction coefficient in inverse world-space units. */
  extinction?: number;
  /** Henyey-Greenstein phase asymmetry in `[-0.95, 0.95]`. */
  anisotropy?: number;
  budget?: ModelDetailBudgetInput;
  overflow?: BudgetOverflowMode;
}

export interface CloudDensityVolumeStats {
  readonly voxelCount: number;
  readonly occupiedVoxelCount: number;
  readonly meanNormalizedDensity: number;
  readonly maximumNormalizedDensity: number;
  readonly byteLength: number;
  readonly reduced: boolean;
}

/**
 * Renderer-neutral R8 density field. Values are tightly packed with X changing
 * fastest, followed by Y, then Z, matching `x + width * (y + height * z)`.
 */
export interface CloudDensityVolume {
  readonly kind: 'cloud-density-volume';
  readonly format: 'r8unorm';
  readonly axisOrder: 'x-y-z';
  readonly profile: CloudVolumeProfile;
  readonly center: Vec3;
  readonly size: Vec3;
  readonly minimum: Vec3;
  readonly maximum: Vec3;
  readonly requestedResolution: readonly [number, number, number];
  readonly resolution: readonly [number, number, number];
  readonly density: Uint8Array;
  readonly densityScale: number;
  readonly scatteringAlbedo: Vec3;
  readonly extinction: number;
  readonly anisotropy: number;
  readonly stats: CloudDensityVolumeStats;
}

export interface HeightWindWeightOptions {
  /** World/model axis used to anchor bending. Defaults to Y. */
  axis?: 'x' | 'y' | 'z';
  /** Coordinate with zero bend. Defaults to the minimum coordinate on the selected axis. */
  anchor?: number;
  /** Coordinate with full bend. Defaults to the maximum coordinate on the selected axis. */
  fullBendAt?: number;
  /** Shapes the transition; values above one keep more of the base rigid. */
  exponent?: number;
  /** Maximum output weight in `[0, 1]`. */
  strength?: number;
}

export type WindWeightPositionInput = Vec3ArrayInput;

export interface ObjParseOptions {
  budget?: ModelDetailBudgetInput;
  scale?: number;
  flipV?: boolean;
}

export interface ObjMaterialGroup {
  readonly objectName: string | null;
  readonly groupName: string | null;
  readonly materialName: string | null;
  readonly smoothingGroup: string | null;
  readonly firstTriangle: number;
  readonly triangleCount: number;
}

export interface ObjParseResult {
  /** Mesh data accepted directly by Scene.createMesh/WebGpuRenderer.createMesh. */
  readonly mesh: MeshDefinition;
  /** UVs aligned to mesh vertices. The current renderer schema does not consume them. */
  readonly textureCoordinates: Float32Array | null;
  readonly hasCompleteTextureCoordinates: boolean;
  readonly groups: readonly ObjMaterialGroup[];
  readonly materialLibraries: readonly string[];
  readonly ignoredDirectives: readonly string[];
  readonly sourcePositionCount: number;
  readonly sourceNormalCount: number;
  readonly sourceTextureCoordinateCount: number;
}
