import {add3, componentMax3, componentMin3, cross3, lengthSquared3} from './math';
import {MAX_SCENE_TRIANGLES} from './limits';
import type {Aabb, Bvh, BvhNode, FlatTriangle, Vec3} from './types';
import {assertFiniteGpuNumber, assertIntegerInRange, validateVec2, validateVec3} from './validation';

export const BVH_LEAF_TRIANGLE_LIMIT = 4;
export const BVH_MAX_DEPTH = 48;
export const BVH_SAH_BIN_COUNT = 12;
export {MAX_SCENE_TRIANGLES};

export type BvhBuildStage = 'validate' | 'bounds' | 'hierarchy' | 'reorder';

export interface BvhBuildProgress {
  readonly stage: BvhBuildStage;
  readonly completed: number;
  readonly total: number;
}

export interface BvhBuildAsyncOptions {
  readonly timeSliceMilliseconds?: number;
}

export type BvhBuildYield = (progress: BvhBuildProgress) => void | Promise<void>;

const EMPTY_MIN: Vec3 = [Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY];
const EMPTY_MAX: Vec3 = [Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY];
const TRIANGLE_EPSILON_SQUARED = 1e-20;

interface MutableBounds {
  min: Vec3;
  max: Vec3;
}

interface SplitResult {
  readonly middle: number;
  readonly leftCount: number;
  readonly rightCount: number;
}

function triangleVertices(triangle: FlatTriangle): readonly [Vec3, Vec3, Vec3] {
  return [triangle.v0, add3(triangle.v0, triangle.edge1), add3(triangle.v0, triangle.edge2)];
}

export function getTriangleBounds(triangle: FlatTriangle): Aabb {
  const [v0, v1, v2] = triangleVertices(triangle);
  const displacement = triangle.windAmplitude ?? 0;
  assertFiniteGpuNumber(displacement, 'triangle.windAmplitude');
  if (displacement < 0) throw new RangeError('triangle.windAmplitude must be non-negative');
  const minimum = componentMin3(v0, componentMin3(v1, v2));
  const maximum = componentMax3(v0, componentMax3(v1, v2));
  return {
    min: [minimum[0] - displacement, minimum[1] - displacement, minimum[2] - displacement],
    max: [maximum[0] + displacement, maximum[1] + displacement, maximum[2] + displacement]
  };
}

export function getTriangleCentroid(triangle: FlatTriangle): Vec3 {
  return [
    triangle.v0[0] + (triangle.edge1[0] + triangle.edge2[0]) / 3,
    triangle.v0[1] + (triangle.edge1[1] + triangle.edge2[1]) / 3,
    triangle.v0[2] + (triangle.edge1[2] + triangle.edge2[2]) / 3
  ];
}

function validateTriangle(triangle: FlatTriangle, index: number): void {
  validateVec3(triangle.v0, `triangles[${index}].v0`);
  validateVec3(triangle.edge1, `triangles[${index}].edge1`);
  validateVec3(triangle.edge2, `triangles[${index}].edge2`);
  validateVec3(triangle.normal, `triangles[${index}].normal`);
  if (lengthSquared3(cross3(triangle.edge1, triangle.edge2)) <= TRIANGLE_EPSILON_SQUARED) {
    throw new RangeError(`triangles[${index}] is degenerate`);
  }
  if (lengthSquared3(triangle.normal) <= TRIANGLE_EPSILON_SQUARED) {
    throw new RangeError(`triangles[${index}].normal must have non-zero length`);
  }
  if (Math.abs(lengthSquared3(triangle.normal) - 1) > 1e-3) {
    throw new RangeError(`triangles[${index}].normal must have unit length`);
  }
  if (triangle.vertexNormals !== undefined) {
    triangle.vertexNormals.forEach((normal, vertexIndex) => {
      validateVec3(normal, `triangles[${index}].vertexNormals[${vertexIndex}]`);
      if (Math.abs(lengthSquared3(normal) - 1) > 1e-3) {
        throw new RangeError(`triangles[${index}].vertexNormals[${vertexIndex}] must have unit length`);
      }
    });
  }
  if (triangle.vertexUvs !== undefined) {
    if (triangle.vertexUvs.length !== 3) {
      throw new RangeError(`triangles[${index}].vertexUvs must contain exactly three texture coordinates`);
    }
    triangle.vertexUvs.forEach((uv, vertexIndex) => {
      validateVec2(uv, `triangles[${index}].vertexUvs[${vertexIndex}]`);
    });
  }
  if (triangle.windWeights !== undefined) {
    triangle.windWeights.forEach((weight, vertexIndex) => {
      assertFiniteGpuNumber(weight, `triangles[${index}].windWeights[${vertexIndex}]`);
      if (weight < 0 || weight > 1) {
        throw new RangeError(`triangles[${index}].windWeights[${vertexIndex}] must be between 0 and 1`);
      }
    });
  }
  const windAmplitude = triangle.windAmplitude ?? 0;
  assertFiniteGpuNumber(windAmplitude, `triangles[${index}].windAmplitude`);
  if (windAmplitude < 0) {
    throw new RangeError(`triangles[${index}].windAmplitude must be non-negative`);
  }
  assertIntegerInRange(triangle.materialIndex, 0, 255, `triangles[${index}].materialIndex`);
  assertIntegerInRange(triangle.sourceTriangleIndex, 0, 0xffff_ffff, `triangles[${index}].sourceTriangleIndex`);
}

function emptyBounds(): MutableBounds {
  return {min: EMPTY_MIN, max: EMPTY_MAX};
}

function extendBounds(bounds: MutableBounds, other: Aabb): void {
  bounds.min = componentMin3(bounds.min, other.min);
  bounds.max = componentMax3(bounds.max, other.max);
}

function boundsForRange(
  order: readonly number[],
  triangleBounds: readonly Aabb[],
  start: number,
  end: number
): MutableBounds {
  const bounds = emptyBounds();
  for (let cursor = start; cursor < end; cursor += 1) {
    const triangleIndex = order[cursor];
    const item = triangleIndex === undefined ? undefined : triangleBounds[triangleIndex];
    if (!item) throw new Error('Internal BVH order invariant failed');
    extendBounds(bounds, item);
  }
  return bounds;
}

function centroidBoundsForRange(
  order: readonly number[],
  centroids: readonly Vec3[],
  start: number,
  end: number
): MutableBounds {
  const bounds = emptyBounds();
  for (let cursor = start; cursor < end; cursor += 1) {
    const triangleIndex = order[cursor];
    const centroid = triangleIndex === undefined ? undefined : centroids[triangleIndex];
    if (!centroid) throw new Error('Internal BVH centroid invariant failed');
    bounds.min = componentMin3(bounds.min, centroid);
    bounds.max = componentMax3(bounds.max, centroid);
  }
  return bounds;
}

function surfaceArea(bounds: Aabb): number {
  const x = Math.max(0, bounds.max[0] - bounds.min[0]);
  const y = Math.max(0, bounds.max[1] - bounds.min[1]);
  const z = Math.max(0, bounds.max[2] - bounds.min[2]);
  return 2 * (x * y + y * z + z * x);
}

function largestAxis(bounds: Aabb): 0 | 1 | 2 {
  const extents = [
    bounds.max[0] - bounds.min[0],
    bounds.max[1] - bounds.min[1],
    bounds.max[2] - bounds.min[2]
  ] as const;
  if (extents[1] > extents[0] && extents[1] >= extents[2]) return 1;
  if (extents[2] > extents[0] && extents[2] > extents[1]) return 2;
  return 0;
}

function childCapacity(depth: number): number {
  const remainingLevels = BVH_MAX_DEPTH - depth - 1;
  return remainingLevels < 0 ? 0 : BVH_LEAF_TRIANGLE_LIMIT * 2 ** remainingLevels;
}

function findSahSplit(
  order: number[],
  triangleBounds: readonly Aabb[],
  centroids: readonly Vec3[],
  start: number,
  end: number,
  depth: number
): SplitResult | null {
  const centroidBounds = centroidBoundsForRange(order, centroids, start, end);
  let bestAxis = -1;
  let bestSplitBin = -1;
  let bestCost = Number.POSITIVE_INFINITY;

  for (let axis = 0; axis < 3; axis += 1) {
    const minimum = centroidBounds.min[axis] ?? 0;
    const extent = (centroidBounds.max[axis] ?? 0) - minimum;
    if (!(extent > 1e-12)) continue;

    const counts = new Uint32Array(BVH_SAH_BIN_COUNT);
    const binBounds = Array.from({length: BVH_SAH_BIN_COUNT}, emptyBounds);
    for (let cursor = start; cursor < end; cursor += 1) {
      const triangleIndex = order[cursor];
      const centroid = triangleIndex === undefined ? undefined : centroids[triangleIndex];
      const bounds = triangleIndex === undefined ? undefined : triangleBounds[triangleIndex];
      if (!centroid || !bounds) throw new Error('Internal BVH bin invariant failed');
      const normalized = ((centroid[axis] ?? 0) - minimum) / extent;
      const bin = Math.min(BVH_SAH_BIN_COUNT - 1, Math.max(0, Math.floor(normalized * BVH_SAH_BIN_COUNT)));
      counts[bin] = (counts[bin] ?? 0) + 1;
      const target = binBounds[bin];
      if (!target) throw new Error('Internal BVH bin invariant failed');
      extendBounds(target, bounds);
    }

    const leftCounts = new Uint32Array(BVH_SAH_BIN_COUNT - 1);
    const rightCounts = new Uint32Array(BVH_SAH_BIN_COUNT - 1);
    const leftAreas = new Float64Array(BVH_SAH_BIN_COUNT - 1);
    const rightAreas = new Float64Array(BVH_SAH_BIN_COUNT - 1);
    const leftBounds = emptyBounds();
    let leftCount = 0;
    for (let bin = 0; bin < BVH_SAH_BIN_COUNT - 1; bin += 1) {
      const bounds = binBounds[bin];
      if (!bounds) throw new Error('Internal BVH bin invariant failed');
      if ((counts[bin] ?? 0) > 0) extendBounds(leftBounds, bounds);
      leftCount += counts[bin] ?? 0;
      leftCounts[bin] = leftCount;
      leftAreas[bin] = leftCount === 0 ? 0 : surfaceArea(leftBounds);
    }
    const rightBounds = emptyBounds();
    let rightCount = 0;
    for (let bin = BVH_SAH_BIN_COUNT - 1; bin > 0; bin -= 1) {
      const bounds = binBounds[bin];
      if (!bounds) throw new Error('Internal BVH bin invariant failed');
      if ((counts[bin] ?? 0) > 0) extendBounds(rightBounds, bounds);
      rightCount += counts[bin] ?? 0;
      const split = bin - 1;
      rightCounts[split] = rightCount;
      rightAreas[split] = rightCount === 0 ? 0 : surfaceArea(rightBounds);
    }

    for (let split = 0; split < BVH_SAH_BIN_COUNT - 1; split += 1) {
      const left = leftCounts[split] ?? 0;
      const right = rightCounts[split] ?? 0;
      if (left === 0 || right === 0 || left > childCapacity(depth) || right > childCapacity(depth)) continue;
      const cost = (leftAreas[split] ?? 0) * left + (rightAreas[split] ?? 0) * right;
      if (cost < bestCost) {
        bestCost = cost;
        bestAxis = axis;
        bestSplitBin = split;
      }
    }
  }

  if (bestAxis < 0) return null;
  const minimum = centroidBounds.min[bestAxis] ?? 0;
  const extent = (centroidBounds.max[bestAxis] ?? 0) - minimum;
  const left: number[] = [];
  const right: number[] = [];
  for (let cursor = start; cursor < end; cursor += 1) {
    const triangleIndex = order[cursor];
    if (triangleIndex === undefined) throw new Error('Internal BVH partition invariant failed');
    const centroid = centroids[triangleIndex];
    if (!centroid) throw new Error('Internal BVH partition invariant failed');
    const normalized = ((centroid[bestAxis] ?? 0) - minimum) / extent;
    const bin = Math.min(BVH_SAH_BIN_COUNT - 1, Math.max(0, Math.floor(normalized * BVH_SAH_BIN_COUNT)));
    (bin <= bestSplitBin ? left : right).push(triangleIndex);
  }
  if (left.length === 0 || right.length === 0) return null;
  let destination = start;
  for (const triangleIndex of left) {
    order[destination] = triangleIndex;
    destination += 1;
  }
  for (const triangleIndex of right) {
    order[destination] = triangleIndex;
    destination += 1;
  }
  return {middle: start + left.length, leftCount: left.length, rightCount: right.length};
}

function medianSplit(
  order: number[],
  centroids: readonly Vec3[],
  start: number,
  end: number,
  depth: number
): SplitResult {
  const bounds = centroidBoundsForRange(order, centroids, start, end);
  const axis = largestAxis(bounds);
  const sorted = order.slice(start, end).sort((leftIndex, rightIndex) => {
    const left = centroids[leftIndex];
    const right = centroids[rightIndex];
    if (!left || !right) throw new Error('Internal BVH median invariant failed');
    const difference = (left[axis] ?? 0) - (right[axis] ?? 0);
    return difference === 0 ? leftIndex - rightIndex : difference;
  });
  const middleOffset = Math.floor(sorted.length / 2);
  const leftCount = middleOffset;
  const rightCount = sorted.length - middleOffset;
  if (leftCount === 0 || rightCount === 0 || leftCount > childCapacity(depth) || rightCount > childCapacity(depth)) {
    throw new RangeError(`Cannot build a BVH within depth ${BVH_MAX_DEPTH}`);
  }
  for (let index = 0; index < sorted.length; index += 1) {
    const triangleIndex = sorted[index];
    if (triangleIndex === undefined) throw new Error('Internal BVH median rewrite invariant failed');
    order[start + index] = triangleIndex;
  }
  return {middle: start + middleOffset, leftCount, rightCount};
}

function makePlaceholder(depth: number): BvhNode {
  return {min: [0, 0, 0], max: [0, 0, 0], leftFirst: 0, count: 0, depth};
}

export function buildBvh(triangles: readonly FlatTriangle[]): Bvh {
  if (triangles.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError(`BVH supports at most ${MAX_SCENE_TRIANGLES.toLocaleString('en-US')} triangles`);
  }
  for (let index = 0; index < triangles.length; index += 1) {
    const triangle = triangles[index];
    if (!triangle) throw new TypeError(`triangles[${index}] is missing`);
    validateTriangle(triangle, index);
  }
  if (triangles.length === 0) {
    return {nodes: [], triangles: [], sourceOrder: new Uint32Array(), maxDepth: 0};
  }

  const triangleBounds = triangles.map(getTriangleBounds);
  const centroids = triangles.map(getTriangleCentroid);
  const order = Array.from({length: triangles.length}, (_, index) => index);
  const nodes: BvhNode[] = [makePlaceholder(0)];
  let maximumDepth = 0;

  const buildNode = (nodeIndex: number, start: number, end: number, depth: number): void => {
    const count = end - start;
    const bounds = boundsForRange(order, triangleBounds, start, end);
    maximumDepth = Math.max(maximumDepth, depth);
    if (count <= BVH_LEAF_TRIANGLE_LIMIT) {
      nodes[nodeIndex] = {...bounds, leftFirst: start, count, depth};
      return;
    }
    if (depth >= BVH_MAX_DEPTH) throw new RangeError(`Cannot build a BVH within depth ${BVH_MAX_DEPTH}`);

    const split = findSahSplit(order, triangleBounds, centroids, start, end, depth)
      ?? medianSplit(order, centroids, start, end, depth);
    const leftIndex = nodes.length;
    nodes.push(makePlaceholder(depth + 1), makePlaceholder(depth + 1));
    nodes[nodeIndex] = {...bounds, leftFirst: leftIndex, count: 0, depth};
    buildNode(leftIndex, start, split.middle, depth + 1);
    buildNode(leftIndex + 1, split.middle, end, depth + 1);
  };

  buildNode(0, 0, triangles.length, 0);
  const reordered = order.map(index => {
    const triangle = triangles[index];
    if (!triangle) throw new Error('Internal BVH reorder invariant failed');
    return triangle;
  });
  return {nodes, triangles: reordered, sourceOrder: Uint32Array.from(order), maxDepth: maximumDepth};
}

const BVH_COOPERATIVE_LOOP_CHUNK = 2_048;
const DEFAULT_BVH_TIME_SLICE_MILLISECONDS = 8;

interface PendingBvhNode {
  readonly nodeIndex: number;
  readonly start: number;
  readonly end: number;
  readonly depth: number;
}

type CooperativeCheckpoint = (progress: BvhBuildProgress, force?: boolean) => Promise<void> | null;

function createCooperativeCheckpoint(
  yieldControl: BvhBuildYield,
  timeSliceMilliseconds: number
): CooperativeCheckpoint {
  if (!Number.isFinite(timeSliceMilliseconds) || timeSliceMilliseconds < 0) {
    throw new RangeError('BVH time slice must be a non-negative finite number');
  }
  let deadline = globalThis.performance.now() + timeSliceMilliseconds;
  return (progress, force = false) => {
    if (!force && globalThis.performance.now() < deadline) return null;
    return Promise.resolve()
      .then(() => yieldControl(progress))
      .then(() => {
        deadline = globalThis.performance.now() + timeSliceMilliseconds;
      });
  };
}

async function cooperativeBoundsForRange(
  order: readonly number[],
  triangleBounds: readonly Aabb[],
  start: number,
  end: number,
  progress: BvhBuildProgress,
  checkpoint: CooperativeCheckpoint
): Promise<MutableBounds> {
  const bounds = emptyBounds();
  for (let chunkStart = start; chunkStart < end; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(end, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let cursor = chunkStart; cursor < chunkEnd; cursor += 1) {
      const triangleIndex = order[cursor];
      const item = triangleIndex === undefined ? undefined : triangleBounds[triangleIndex];
      if (!item) throw new Error('Internal BVH order invariant failed');
      extendBounds(bounds, item);
    }
    const pending = checkpoint(progress);
    if (pending) await pending;
  }
  return bounds;
}

async function cooperativeCentroidBoundsForRange(
  order: readonly number[],
  centroids: readonly Vec3[],
  start: number,
  end: number,
  progress: BvhBuildProgress,
  checkpoint: CooperativeCheckpoint
): Promise<MutableBounds> {
  const bounds = emptyBounds();
  for (let chunkStart = start; chunkStart < end; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(end, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let cursor = chunkStart; cursor < chunkEnd; cursor += 1) {
      const triangleIndex = order[cursor];
      const centroid = triangleIndex === undefined ? undefined : centroids[triangleIndex];
      if (!centroid) throw new Error('Internal BVH centroid invariant failed');
      bounds.min = componentMin3(bounds.min, centroid);
      bounds.max = componentMax3(bounds.max, centroid);
    }
    const pending = checkpoint(progress);
    if (pending) await pending;
  }
  return bounds;
}

async function findSahSplitCooperatively(
  order: number[],
  triangleBounds: readonly Aabb[],
  centroids: readonly Vec3[],
  start: number,
  end: number,
  depth: number,
  progress: BvhBuildProgress,
  checkpoint: CooperativeCheckpoint
): Promise<SplitResult | null> {
  const centroidBounds = await cooperativeCentroidBoundsForRange(
    order,
    centroids,
    start,
    end,
    progress,
    checkpoint
  );
  let bestAxis = -1;
  let bestSplitBin = -1;
  let bestCost = Number.POSITIVE_INFINITY;

  for (let axis = 0; axis < 3; axis += 1) {
    const minimum = centroidBounds.min[axis] ?? 0;
    const extent = (centroidBounds.max[axis] ?? 0) - minimum;
    if (!(extent > 1e-12)) continue;

    const counts = new Uint32Array(BVH_SAH_BIN_COUNT);
    const binBounds = Array.from({length: BVH_SAH_BIN_COUNT}, emptyBounds);
    for (let chunkStart = start; chunkStart < end; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
      const chunkEnd = Math.min(end, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
      for (let cursor = chunkStart; cursor < chunkEnd; cursor += 1) {
        const triangleIndex = order[cursor];
        const centroid = triangleIndex === undefined ? undefined : centroids[triangleIndex];
        const bounds = triangleIndex === undefined ? undefined : triangleBounds[triangleIndex];
        if (!centroid || !bounds) throw new Error('Internal BVH bin invariant failed');
        const normalized = ((centroid[axis] ?? 0) - minimum) / extent;
        const bin = Math.min(BVH_SAH_BIN_COUNT - 1, Math.max(0, Math.floor(normalized * BVH_SAH_BIN_COUNT)));
        counts[bin] = (counts[bin] ?? 0) + 1;
        const target = binBounds[bin];
        if (!target) throw new Error('Internal BVH bin invariant failed');
        extendBounds(target, bounds);
      }
      const pending = checkpoint(progress);
      if (pending) await pending;
    }

    const leftCounts = new Uint32Array(BVH_SAH_BIN_COUNT - 1);
    const rightCounts = new Uint32Array(BVH_SAH_BIN_COUNT - 1);
    const leftAreas = new Float64Array(BVH_SAH_BIN_COUNT - 1);
    const rightAreas = new Float64Array(BVH_SAH_BIN_COUNT - 1);
    const leftBounds = emptyBounds();
    let leftCount = 0;
    for (let bin = 0; bin < BVH_SAH_BIN_COUNT - 1; bin += 1) {
      const bounds = binBounds[bin];
      if (!bounds) throw new Error('Internal BVH bin invariant failed');
      if ((counts[bin] ?? 0) > 0) extendBounds(leftBounds, bounds);
      leftCount += counts[bin] ?? 0;
      leftCounts[bin] = leftCount;
      leftAreas[bin] = leftCount === 0 ? 0 : surfaceArea(leftBounds);
    }
    const rightBounds = emptyBounds();
    let rightCount = 0;
    for (let bin = BVH_SAH_BIN_COUNT - 1; bin > 0; bin -= 1) {
      const bounds = binBounds[bin];
      if (!bounds) throw new Error('Internal BVH bin invariant failed');
      if ((counts[bin] ?? 0) > 0) extendBounds(rightBounds, bounds);
      rightCount += counts[bin] ?? 0;
      const split = bin - 1;
      rightCounts[split] = rightCount;
      rightAreas[split] = rightCount === 0 ? 0 : surfaceArea(rightBounds);
    }

    for (let split = 0; split < BVH_SAH_BIN_COUNT - 1; split += 1) {
      const left = leftCounts[split] ?? 0;
      const right = rightCounts[split] ?? 0;
      if (left === 0 || right === 0 || left > childCapacity(depth) || right > childCapacity(depth)) continue;
      const cost = (leftAreas[split] ?? 0) * left + (rightAreas[split] ?? 0) * right;
      if (cost < bestCost) {
        bestCost = cost;
        bestAxis = axis;
        bestSplitBin = split;
      }
    }
  }

  if (bestAxis < 0) return null;
  const minimum = centroidBounds.min[bestAxis] ?? 0;
  const extent = (centroidBounds.max[bestAxis] ?? 0) - minimum;
  const left: number[] = [];
  const right: number[] = [];
  for (let chunkStart = start; chunkStart < end; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(end, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let cursor = chunkStart; cursor < chunkEnd; cursor += 1) {
      const triangleIndex = order[cursor];
      if (triangleIndex === undefined) throw new Error('Internal BVH partition invariant failed');
      const centroid = centroids[triangleIndex];
      if (!centroid) throw new Error('Internal BVH partition invariant failed');
      const normalized = ((centroid[bestAxis] ?? 0) - minimum) / extent;
      const bin = Math.min(BVH_SAH_BIN_COUNT - 1, Math.max(0, Math.floor(normalized * BVH_SAH_BIN_COUNT)));
      (bin <= bestSplitBin ? left : right).push(triangleIndex);
    }
    const pending = checkpoint(progress);
    if (pending) await pending;
  }
  if (left.length === 0 || right.length === 0) return null;
  let destination = start;
  for (const partition of [left, right]) {
    for (let chunkStart = 0; chunkStart < partition.length; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
      const chunkEnd = Math.min(partition.length, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
      for (let index = chunkStart; index < chunkEnd; index += 1) {
        const triangleIndex = partition[index];
        if (triangleIndex === undefined) throw new Error('Internal BVH partition rewrite invariant failed');
        order[destination] = triangleIndex;
        destination += 1;
      }
      const pending = checkpoint(progress);
      if (pending) await pending;
    }
  }
  return {middle: start + left.length, leftCount: left.length, rightCount: right.length};
}

export async function buildBvhAsync(
  triangles: readonly FlatTriangle[],
  yieldControl: BvhBuildYield,
  options: BvhBuildAsyncOptions = {}
): Promise<Bvh> {
  if (triangles.length > MAX_SCENE_TRIANGLES) {
    throw new RangeError(`BVH supports at most ${MAX_SCENE_TRIANGLES.toLocaleString('en-US')} triangles`);
  }
  const total = triangles.length;
  const checkpoint = createCooperativeCheckpoint(
    yieldControl,
    options.timeSliceMilliseconds ?? DEFAULT_BVH_TIME_SLICE_MILLISECONDS
  );

  let pending = checkpoint({stage: 'validate', completed: 0, total}, true);
  if (pending) await pending;
  for (let chunkStart = 0; chunkStart < total; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(total, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const triangle = triangles[index];
      if (!triangle) throw new TypeError(`triangles[${index}] is missing`);
      validateTriangle(triangle, index);
    }
    pending = checkpoint({stage: 'validate', completed: chunkEnd, total});
    if (pending) await pending;
  }
  pending = checkpoint({stage: 'validate', completed: total, total}, true);
  if (pending) await pending;
  if (total === 0) {
    return {nodes: [], triangles: [], sourceOrder: new Uint32Array(), maxDepth: 0};
  }

  const triangleBounds = new Array<Aabb>(total);
  const centroids = new Array<Vec3>(total);
  const order = new Array<number>(total);
  pending = checkpoint({stage: 'bounds', completed: 0, total}, true);
  if (pending) await pending;
  for (let chunkStart = 0; chunkStart < total; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(total, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const triangle = triangles[index];
      if (!triangle) throw new TypeError(`triangles[${index}] is missing`);
      triangleBounds[index] = getTriangleBounds(triangle);
      centroids[index] = getTriangleCentroid(triangle);
      order[index] = index;
    }
    pending = checkpoint({stage: 'bounds', completed: chunkEnd, total});
    if (pending) await pending;
  }
  pending = checkpoint({stage: 'bounds', completed: total, total}, true);
  if (pending) await pending;

  const nodes: BvhNode[] = [makePlaceholder(0)];
  const stack: PendingBvhNode[] = [{nodeIndex: 0, start: 0, end: total, depth: 0}];
  let maximumDepth = 0;
  let processedNodes = 0;
  pending = checkpoint({stage: 'hierarchy', completed: 0, total}, true);
  if (pending) await pending;
  while (stack.length > 0) {
    const task = stack.pop();
    if (!task) throw new Error('Internal BVH task invariant failed');
    const count = task.end - task.start;
    const hierarchyProgress = Math.min(total - 1, processedNodes);
    const progress = {stage: 'hierarchy', completed: hierarchyProgress, total} as const;
    const bounds = await cooperativeBoundsForRange(
      order,
      triangleBounds,
      task.start,
      task.end,
      progress,
      checkpoint
    );
    maximumDepth = Math.max(maximumDepth, task.depth);
    if (count <= BVH_LEAF_TRIANGLE_LIMIT) {
      nodes[task.nodeIndex] = {...bounds, leftFirst: task.start, count, depth: task.depth};
    } else {
      if (task.depth >= BVH_MAX_DEPTH) {
        throw new RangeError(`Cannot build a BVH within depth ${BVH_MAX_DEPTH}`);
      }
      const split = await findSahSplitCooperatively(
        order,
        triangleBounds,
        centroids,
        task.start,
        task.end,
        task.depth,
        progress,
        checkpoint
      ) ?? medianSplit(order, centroids, task.start, task.end, task.depth);
      const leftIndex = nodes.length;
      nodes.push(makePlaceholder(task.depth + 1), makePlaceholder(task.depth + 1));
      nodes[task.nodeIndex] = {...bounds, leftFirst: leftIndex, count: 0, depth: task.depth};
      stack.push(
        {nodeIndex: leftIndex + 1, start: split.middle, end: task.end, depth: task.depth + 1},
        {nodeIndex: leftIndex, start: task.start, end: split.middle, depth: task.depth + 1}
      );
    }
    processedNodes += 1;
    pending = checkpoint({stage: 'hierarchy', completed: Math.min(total - 1, processedNodes), total});
    if (pending) await pending;
  }
  pending = checkpoint({stage: 'hierarchy', completed: total, total}, true);
  if (pending) await pending;

  const reordered = new Array<FlatTriangle>(total);
  pending = checkpoint({stage: 'reorder', completed: 0, total}, true);
  if (pending) await pending;
  for (let chunkStart = 0; chunkStart < total; chunkStart += BVH_COOPERATIVE_LOOP_CHUNK) {
    const chunkEnd = Math.min(total, chunkStart + BVH_COOPERATIVE_LOOP_CHUNK);
    for (let index = chunkStart; index < chunkEnd; index += 1) {
      const sourceIndex = order[index];
      const triangle = sourceIndex === undefined ? undefined : triangles[sourceIndex];
      if (!triangle) throw new Error('Internal BVH reorder invariant failed');
      reordered[index] = triangle;
    }
    pending = checkpoint({stage: 'reorder', completed: chunkEnd, total});
    if (pending) await pending;
  }
  pending = checkpoint({stage: 'reorder', completed: total, total}, true);
  if (pending) await pending;
  return {nodes, triangles: reordered, sourceOrder: Uint32Array.from(order), maxDepth: maximumDepth};
}

/** Throws when node topology, bounds, or leaf coverage is malformed. */
export function validateBvh(bvh: Bvh): void {
  if (bvh.triangles.length === 0) {
    if (bvh.nodes.length !== 0) throw new RangeError('An empty BVH cannot contain nodes');
    return;
  }
  if (bvh.nodes.length === 0) throw new RangeError('A non-empty BVH must have a root node');
  const covered = new Uint8Array(bvh.triangles.length);
  const visit = (nodeIndex: number, expectedDepth: number): void => {
    const node = bvh.nodes[nodeIndex];
    if (!node) throw new RangeError(`BVH node ${nodeIndex} is missing`);
    for (let axis = 0; axis < 3; axis += 1) {
      assertFiniteGpuNumber(node.min[axis] ?? Number.NaN, `bvh.nodes[${nodeIndex}].min[${axis}]`);
      assertFiniteGpuNumber(node.max[axis] ?? Number.NaN, `bvh.nodes[${nodeIndex}].max[${axis}]`);
      if ((node.min[axis] ?? 0) > (node.max[axis] ?? 0)) throw new RangeError(`BVH node ${nodeIndex} has inverted bounds`);
    }
    if (node.depth !== expectedDepth || node.depth > BVH_MAX_DEPTH) throw new RangeError(`BVH node ${nodeIndex} has invalid depth`);
    if (node.count > 0) {
      if (node.count > BVH_LEAF_TRIANGLE_LIMIT) throw new RangeError(`BVH leaf ${nodeIndex} is too large`);
      if (node.leftFirst + node.count > bvh.triangles.length) throw new RangeError(`BVH leaf ${nodeIndex} is out of range`);
      for (let index = node.leftFirst; index < node.leftFirst + node.count; index += 1) {
        if (covered[index] !== 0) throw new RangeError(`BVH triangle ${index} is covered more than once`);
        covered[index] = 1;
      }
      return;
    }
    if (node.leftFirst <= nodeIndex || node.leftFirst + 1 >= bvh.nodes.length) {
      throw new RangeError(`BVH interior node ${nodeIndex} has invalid consecutive children`);
    }
    visit(node.leftFirst, expectedDepth + 1);
    visit(node.leftFirst + 1, expectedDepth + 1);
  };
  visit(0, 0);
  if (covered.some(value => value === 0)) throw new RangeError('BVH leaves do not cover every triangle');
}
