import {add3, cross3, dot3, lengthSquared3, multiply3, subtract3} from './math';
import type {Aabb, Bvh, FlatTriangle, Ray, RayHit, Vec3} from './types';
import {assertFiniteGpuNumber, validateVec3} from './validation';

const PARALLEL_EPSILON = 1e-12;
const HIT_TIE_EPSILON = 1e-10;

interface ValidatedRay {
  readonly origin: Vec3;
  readonly direction: Vec3;
  readonly tMin: number;
  readonly tMax: number;
}

function validateRay(ray: Ray): ValidatedRay {
  if (!ray || typeof ray !== 'object') throw new TypeError('ray must be an object');
  const origin = validateVec3(ray.origin, 'ray.origin');
  const direction = validateVec3(ray.direction, 'ray.direction');
  if (lengthSquared3(direction) <= 1e-20) throw new RangeError('ray.direction must have non-zero length');
  const tMin = ray.tMin ?? 1e-4;
  const tMax = ray.tMax ?? Number.POSITIVE_INFINITY;
  assertFiniteGpuNumber(tMin, 'ray.tMin');
  if (Number.isNaN(tMax) || tMax === Number.NEGATIVE_INFINITY) {
    throw new TypeError('ray.tMax must be finite or positive infinity');
  }
  if (tMax !== Number.POSITIVE_INFINITY) assertFiniteGpuNumber(tMax, 'ray.tMax');
  if (tMax < tMin) throw new RangeError('ray.tMax must be greater than or equal to ray.tMin');
  return {origin, direction, tMin, tMax};
}

function intersectBounds(ray: ValidatedRay, bounds: Aabb, maximumDistance: number): number | null {
  let near = ray.tMin;
  let far = Math.min(ray.tMax, maximumDistance);
  for (let axis = 0; axis < 3; axis += 1) {
    const origin = ray.origin[axis] ?? 0;
    const direction = ray.direction[axis] ?? 0;
    const minimum = bounds.min[axis] ?? 0;
    const maximum = bounds.max[axis] ?? 0;
    if (Math.abs(direction) <= PARALLEL_EPSILON) {
      if (origin < minimum || origin > maximum) return null;
      continue;
    }
    const inverse = 1 / direction;
    let first = (minimum - origin) * inverse;
    let second = (maximum - origin) * inverse;
    if (first > second) [first, second] = [second, first];
    near = Math.max(near, first);
    far = Math.min(far, second);
    if (far < near) return null;
  }
  return near;
}

function intersectTriangleValidated(
  ray: ValidatedRay,
  triangle: FlatTriangle,
  triangleIndex: number,
  maximumDistance: number
): RayHit | null {
  const p = cross3(ray.direction, triangle.edge2);
  const determinant = dot3(triangle.edge1, p);
  if (Math.abs(determinant) <= PARALLEL_EPSILON) return null;
  const inverseDeterminant = 1 / determinant;
  const fromV0 = subtract3(ray.origin, triangle.v0);
  const u = dot3(fromV0, p) * inverseDeterminant;
  if (u < 0 || u > 1) return null;
  const q = cross3(fromV0, triangle.edge1);
  const v = dot3(ray.direction, q) * inverseDeterminant;
  if (v < 0 || u + v > 1) return null;
  const distance = dot3(triangle.edge2, q) * inverseDeterminant;
  if (distance < ray.tMin || distance > ray.tMax || distance > maximumDistance) return null;
  return {
    distance,
    triangleIndex,
    barycentric: [1 - u - v, u, v],
    position: add3(ray.origin, multiply3(ray.direction, distance)),
    normal: triangle.normal,
    materialIndex: triangle.materialIndex
  };
}

function preferHit(candidate: RayHit, current: RayHit | null): boolean {
  if (!current) return true;
  if (candidate.distance < current.distance - HIT_TIE_EPSILON) return true;
  return Math.abs(candidate.distance - current.distance) <= HIT_TIE_EPSILON
    && candidate.triangleIndex < current.triangleIndex;
}

export function intersectRayTriangle(ray: Ray, triangle: FlatTriangle, triangleIndex = 0): RayHit | null {
  return intersectTriangleValidated(validateRay(ray), triangle, triangleIndex, ray.tMax ?? Number.POSITIVE_INFINITY);
}

export function intersectRayBruteForce(ray: Ray, triangles: readonly FlatTriangle[]): RayHit | null {
  const validated = validateRay(ray);
  let closest: RayHit | null = null;
  for (let index = 0; index < triangles.length; index += 1) {
    const triangle = triangles[index];
    if (!triangle) continue;
    const candidate = intersectTriangleValidated(validated, triangle, index, closest?.distance ?? validated.tMax);
    if (candidate && preferHit(candidate, closest)) closest = candidate;
  }
  return closest;
}

export function intersectRayBvh(ray: Ray, bvh: Bvh): RayHit | null {
  if (bvh.nodes.length === 0 || bvh.triangles.length === 0) return null;
  const validated = validateRay(ray);
  const root = bvh.nodes[0];
  if (!root || intersectBounds(validated, root, validated.tMax) === null) return null;
  const stack: number[] = [0];
  let closest: RayHit | null = null;

  while (stack.length > 0) {
    const nodeIndex = stack.pop();
    if (nodeIndex === undefined) break;
    const node = bvh.nodes[nodeIndex];
    if (!node) throw new RangeError(`BVH node ${nodeIndex} is missing`);
    const maximumDistance = closest?.distance ?? validated.tMax;
    if (intersectBounds(validated, node, maximumDistance) === null) continue;

    if (node.count > 0) {
      const end = node.leftFirst + node.count;
      for (let triangleIndex = node.leftFirst; triangleIndex < end; triangleIndex += 1) {
        const triangle = bvh.triangles[triangleIndex];
        if (!triangle) throw new RangeError(`BVH triangle ${triangleIndex} is missing`);
        const candidate = intersectTriangleValidated(
          validated,
          triangle,
          triangleIndex,
          closest?.distance ?? validated.tMax
        );
        if (candidate && preferHit(candidate, closest)) closest = candidate;
      }
      continue;
    }

    const leftIndex = node.leftFirst;
    const rightIndex = leftIndex + 1;
    const left = bvh.nodes[leftIndex];
    const right = bvh.nodes[rightIndex];
    if (!left || !right) throw new RangeError(`BVH node ${nodeIndex} has missing children`);
    const limit = closest?.distance ?? validated.tMax;
    const leftDistance = intersectBounds(validated, left, limit);
    const rightDistance = intersectBounds(validated, right, limit);
    if (leftDistance !== null && rightDistance !== null) {
      if (leftDistance <= rightDistance) {
        stack.push(rightIndex, leftIndex);
      } else {
        stack.push(leftIndex, rightIndex);
      }
    } else if (leftDistance !== null) {
      stack.push(leftIndex);
    } else if (rightDistance !== null) {
      stack.push(rightIndex);
    }
  }

  return closest;
}
