import type {
  ModelComplexity,
  ModelDetailBudget,
  ModelDetailBudgetInput,
  ModelDetailPreset,
  ModelLodCandidate,
  PlannedGrid,
  PlannedUvSphere
} from './types';
import {HARD_MODEL_LIMITS} from './types';

const MAX_REQUESTED_SUBDIVISIONS = 1_000_000;

export const MODEL_DETAIL_PRESETS: Readonly<Record<ModelDetailPreset, ModelDetailBudget>> = Object.freeze({
  preview: Object.freeze({
    maxVertices: 12_288,
    maxTriangles: 4_096,
    maxSourceBytes: 4 * 1024 * 1024,
    maxPolygonVertices: 256
  }),
  realtime: Object.freeze({
    maxVertices: 98_304,
    maxTriangles: 32_768,
    maxSourceBytes: 24 * 1024 * 1024,
    maxPolygonVertices: 1_024
  }),
  quality: Object.freeze({
    maxVertices: 393_216,
    maxTriangles: 131_072,
    maxSourceBytes: 64 * 1024 * 1024,
    maxPolygonVertices: 2_048
  }),
  cinematic: Object.freeze({...HARD_MODEL_LIMITS})
});

function boundedInteger(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be an integer from ${minimum} through ${maximum}`);
  }
  return value;
}

export function resolveModelBudget(input: ModelDetailBudgetInput = 'cinematic'): ModelDetailBudget {
  if (typeof input === 'string') {
    const preset = MODEL_DETAIL_PRESETS[input] as ModelDetailBudget | undefined;
    if (!preset) throw new RangeError(`Unknown model detail preset: ${input}`);
    return {...preset};
  }
  if (!input || typeof input !== 'object') throw new TypeError('model budget must be a detail preset or object');
  return {
    maxVertices: boundedInteger(input.maxVertices ?? HARD_MODEL_LIMITS.maxVertices, 3, HARD_MODEL_LIMITS.maxVertices, 'budget.maxVertices'),
    maxTriangles: boundedInteger(input.maxTriangles ?? HARD_MODEL_LIMITS.maxTriangles, 1, HARD_MODEL_LIMITS.maxTriangles, 'budget.maxTriangles'),
    maxSourceBytes: boundedInteger(input.maxSourceBytes ?? HARD_MODEL_LIMITS.maxSourceBytes, 1, HARD_MODEL_LIMITS.maxSourceBytes, 'budget.maxSourceBytes'),
    maxPolygonVertices: boundedInteger(
      input.maxPolygonVertices ?? HARD_MODEL_LIMITS.maxPolygonVertices,
      3,
      HARD_MODEL_LIMITS.maxPolygonVertices,
      'budget.maxPolygonVertices'
    )
  };
}

export function assertWithinModelBudget(
  complexity: ModelComplexity,
  budgetInput: ModelDetailBudgetInput = 'cinematic',
  label = 'model'
): void {
  const budget = resolveModelBudget(budgetInput);
  const vertexCount = boundedInteger(complexity.vertexCount, 0, Number.MAX_SAFE_INTEGER, `${label}.vertexCount`);
  const triangleCount = boundedInteger(complexity.triangleCount, 0, Number.MAX_SAFE_INTEGER, `${label}.triangleCount`);
  if (vertexCount > budget.maxVertices) {
    throw new RangeError(`${label} requires ${vertexCount} vertices, exceeding the budget of ${budget.maxVertices}`);
  }
  if (triangleCount > budget.maxTriangles) {
    throw new RangeError(`${label} requires ${triangleCount} triangles, exceeding the budget of ${budget.maxTriangles}`);
  }
}

export function estimateMeshCpuBytes(
  complexity: ModelComplexity,
  includeNormals = true,
  includeWindWeights = false,
  includeUvs = true
): number {
  const positions = complexity.vertexCount * 3 * Float32Array.BYTES_PER_ELEMENT;
  const normals = includeNormals ? positions : 0;
  const uvs = includeUvs ? complexity.vertexCount * 2 * Float32Array.BYTES_PER_ELEMENT : 0;
  const windWeights = includeWindWeights ? complexity.vertexCount * Float32Array.BYTES_PER_ELEMENT : 0;
  const indices = complexity.triangleCount * 3 * Uint32Array.BYTES_PER_ELEMENT;
  const total = positions + normals + uvs + windWeights + indices;
  if (!Number.isSafeInteger(total)) throw new RangeError('mesh byte estimate exceeds the safe integer range');
  return total;
}

function sphereComplexity(segments: number, rings: number): ModelComplexity {
  return {
    vertexCount: 2 + (segments + 1) * (rings - 1),
    triangleCount: 2 * segments * (rings - 1)
  };
}

function gridComplexity(xSegments: number, zSegments: number): ModelComplexity {
  return {
    vertexCount: (xSegments + 1) * (zSegments + 1),
    triangleCount: 2 * xSegments * zSegments
  };
}

function fitPair(
  first: number,
  second: number,
  firstMinimum: number,
  secondMinimum: number,
  budget: ModelDetailBudget,
  getComplexity: (first: number, second: number) => ModelComplexity
): readonly [number, number] {
  const requested = getComplexity(first, second);
  const triangleScale = Math.sqrt(budget.maxTriangles / Math.max(1, requested.triangleCount));
  const vertexScale = Math.sqrt(budget.maxVertices / Math.max(1, requested.vertexCount));
  const scale = Math.min(1, triangleScale, vertexScale);
  let fittedFirst = Math.max(firstMinimum, Math.floor(first * scale));
  let fittedSecond = Math.max(secondMinimum, Math.floor(second * scale));

  while (true) {
    const complexity = getComplexity(fittedFirst, fittedSecond);
    if (complexity.vertexCount <= budget.maxVertices && complexity.triangleCount <= budget.maxTriangles) break;
    const firstRatio = fittedFirst / first;
    const secondRatio = fittedSecond / second;
    if (fittedFirst > firstMinimum && (firstRatio >= secondRatio || fittedSecond === secondMinimum)) fittedFirst -= 1;
    else if (fittedSecond > secondMinimum) fittedSecond -= 1;
    else throw new RangeError('model budget cannot fit the minimum supported detail');
  }
  return [fittedFirst, fittedSecond];
}

export function planUvSphereDetail(
  segments = 64,
  rings = 32,
  budgetInput: ModelDetailBudgetInput = 'cinematic',
  overflow: 'error' | 'fit' = 'error'
): PlannedUvSphere {
  const requestedSegments = boundedInteger(segments, 3, MAX_REQUESTED_SUBDIVISIONS, 'sphere.segments');
  const requestedRings = boundedInteger(rings, 2, MAX_REQUESTED_SUBDIVISIONS, 'sphere.rings');
  const budget = resolveModelBudget(budgetInput);
  const requested = sphereComplexity(requestedSegments, requestedRings);
  let actualSegments = requestedSegments;
  let actualRings = requestedRings;
  if (requested.vertexCount > budget.maxVertices || requested.triangleCount > budget.maxTriangles) {
    if (overflow === 'error') assertWithinModelBudget(requested, budget, 'UV sphere');
    else [actualSegments, actualRings] = fitPair(requestedSegments, requestedRings, 3, 2, budget, sphereComplexity);
  }
  const actual = sphereComplexity(actualSegments, actualRings);
  return {
    requestedSegments,
    requestedRings,
    segments: actualSegments,
    rings: actualRings,
    reduced: actualSegments !== requestedSegments || actualRings !== requestedRings,
    ...actual
  };
}

export function planGridDetail(
  xSegments = 64,
  zSegments = 64,
  budgetInput: ModelDetailBudgetInput = 'cinematic',
  overflow: 'error' | 'fit' = 'error'
): PlannedGrid {
  const requestedXSegments = boundedInteger(xSegments, 1, MAX_REQUESTED_SUBDIVISIONS, 'grid.xSegments');
  const requestedZSegments = boundedInteger(zSegments, 1, MAX_REQUESTED_SUBDIVISIONS, 'grid.zSegments');
  const budget = resolveModelBudget(budgetInput);
  const requested = gridComplexity(requestedXSegments, requestedZSegments);
  let actualXSegments = requestedXSegments;
  let actualZSegments = requestedZSegments;
  if (requested.vertexCount > budget.maxVertices || requested.triangleCount > budget.maxTriangles) {
    if (overflow === 'error') assertWithinModelBudget(requested, budget, 'heightfield grid');
    else [actualXSegments, actualZSegments] = fitPair(requestedXSegments, requestedZSegments, 1, 1, budget, gridComplexity);
  }
  const actual = gridComplexity(actualXSegments, actualZSegments);
  return {
    requestedXSegments,
    requestedZSegments,
    xSegments: actualXSegments,
    zSegments: actualZSegments,
    reduced: actualXSegments !== requestedXSegments || actualZSegments !== requestedZSegments,
    ...actual
  };
}

export function selectModelLod<T>(
  candidates: readonly ModelLodCandidate<T>[],
  distance: number,
  budgetInput: ModelDetailBudgetInput = 'cinematic'
): ModelLodCandidate<T> {
  if (!Number.isFinite(distance) || distance < 0) throw new RangeError('LOD distance must be a finite non-negative number');
  if (candidates.length === 0) throw new RangeError('At least one LOD candidate is required');
  const budget = resolveModelBudget(budgetInput);
  let previousLevel = -1;
  let previousDistance = Number.POSITIVE_INFINITY;
  const fitting: ModelLodCandidate<T>[] = [];
  for (let index = 0; index < candidates.length; index += 1) {
    const candidate = candidates[index];
    if (!candidate) throw new TypeError(`LOD candidate ${index} is missing`);
    boundedInteger(candidate.level, 0, Number.MAX_SAFE_INTEGER, `LOD candidate ${index}.level`);
    boundedInteger(candidate.vertexCount, 0, Number.MAX_SAFE_INTEGER, `LOD candidate ${index}.vertexCount`);
    boundedInteger(candidate.triangleCount, 0, Number.MAX_SAFE_INTEGER, `LOD candidate ${index}.triangleCount`);
    if (candidate.level <= previousLevel) throw new RangeError('LOD candidate levels must be strictly increasing');
    if ((!Number.isFinite(candidate.maxDistance) && candidate.maxDistance !== Number.POSITIVE_INFINITY) || candidate.maxDistance < 0) {
      throw new RangeError(`LOD candidate ${index}.maxDistance must be non-negative or Infinity`);
    }
    if (candidate.maxDistance > previousDistance) throw new RangeError('LOD maximum distances must be non-increasing as detail rises');
    previousLevel = candidate.level;
    previousDistance = candidate.maxDistance;
    if (candidate.vertexCount <= budget.maxVertices && candidate.triangleCount <= budget.maxTriangles) fitting.push(candidate);
  }
  if (fitting.length === 0) throw new RangeError('No LOD candidate fits the model detail budget');

  let requested: ModelLodCandidate<T> | undefined;
  for (const candidate of fitting) {
    if (distance <= candidate.maxDistance) requested = candidate;
  }
  return requested ?? (fitting[0] as ModelLodCandidate<T>);
}
