import type {MeshDefinition, Vec3} from '../scene';
import {planGridDetail} from './budget';
import {calculateSmoothNormals} from './normals';
import type {FractalTerrainOptions, HeightfieldOptions} from './types';

function finiteNumber(value: number, label: string): number {
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value))) {
    throw new RangeError(`${label} must be a finite 32-bit number`);
  }
  return value;
}

function positive(value: number, label: string): number {
  finiteNumber(value, label);
  if (value <= 0) throw new RangeError(`${label} must be greater than zero`);
  return value;
}

function center(value: Vec3 | undefined): Vec3 {
  const result = value ?? [0, 0, 0];
  if (result.length !== 3) throw new TypeError('terrain.center must have exactly three components');
  return [finiteNumber(result[0], 'terrain.center[0]'), finiteNumber(result[1], 'terrain.center[1]'), finiteNumber(result[2], 'terrain.center[2]')];
}

function createGrid(
  width: number,
  depth: number,
  xSegments: number,
  zSegments: number,
  origin: Vec3,
  sample: (xIndex: number, zIndex: number, xRatio: number, zRatio: number) => number
): MeshDefinition {
  const columns = xSegments + 1;
  const rows = zSegments + 1;
  const positions = new Float32Array(columns * rows * 3);
  const uvs = new Float32Array(columns * rows * 2);
  let offset = 0;
  for (let z = 0; z < rows; z += 1) {
    const zRatio = z / zSegments;
    for (let x = 0; x < columns; x += 1) {
      const xRatio = x / xSegments;
      positions[offset] = origin[0] + (xRatio - 0.5) * width;
      positions[offset + 1] = origin[1] + finiteNumber(sample(x, z, xRatio, zRatio), `terrain height (${x}, ${z})`);
      positions[offset + 2] = origin[2] + (zRatio - 0.5) * depth;
      const uvOffset = (z * columns + x) * 2;
      uvs[uvOffset] = xRatio;
      uvs[uvOffset + 1] = zRatio;
      offset += 3;
    }
  }
  const indices = new Uint32Array(xSegments * zSegments * 6);
  offset = 0;
  for (let z = 0; z < zSegments; z += 1) {
    for (let x = 0; x < xSegments; x += 1) {
      const a = z * columns + x;
      const b = a + 1;
      const c = a + columns;
      const d = c + 1;
      indices[offset] = a;
      indices[offset + 1] = c;
      indices[offset + 2] = b;
      indices[offset + 3] = b;
      indices[offset + 4] = c;
      indices[offset + 5] = d;
      offset += 6;
    }
  }
  return {positions, indices, normals: calculateSmoothNormals(positions, indices), uvs};
}

export function createHeightfield(options: HeightfieldOptions): MeshDefinition {
  if (!options || typeof options !== 'object') throw new TypeError('heightfield options must be an object');
  const width = positive(options.width ?? 10, 'terrain.width');
  const depth = positive(options.depth ?? 10, 'terrain.depth');
  const plan = planGridDetail(options.xSegments ?? 64, options.zSegments ?? 64, options.budget, options.overflow ?? 'error');
  const origin = center(options.center);
  if (typeof options.heights === 'function') {
    const heightFunction = options.heights;
    return createGrid(width, depth, plan.xSegments, plan.zSegments, origin, (x, z) => heightFunction(x, z));
  }
  if (!options.heights || typeof options.heights !== 'object' || !Number.isSafeInteger(options.heights.length)) {
    throw new TypeError('terrain.heights must be an array-like collection or function');
  }
  const required = plan.vertexCount;
  if (options.heights.length !== required) {
    if (plan.reduced) {
      throw new RangeError(`terrain.heights must contain ${required} values after fitted grid reduction; use a height function when overflow is "fit"`);
    }
    throw new RangeError(`terrain.heights must contain exactly ${required} values`);
  }
  const heights = options.heights;
  return createGrid(width, depth, plan.xSegments, plan.zSegments, origin, (x, z) => {
    const value = heights[z * (plan.xSegments + 1) + x];
    if (value === undefined) throw new TypeError(`terrain.heights[${z * (plan.xSegments + 1) + x}] is missing`);
    return value;
  });
}

function hashSeed(seed: number | string): number {
  if (typeof seed === 'number') {
    if (!Number.isFinite(seed)) throw new RangeError('terrain.seed must be finite');
    return (Math.trunc(seed) >>> 0) || 0x9e3779b9;
  }
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function lattice(seed: number, x: number, z: number): number {
  let hash = seed ^ Math.imul(x, 0x1f123bb5) ^ Math.imul(z, 0x5f356495);
  hash = Math.imul(hash ^ (hash >>> 16), 0x7feb352d);
  hash = Math.imul(hash ^ (hash >>> 15), 0x846ca68b);
  hash ^= hash >>> 16;
  return (hash >>> 0) / 0xffffffff * 2 - 1;
}

function smootherStep(value: number): number {
  return value * value * value * (value * (value * 6 - 15) + 10);
}

function valueNoise(seed: number, x: number, z: number): number {
  const x0 = Math.floor(x);
  const z0 = Math.floor(z);
  const tx = smootherStep(x - x0);
  const tz = smootherStep(z - z0);
  const a = lattice(seed, x0, z0);
  const b = lattice(seed, x0 + 1, z0);
  const c = lattice(seed, x0, z0 + 1);
  const d = lattice(seed, x0 + 1, z0 + 1);
  const top = a + (b - a) * tx;
  const bottom = c + (d - c) * tx;
  return top + (bottom - top) * tz;
}

export function createFractalTerrain(options: FractalTerrainOptions = {}): MeshDefinition {
  const width = positive(options.width ?? 50, 'terrain.width');
  const depth = positive(options.depth ?? 50, 'terrain.depth');
  const heightScale = finiteNumber(options.heightScale ?? 6, 'terrain.heightScale');
  const baseHeight = finiteNumber(options.baseHeight ?? 0, 'terrain.baseHeight');
  const frequency = positive(options.frequency ?? 2, 'terrain.frequency');
  const octaves = options.octaves ?? 6;
  if (!Number.isSafeInteger(octaves) || octaves < 1 || octaves > 12) throw new RangeError('terrain.octaves must be an integer from 1 through 12');
  const persistence = finiteNumber(options.persistence ?? 0.5, 'terrain.persistence');
  if (persistence < 0 || persistence > 1) throw new RangeError('terrain.persistence must be from 0 through 1');
  const lacunarity = finiteNumber(options.lacunarity ?? 2, 'terrain.lacunarity');
  if (lacunarity < 1 || lacunarity > 8) throw new RangeError('terrain.lacunarity must be from 1 through 8');
  const plan = planGridDetail(options.xSegments ?? 64, options.zSegments ?? 64, options.budget, options.overflow ?? 'error');
  const origin = center(options.center);
  const seed = hashSeed(options.seed ?? 1);
  return createGrid(width, depth, plan.xSegments, plan.zSegments, origin, (_x, _z, xRatio, zRatio) => {
    let amplitude = 1;
    let octaveFrequency = frequency;
    let total = 0;
    let normalization = 0;
    for (let octave = 0; octave < octaves; octave += 1) {
      total += valueNoise((seed + Math.imul(octave, 0x9e3779b9)) >>> 0, xRatio * octaveFrequency, zRatio * octaveFrequency) * amplitude;
      normalization += amplitude;
      amplitude *= persistence;
      octaveFrequency *= lacunarity;
    }
    return baseHeight + (normalization > 0 ? total / normalization : 0) * heightScale;
  });
}
