export type Vec3 = readonly [number, number, number];
export type RGB = readonly [number, number, number];

export type RenderMode = 'ray-trace' | 'path-trace' | 'raster';
export type FrameBackend =
  | 'none'
  | 'gpu-compute-ray-trace'
  | 'gpu-compute-path-trace'
  | 'gpu-rasterization';
export type AntiAliasingMode =
  | 'none'
  | 'fxaa'
  | 'temporal'
  | 'ssaa-2x'
  | 'ssaa-4x';
export type ToneMappingMode = 'aces' | 'reinhard' | 'linear';
export type DenoisingMode = 'off' | 'fast' | 'quality';
export type ExperimentalLearnedEnhancementMode =
  | 'off'
  | 'quality-gated'
  | 'quality-gated-2x';
export type ExperimentalLearnedEnhancementPreset =
  | 'balanced'
  | 'photoreal-detail'
  | 'artifact-cleanup';
export type UpscalingMode =
  | 'native'
  | 'fsr1-quality'
  | 'fsr1-balanced'
  | 'fsr1-performance'
  | 'fsr3-experimental-native-aa'
  | 'fsr3-experimental-quality'
  | 'fsr3-experimental-balanced'
  | 'fsr3-experimental-performance';
export type FrameGenerationMode = 'off' | 'fsr3-experimental';
export type HDROutputMode = 'sdr' | 'auto' | 'hdr';
export type OutputResolutionMode = 'stage' | 'custom';
export type TextureAnisotropyLevel = 2 | 4 | 6 | 8 | 10 | 12 | 14 | 16;
export type OutputStyleMode = 'photoreal' | 'toon' | 'pixel-art' | 'monochrome';
export type PixelPaletteMode = 'rgb-332' | 'pico-8' | 'gameboy' | 'grayscale-8';

/** Supported photographic aperture range for the GPU thin-lens camera. */
export const CAMERA_F_STOP_RANGE = Object.freeze({minimum: 1, maximum: 25});

export interface OutputStyleSettings {
  mode: OutputStyleMode;
  /** Number of diffuse-looking luminance bands used by the toon finish. */
  toonBands: number;
  /** Normal/depth outline opacity used by the toon finish. */
  toonOutlineStrength: number;
  /** Width and height of one logical pixel in output pixels. */
  pixelSize: number;
  pixelPalette: PixelPaletteMode;
  /** Ordered 4x4 Bayer dither strength. Zero disables dithering. */
  pixelDitherStrength: number;
  monochromeTint: RGB;
  monochromeContrast: number;
}

export interface TextureAnisotropyStatus {
  requestedMaxAnisotropy: TextureAnisotropyLevel;
  /** Value submitted to the active sampler, or zero before GPU initialization. */
  submittedMaxAnisotropy: number;
  /** Optional implementation-specific limit when the host exposes one. */
  reportedMaxAnisotropy: number | null;
  anisotropyFallbackActive: boolean;
}

export const DEFAULT_OUTPUT_STYLE_SETTINGS: Readonly<OutputStyleSettings> = Object.freeze({
  mode: 'photoreal',
  toonBands: 5,
  toonOutlineStrength: 0.7,
  pixelSize: 4,
  pixelPalette: 'rgb-332',
  pixelDitherStrength: 0,
  monochromeTint: Object.freeze([1, 1, 1] as const),
  monochromeContrast: 1
});

export interface OutputResolutionSettings {
  mode: OutputResolutionMode;
  width: number;
  height: number;
}

export interface CameraSettings {
  position: Vec3;
  target: Vec3;
  verticalFovDegrees: number;
}

export interface AmbientWindSettings {
  enabled: boolean;
  /** Maximum animated displacement in world units. */
  strength: number;
  /** Animation rate multiplier. */
  speed: number;
  /** Horizontal direction in degrees, where zero points toward +X. */
  directionDegrees: number;
  /** Secondary gust/noise strength in the inclusive range `[0, 1]`. */
  turbulence: number;
}

export interface SphereDefinition {
  center: Vec3;
  radius: number;
  color: RGB;
  roughness: number;
  metallic: number;
  emission: number;
}

export interface RenderSettings {
  mode: RenderMode;
  outputStyle: OutputStyleSettings;
  antiAliasing: AntiAliasingMode;
  toneMapping: ToneMappingMode;
  renderScale: number;
  /**
   * Enables ray-footprint mip selection for material textures. Per-material
   * texture LOD remains a minimum while enabled and the requested level
   * otherwise. Resource limits and guarded atlas tiles can lower either value.
   */
  automaticTextureLod: boolean;
  samplesPerFrame: number;
  /** Minimum path depth before Russian roulette may terminate a surviving path. */
  minBounces: number;
  maxBounces: number;
  /** Number of stochastic direct-light paths evaluated at each surface bounce. */
  lightSamples: number;
  rayDiffuseWeight: number;
  rayGlossyWeight: number;
  rayTransparentWeight: number;
  rayVolumeWeight: number;
  /** Relative per-pixel convergence threshold; zero disables adaptive convergence. */
  noiseThreshold: number;
  convergenceMinSamples: number;
  exposure: number;
  /**
   * Photographic lens f-number in the inclusive range f/1 through f/25.
   * Ray and path tracing use a 24 mm-high full-frame sensor model and focus
   * on the current camera target. Rasterization remains a pinhole camera.
   */
  cameraFStop: number;
  /** Linear sensor-channel gains applied after bloom and before exposure. */
  cameraWhiteBalance: RGB;
  /** Display-only luminance lift for dark SDR ACES regions, measured in stops. */
  cameraShadowLiftStops: number;
  /** Display-only logarithmic highlight protection for SDR ACES output. */
  cameraHighlightProtection: number;
  fogDensity: number;
  fogColor: RGB;
  fogHeightFalloff: number;
  fogAnisotropy: number;
  volumetricSteps: number;
  denoising: DenoisingMode;
  /** Opt-in, conservatively gated learned filter. Off is the production default. */
  experimentalLearnedEnhancement: ExperimentalLearnedEnhancementMode;
  /** Conservative tuning profile for the fixed learned filter. */
  experimentalLearnedEnhancementPreset: ExperimentalLearnedEnhancementPreset;
  upscaling: UpscalingMode;
  frameGeneration: FrameGenerationMode;
  bloomStrength: number;
  bloomThreshold: number;
  /** Fractional, zero-mean midtone modulation; zero disables film grain. */
  filmGrainStrength: number;
  /** Approximate film-grain cell size in output pixels. */
  filmGrainScale: number;
  /** Maximum radial red/blue displacement in output pixels; zero disables the effect. */
  chromaticAberrationPixels: number;
  /** Normalized diagonal radius at which chromatic separation begins. */
  chromaticAberrationEdgeStart: number;
  /** Normalized radial distance over which chromatic separation reaches full strength. */
  chromaticAberrationFalloff: number;
  autoExposure: boolean;
  hdrOutput: HDROutputMode;
  /** Opt-in energy matching between a captured HDR sun and the primary aligned directional light. */
  hdrEnvironmentSunMatching: boolean;
}

export interface RendererCapabilities {
  secureContext: boolean;
  webGPU: boolean;
  adapter: boolean;
  device: boolean;
  fallbackAdapter: boolean | null;
  hdrCanvas: boolean;
  gpuComputeRayTracing: boolean;
  /** A compiled WebGPU graphics pipeline, distinct from the compute tracers. */
  gpuRasterization: boolean;
  /** Known feature boundaries of the forward raster path. */
  rasterizationLimitations: readonly string[];
  nativeRayTracing: boolean;
  dlss: boolean;
  dlaa: boolean;
  fsr1: boolean;
  fsr3Experimental: boolean;
  features: readonly string[];
  wgslLanguageFeatures: readonly string[];
  limits: Readonly<Record<string, number>>;
  unavailable: readonly string[];
}

export type RendererState =
  | 'idle'
  | 'initializing'
  | 'ready'
  | 'running'
  | 'unsupported'
  | 'lost'
  | 'destroyed'
  | 'error';

export interface RendererStatus {
  state: RendererState;
  message: string;
  sampleCount: number;
  width: number;
  height: number;
  outputWidth: number;
  outputHeight: number;
  effectiveRenderScale: number;
  resolutionMode: OutputResolutionMode;
  requestedOutputWidth: number;
  requestedOutputHeight: number;
  estimatedTextureBytes: number;
  triangles: number;
  triangleBudget: number;
  bvhNodes: number;
  materials: number;
  lights: number;
  generatedFrames: number;
  /** Successfully submitted frames produced by the WebGPU graphics raster pipeline. */
  rasterFrames: number;
  /** Frames that dispatched the opt-in fixed learned compute pass. */
  learnedEnhancementDispatches: number;
  /** True only after the GPU post pipeline containing the learned pass has been created. */
  learnedEnhancementPipelineReady: boolean;
  lastLearnedEnhancementMode: ExperimentalLearnedEnhancementMode;
  lastFrameBackend: FrameBackend;
  measuredFps: number;
  cameraLens: CameraLensStatus;
  cameraWhiteBalance: RGB;
  outputStyle: OutputStyleSettings;
  textureAnisotropy: TextureAnisotropyStatus;
  capabilities: RendererCapabilities;
}

export interface CameraLensStatus {
  /** Configured photographic aperture. */
  fStop: number;
  /** Distance from camera position to its target in scene meters. */
  focusDistanceMeters: number;
  /** Focal length implied by the vertical field of view on a 24 mm-high sensor. */
  focalLengthMillimeters: number;
  /** Physical entrance-pupil diameter derived from focal length / f-number. */
  apertureDiameterMillimeters: number;
  /** Compute tracing uses the thin lens; rasterization intentionally stays pinhole. */
  backend: 'gpu-thin-lens' | 'raster-pinhole';
}

export interface StageHost {
  stageCanvas: HTMLCanvasElement;
  runtime?: {
    on?(event: string, listener: (...args: unknown[]) => void): void;
    off?(event: string, listener: (...args: unknown[]) => void): void;
  };
}

