import {
  CanvasVideoRecorder,
  type FinishedVideoRecording,
  type VideoCodecPreference,
  type VideoRecordingMode
} from '../video';
import {WebGPURenderer} from '../renderer/webgpu-renderer';

export type PerformanceProfile = 'realtime-61-plus' | 'balanced' | 'cinematic';

const REALTIME_QUALITY_LEVELS = [
  {upscaling: 'fsr3-experimental-quality' as const, renderScale: 1},
  {upscaling: 'fsr3-experimental-balanced' as const, renderScale: 1},
  {upscaling: 'fsr3-experimental-performance' as const, renderScale: 1},
  {upscaling: 'fsr3-experimental-performance' as const, renderScale: 0.75},
  {upscaling: 'fsr3-experimental-performance' as const, renderScale: 0.625},
  {upscaling: 'fsr3-experimental-performance' as const, renderScale: 0.5}
] as const;

const DEFAULT_REALTIME_QUALITY_LEVEL = 3;

interface RendererRuntimeSnapshot {
  readonly settings: ReturnType<WebGPURenderer['getSettings']>;
  readonly wasRunning: boolean;
  readonly profile: PerformanceProfile;
  readonly targetFps: number;
  readonly realtimeAdaptationActive: boolean;
  readonly adaptiveLevel: number;
  readonly lowFpsWindows: number;
  readonly highFpsWindows: number;
  readonly lastAdaptiveCheck: number;
}

interface StartTransactionSnapshot extends RendererRuntimeSnapshot {
  readonly offlineRestore: RendererRuntimeSnapshot | null;
  readonly lastFinished: FinishedVideoRecording | null;
  readonly lastError: string;
}

export class VideoController {
  private readonly renderer: WebGPURenderer;
  private readonly recorder = new CanvasVideoRecorder();
  private profile: PerformanceProfile = 'realtime-61-plus';
  private targetFps = 72;
  private adaptiveQuality = true;
  private adaptiveLevel = DEFAULT_REALTIME_QUALITY_LEVEL;
  private realtimeAdaptationActive = false;
  private lowFpsWindows = 0;
  private highFpsWindows = 0;
  private lastAdaptiveCheck = 0;
  private offlineRestore: RendererRuntimeSnapshot | null = null;
  private lastFinished: FinishedVideoRecording | null = null;
  private lastError = '';
  private objectUrls = new Set<string>();
  private startInProgress = false;
  private offlineCapture: Promise<void> | null = null;
  private captureGeneration = 0;
  private offlineRestorePending = false;
  private destroyed = false;

  constructor(renderer: WebGPURenderer) {
    this.renderer = renderer;
  }

  applyPerformanceProfile(profile: PerformanceProfile): void {
    this.assertNotDestroyed();
    let patch: Parameters<WebGPURenderer['updateSettings']>[0];
    if (profile === 'realtime-61-plus') {
      const quality = REALTIME_QUALITY_LEVELS[DEFAULT_REALTIME_QUALITY_LEVEL]!;
      patch = {
        mode: 'ray-trace',
        antiAliasing: 'temporal',
        toneMapping: 'aces',
        renderScale: quality.renderScale,
        samplesPerFrame: 1,
        minBounces: 1,
        maxBounces: 2,
        lightSamples: 1,
        rayDiffuseWeight: 1,
        rayGlossyWeight: 1,
        rayTransparentWeight: 0.65,
        rayVolumeWeight: 0,
        noiseThreshold: 0.025,
        convergenceMinSamples: 6,
        fogDensity: 0,
        volumetricSteps: 8,
        denoising: 'fast',
        upscaling: quality.upscaling,
        frameGeneration: 'fsr3-experimental',
        bloomStrength: 0,
        autoExposure: false,
        hdrOutput: 'sdr'
      };
    } else if (profile === 'balanced') {
      patch = {
        mode: 'path-trace',
        antiAliasing: 'fxaa',
        toneMapping: 'aces',
        renderScale: 1,
        samplesPerFrame: 1,
        minBounces: 2,
        maxBounces: 4,
        lightSamples: 1,
        rayDiffuseWeight: 1,
        rayGlossyWeight: 1,
        rayTransparentWeight: 1,
        rayVolumeWeight: 0.75,
        noiseThreshold: 0.012,
        convergenceMinSamples: 10,
        fogDensity: 0,
        volumetricSteps: 16,
        denoising: 'fast',
        upscaling: 'fsr1-balanced',
        frameGeneration: 'off',
        hdrOutput: 'sdr'
      };
    } else {
      patch = {
        mode: 'path-trace',
        antiAliasing: 'temporal',
        toneMapping: 'aces',
        renderScale: 1,
        samplesPerFrame: 1,
        minBounces: 4,
        maxBounces: 12,
        lightSamples: 4,
        rayDiffuseWeight: 1,
        rayGlossyWeight: 1,
        rayTransparentWeight: 1,
        rayVolumeWeight: 1,
        noiseThreshold: 0.002,
        convergenceMinSamples: 32,
        fogDensity: 0,
        volumetricSteps: 32,
        denoising: 'quality',
        upscaling: 'native',
        frameGeneration: 'off',
        hdrOutput: 'auto'
      };
    }

    this.updateRendererSettingsTransactionally(patch);
    this.profile = profile;
    this.realtimeAdaptationActive = profile === 'realtime-61-plus';
    if (profile === 'realtime-61-plus') {
      this.adaptiveLevel = DEFAULT_REALTIME_QUALITY_LEVEL;
    }
    this.lowFpsWindows = 0;
    this.highFpsWindows = 0;
    this.lastAdaptiveCheck = 0;
  }

  configureRealtimeTarget(targetFps: number, adaptiveQuality: boolean): void {
    if (!Number.isFinite(targetFps) || targetFps < 1 || targetFps > 240) {
      throw new RangeError('Real-time target FPS must be from 1 through 240.');
    }
    this.targetFps = targetFps;
    this.adaptiveQuality = adaptiveQuality;
    this.lowFpsWindows = 0;
    this.highFpsWindows = 0;
  }

  async start(
    mode: VideoRecordingMode,
    fps: number,
    bitrateMegabits: number,
    codec: VideoCodecPreference
  ): Promise<void> {
    this.assertNotDestroyed();
    this.assertCanStart();
    this.startInProgress = true;
    let transaction: StartTransactionSnapshot | null = null;
    let recorderStartAttempted = false;
    try {
      const canvas = this.renderer.getOutputCanvas();
      const rendererState = this.renderer.getStatus().state;
      if (canvas === null || (rendererState !== 'ready' && rendererState !== 'running')) {
        throw new Error('Initialize the GPU renderer before starting video recording.');
      }
      if (!Number.isFinite(bitrateMegabits) || bitrateMegabits < 0.25 || bitrateMegabits > 500) {
        throw new RangeError('Video bitrate must be from 0.25 through 500 Mbps.');
      }

      transaction = {
        ...this.captureRuntimeSnapshot(rendererState === 'running'),
        offlineRestore: this.offlineRestore,
        lastFinished: this.lastFinished,
        lastError: this.lastError
      };
      this.lastError = '';
      this.lastFinished = null;
      this.targetFps = fps;
      if (mode === 'realtime') {
        this.applyPerformanceProfile('realtime-61-plus');
      } else {
        this.offlineRestore = transaction;
        this.applyPerformanceProfile('cinematic');
        this.renderer.stop();
        this.renderer.updateSettings({frameGeneration: 'off', hdrOutput: 'sdr'});
      }

      recorderStartAttempted = true;
      await this.recorder.start(canvas, {
        mode,
        fps,
        bitrate: Math.round(bitrateMegabits * 1_000_000),
        codec,
        maxQueueSize: mode === 'realtime' ? 2 : 8,
        keyFrameIntervalSeconds: 2
      });
      if (mode === 'realtime') this.renderer.start();
    } catch (error) {
      if (recorderStartAttempted) {
        try {
          this.recorder.cancel();
        } catch {
          // Restoring the renderer is still required if recorder cleanup fails.
        }
      }
      if (transaction !== null) this.rollbackFailedStart(transaction);
      throw error;
    } finally {
      this.startInProgress = false;
    }
  }

  capturePresentedFrame(timestampMilliseconds: number): void {
    const status = this.recorder.getStatus();
    const capturingRealtime = status.state === 'recording' && status.mode === 'realtime';
    if (!capturingRealtime && !this.realtimeAdaptationActive) return;
    if (capturingRealtime) {
      try {
        this.recorder.captureRealtimeFrame();
      } catch (error) {
        this.lastError = errorMessage(error);
        this.recorder.cancel();
        return;
      }
    }
    if (this.realtimeAdaptationActive) {
      try {
        this.adaptRealtimeQuality(timestampMilliseconds);
      } catch (error) {
        this.lastError = errorMessage(error);
      }
    }
  }

  async captureOfflineFrame(samples: number): Promise<void> {
    this.assertNotDestroyed();
    if (this.offlineCapture !== null) {
      throw new Error('A cinematic frame is already being captured. Wait for it to finish.');
    }
    if (!Number.isFinite(samples)) throw new TypeError('Cinematic sample count must be finite.');
    const status = this.recorder.getStatus();
    if (status.state !== 'recording' || status.mode !== 'offline') {
      throw new Error('Start an offline video recording before capturing cinematic frames.');
    }
    const requestedSamples = Math.min(16_384, Math.max(1, Math.round(samples)));
    const generation = this.captureGeneration;
    const operation = (async (): Promise<void> => {
      this.renderer.resetAccumulation();
      const completed = await this.renderer.renderSamples(requestedSamples, 8);
      if (generation !== this.captureGeneration || this.destroyed) {
        throw new Error('Cinematic frame capture was canceled. No frame was recorded.');
      }
      if (completed !== requestedSamples) {
        throw new Error(`Cinematic rendering stopped after ${completed} / ${requestedSamples} samples. No frame was recorded.`);
      }
      await this.recorder.captureOfflineFrame();
      if (generation !== this.captureGeneration || this.destroyed) {
        throw new Error('Cinematic frame capture was canceled.');
      }
    })();
    this.offlineCapture = operation;
    try {
      await operation;
    } finally {
      if (this.offlineCapture === operation) this.offlineCapture = null;
      if (this.offlineRestorePending && !this.destroyed) {
        this.offlineRestorePending = false;
        this.restoreOfflineRenderer();
      }
    }
  }

  async finish(filename: string): Promise<void> {
    this.assertNotDestroyed();
    const mode = this.recorder.getStatus().mode;
    try {
      if (this.offlineCapture !== null) await this.offlineCapture;
      const result = await this.recorder.finish();
      this.lastFinished = result;
      this.download(result.blob, filename);
    } catch (error) {
      this.lastError = errorMessage(error);
      throw error;
    } finally {
      if (mode === 'offline') this.restoreOfflineRenderer();
    }
  }

  cancel(): void {
    if (this.destroyed) return;
    this.captureGeneration += 1;
    const mode = this.recorder.getStatus().mode;
    if (mode === 'offline' || this.offlineCapture !== null) this.renderer.stop();
    this.recorder.cancel();
    if (mode === 'offline') {
      if (this.offlineCapture !== null) this.offlineRestorePending = true;
      else this.restoreOfflineRenderer();
    }
  }

  isRecording(): boolean {
    const state = this.recorder.getStatus().state;
    return state === 'configuring' || state === 'recording' || state === 'finishing';
  }

  recordingMode(): VideoRecordingMode | null {
    return this.recorder.getStatus().mode;
  }

  recordingFps(): number {
    return this.recorder.getStatus().fps;
  }

  supported(): boolean {
    const canvasWindow = this.renderer.getOutputCanvas()?.ownerDocument?.defaultView;
    const host = canvasWindow ?? globalThis;
    return typeof (host as unknown as {VideoEncoder?: unknown}).VideoEncoder === 'function'
      && typeof (host as unknown as {VideoFrame?: unknown}).VideoFrame === 'function';
  }

  status(): object {
    const recorder = this.recorder.getStatus();
    const measuredRendererFps = this.renderer.getMeasuredFps();
    return {
      ...recorder,
      supported: this.supported(),
      profile: this.profile,
      adaptiveQuality: this.adaptiveQuality,
      adaptiveLevel: this.adaptiveLevel,
      targetRendererFps: this.targetFps,
      measuredRendererFps,
      meetsTarget: measuredRendererFps > 0 && measuredRendererFps >= this.targetFps,
      lastBytes: this.lastFinished?.stats.bytes ?? recorder.bytes,
      lastError: this.lastError
    };
  }

  destroy(): void {
    if (this.destroyed) return;
    this.cancel();
    this.destroyed = true;
    this.offlineRestorePending = false;
    this.offlineRestore = null;
    this.recorder.destroy();
    const ownerWindow = this.renderer.getOutputCanvas()?.ownerDocument?.defaultView;
    for (const url of this.objectUrls) ownerWindow?.URL.revokeObjectURL(url);
    this.objectUrls.clear();
  }

  private adaptRealtimeQuality(now: number): void {
    if (!this.adaptiveQuality || this.profile !== 'realtime-61-plus') return;
    if (!Number.isFinite(now) || now - this.lastAdaptiveCheck < 1_000) return;
    this.lastAdaptiveCheck = now;
    const measured = this.renderer.getMeasuredFps();
    if (measured <= 0) return;

    if (measured < this.targetFps * 0.94) {
      this.lowFpsWindows += 1;
      this.highFpsWindows = 0;
      if (this.lowFpsWindows >= 2 && this.adaptiveLevel < REALTIME_QUALITY_LEVELS.length - 1) {
        this.applyRealtimeQualityLevel(this.adaptiveLevel + 1);
      }
      return;
    }
    if (measured > this.targetFps * 1.2) {
      this.highFpsWindows += 1;
      this.lowFpsWindows = 0;
      if (this.highFpsWindows >= 4 && this.adaptiveLevel > 0) {
        this.applyRealtimeQualityLevel(this.adaptiveLevel - 1);
      }
      return;
    }
    this.lowFpsWindows = 0;
    this.highFpsWindows = 0;
  }

  private applyRealtimeQualityLevel(level: number): void {
    const quality = REALTIME_QUALITY_LEVELS[level]!;
    this.updateRendererSettingsTransactionally({
      upscaling: quality.upscaling,
      renderScale: quality.renderScale,
      antiAliasing: 'temporal',
      frameGeneration: 'fsr3-experimental'
    });
    this.adaptiveLevel = level;
    this.lowFpsWindows = 0;
    this.highFpsWindows = 0;
  }

  private restoreOfflineRenderer(): void {
    const restore = this.offlineRestore;
    if (restore === null) return;
    this.restoreRuntimeSnapshot(restore);
    this.offlineRestore = null;
  }

  private assertCanStart(): void {
    const state = this.recorder.getStatus().state;
    if (
      this.startInProgress
      || this.offlineCapture !== null
      || this.offlineRestore !== null
      || state === 'configuring'
      || state === 'recording'
      || state === 'finishing'
    ) {
      throw new Error('A video recording is already starting or active. Finish or cancel it first.');
    }
  }

  private captureRuntimeSnapshot(wasRunning: boolean): RendererRuntimeSnapshot {
    return {
      settings: this.renderer.getSettings(),
      wasRunning,
      profile: this.profile,
      targetFps: this.targetFps,
      realtimeAdaptationActive: this.realtimeAdaptationActive,
      adaptiveLevel: this.adaptiveLevel,
      lowFpsWindows: this.lowFpsWindows,
      highFpsWindows: this.highFpsWindows,
      lastAdaptiveCheck: this.lastAdaptiveCheck
    };
  }

  private restoreRuntimeSnapshot(snapshot: RendererRuntimeSnapshot): void {
    if (!snapshot.wasRunning) this.renderer.stop();
    try {
      this.renderer.updateSettings(snapshot.settings);
      if (snapshot.wasRunning) this.renderer.start();
    } finally {
      this.profile = snapshot.profile;
      this.targetFps = snapshot.targetFps;
      this.realtimeAdaptationActive = snapshot.realtimeAdaptationActive;
      this.adaptiveLevel = snapshot.adaptiveLevel;
      this.lowFpsWindows = snapshot.lowFpsWindows;
      this.highFpsWindows = snapshot.highFpsWindows;
      this.lastAdaptiveCheck = snapshot.lastAdaptiveCheck;
    }
  }

  private rollbackFailedStart(snapshot: StartTransactionSnapshot): void {
    try {
      this.restoreRuntimeSnapshot(snapshot);
    } catch (rollbackError) {
      this.lastError = `Could not completely restore video settings: ${errorMessage(rollbackError)}`;
    } finally {
      this.offlineRestore = snapshot.offlineRestore;
      this.lastFinished = snapshot.lastFinished;
      if (this.lastError === '') this.lastError = snapshot.lastError;
    }
  }

  private updateRendererSettingsTransactionally(
    patch: Parameters<WebGPURenderer['updateSettings']>[0]
  ): void {
    const previous = this.renderer.getSettings();
    try {
      this.renderer.updateSettings(patch);
    } catch (error) {
      try {
        this.renderer.updateSettings(previous);
      } catch (rollbackError) {
        throw new Error(
          `${errorMessage(error)} (renderer settings rollback failed: ${errorMessage(rollbackError)})`
        );
      }
      throw error;
    }
  }

  private download(blob: Blob, filename: string): void {
    const canvas = this.renderer.getOutputCanvas();
    const ownerWindow = canvas?.ownerDocument?.defaultView;
    const document = canvas?.ownerDocument;
    if (ownerWindow === null || ownerWindow === undefined || document === undefined) {
      throw new Error('The browser document is unavailable for video download.');
    }
    const safeName = sanitizeWebMFilename(filename);
    const url = ownerWindow.URL.createObjectURL(blob);
    this.objectUrls.add(url);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = safeName;
    anchor.style.display = 'none';
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    ownerWindow.setTimeout(() => {
      ownerWindow.URL.revokeObjectURL(url);
      this.objectUrls.delete(url);
    }, 60_000);
  }

  private assertNotDestroyed(): void {
    if (this.destroyed) throw new Error('Video controller has been destroyed.');
  }
}

export function sanitizeWebMFilename(value: string): string {
  const stem = value
    .replace(/[<>:"/\\|?*\u0000-\u001f]/g, '_')
    .trim()
    .replace(/[. ]+$/g, '') || 'priosdk-video';
  return stem.toLowerCase().endsWith('.webm') ? stem : `${stem}.webm`;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
