import {cross3, lengthSquared3, normalize3, resolveTransform, subtract3} from './math';
import {
  MAX_SCENE_TRIANGLES,
  MAX_TEXTURE_LAYER,
  MAX_TEXTURE_LOD,
  MAX_UV_REPEAT,
  NO_TEXTURE_LAYER
} from './limits';
import type {
  DirectionalLightRecord,
  LightDefinition,
  LightRecord,
  MaterialDefinition,
  MaterialRecord,
  MeshDefinition,
  MeshRecord,
  PointLightRecord,
  SurfaceDetailMode,
  Transform,
  TransformInput,
  Vec2,
  Vec2ArrayInput,
  Vec3,
  Vec3ArrayInput
} from './types';

const DEGENERATE_AREA_SQUARED = 1e-20;
const SCALE_EPSILON = 1e-8;
const MAX_MESH_TRIANGLES = MAX_SCENE_TRIANGLES;
const MAX_MESH_VERTICES = MAX_MESH_TRIANGLES * 3;

export function assertFiniteGpuNumber(value: number, label: string): number {
  if (!Number.isFinite(value) || !Number.isFinite(Math.fround(value))) {
    throw new TypeError(`${label} must be a finite 32-bit floating-point value`);
  }
  return value;
}

export function assertIntegerInRange(value: number, minimum: number, maximum: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be an integer from ${minimum} through ${maximum}`);
  }
  return value;
}

function assertRange(value: number, minimum: number, maximum: number, label: string): number {
  assertFiniteGpuNumber(value, label);
  if (value < minimum || value > maximum) {
    throw new RangeError(`${label} must be from ${minimum} through ${maximum}`);
  }
  return value;
}

export function validateVec3(value: Vec3, label: string): Vec3 {
  if (!Array.isArray(value) && !ArrayBuffer.isView(value)) {
    throw new TypeError(`${label} must be a three-component vector`);
  }
  if (value.length !== 3) throw new RangeError(`${label} must contain exactly three components`);
  return [
    assertFiniteGpuNumber(value[0], `${label}[0]`),
    assertFiniteGpuNumber(value[1], `${label}[1]`),
    assertFiniteGpuNumber(value[2], `${label}[2]`)
  ];
}

export function validateVec2(value: Vec2, label: string): Vec2 {
  if (!Array.isArray(value) && !ArrayBuffer.isView(value)) {
    throw new TypeError(`${label} must be a two-component vector`);
  }
  if (value.length !== 2) throw new RangeError(`${label} must contain exactly two components`);
  return [
    assertFiniteGpuNumber(value[0], `${label}[0]`),
    assertFiniteGpuNumber(value[1], `${label}[1]`)
  ];
}

function validateColor(value: Vec3, label: string, maximum: number): Vec3 {
  const color = validateVec3(value, label);
  for (let component = 0; component < 3; component += 1) {
    assertRange(color[component] ?? Number.NaN, 0, maximum, `${label}[${component}]`);
  }
  return color;
}

function validateSurfaceDetail(value: SurfaceDetailMode | undefined): SurfaceDetailMode {
  const resolved = value ?? 'standard';
  if (
    resolved !== 'standard'
    && resolved !== 'foliage'
    && resolved !== 'bark'
    && resolved !== 'grass'
    && resolved !== 'ground'
    && resolved !== 'plaster'
    && resolved !== 'wood'
    && resolved !== 'fabric'
    && resolved !== 'glass'
    && resolved !== 'solid-glass'
    && resolved !== 'unlit'
  ) {
    throw new RangeError(
      'material.surfaceDetail must be standard, foliage, bark, grass, ground, plaster, wood, fabric, glass, solid-glass, or unlit'
    );
  }
  return resolved;
}

function defaultRoughnessVariation(surfaceDetail: SurfaceDetailMode): number {
  if (surfaceDetail === 'plaster') return 0.1;
  if (surfaceDetail === 'wood') return 0.12;
  if (surfaceDetail === 'fabric') return 0.08;
  if (surfaceDetail === 'glass' || surfaceDetail === 'solid-glass') return 0.012;
  return 0;
}

function defaultNormalStrength(surfaceDetail: SurfaceDetailMode): number {
  if (surfaceDetail === 'plaster') return 0.012;
  if (surfaceDetail === 'wood') return 0.018;
  if (surfaceDetail === 'fabric') return 0.02;
  if (surfaceDetail === 'glass' || surfaceDetail === 'solid-glass') return 0.001;
  return 0;
}

export function validateMaterial(definition: MaterialDefinition): MaterialRecord {
  if (!definition || typeof definition !== 'object') throw new TypeError('material must be an object');
  const doubleSided = definition.doubleSided ?? false;
  const surfaceDetail = validateSurfaceDetail(definition.surfaceDetail);
  if (
    definition.textureLayer !== undefined
    && definition.baseColorTextureLayer !== undefined
    && definition.textureLayer !== definition.baseColorTextureLayer
  ) {
    throw new RangeError('material.textureLayer and material.baseColorTextureLayer must match when both are provided');
  }
  const textureLayer = assertIntegerInRange(
    definition.baseColorTextureLayer ?? definition.textureLayer ?? NO_TEXTURE_LAYER,
    0,
    NO_TEXTURE_LAYER,
    'material.textureLayer'
  );
  const normalTextureLayer = assertIntegerInRange(
    definition.normalTextureLayer ?? NO_TEXTURE_LAYER,
    0,
    NO_TEXTURE_LAYER,
    'material.normalTextureLayer'
  );
  const roughnessTextureLayer = assertIntegerInRange(
    definition.roughnessTextureLayer ?? NO_TEXTURE_LAYER,
    0,
    NO_TEXTURE_LAYER,
    'material.roughnessTextureLayer'
  );
  const inferredTextureFlags = (textureLayer === NO_TEXTURE_LAYER ? 0 : 1)
    | (normalTextureLayer === NO_TEXTURE_LAYER ? 0 : 1 << 3)
    | (roughnessTextureLayer === NO_TEXTURE_LAYER ? 0 : 1 << 4);
  const textureFlags = assertIntegerInRange(
    definition.textureFlags ?? inferredTextureFlags,
    0,
    0xffff_ffff,
    'material.textureFlags'
  );
  if ((textureFlags & (1 << 3)) !== 0 && normalTextureLayer === NO_TEXTURE_LAYER) {
    throw new RangeError('material.normalTextureLayer is required when the independent normal-map flag is enabled');
  }
  if ((textureFlags & (1 << 4)) !== 0 && roughnessTextureLayer === NO_TEXTURE_LAYER) {
    throw new RangeError('material.roughnessTextureLayer is required when the independent roughness-map flag is enabled');
  }
  if ((textureFlags & (1 << 5)) !== 0 && roughnessTextureLayer === NO_TEXTURE_LAYER) {
    throw new RangeError('material.roughnessTextureLayer is required when the packed metallic-roughness flag is enabled');
  }
  const uvRepeat = validateVec2(definition.uvRepeat ?? [1, 1], 'material.uvRepeat');
  const atlasOffset = validateVec2(definition.atlasOffset ?? [0, 0], 'material.atlasOffset');
  const atlasScale = validateVec2(definition.atlasScale ?? [1, 1], 'material.atlasScale');
  for (let component = 0; component < 2; component += 1) {
    assertRange(uvRepeat[component] ?? Number.NaN, 0.0001, MAX_UV_REPEAT, `material.uvRepeat[${component}]`);
    assertRange(atlasOffset[component] ?? Number.NaN, 0, 1, `material.atlasOffset[${component}]`);
    assertRange(atlasScale[component] ?? Number.NaN, 0.0001, 1, `material.atlasScale[${component}]`);
    if ((atlasOffset[component] ?? 0) + (atlasScale[component] ?? 0) > 1 + 1e-7) {
      throw new RangeError(`material atlas tile exceeds the normalized texture bounds on axis ${component}`);
    }
  }
  if (typeof doubleSided !== 'boolean') throw new TypeError('material.doubleSided must be a boolean');
  return {
    baseColor: validateColor(definition.baseColor, 'material.baseColor', 1),
    roughness: assertRange(definition.roughness, 0, 1, 'material.roughness'),
    metallic: assertRange(definition.metallic, 0, 1, 'material.metallic'),
    emissionColor: validateColor(definition.emissionColor ?? [0, 0, 0], 'material.emissionColor', Number.MAX_VALUE),
    emissionStrength: assertRange(definition.emissionStrength ?? 0, 0, Number.MAX_VALUE, 'material.emissionStrength'),
    transmission: assertRange(definition.transmission ?? 0, 0, 1, 'material.transmission'),
    ior: assertRange(definition.ior ?? 1.5, 1, 3, 'material.ior'),
    alpha: assertRange(definition.alpha ?? 1, 0, 1, 'material.alpha'),
    doubleSided,
    windInfluence: assertRange(definition.windInfluence ?? 0, 0, 1, 'material.windInfluence'),
    surfaceDetail,
    colorVariation: assertRange(definition.colorVariation ?? 0, 0, 1, 'material.colorVariation'),
    detailScale: assertRange(definition.detailScale ?? 1, 0.001, 10_000, 'material.detailScale'),
    roughnessVariation: assertRange(
      definition.roughnessVariation ?? defaultRoughnessVariation(surfaceDetail),
      0,
      1,
      'material.roughnessVariation'
    ),
    normalStrength: assertRange(
      definition.normalStrength ?? defaultNormalStrength(surfaceDetail),
      0,
      1,
      'material.normalStrength'
    ),
    textureLayer: textureLayer === NO_TEXTURE_LAYER
      ? NO_TEXTURE_LAYER
      : assertIntegerInRange(textureLayer, 0, MAX_TEXTURE_LAYER, 'material.textureLayer'),
    normalTextureLayer: normalTextureLayer === NO_TEXTURE_LAYER
      ? NO_TEXTURE_LAYER
      : assertIntegerInRange(normalTextureLayer, 0, MAX_TEXTURE_LAYER, 'material.normalTextureLayer'),
    roughnessTextureLayer: roughnessTextureLayer === NO_TEXTURE_LAYER
      ? NO_TEXTURE_LAYER
      : assertIntegerInRange(roughnessTextureLayer, 0, MAX_TEXTURE_LAYER, 'material.roughnessTextureLayer'),
    textureFlags,
    uvRepeat,
    atlasOffset,
    atlasScale,
    textureStrength: assertRange(definition.textureStrength ?? 1, 0, 1, 'material.textureStrength'),
    textureNormalStrength: assertRange(
      definition.textureNormalStrength ?? 0,
      0,
      4,
      'material.textureNormalStrength'
    ),
    textureRoughnessStrength: assertRange(
      definition.textureRoughnessStrength ?? 0,
      0,
      1,
      'material.textureRoughnessStrength'
    ),
    textureLod: assertRange(definition.textureLod ?? 0, 0, MAX_TEXTURE_LOD, 'material.textureLod')
  };
}

function isNestedVec3Input(input: Vec3ArrayInput): input is readonly Vec3[] {
  if (input.length === 0) return false;
  const first = (input as ArrayLike<unknown>)[0];
  return typeof first !== 'number';
}

function flattenVec3Input(input: Vec3ArrayInput, label: string): Float32Array {
  if (!input || typeof input !== 'object' || !Number.isSafeInteger(input.length)) {
    throw new TypeError(`${label} must be an array-like collection`);
  }
  if (isNestedVec3Input(input)) {
    const output = new Float32Array(input.length * 3);
    for (let index = 0; index < input.length; index += 1) {
      const value = input[index];
      if (!value) throw new TypeError(`${label}[${index}] must be a three-component vector`);
      const vector = validateVec3(value, `${label}[${index}]`);
      output[index * 3] = vector[0];
      output[index * 3 + 1] = vector[1];
      output[index * 3 + 2] = vector[2];
    }
    return output;
  }
  if (input.length % 3 !== 0) throw new RangeError(`${label} length must be divisible by three`);
  const output = new Float32Array(input.length);
  for (let index = 0; index < input.length; index += 1) {
    const value = (input as ArrayLike<number>)[index];
    if (value === undefined) throw new TypeError(`${label}[${index}] is missing`);
    output[index] = assertFiniteGpuNumber(value, `${label}[${index}]`);
  }
  return output;
}

function isNestedVec2Input(input: Vec2ArrayInput): input is readonly Vec2[] {
  if (input.length === 0) return false;
  const first = (input as ArrayLike<unknown>)[0];
  return typeof first !== 'number';
}

function flattenVec2Input(input: Vec2ArrayInput, label: string): Float32Array {
  if (!input || typeof input !== 'object' || !Number.isSafeInteger(input.length)) {
    throw new TypeError(`${label} must be an array-like collection`);
  }
  if (isNestedVec2Input(input)) {
    const output = new Float32Array(input.length * 2);
    for (let index = 0; index < input.length; index += 1) {
      const value = input[index];
      if (!value) throw new TypeError(`${label}[${index}] must be a two-component vector`);
      const vector = validateVec2(value, `${label}[${index}]`);
      output[index * 2] = vector[0];
      output[index * 2 + 1] = vector[1];
    }
    return output;
  }
  if (input.length % 2 !== 0) throw new RangeError(`${label} length must be divisible by two`);
  const output = new Float32Array(input.length);
  for (let index = 0; index < input.length; index += 1) {
    const value = (input as ArrayLike<number>)[index];
    if (value === undefined) throw new TypeError(`${label}[${index}] is missing`);
    output[index] = assertFiniteGpuNumber(value, `${label}[${index}]`);
  }
  return output;
}

function readPosition(positions: Float32Array, index: number): Vec3 {
  const offset = index * 3;
  const x = positions[offset];
  const y = positions[offset + 1];
  const z = positions[offset + 2];
  if (x === undefined || y === undefined || z === undefined) throw new Error('Internal position invariant failed');
  return [x, y, z];
}

export function validateMesh(definition: MeshDefinition): MeshRecord {
  if (!definition || typeof definition !== 'object') throw new TypeError('mesh must be an object');
  if (!definition.positions || typeof definition.positions !== 'object') {
    throw new TypeError('mesh.positions must be an array-like collection');
  }
  const nestedPositions = isNestedVec3Input(definition.positions);
  const inputVertexCount = nestedPositions ? definition.positions.length : definition.positions.length / 3;
  if (inputVertexCount > MAX_MESH_VERTICES) {
    throw new RangeError(`mesh.positions cannot contain more than ${MAX_MESH_VERTICES} vertices`);
  }
  const positions = flattenVec3Input(definition.positions, 'mesh.positions');
  if (positions.length < 9) throw new RangeError('mesh.positions must contain at least three vertices');
  const vertexCount = positions.length / 3;

  const rawIndices = definition.indices;
  if (!rawIndices || typeof rawIndices !== 'object' || !Number.isSafeInteger(rawIndices.length)) {
    throw new TypeError('mesh.indices must be an array-like collection');
  }
  if (rawIndices.length < 3 || rawIndices.length % 3 !== 0) {
    throw new RangeError('mesh.indices must contain a positive multiple of three indices');
  }
  if (rawIndices.length / 3 > MAX_MESH_TRIANGLES) {
    throw new RangeError(`mesh.indices cannot contain more than ${MAX_MESH_TRIANGLES} triangles`);
  }
  const indices = new Uint32Array(rawIndices.length);
  for (let index = 0; index < rawIndices.length; index += 1) {
    const value = rawIndices[index];
    if (value === undefined) throw new TypeError(`mesh.indices[${index}] is missing`);
    indices[index] = assertIntegerInRange(value, 0, vertexCount - 1, `mesh.indices[${index}]`);
  }

  let normals: Float32Array | null = null;
  if (definition.normals !== undefined) {
    normals = flattenVec3Input(definition.normals, 'mesh.normals');
    if (normals.length !== positions.length) {
      throw new RangeError('mesh.normals must have exactly one normal per position');
    }
    for (let vertex = 0; vertex < vertexCount; vertex += 1) {
      const normal = readPosition(normals, vertex);
      if (lengthSquared3(normal) <= DEGENERATE_AREA_SQUARED) {
        throw new RangeError(`mesh.normals[${vertex}] must have non-zero length`);
      }
    }
  }

  let uvs: Float32Array | null = null;
  if (definition.uvs !== undefined) {
    uvs = flattenVec2Input(definition.uvs, 'mesh.uvs');
    if (uvs.length !== vertexCount * 2) {
      throw new RangeError('mesh.uvs must have exactly one texture coordinate per position');
    }
  }

  let windWeights: Float32Array | null = null;
  if (definition.windWeights !== undefined) {
    if (
      !definition.windWeights
      || typeof definition.windWeights !== 'object'
      || !Number.isSafeInteger(definition.windWeights.length)
      || definition.windWeights.length !== vertexCount
    ) {
      throw new RangeError('mesh.windWeights must have exactly one value per position');
    }
    windWeights = new Float32Array(vertexCount);
    for (let vertex = 0; vertex < vertexCount; vertex += 1) {
      const weight = definition.windWeights[vertex];
      if (weight === undefined) throw new TypeError(`mesh.windWeights[${vertex}] is missing`);
      windWeights[vertex] = assertRange(weight, 0, 1, `mesh.windWeights[${vertex}]`);
    }
  }

  for (let triangle = 0; triangle < indices.length / 3; triangle += 1) {
    const offset = triangle * 3;
    const i0 = indices[offset];
    const i1 = indices[offset + 1];
    const i2 = indices[offset + 2];
    if (i0 === undefined || i1 === undefined || i2 === undefined) throw new Error('Internal index invariant failed');
    if (i0 === i1 || i0 === i2 || i1 === i2) {
      throw new RangeError(`mesh triangle ${triangle} has repeated indices`);
    }
    const edge1 = subtract3(readPosition(positions, i1), readPosition(positions, i0));
    const edge2 = subtract3(readPosition(positions, i2), readPosition(positions, i0));
    if (lengthSquared3(cross3(edge1, edge2)) <= DEGENERATE_AREA_SQUARED) {
      throw new RangeError(`mesh triangle ${triangle} is degenerate`);
    }
  }

  return {positions, indices, normals, uvs, windWeights, vertexCount, triangleCount: indices.length / 3};
}

export function validateTransform(input: TransformInput = {}, base?: Transform): Transform {
  const transform = resolveTransform(input, base);
  const translation = validateVec3(transform.translation, 'transform.translation');
  const rotation = validateVec3(transform.rotation, 'transform.rotation');
  const scale = validateVec3(transform.scale, 'transform.scale');
  for (let axis = 0; axis < 3; axis += 1) {
    if (Math.abs(scale[axis] ?? 0) < SCALE_EPSILON) {
      throw new RangeError(`transform.scale[${axis}] must be non-zero`);
    }
  }
  return {translation, rotation, scale};
}

export function validateLight(definition: LightDefinition): LightRecord {
  if (!definition || typeof definition !== 'object') throw new TypeError('light must be an object');
  const color = validateColor(definition.color, 'light.color', Number.MAX_VALUE);
  const intensity = assertRange(definition.intensity, 0, Number.MAX_VALUE, 'light.intensity');
  const castShadow = definition.castShadow ?? true;
  if (typeof castShadow !== 'boolean') throw new TypeError('light.castShadow must be a boolean');
  if (definition.type === 'point') {
    const result: PointLightRecord = {
      type: 'point',
      position: validateVec3(definition.position, 'light.position'),
      color,
      intensity,
      range: assertRange(definition.range ?? 0, 0, Number.MAX_VALUE, 'light.range'),
      radius: assertRange(definition.radius ?? 0, 0, Number.MAX_VALUE, 'light.radius'),
      castShadow
    };
    return result;
  }
  if (definition.type === 'directional') {
    const direction = normalize3(validateVec3(definition.direction, 'light.direction'), 'light.direction');
    const result: DirectionalLightRecord = {
      type: 'directional',
      direction,
      color,
      intensity,
      angularRadius: assertRange(definition.angularRadius ?? 0, 0, Math.PI / 2, 'light.angularRadius'),
      castShadow
    };
    return result;
  }
  throw new RangeError('light.type must be "point" or "directional"');
}

export function cloneMaterial(material: MaterialRecord): MaterialRecord {
  return {
    ...material,
    baseColor: [...material.baseColor],
    emissionColor: [...material.emissionColor],
    uvRepeat: [...material.uvRepeat],
    atlasOffset: [...material.atlasOffset],
    atlasScale: [...material.atlasScale]
  };
}

export function cloneMesh(mesh: MeshRecord): MeshRecord {
  return {
    positions: mesh.positions.slice(),
    indices: mesh.indices.slice(),
    normals: mesh.normals?.slice() ?? null,
    uvs: mesh.uvs?.slice() ?? null,
    windWeights: mesh.windWeights?.slice() ?? null,
    vertexCount: mesh.vertexCount,
    triangleCount: mesh.triangleCount
  };
}

export function cloneLight(light: LightRecord): LightRecord {
  return light.type === 'point'
    ? {...light, position: [...light.position], color: [...light.color]}
    : {...light, direction: [...light.direction], color: [...light.color]};
}
