import {
  CooperativeTextureWork,
  type CooperativeTextureWorkOptions
} from './cooperative-work';
import {decodeRadianceHdrAsync, isRadianceHdr} from './radiance-hdr';
import type {
  DecodedFloatImage,
  DecodedRasterImage,
  DecodedTextureImage,
  TextureImageProcessor,
  TextureImageSource,
  TextureLoadOptions
} from './types';

export const DEFAULT_MAX_IMAGE_SOURCE_BYTES = 64 * 1024 * 1024;
const MAX_RASTER_PIXELS = 67_108_864;
const SUPPORTED_PROTOCOLS = new Set(['http:', 'https:', 'data:', 'blob:']);

export class BrowserTextureImageProcessor implements TextureImageProcessor {
  async decode(
    source: TextureImageSource,
    options: TextureLoadOptions,
    signal: AbortSignal
  ): Promise<DecodedTextureImage> {
    const maxBytes = normalizeByteLimit(options.maxSourceBytes);
    const label = options.label?.trim() || sourceLabel(source);
    const blob = source instanceof Blob ? source : await fetchImageBlob(source, maxBytes, signal);
    if (blob.size > maxBytes) {
      throw new RangeError(`Image source is ${blob.size} bytes; the limit is ${maxBytes} bytes.`);
    }
    if (signal.aborted) throw abortError();

    const prefix = new Uint8Array(await blob.slice(0, 16).arrayBuffer());
    if (isRadianceHdr(prefix) || isHdrMimeType(blob.type) || hasHdrFileExtension(source)) {
      const encoded = await blob.arrayBuffer();
      if (signal.aborted) throw abortError();
      const decoded = await decodeRadianceHdrAsync(encoded, {signal});
      return {
        kind: 'float',
        data: decoded.data,
        width: decoded.width,
        height: decoded.height,
        label,
        dynamicRange: 'radiance-hdr',
        close(): void {}
      } satisfies DecodedFloatImage;
    }

    const bitmapFactory = globalThis.createImageBitmap;
    if (typeof bitmapFactory !== 'function') {
      throw new Error('createImageBitmap is unavailable; this browser cannot decode GPU image textures.');
    }
    let bitmap: ImageBitmap;
    try {
      bitmap = await bitmapFactory(blob, {
        imageOrientation: options.flipY ? 'flipY' : 'none',
        premultiplyAlpha: 'default',
        colorSpaceConversion: 'default'
      });
    } catch (error) {
      throw new TypeError(`Unable to decode image ${label}: ${errorMessage(error)}`);
    }
    if (signal.aborted) {
      bitmap.close();
      throw abortError();
    }
    if (
      bitmap.width < 1
      || bitmap.height < 1
      || bitmap.width * bitmap.height > MAX_RASTER_PIXELS
    ) {
      bitmap.close();
      throw new RangeError(`Decoded image dimensions exceed the ${MAX_RASTER_PIXELS}-pixel safety limit.`);
    }
    return {
      kind: 'raster',
      image: bitmap,
      width: bitmap.width,
      height: bitmap.height,
      label,
      close: (): void => bitmap.close()
    } satisfies DecodedRasterImage;
  }

  resampleRgba8(image: DecodedRasterImage, width: number, height: number): Uint8Array {
    const context = drawResampledRaster(image, width, height);
    const pixels = context.getImageData(0, 0, width, height).data;
    return new Uint8Array(pixels.buffer.slice(pixels.byteOffset, pixels.byteOffset + pixels.byteLength));
  }

  resampleLinearRgba(image: DecodedTextureImage, width: number, height: number): Float32Array {
    if (image.kind === 'float') {
      return resampleFloatRgba(image.data, image.width, image.height, width, height);
    }
    const bytes = this.resampleRgba8(image, width, height);
    const output = new Float32Array(width * height * 4);
    for (let index = 0; index < output.length; index += 4) {
      output[index] = srgbToLinear(bytes[index]! / 255);
      output[index + 1] = srgbToLinear(bytes[index + 1]! / 255);
      output[index + 2] = srgbToLinear(bytes[index + 2]! / 255);
      output[index + 3] = bytes[index + 3]! / 255;
    }
    return output;
  }

  async resampleRgba8Async(
    image: DecodedRasterImage,
    width: number,
    height: number,
    options: CooperativeTextureWorkOptions = {}
  ): Promise<Uint8Array> {
    const work = new CooperativeTextureWork(options);
    await work.checkpoint(true);
    const context = drawResampledRaster(image, width, height);
    await work.checkpoint(true);
    const output = new Uint8Array(width * height * 4);
    const rowsPerRead = Math.max(1, Math.floor((4 * 1024 * 1024) / (width * 4)));
    for (let firstRow = 0; firstRow < height; firstRow += rowsPerRead) {
      const rowCount = Math.min(rowsPerRead, height - firstRow);
      const pixels = context.getImageData(0, firstRow, width, rowCount).data;
      output.set(pixels, firstRow * width * 4);
      if (work.shouldYield()) await work.checkpoint(true);
    }
    work.assertCurrent();
    return output;
  }

  async resampleLinearRgbaAsync(
    image: DecodedTextureImage,
    width: number,
    height: number,
    options: CooperativeTextureWorkOptions = {}
  ): Promise<Float32Array> {
    if (image.kind === 'float') {
      return resampleFloatRgbaAsync(image.data, image.width, image.height, width, height, options);
    }
    const work = new CooperativeTextureWork(options);
    const bytes = await this.resampleRgba8Async(image, width, height, options);
    work.assertCurrent();
    const output = new Float32Array(width * height * 4);
    for (let index = 0; index < output.length; index += 4) {
      output[index] = srgbToLinear(bytes[index]! / 255);
      output[index + 1] = srgbToLinear(bytes[index + 1]! / 255);
      output[index + 2] = srgbToLinear(bytes[index + 2]! / 255);
      output[index + 3] = bytes[index + 3]! / 255;
      if ((index & 0x3fff) === 0x3ffc && work.shouldYield()) await work.checkpoint(true);
    }
    work.assertCurrent();
    return output;
  }
}

function drawResampledRaster(
  image: DecodedRasterImage,
  width: number,
  height: number
): OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D {
  const context = createCanvasContext(width, height);
  context.clearRect(0, 0, width, height);
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = 'high';
  context.drawImage(image.image, 0, 0, width, height);
  return context;
}

async function fetchImageBlob(source: string | URL, maxBytes: number, signal: AbortSignal): Promise<Blob> {
  const raw = String(source).trim();
  let url: URL;
  try {
    url = new URL(raw, globalThis.location?.href);
  } catch {
    throw new TypeError(`Invalid image URL: ${raw || '(empty)'}.`);
  }
  if (!SUPPORTED_PROTOCOLS.has(url.protocol)) {
    throw new TypeError(`Unsupported image URL protocol ${url.protocol}; use http, https, data, or blob.`);
  }
  if (url.protocol === 'data:' && raw.length > maxBytes * 2) {
    throw new RangeError(`Data URL exceeds the ${maxBytes}-byte image source limit.`);
  }

  let response: Response;
  try {
    response = await fetch(url, {
      method: 'GET',
      mode: 'cors',
      credentials: 'omit',
      redirect: 'follow',
      signal
    });
  } catch (error) {
    if (signal.aborted) throw abortError();
    throw new TypeError(
      `Unable to fetch image ${safeUrl(url)} with credentials omitted. Check the URL and CORS policy: ${errorMessage(error)}`
    );
  }
  if (!response.ok) {
    throw new TypeError(`Image request failed with HTTP ${response.status} ${response.statusText || ''}`.trim());
  }
  const declaredBytes = Number(response.headers.get('content-length'));
  if (Number.isFinite(declaredBytes) && declaredBytes > maxBytes) {
    throw new RangeError(`Image response declares ${declaredBytes} bytes; the limit is ${maxBytes} bytes.`);
  }
  return readResponseBlobBounded(response, maxBytes, signal);
}

async function readResponseBlobBounded(response: Response, maxBytes: number, signal: AbortSignal): Promise<Blob> {
  if (response.body === null) {
    const blob = await response.blob();
    if (blob.size > maxBytes) {
      throw new RangeError(`Image response is ${blob.size} bytes; the limit is ${maxBytes} bytes.`);
    }
    return blob;
  }

  const reader = response.body.getReader();
  const chunks: Uint8Array<ArrayBuffer>[] = [];
  let receivedBytes = 0;
  try {
    while (true) {
      if (signal.aborted) throw abortError();
      const {done, value} = await reader.read();
      if (done) break;
      if (value === undefined || value.byteLength === 0) continue;
      receivedBytes += value.byteLength;
      if (receivedBytes > maxBytes) {
        await reader.cancel('Image source exceeded its byte limit.');
        throw new RangeError(`Image response exceeds the ${maxBytes}-byte limit.`);
      }
      const ownedChunk = new Uint8Array(value.byteLength);
      ownedChunk.set(value);
      chunks.push(ownedChunk);
    }
  } finally {
    reader.releaseLock();
  }
  return new Blob(chunks, {type: response.headers.get('content-type') ?? ''});
}

function createCanvasContext(width: number, height: number): OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D {
  requireDimension(width, 'resample width');
  requireDimension(height, 'resample height');
  if (typeof OffscreenCanvas !== 'undefined') {
    const canvas = new OffscreenCanvas(width, height);
    const context = canvas.getContext('2d', {alpha: true, willReadFrequently: true});
    if (context !== null) return context;
  }
  const documentObject = globalThis.document;
  if (documentObject !== undefined) {
    const canvas = documentObject.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d', {alpha: true, willReadFrequently: true});
    if (context !== null) return context;
  }
  throw new Error('OffscreenCanvas and a document canvas are unavailable for safe image resampling.');
}

function resampleFloatRgba(
  source: Float32Array,
  sourceWidth: number,
  sourceHeight: number,
  width: number,
  height: number
): Float32Array {
  requireDimension(width, 'resample width');
  requireDimension(height, 'resample height');
  if (source.length !== sourceWidth * sourceHeight * 4) {
    throw new RangeError('Float environment data must contain exactly width * height * 4 values.');
  }
  if (sourceWidth === width && sourceHeight === height) return new Float32Array(source);
  const output = new Float32Array(width * height * 4);
  for (let y = 0; y < height; y += 1) {
    const sourceY = ((y + 0.5) * sourceHeight / height) - 0.5;
    const y0 = clampInteger(Math.floor(sourceY), 0, sourceHeight - 1);
    const y1 = Math.min(y0 + 1, sourceHeight - 1);
    const ty = Math.max(0, Math.min(1, sourceY - y0));
    for (let x = 0; x < width; x += 1) {
      const sourceX = ((x + 0.5) * sourceWidth / width) - 0.5;
      const x0 = clampInteger(Math.floor(sourceX), 0, sourceWidth - 1);
      const x1 = Math.min(x0 + 1, sourceWidth - 1);
      const tx = Math.max(0, Math.min(1, sourceX - x0));
      const destinationOffset = (y * width + x) * 4;
      for (let channel = 0; channel < 4; channel += 1) {
        const top = mix(
          finiteOrZero(source[(y0 * sourceWidth + x0) * 4 + channel]),
          finiteOrZero(source[(y0 * sourceWidth + x1) * 4 + channel]),
          tx
        );
        const bottom = mix(
          finiteOrZero(source[(y1 * sourceWidth + x0) * 4 + channel]),
          finiteOrZero(source[(y1 * sourceWidth + x1) * 4 + channel]),
          tx
        );
        output[destinationOffset + channel] = Math.max(0, mix(top, bottom, ty));
      }
    }
  }
  return output;
}

async function resampleFloatRgbaAsync(
  source: Float32Array,
  sourceWidth: number,
  sourceHeight: number,
  width: number,
  height: number,
  options: CooperativeTextureWorkOptions
): Promise<Float32Array> {
  requireDimension(width, 'resample width');
  requireDimension(height, 'resample height');
  if (source.length !== sourceWidth * sourceHeight * 4) {
    throw new RangeError('Float environment data must contain exactly width * height * 4 values.');
  }
  const work = new CooperativeTextureWork(options);
  await work.checkpoint(true);
  if (sourceWidth === width && sourceHeight === height) {
    const copy = new Float32Array(source.length);
    for (let index = 0; index < source.length; index += 1) {
      copy[index] = source[index]!;
      if ((index & 0x3fff) === 0x3fff && work.shouldYield()) await work.checkpoint(true);
    }
    work.assertCurrent();
    return copy;
  }
  const output = new Float32Array(width * height * 4);
  for (let y = 0; y < height; y += 1) {
    const sourceY = ((y + 0.5) * sourceHeight / height) - 0.5;
    const y0 = clampInteger(Math.floor(sourceY), 0, sourceHeight - 1);
    const y1 = Math.min(y0 + 1, sourceHeight - 1);
    const ty = Math.max(0, Math.min(1, sourceY - y0));
    for (let x = 0; x < width; x += 1) {
      const sourceX = ((x + 0.5) * sourceWidth / width) - 0.5;
      const x0 = clampInteger(Math.floor(sourceX), 0, sourceWidth - 1);
      const x1 = Math.min(x0 + 1, sourceWidth - 1);
      const tx = Math.max(0, Math.min(1, sourceX - x0));
      const destinationOffset = (y * width + x) * 4;
      for (let channel = 0; channel < 4; channel += 1) {
        const top = mix(
          finiteOrZero(source[(y0 * sourceWidth + x0) * 4 + channel]),
          finiteOrZero(source[(y0 * sourceWidth + x1) * 4 + channel]),
          tx
        );
        const bottom = mix(
          finiteOrZero(source[(y1 * sourceWidth + x0) * 4 + channel]),
          finiteOrZero(source[(y1 * sourceWidth + x1) * 4 + channel]),
          tx
        );
        output[destinationOffset + channel] = Math.max(0, mix(top, bottom, ty));
      }
    }
    if (work.shouldYield()) await work.checkpoint(true);
  }
  work.assertCurrent();
  return output;
}

function normalizeByteLimit(value: number | undefined): number {
  if (value === undefined) return DEFAULT_MAX_IMAGE_SOURCE_BYTES;
  if (!Number.isSafeInteger(value) || value < 1 || value > DEFAULT_MAX_IMAGE_SOURCE_BYTES) {
    throw new RangeError(`maxSourceBytes must be an integer from 1 through ${DEFAULT_MAX_IMAGE_SOURCE_BYTES}.`);
  }
  return value;
}

function requireDimension(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 1 || value > 32_768) {
    throw new RangeError(`${label} must be an integer from 1 through 32768.`);
  }
}

function sourceLabel(source: TextureImageSource): string {
  if (source instanceof Blob) return source.type ? `blob (${source.type})` : 'blob';
  try {
    return safeUrl(new URL(String(source), globalThis.location?.href));
  } catch {
    return 'image URL';
  }
}

function safeUrl(url: URL): string {
  if (url.protocol === 'data:') return 'data URL';
  if (url.protocol === 'blob:') return 'blob URL';
  return `${url.origin}${url.pathname}`;
}

function hasHdrFileExtension(source: TextureImageSource): boolean {
  if (source instanceof Blob) return false;
  try {
    return new URL(String(source), globalThis.location?.href).pathname.toLowerCase().endsWith('.hdr');
  } catch {
    return false;
  }
}

function isHdrMimeType(type: string): boolean {
  const normalized = type.toLowerCase();
  return normalized.includes('radiance') || normalized === 'image/x-hdr' || normalized === 'image/vnd.radiance';
}

function srgbToLinear(value: number): number {
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
}

function finiteOrZero(value: number | undefined): number {
  return Number.isFinite(value) ? value! : 0;
}

function mix(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

function clampInteger(value: number, minimum: number, maximum: number): number {
  return Math.max(minimum, Math.min(maximum, value));
}

function abortError(): DOMException {
  return new DOMException('Image loading was aborted.', 'AbortError');
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
