import type {
  NormalizedVideoRecordingOptions,
  VideoRecordingOptions
} from './types';

const MICROSECONDS_PER_SECOND = 1_000_000;
const DEFAULT_MAX_OUTPUT_BYTES = 512 * 1024 * 1024;

function positiveFinite(name: string, value: number): number {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive finite number`);
  }
  return value;
}

export function normalizeVideoRecordingOptions(
  options: VideoRecordingOptions
): NormalizedVideoRecordingOptions {
  const fps = positiveFinite('fps', options.fps);
  if (fps > 1_000) {
    throw new RangeError('fps must not exceed 1000');
  }

  const bitrate = Math.round(positiveFinite('bitrate', options.bitrate));
  if (!Number.isSafeInteger(bitrate)) {
    throw new RangeError('bitrate must be a safe integer');
  }

  const maxQueueSize = options.maxQueueSize ?? 2;
  if (!Number.isInteger(maxQueueSize) || maxQueueSize < 1 || maxQueueSize > 64) {
    throw new RangeError('maxQueueSize must be an integer from 1 through 64');
  }

  const keyFrameIntervalSeconds = positiveFinite(
    'keyFrameIntervalSeconds',
    options.keyFrameIntervalSeconds ?? 2
  );
  if (keyFrameIntervalSeconds > 3_600) {
    throw new RangeError('keyFrameIntervalSeconds must not exceed 3600');
  }

  const maxOutputBytes = options.maxOutputBytes ?? DEFAULT_MAX_OUTPUT_BYTES;
  if (!Number.isSafeInteger(maxOutputBytes) || maxOutputBytes < 1_048_576) {
    throw new RangeError('maxOutputBytes must be a safe integer of at least 1048576');
  }

  return {
    mode: options.mode,
    fps,
    bitrate,
    codec: options.codec ?? 'auto',
    maxQueueSize,
    keyFrameIntervalSeconds,
    maxOutputBytes
  };
}

export function frameTimestampUs(frameIndex: number, fps: number): number {
  positiveFinite('fps', fps);
  if (!Number.isSafeInteger(frameIndex) || frameIndex < 0) {
    throw new RangeError('frameIndex must be a non-negative safe integer');
  }

  const timestamp = Math.round((frameIndex * MICROSECONDS_PER_SECOND) / fps);
  if (!Number.isSafeInteger(timestamp)) {
    throw new RangeError('frame timestamp exceeds the safe integer range');
  }
  return timestamp;
}

export function frameTiming(
  frameIndex: number,
  fps: number
): Readonly<{timestamp: number; duration: number}> {
  const timestamp = frameTimestampUs(frameIndex, fps);
  const end = frameTimestampUs(frameIndex + 1, fps);
  return {timestamp, duration: end - timestamp};
}

export function realtimeFrameSlot(elapsedMilliseconds: number, fps: number): number {
  positiveFinite('fps', fps);
  if (!Number.isFinite(elapsedMilliseconds)) {
    throw new RangeError('elapsedMilliseconds must be finite');
  }
  if (elapsedMilliseconds <= 0) return 0;

  const slot = Math.floor((elapsedMilliseconds * fps) / 1_000);
  if (!Number.isSafeInteger(slot)) {
    throw new RangeError('realtime frame slot exceeds the safe integer range');
  }
  return slot;
}

export function shouldRequestKeyFrame(
  timestampUs: number,
  lastKeyFrameTimestampUs: number | null,
  intervalSeconds: number
): boolean {
  if (lastKeyFrameTimestampUs === null) return true;
  return timestampUs - lastKeyFrameTimestampUs >= intervalSeconds * MICROSECONDS_PER_SECOND;
}
