import type {EncodedVideoChunkSource, WebMVideoCodec} from './types';

interface ByteSequence {
  readonly parts: readonly BytePart[];
  readonly byteLength: number;
}

type BytePart = Uint8Array | ByteSequence;

interface StoredVideoChunk {
  readonly data: Uint8Array;
  readonly durationUs: number;
  readonly timestampUs: number;
  readonly keyFrame: boolean;
}

interface ClusterDescription {
  readonly timestampMs: number;
  readonly chunks: readonly StoredVideoChunk[];
}

export interface WebMMuxerOptions {
  width: number;
  height: number;
  fps: number;
  codec: WebMVideoCodec;
  clusterDurationMs?: number;
  muxingApp?: string;
  maxOutputBytes?: number;
}

const IDS = {
  ebml: [0x1a, 0x45, 0xdf, 0xa3],
  ebmlVersion: [0x42, 0x86],
  ebmlReadVersion: [0x42, 0xf7],
  ebmlMaxIdLength: [0x42, 0xf2],
  ebmlMaxSizeLength: [0x42, 0xf3],
  docType: [0x42, 0x82],
  docTypeVersion: [0x42, 0x87],
  docTypeReadVersion: [0x42, 0x85],
  segment: [0x18, 0x53, 0x80, 0x67],
  info: [0x15, 0x49, 0xa9, 0x66],
  timestampScale: [0x2a, 0xd7, 0xb1],
  duration: [0x44, 0x89],
  muxingApp: [0x4d, 0x80],
  writingApp: [0x57, 0x41],
  tracks: [0x16, 0x54, 0xae, 0x6b],
  trackEntry: [0xae],
  trackNumber: [0xd7],
  trackUid: [0x73, 0xc5],
  trackType: [0x83],
  flagLacing: [0x9c],
  codecId: [0x86],
  defaultDuration: [0x23, 0xe3, 0x83],
  video: [0xe0],
  pixelWidth: [0xb0],
  pixelHeight: [0xba],
  displayWidth: [0x54, 0xb0],
  displayHeight: [0x54, 0xba],
  cluster: [0x1f, 0x43, 0xb6, 0x75],
  timestamp: [0xe7],
  simpleBlock: [0xa3],
  cues: [0x1c, 0x53, 0xbb, 0x6b],
  cuePoint: [0xbb],
  cueTime: [0xb3],
  cueTrackPositions: [0xb7],
  cueTrack: [0xf7],
  cueClusterPosition: [0xf1]
} as const;

const TIMESTAMP_SCALE_NS = 1_000_000;
const DEFAULT_CLUSTER_DURATION_MS = 5_000;
const DEFAULT_MAX_OUTPUT_BYTES = 512 * 1024 * 1024;
const MAX_BLOCK_TIMECODE = 32_767;
const MIN_BLOCK_TIMECODE = -32_768;
const textEncoder = new TextEncoder();

function sequence(...parts: readonly BytePart[]): ByteSequence {
  let byteLength = 0;
  for (const part of parts) byteLength += part.byteLength;
  return {parts, byteLength};
}

function flatten(part: BytePart): Uint8Array {
  const output = new Uint8Array(part.byteLength);
  const stack: Array<{part: BytePart; offset: number}> = [{part, offset: 0}];
  while (stack.length > 0) {
    const current = stack.pop();
    if (!current) break;
    if (current.part instanceof Uint8Array) {
      output.set(current.part, current.offset);
      continue;
    }

    let childOffset = current.offset;
    const children: Array<{part: BytePart; offset: number}> = [];
    for (const child of current.part.parts) {
      children.push({part: child, offset: childOffset});
      childOffset += child.byteLength;
    }
    for (let index = children.length - 1; index >= 0; index -= 1) {
      const child = children[index];
      if (child) stack.push(child);
    }
  }
  return output;
}

export function encodeEbmlSize(value: number): Uint8Array {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError('EBML size must be a non-negative safe integer');
  }

  const size = BigInt(value);
  for (let width = 1; width <= 8; width += 1) {
    const maximum = (1n << BigInt(width * 7)) - 2n;
    if (size > maximum) continue;

    const output = new Uint8Array(width);
    let remaining = size;
    for (let index = width - 1; index >= 0; index -= 1) {
      output[index] = Number(remaining & 0xffn);
      remaining >>= 8n;
    }
    const marker = 1 << (8 - width);
    output[0] = (output[0] ?? 0) | marker;
    return output;
  }
  throw new RangeError('EBML size exceeds the supported 56-bit range');
}

function unsignedBytes(value: number | bigint, minimumWidth = 1): Uint8Array {
  let remaining = typeof value === 'bigint' ? value : BigInt(value);
  if (remaining < 0n) throw new RangeError('EBML unsigned integers cannot be negative');

  let width = minimumWidth;
  let probe = remaining;
  while (probe > 0xffn) {
    width += 1;
    probe >>= 8n;
  }

  const output = new Uint8Array(width);
  for (let index = width - 1; index >= 0; index -= 1) {
    output[index] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return output;
}

function float64Bytes(value: number): Uint8Array {
  const output = new Uint8Array(8);
  new DataView(output.buffer).setFloat64(0, value, false);
  return output;
}

function element(id: readonly number[], payload: BytePart): ByteSequence {
  return sequence(Uint8Array.from(id), encodeEbmlSize(payload.byteLength), payload);
}

function unsignedElement(
  id: readonly number[],
  value: number | bigint,
  minimumWidth = 1
): ByteSequence {
  return element(id, unsignedBytes(value, minimumWidth));
}

function stringElement(id: readonly number[], value: string): ByteSequence {
  return element(id, textEncoder.encode(value));
}

function floatElement(id: readonly number[], value: number): ByteSequence {
  return element(id, float64Bytes(value));
}

function finitePositive(name: string, value: number): number {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive finite number`);
  }
  return value;
}

function integerDimension(name: string, value: number): number {
  if (!Number.isSafeInteger(value) || value <= 0 || value > 65_535) {
    throw new RangeError(`${name} must be an integer from 1 through 65535`);
  }
  return value;
}

function codecId(codec: WebMVideoCodec): string {
  return codec === 'vp9' ? 'V_VP9' : 'V_VP8';
}

function simpleBlock(chunk: StoredVideoChunk, clusterTimestampMs: number): ByteSequence {
  const timestampMs = Math.round(chunk.timestampUs / 1_000);
  const relativeTimestamp = timestampMs - clusterTimestampMs;
  if (relativeTimestamp < MIN_BLOCK_TIMECODE || relativeTimestamp > MAX_BLOCK_TIMECODE) {
    throw new RangeError('SimpleBlock timestamp is outside the signed 16-bit range');
  }

  const header = new Uint8Array(4);
  header[0] = 0x81;
  new DataView(header.buffer).setInt16(1, relativeTimestamp, false);
  header[3] = chunk.keyFrame ? 0x80 : 0;
  return element(IDS.simpleBlock, sequence(header, chunk.data));
}

export class WebMMuxer {
  readonly width: number;
  readonly height: number;
  readonly fps: number;
  readonly codec: WebMVideoCodec;

  private readonly clusterDurationMs: number;
  private readonly muxingApp: string;
  private readonly maxOutputBytes: number;
  private readonly chunks: StoredVideoChunk[] = [];
  private payloadBytes = 0;
  private finalized = false;

  constructor(options: WebMMuxerOptions) {
    this.width = integerDimension('width', options.width);
    this.height = integerDimension('height', options.height);
    this.fps = finitePositive('fps', options.fps);
    if (this.fps > 1_000) throw new RangeError('fps must not exceed 1000');
    this.codec = options.codec;
    this.clusterDurationMs = finitePositive(
      'clusterDurationMs',
      options.clusterDurationMs ?? DEFAULT_CLUSTER_DURATION_MS
    );
    this.muxingApp = options.muxingApp ?? 'PrioSDK Gen 4';
    this.maxOutputBytes = options.maxOutputBytes ?? DEFAULT_MAX_OUTPUT_BYTES;
    if (!Number.isSafeInteger(this.maxOutputBytes) || this.maxOutputBytes < 1_048_576) {
      throw new RangeError('maxOutputBytes must be a safe integer of at least 1048576');
    }
  }

  get frameCount(): number {
    return this.chunks.length;
  }

  addChunk(chunk: EncodedVideoChunkSource): void {
    if (this.finalized) throw new Error('Cannot add a chunk after the WebM has been finalized');
    if (!Number.isSafeInteger(chunk.timestamp) || chunk.timestamp < 0) {
      throw new RangeError('Encoded chunk timestamp must be a non-negative safe integer');
    }
    if (!Number.isSafeInteger(chunk.byteLength) || chunk.byteLength <= 0) {
      throw new RangeError('Encoded chunk byteLength must be a positive safe integer');
    }
    if (this.payloadBytes + chunk.byteLength > this.maxOutputBytes) {
      throw new RangeError(
        `WebM encoded payload exceeds the configured ${this.maxOutputBytes}-byte limit`
      );
    }

    const previous = this.chunks.at(-1);
    if (previous && chunk.timestamp <= previous.timestampUs) {
      throw new RangeError('Encoded chunk timestamps must be strictly increasing');
    }
    if (!previous && chunk.type !== 'key') {
      throw new Error('The first encoded video chunk must be a key frame');
    }

    const defaultDuration = Math.max(1, Math.round(1_000_000 / this.fps));
    const durationUs = chunk.duration ?? defaultDuration;
    if (!Number.isSafeInteger(durationUs) || durationUs <= 0) {
      throw new RangeError('Encoded chunk duration must be a positive safe integer');
    }

    const data = new Uint8Array(chunk.byteLength);
    chunk.copyTo(data);
    this.chunks.push({
      data,
      durationUs,
      timestampUs: chunk.timestamp,
      keyFrame: chunk.type === 'key'
    });
    this.payloadBytes += chunk.byteLength;
  }

  finalize(): Uint8Array {
    if (this.finalized) throw new Error('WebM has already been finalized');
    this.finalized = true;

    const header = this.createEbmlHeader();
    const info = this.createInfo();
    const tracks = this.createTracks();
    const clusterDescriptions = this.describeClusters();
    const clusters = clusterDescriptions.map(cluster => this.createCluster(cluster));

    let clusterPosition = info.byteLength + tracks.byteLength;
    const cuePoints: ByteSequence[] = [];
    for (let index = 0; index < clusters.length; index += 1) {
      const cluster = clusters[index];
      const description = clusterDescriptions[index];
      if (!cluster || !description) continue;
      cuePoints.push(this.createCuePoint(description.timestampMs, clusterPosition));
      clusterPosition += cluster.byteLength;
    }
    const cues = element(IDS.cues, sequence(...cuePoints));
    const segment = element(IDS.segment, sequence(info, tracks, ...clusters, cues));
    const document = sequence(header, segment);
    if (document.byteLength > this.maxOutputBytes) {
      throw new RangeError(
        `Final WebM exceeds the configured ${this.maxOutputBytes}-byte limit`
      );
    }
    return flatten(document);
  }

  private durationUs(): number {
    let duration = 0;
    for (const chunk of this.chunks) {
      duration = Math.max(duration, chunk.timestampUs + chunk.durationUs);
    }
    return duration;
  }

  private createEbmlHeader(): ByteSequence {
    return element(
      IDS.ebml,
      sequence(
        unsignedElement(IDS.ebmlVersion, 1),
        unsignedElement(IDS.ebmlReadVersion, 1),
        unsignedElement(IDS.ebmlMaxIdLength, 4),
        unsignedElement(IDS.ebmlMaxSizeLength, 8),
        stringElement(IDS.docType, 'webm'),
        unsignedElement(IDS.docTypeVersion, 4),
        unsignedElement(IDS.docTypeReadVersion, 2)
      )
    );
  }

  private createInfo(): ByteSequence {
    return element(
      IDS.info,
      sequence(
        unsignedElement(IDS.timestampScale, TIMESTAMP_SCALE_NS),
        floatElement(IDS.duration, this.durationUs() / 1_000),
        stringElement(IDS.muxingApp, this.muxingApp),
        stringElement(IDS.writingApp, this.muxingApp)
      )
    );
  }

  private createTracks(): ByteSequence {
    const defaultDurationNs = Math.max(1, Math.round(1_000_000_000 / this.fps));
    const video = element(
      IDS.video,
      sequence(
        unsignedElement(IDS.pixelWidth, this.width),
        unsignedElement(IDS.pixelHeight, this.height),
        unsignedElement(IDS.displayWidth, this.width),
        unsignedElement(IDS.displayHeight, this.height)
      )
    );
    const track = element(
      IDS.trackEntry,
      sequence(
        unsignedElement(IDS.trackNumber, 1),
        unsignedElement(IDS.trackUid, 1),
        unsignedElement(IDS.trackType, 1),
        unsignedElement(IDS.flagLacing, 0),
        stringElement(IDS.codecId, codecId(this.codec)),
        unsignedElement(IDS.defaultDuration, defaultDurationNs),
        video
      )
    );
    return element(IDS.tracks, track);
  }

  private describeClusters(): ClusterDescription[] {
    const clusters: Array<{timestampMs: number; chunks: StoredVideoChunk[]}> = [];
    for (const chunk of this.chunks) {
      const timestampMs = Math.round(chunk.timestampUs / 1_000);
      const current = clusters.at(-1);
      const relative = current ? timestampMs - current.timestampMs : 0;
      const outsideBlockRange =
        relative < MIN_BLOCK_TIMECODE || relative > MAX_BLOCK_TIMECODE;
      const keyFrameBoundary =
        Boolean(current) &&
        chunk.keyFrame &&
        relative >= this.clusterDurationMs;
      if (!current || outsideBlockRange || keyFrameBoundary) {
        clusters.push({timestampMs, chunks: [chunk]});
      } else {
        current.chunks.push(chunk);
      }
    }
    return clusters;
  }

  private createCluster(cluster: ClusterDescription): ByteSequence {
    return element(
      IDS.cluster,
      sequence(
        unsignedElement(IDS.timestamp, cluster.timestampMs),
        ...cluster.chunks.map(chunk => simpleBlock(chunk, cluster.timestampMs))
      )
    );
  }

  private createCuePoint(timestampMs: number, clusterPosition: number): ByteSequence {
    const trackPosition = element(
      IDS.cueTrackPositions,
      sequence(
        unsignedElement(IDS.cueTrack, 1),
        unsignedElement(IDS.cueClusterPosition, clusterPosition)
      )
    );
    return element(
      IDS.cuePoint,
      sequence(unsignedElement(IDS.cueTime, timestampMs), trackPosition)
    );
  }
}
