  createDetailedMaterial(args: BlockArguments): string {
    return this.runReporter(() => {
      const surfaceDetail = this.text(args.SURFACE);
      const definition: DynamicApi = {
        baseColor: [this.number(args.RED), this.number(args.GREEN), this.number(args.BLUE)],
        roughness: this.number(args.ROUGHNESS),
        metallic: this.number(args.METALLIC),
        surfaceDetail,
        colorVariation: this.number(args.VARIATION),
        roughnessVariation: this.number(args.ROUGHNESS_VARIATION),
        normalStrength: this.number(args.NORMAL_STRENGTH),
        detailScale: this.number(args.DETAIL_SCALE),
        windInfluence: this.number(args.WIND),
        doubleSided: this.boolean(args.DOUBLE_SIDED)
      };
      if (surfaceDetail === 'glass' || surfaceDetail === 'solid-glass') {
        definition.metallic = 0;
        definition.transmission = 0.98;
        definition.ior = 1.52;
        definition.alpha = 1;
      } else if (surfaceDetail === 'unlit') {
        definition.emissionColor = [1, 1, 1];
        definition.emissionStrength = 1;
      }
      return this.invokeRendererHandle('createMaterial', definition);
    }, '');
  }

