  async loadNativePanorama(args: BlockArguments): Promise<void> {
    await this.runAsync(async () => {
      const layer = this.panoramaLayer(args.LAYER);
      const source = await this.resolveImageSource(args.SOURCE);
      const options = {
        intensity: this.number(args.INTENSITY),
        rotationDegrees: this.number(args.YAW),
        pitchDegrees: this.number(args.PITCH),
        flipY: this.boolean(args.FLIP_Y)
      };
      if (layer === 'physical sky + lighting') {
        await this.renderer.loadEnvironmentMap(source, options);
      } else {
        await this.renderer.loadBackplateMap(source, options);
      }
    });
  }

  configureNativePanorama(args: BlockArguments): void {
    this.run(() => {
      const layer = this.panoramaLayer(args.LAYER);
      const intensity = this.number(args.INTENSITY);
      const yaw = this.number(args.YAW);
      const pitch = this.number(args.PITCH);
      if (layer === 'physical sky + lighting') {
        this.renderer.setEnvironmentMapIntensity(intensity);
        this.renderer.setEnvironmentMapOrientation(yaw, pitch);
      } else {
        this.renderer.setBackplateMapIntensity(intensity);
        this.renderer.setBackplateMapOrientation(yaw, pitch);
      }
    });
  }

  clearNativePanorama(args: BlockArguments): void {
    this.run(() => {
      const layer = this.panoramaLayer(args.LAYER);
      if (layer === 'physical sky + lighting') this.renderer.clearEnvironmentMap();
      else this.renderer.clearBackplateMap();
    });
  }

  nativePanoramaStatus(args: BlockArguments): string {
    return this.runReporter(() => {
      const layer = this.panoramaLayer(args.LAYER);
      const status = layer === 'physical sky + lighting'
        ? this.renderer.getEnvironmentMapStatus()
        : this.renderer.getBackplateMapStatus();
      const cameraOnlyBackgroundReady = layer === 'camera-only background'
        ? status.state === 'ready'
        : this.renderer.getBackplateMapStatus().state === 'ready';
      return JSON.stringify({
        layer,
        projection: 'equirectangular',
        gpuNative: true,
        cameraVisible: status.state === 'ready'
          && (layer === 'camera-only background' || !cameraOnlyBackgroundReady),
        contributesLighting: layer === 'physical sky + lighting',
        contributesReflections: layer === 'physical sky + lighting',
        ...status
      }) ?? '{}';
    }, '{}');
  }

