import type {TextureHandle} from './types';

interface TextureSlot<T> {
  generation: number;
  value: T | null;
}

const TEXTURE_HANDLE_PATTERN = /^texture:([a-z0-9]+):(\d+):(\d+)$/;
let nextTextureOwner = 1;

export class TextureHandleRegistry<T> {
  readonly #owner = `t${(nextTextureOwner++).toString(36)}`;
  readonly #slots: TextureSlot<T>[];
  #size = 0;

  constructor(capacity: number) {
    if (!Number.isSafeInteger(capacity) || capacity < 1) {
      throw new RangeError('Texture handle capacity must be a positive safe integer.');
    }
    this.#slots = Array.from({length: capacity}, () => ({generation: 1, value: null}));
  }

  get capacity(): number {
    return this.#slots.length;
  }

  get size(): number {
    return this.#size;
  }

  create(value: T): TextureHandle {
    const slotIndex = this.#slots.findIndex(slot => slot.value === null);
    if (slotIndex < 0) {
      throw new RangeError(`The texture registry is full (${this.capacity} user textures).`);
    }
    const slot = this.#slots[slotIndex];
    if (!slot) throw new Error('Internal texture-handle slot invariant failed.');
    slot.value = value;
    this.#size += 1;
    return this.#format(slotIndex, slot.generation);
  }

  has(handle: unknown): handle is TextureHandle {
    const parsed = this.#parse(handle);
    if (parsed === null) return false;
    const slot = this.#slots[parsed.slot];
    return slot !== undefined && slot.value !== null && slot.generation === parsed.generation;
  }

  get(handle: TextureHandle): T {
    const parsed = this.#require(handle);
    const value = this.#slots[parsed.slot]?.value;
    if (value === null || value === undefined) throw this.#invalid(handle);
    return value;
  }

  set(handle: TextureHandle, value: T): void {
    const parsed = this.#require(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null) throw this.#invalid(handle);
    slot.value = value;
  }

  remove(handle: TextureHandle): T {
    const parsed = this.#require(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null) throw this.#invalid(handle);
    const value = slot.value;
    slot.value = null;
    slot.generation = nextGeneration(slot.generation);
    this.#size -= 1;
    return value;
  }

  clear(): void {
    for (const slot of this.#slots) {
      if (slot.value !== null) {
        slot.value = null;
        slot.generation = nextGeneration(slot.generation);
      }
    }
    this.#size = 0;
  }

  entries(): Array<{readonly handle: TextureHandle; readonly value: T}> {
    const entries: Array<{handle: TextureHandle; value: T}> = [];
    for (let index = 0; index < this.#slots.length; index += 1) {
      const slot = this.#slots[index];
      if (slot?.value !== null && slot?.value !== undefined) {
        entries.push({handle: this.#format(index, slot.generation), value: slot.value});
      }
    }
    return entries;
  }

  #format(slot: number, generation: number): TextureHandle {
    return `texture:${this.#owner}:${slot}:${generation}` as TextureHandle;
  }

  #parse(handle: unknown): {slot: number; generation: number} | null {
    if (typeof handle !== 'string') return null;
    const match = TEXTURE_HANDLE_PATTERN.exec(handle);
    if (!match || match[1] !== this.#owner) return null;
    const slot = Number(match[2]);
    const generation = Number(match[3]);
    if (
      !Number.isSafeInteger(slot)
      || !Number.isSafeInteger(generation)
      || slot < 0
      || slot >= this.#slots.length
      || generation < 1
    ) return null;
    return {slot, generation};
  }

  #require(handle: TextureHandle): {slot: number; generation: number} {
    const parsed = this.#parse(handle);
    if (parsed === null) throw this.#invalid(handle);
    const slot = this.#slots[parsed.slot];
    if (!slot || slot.value === null || slot.generation !== parsed.generation) {
      throw this.#invalid(handle);
    }
    return parsed;
  }

  #invalid(handle: unknown): RangeError {
    return new RangeError(`Invalid or stale texture handle: ${String(handle)}`);
  }
}

function nextGeneration(generation: number): number {
  return generation === Number.MAX_SAFE_INTEGER ? 1 : generation + 1;
}
