export const PATH_TRACER_SHADER = /* wgsl */ `
struct Globals {
  resolution_samples: vec4<f32>,
  camera_position_tan_fov: vec4<f32>,
  camera_forward_mode: vec4<f32>,
  camera_right_exposure: vec4<f32>,
  camera_up_fog_density: vec4<f32>,
  fog_color_jitter_x: vec4<f32>,
  jitter_y_params: vec4<f32>,
  render_params: vec4<f32>,
}

struct Sphere {
  center_radius: vec4<f32>,
  color_roughness: vec4<f32>,
  material: vec4<f32>,
}

struct Ray {
  origin: vec3<f32>,
  direction: vec3<f32>,
}

struct Hit {
  t: f32,
  position: vec3<f32>,
  normal: vec3<f32>,
  albedo: vec3<f32>,
  roughness: f32,
  metallic: f32,
  emission: f32,
  hit: u32,
}

@group(0) @binding(0) var<uniform> globals: Globals;
@group(0) @binding(1) var<storage, read> spheres: array<Sphere>;
@group(0) @binding(2) var previous_frame: texture_2d<f32>;
@group(0) @binding(3) var output_frame: texture_storage_2d<rgba16float, write>;

const PI: f32 = 3.141592653589793;
const EPSILON: f32 = 0.001;
const MAX_BOUNCES: u32 = 8u;
const MAX_SAMPLES_PER_FRAME: u32 = 8u;

fn hash_u32(value: u32) -> u32 {
  var result = value + 0x9e3779b9u;
  result = (result ^ (result >> 16u)) * 0x21f0aaadu;
  result = (result ^ (result >> 15u)) * 0x735a2d97u;
  return result ^ (result >> 15u);
}

fn random(state: ptr<function, u32>) -> f32 {
  *state = hash_u32(*state);
  return f32(*state) * (1.0 / 4294967296.0);
}

fn sun_direction() -> vec3<f32> {
  return normalize(vec3<f32>(0.48, 0.82, 0.31));
}

fn environment(direction: vec3<f32>) -> vec3<f32> {
  let sky_factor = smoothstep(-0.15, 0.8, direction.y);
  let sky = mix(
    vec3<f32>(0.78, 0.87, 1.02),
    vec3<f32>(0.12, 0.32, 0.82),
    sky_factor
  );
  let lower_hemisphere = vec3<f32>(0.035, 0.045, 0.065);
  let base = select(lower_hemisphere, sky, direction.y > 0.0);
  let sun = pow(max(dot(direction, sun_direction()), 0.0), 1024.0) * 24.0;
  return base + vec3<f32>(1.0, 0.78, 0.48) * sun;
}

fn miss() -> Hit {
  return Hit(
    1e30,
    vec3<f32>(0.0),
    vec3<f32>(0.0, 1.0, 0.0),
    vec3<f32>(0.0),
    1.0,
    0.0,
    0.0,
    0u
  );
}

fn intersect_sphere(ray: Ray, sphere: Sphere, closest: f32) -> Hit {
  let center = sphere.center_radius.xyz;
  let radius = sphere.center_radius.w;
  if (radius <= EPSILON) {
    return miss();
  }
  let offset = ray.origin - center;
  let half_b = dot(offset, ray.direction);
  let c = dot(offset, offset) - radius * radius;
  let discriminant = half_b * half_b - c;
  if (discriminant < 0.0) {
    return miss();
  }

  let root = sqrt(discriminant);
  var distance = -half_b - root;
  if (distance <= EPSILON) {
    distance = -half_b + root;
  }
  if (distance <= EPSILON || distance >= closest) {
    return miss();
  }

  let position = ray.origin + ray.direction * distance;
  return Hit(
    distance,
    position,
    normalize(position - center),
    max(sphere.color_roughness.xyz, vec3<f32>(0.0)),
    clamp(sphere.color_roughness.w, 0.02, 1.0),
    clamp(sphere.material.x, 0.0, 1.0),
    max(sphere.material.y, 0.0),
    1u
  );
}

fn intersect_scene(ray: Ray) -> Hit {
  var closest_hit = miss();
  let sphere_count = min(u32(globals.jitter_y_params.w), arrayLength(&spheres));
  for (var sphere_index = 0u; sphere_index < sphere_count; sphere_index += 1u) {
    let candidate = intersect_sphere(ray, spheres[sphere_index], closest_hit.t);
    if (candidate.hit != 0u) {
      closest_hit = candidate;
    }
  }

  if (ray.direction.y < -0.00001) {
    let plane_distance = -ray.origin.y / ray.direction.y;
    if (plane_distance > EPSILON && plane_distance < closest_hit.t) {
      let position = ray.origin + ray.direction * plane_distance;
      let checker_index = (i32(floor(position.x)) + i32(floor(position.z))) & 1;
      let checker = select(0.32, 0.72, checker_index == 0);
      closest_hit = Hit(
        plane_distance,
        position,
        vec3<f32>(0.0, 1.0, 0.0),
        vec3<f32>(checker, checker * 0.96, checker * 0.88),
        0.88,
        0.0,
        0.0,
        1u
      );
    }
  }

  return closest_hit;
}

fn is_occluded(origin: vec3<f32>, direction: vec3<f32>) -> bool {
  let shadow_hit = intersect_scene(Ray(origin, direction));
  return shadow_hit.hit != 0u;
}

fn make_basis_direction(normal: vec3<f32>, state: ptr<function, u32>) -> vec3<f32> {
  let radius = sqrt(random(state));
  let angle = 2.0 * PI * random(state);
  let local = vec3<f32>(radius * cos(angle), sqrt(max(0.0, 1.0 - radius * radius)), radius * sin(angle));
  let helper = select(vec3<f32>(0.0, 1.0, 0.0), vec3<f32>(1.0, 0.0, 0.0), abs(normal.y) > 0.98);
  let tangent = normalize(cross(helper, normal));
  let bitangent = cross(normal, tangent);
  return normalize(tangent * local.x + normal * local.y + bitangent * local.z);
}

fn direct_lighting(hit: Hit, view_direction: vec3<f32>) -> vec3<f32> {
  let light_direction = sun_direction();
  let n_dot_l = max(dot(hit.normal, light_direction), 0.0);
  let visible = select(1.0, 0.0, is_occluded(hit.position + hit.normal * (EPSILON * 3.0), light_direction));
  let sunlight = vec3<f32>(5.4, 4.35, 3.15) * n_dot_l * visible;
  let ambient = environment(hit.normal) * 0.16;
  let half_sum = light_direction - view_direction;
  let half_length_squared = dot(half_sum, half_sum);
  let half_vector = half_sum * inverseSqrt(max(half_length_squared, 0.000001));
  let specular_power = mix(10.0, 384.0, 1.0 - hit.roughness);
  let fresnel_zero = mix(vec3<f32>(0.04), hit.albedo, hit.metallic);
  let specular_alignment = select(0.0, max(dot(hit.normal, half_vector), 0.0), half_length_squared > 0.000001);
  let specular = fresnel_zero * pow(specular_alignment, specular_power) * sunlight;
  return hit.albedo * (sunlight + ambient) * (1.0 - hit.metallic) + specular;
}

fn trace_ray(primary_ray: Ray) -> vec3<f32> {
  let hit = intersect_scene(primary_ray);
  if (hit.hit == 0u) {
    return environment(primary_ray.direction);
  }

  let emitted = hit.albedo * hit.emission;
  let local_lighting = direct_lighting(hit, primary_ray.direction);
  let reflected_direction = reflect(primary_ray.direction, hit.normal);
  let reflected_hit = intersect_scene(Ray(hit.position + hit.normal * (EPSILON * 3.0), reflected_direction));
  var reflected_radiance = environment(reflected_direction);
  if (reflected_hit.hit != 0u) {
    reflected_radiance = reflected_hit.albedo * reflected_hit.emission
      + direct_lighting(reflected_hit, reflected_direction);
  }
  let reflection_strength = mix(0.04, 0.92, hit.metallic) * (1.0 - hit.roughness * 0.65);
  return emitted + mix(local_lighting, reflected_radiance * mix(vec3<f32>(1.0), hit.albedo, hit.metallic), reflection_strength);
}

fn trace_path(primary_ray: Ray, initial_state: u32) -> vec3<f32> {
  var state = initial_state;
  var ray = primary_ray;
  var throughput = vec3<f32>(1.0);
  var radiance = vec3<f32>(0.0);
  let bounce_limit = min(u32(globals.jitter_y_params.z), MAX_BOUNCES);

  for (var bounce = 0u; bounce < MAX_BOUNCES; bounce += 1u) {
    if (bounce >= bounce_limit) {
      break;
    }

    let hit = intersect_scene(ray);
    if (hit.hit == 0u) {
      radiance += throughput * environment(ray.direction);
      break;
    }

    radiance += throughput * hit.albedo * hit.emission;

    let light_direction = sun_direction();
    let n_dot_l = max(dot(hit.normal, light_direction), 0.0);
    if (n_dot_l > 0.0 && !is_occluded(hit.position + hit.normal * (EPSILON * 3.0), light_direction)) {
      let diffuse_weight = (1.0 - hit.metallic) / PI;
      radiance += throughput * hit.albedo * vec3<f32>(5.4, 4.35, 3.15) * n_dot_l * diffuse_weight;
    }

    let diffuse_direction = make_basis_direction(hit.normal, &state);
    if (random(&state) < hit.metallic) {
      let perfect_reflection = reflect(ray.direction, hit.normal);
      ray.direction = normalize(mix(perfect_reflection, diffuse_direction, hit.roughness * hit.roughness));
      throughput *= mix(vec3<f32>(0.65), hit.albedo, 0.9);
    } else {
      ray.direction = diffuse_direction;
      throughput *= hit.albedo;
    }
    ray.origin = hit.position + hit.normal * (EPSILON * 3.0);

    if (bounce >= 2u) {
      let survival_probability = clamp(max(throughput.r, max(throughput.g, throughput.b)), 0.1, 0.95);
      if (random(&state) > survival_probability) {
        break;
      }
      throughput /= survival_probability;
    }
  }

  return radiance;
}

fn apply_volumetric_fog(color: vec3<f32>, ray: Ray, distance: f32) -> vec3<f32> {
  let density = globals.camera_up_fog_density.w;
  if (density <= 0.0) {
    return color;
  }

  let transmittance = exp(-density * max(distance, 0.0));
  let forward_scattering = pow(max(dot(ray.direction, sun_direction()), 0.0), 18.0);
  let fog_color = globals.fog_color_jitter_x.xyz;
  let in_scattering = fog_color * (0.38 + forward_scattering * 2.8);
  return color * transmittance + in_scattering * (1.0 - transmittance);
}

fn camera_ray(pixel: vec2<u32>, jitter: vec2<f32>) -> Ray {
  let resolution = globals.resolution_samples.xy;
  let screen = ((vec2<f32>(pixel) + vec2<f32>(0.5) + jitter) / resolution) * 2.0 - vec2<f32>(1.0);
  let aspect = resolution.x / resolution.y;
  let tan_half_fov = globals.camera_position_tan_fov.w;
  let direction = normalize(
    globals.camera_forward_mode.xyz
    + globals.camera_right_exposure.xyz * (screen.x * aspect * tan_half_fov)
    - globals.camera_up_fog_density.xyz * (screen.y * tan_half_fov)
  );
  return Ray(globals.camera_position_tan_fov.xyz, direction);
}

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
  let resolution = vec2<u32>(globals.resolution_samples.xy);
  let pixel = global_id.xy;
  if (pixel.x >= resolution.x || pixel.y >= resolution.y) {
    return;
  }

  let frame_index = u32(globals.resolution_samples.w);
  let sample_limit = min(u32(globals.jitter_y_params.y), MAX_SAMPLES_PER_FRAME);
  let temporal_aa = u32(globals.render_params.x) == 2u;
  var summed_radiance = vec3<f32>(0.0);

  for (var sample_index = 0u; sample_index < MAX_SAMPLES_PER_FRAME; sample_index += 1u) {
    if (sample_index >= sample_limit) {
      break;
    }

    var state = hash_u32(
      pixel.x * 1973u
      + pixel.y * 9277u
      + frame_index * 26699u
      + sample_index * 31847u
    );
    var jitter = vec2<f32>(0.0);
    if (temporal_aa) {
      jitter = vec2<f32>(globals.fog_color_jitter_x.w, globals.jitter_y_params.x);
      if (sample_limit > 1u) {
        jitter += vec2<f32>(random(&state) - 0.5, random(&state) - 0.5) * 0.7;
      }
    }

    let ray = camera_ray(pixel, jitter);
    var sample_radiance = vec3<f32>(0.0);
    if (globals.camera_forward_mode.w < 0.5) {
      sample_radiance = trace_ray(ray);
    } else {
      sample_radiance = trace_path(ray, state);
    }

    let primary_hit = intersect_scene(ray);
    let fog_distance = select(60.0, min(primary_hit.t, 60.0), primary_hit.hit != 0u);
    summed_radiance += apply_volumetric_fog(sample_radiance, ray, fog_distance);
  }

  let previous_samples = globals.resolution_samples.z;
  let current_samples = f32(sample_limit);
  var accumulated = summed_radiance / max(current_samples, 1.0);
  if (previous_samples > 0.0) {
    let previous = textureLoad(previous_frame, vec2<i32>(pixel), 0).rgb;
    accumulated = (previous * previous_samples + summed_radiance) / (previous_samples + current_samples);
  }
  textureStore(output_frame, vec2<i32>(pixel), vec4<f32>(accumulated, 1.0));
}
`;

export const PRESENTATION_SHADER = /* wgsl */ `
struct DisplaySettings {
  values: vec4<f32>,
}

struct VertexOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var hdr_texture: texture_2d<f32>;
@group(0) @binding(1) var hdr_sampler: sampler;
@group(0) @binding(2) var<uniform> display: DisplaySettings;

@vertex
fn vertex_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {
  let positions = array<vec2<f32>, 3>(
    vec2<f32>(-1.0, -1.0),
    vec2<f32>(3.0, -1.0),
    vec2<f32>(-1.0, 3.0)
  );
  let position = positions[vertex_index];
  var output: VertexOutput;
  output.position = vec4<f32>(position, 0.0, 1.0);
  output.uv = position * vec2<f32>(0.5, -0.5) + vec2<f32>(0.5);
  return output;
}

fn aces_tone_map(color: vec3<f32>) -> vec3<f32> {
  let a = 2.51;
  let b = 0.03;
  let c = 2.43;
  let d = 0.59;
  let e = 0.14;
  return clamp((color * (a * color + b)) / (color * (c * color + d) + e), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn tone_map(color: vec3<f32>) -> vec3<f32> {
  let exposed = max(color * display.values.x, vec3<f32>(0.0));
  let mode = display.values.y;
  if (mode < 0.5) {
    return aces_tone_map(exposed);
  }
  if (mode < 1.5) {
    return exposed / (vec3<f32>(1.0) + exposed);
  }
  return clamp(exposed, vec3<f32>(0.0), vec3<f32>(1.0));
}

fn sample_display(uv: vec2<f32>) -> vec3<f32> {
  let sampled = textureSampleLevel(hdr_texture, hdr_sampler, clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0)), 0.0).rgb;
  return select(tone_map(sampled), sampled, display.values.w > 0.5);
}

fn luminance(color: vec3<f32>) -> f32 {
  return dot(color, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn fxaa(uv: vec2<f32>) -> vec3<f32> {
  let dimensions = vec2<f32>(textureDimensions(hdr_texture));
  let texel = vec2<f32>(1.0) / dimensions;
  let center = sample_display(uv);
  let north = sample_display(uv + vec2<f32>(0.0, -texel.y));
  let south = sample_display(uv + vec2<f32>(0.0, texel.y));
  let west = sample_display(uv + vec2<f32>(-texel.x, 0.0));
  let east = sample_display(uv + vec2<f32>(texel.x, 0.0));

  let luma_center = luminance(center);
  let luma_north = luminance(north);
  let luma_south = luminance(south);
  let luma_west = luminance(west);
  let luma_east = luminance(east);
  let luma_min = min(luma_center, min(min(luma_north, luma_south), min(luma_west, luma_east)));
  let luma_max = max(luma_center, max(max(luma_north, luma_south), max(luma_west, luma_east)));
  if (luma_max - luma_min < max(0.0312, luma_max * 0.125)) {
    return center;
  }

  var direction = vec2<f32>(-(luma_north - luma_south), luma_east - luma_west);
  let reduction = max((luma_north + luma_south + luma_west + luma_east) * 0.03125, 0.0078125);
  let reciprocal_minimum = 1.0 / (min(abs(direction.x), abs(direction.y)) + reduction);
  direction = clamp(direction * reciprocal_minimum, vec2<f32>(-8.0), vec2<f32>(8.0)) * texel;

  let rgb_a = 0.5 * (
    sample_display(uv + direction * (1.0 / 3.0 - 0.5))
    + sample_display(uv + direction * (2.0 / 3.0 - 0.5))
  );
  let rgb_b = rgb_a * 0.5 + 0.25 * (
    sample_display(uv + direction * -0.5)
    + sample_display(uv + direction * 0.5)
  );
  let luma_b = luminance(rgb_b);
  return select(rgb_b, rgb_a, luma_b < luma_min || luma_b > luma_max);
}

fn linear_to_srgb(color: vec3<f32>) -> vec3<f32> {
  let low = color * 12.92;
  let high = 1.055 * pow(max(color, vec3<f32>(0.0)), vec3<f32>(1.0 / 2.4)) - 0.055;
  return select(high, low, color <= vec3<f32>(0.0031308));
}

fn srgb_to_linear(color: vec3<f32>) -> vec3<f32> {
  let low = color / 12.92;
  let high = pow((max(color, vec3<f32>(0.0)) + 0.055) / 1.055, vec3<f32>(2.4));
  return select(high, low, color <= vec3<f32>(0.04045));
}

@fragment
fn fragment_main(input: VertexOutput) -> @location(0) vec4<f32> {
  var color = sample_display(input.uv);
  if (display.values.z > 0.5) {
    color = fxaa(input.uv);
  }
  var output_color = select(linear_to_srgb(color), color, display.values.w > 0.5);
  if (display.values.w > 2.5) {
    output_color = srgb_to_linear(color);
  }
  return vec4<f32>(output_color, 1.0);
}
`;
