import {
  capturePhysicsModuleLoadContext,
  PrioSDKExtension
} from './extension/prio-sdk-extension';
import {PRIOSDK_RUNTIME_BUILD} from './runtime-version';

const REGISTRATION_STATE_KEY = Symbol.for('priosdkgen4.extension.registration');

interface RegistrationState {
  readonly extensions: WeakMap<object, PrioSDKExtension>;
  runtimes?: WeakMap<object, PrioSDKExtension>;
}

function registrationState(): RegistrationState {
  const host = globalThis as unknown as Record<PropertyKey, unknown>;
  const existing = host[REGISTRATION_STATE_KEY];
  if (isRegistrationState(existing)) {
    if (!(existing.runtimes instanceof WeakMap)) existing.runtimes = new WeakMap();
    return existing;
  }

  const created: RegistrationState = {extensions: new WeakMap<object, PrioSDKExtension>(), runtimes: new WeakMap()};
  host[REGISTRATION_STATE_KEY] = created;
  return created;
}

function isRegistrationState(value: unknown): value is RegistrationState {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  return (value as {extensions?: unknown}).extensions instanceof WeakMap;
}

function canReuseExtension(extension: PrioSDKExtension): boolean {
  try {
    const candidate = extension as PrioSDKExtension & {isDisposed?: () => boolean};
    if (typeof candidate.isDisposed === 'function') {
      return !candidate.isDisposed();
    }
    // Bundles from before lifecycle recovery exposed the renderer but not
    // isDisposed(). This lets a newly loaded project replace one of those
    // terminal instances without requiring a new browser tab.
    return extension.renderer.getStatus().state !== 'destroyed';
  } catch {
    return false;
  }
}

export function registerPrioSDKExtension(scratch: ScratchAPI = Scratch): PrioSDKExtension {
  if (!scratch.extensions.unsandboxed) {
    throw new Error('PrioSDK Gen 4 must run as an unsandboxed TurboWarp extension.');
  }

  const physicsModuleLoadContext = capturePhysicsModuleLoadContext();
  const state = registrationState();
  const registered = state.runtimes?.get(scratch.vm.runtime) ?? state.extensions.get(scratch.extensions);
  if (registered !== undefined && canReuseExtension(registered)) {
    const versioned = registered as PrioSDKExtension & {getRuntimeVersion?: () => string};
    const existingVersion = versioned.getRuntimeVersion?.() ?? 'an older unversioned build';
    if (existingVersion !== PRIOSDK_RUNTIME_BUILD) {
      throw new Error(`This tab already contains PrioSDK ${existingVersion}, but this project requires ${PRIOSDK_RUNTIME_BUILD}. Open the project in a fresh tab to load its bundled runtime. No existing project was replaced.`);
    }
    const configurable = registered as PrioSDKExtension & {
      configurePhysicsModuleLoading?: PrioSDKExtension['configurePhysicsModuleLoading'];
    };
    configurable.configurePhysicsModuleLoading?.(physicsModuleLoadContext);
    state.runtimes?.set(scratch.vm.runtime, registered);
    state.extensions.set(scratch.extensions, registered);
    return registered;
  }

  const extension = new PrioSDKExtension(scratch, physicsModuleLoadContext);
  scratch.extensions.register(extension);
  state.extensions.set(scratch.extensions, extension);
  state.runtimes?.set(scratch.vm.runtime, extension);
  return extension;
}

if (!Scratch.extensions.unsandboxed) {
  throw new Error('PrioSDK Gen 4 must run as an unsandboxed TurboWarp extension.');
}

registerPrioSDKExtension(Scratch);

