import type {GuidedReconstructionMode, GuidedTensor} from './guided-reconstruction-graph';

export type GuidedInferencePreference = 'auto' | 'webgpu' | 'webnn' | 'webnn-npu';
export type GuidedInferenceBackend = 'webgpu' | 'webnn';

export interface GuidedInferenceReport {
  readonly requestedBackend: GuidedInferencePreference;
  readonly executedBackend: GuidedInferenceBackend;
  readonly hardwareUnits: 'unverified';
  readonly milliseconds: number;
  readonly tileCount: number;
  readonly hostTransfers: boolean;
  readonly fallbackReason?: string;
  readonly webnnAccelerated?: boolean;
  readonly reportedDevices?: readonly ('cpu' | 'gpu' | 'npu')[];
  readonly benchmarkMilliseconds?: Readonly<Partial<Record<GuidedInferenceBackend, number>>>;
}

export interface GuidedInferenceProgress {
  readonly phase: 'validating' | 'probing' | 'restoring';
  readonly completedTiles: number;
  readonly totalTiles: number;
}

export interface GuidedInferenceOptions {
  readonly signal?: AbortSignal;
  readonly onProgress?: (progress: GuidedInferenceProgress) => void;
}

export interface GuidedGpuTensor {
  readonly buffer: GPUBuffer;
  readonly channels: number;
  readonly width: number;
  readonly height: number;
}

export interface GuidedGpuInferenceResult {
  readonly tensor: GuidedGpuTensor;
  readonly report: GuidedInferenceReport;
  release(): void;
}

export interface GuidedInferenceResult {
  readonly tensor: GuidedTensor;
  readonly report: GuidedInferenceReport;
}

export interface GuidedTileBackend {
  readonly kind: GuidedInferenceBackend;
  inferTile(input: GuidedTensor, mode: GuidedReconstructionMode, signal?: AbortSignal): Promise<GuidedTensor>;
  dispose(): void;
}

export function throwIfGuidedAborted(signal?: AbortSignal): void {
  if (signal?.aborted) throw new DOMException('Reconstruction was cancelled.', 'AbortError');
}

export async function awaitGuidedOperation<T>(
  operation: Promise<T>, timeoutMs: number, signal?: AbortSignal, onLateValue?: (value: T) => void
): Promise<T> {
  if (signal?.aborted) {
    void operation.then(value => onLateValue?.(value), () => undefined).catch(() => undefined);
    throwIfGuidedAborted(signal);
  }
  let timer: ReturnType<typeof setTimeout> | undefined;
  let abort: (() => void) | undefined;
  let abandoned = false;
  try {
    return await Promise.race([
      operation.then(value => {
        if (abandoned) onLateValue?.(value);
        return value;
      }),
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error('Reconstruction operation timed out.')), timeoutMs);
        abort = () => reject(new DOMException('Reconstruction was cancelled.', 'AbortError'));
        signal?.addEventListener('abort', abort, {once: true});
        if (signal?.aborted) abort();
      })
    ]);
  } catch (error) {
    abandoned = true;
    throw error;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    if (abort !== undefined) signal?.removeEventListener('abort', abort);
  }
}

export function assertGuidedParity(actual: Float32Array, expected: Float32Array): void {
  if (actual.length !== expected.length) throw new Error('Inference output shape does not match the reference.');
  for (let index = 0; index < expected.length; index++) {
    const left = actual[index]!;
    const right = expected[index]!;
    if (!Number.isFinite(left) || !Number.isFinite(right)
        || Math.abs(left - right) > 0.0003 + Math.abs(right) * 0.001) {
      throw new Error(`Inference numerical probe failed at output ${index}.`);
    }
  }
}
